// Función para calcular el porcentaje de relación entre palabras clave y descripciones
function calculateMatchPercentage(keywords, key, description) {
    const keywordCount = keywords.length;
    let matchCount = 0;

    for (const word of keywords) {
        if (key.split(" ").includes(word) || description.split(" ").includes(word)) {
            matchCount++;
        }
    }

    return (matchCount / keywordCount) * 100;
}


