function createOption(text) {
    const li = document.createElement("li");
    const link = document.createElement("a");
    link.href = "#";
    link.textContent = text;
    li.appendChild(link);

    link.addEventListener("click", (event) => {
        event.preventDefault();
        const selectedOption = event.target.textContent;
        handleOptionSelection(selectedOption, li);
    });

    return li;
}

function scrollToBottom() {
    chatContent.scrollTop = chatContent.scrollHeight;
}

function addMessageWithTypingEffect(content, isReceived, typingDelay, messageDuration) {
    // Muestra "Escribiendo..." primero
    const typingMessage = document.createElement("div");
    typingMessage.className = `message ${isReceived ? "received" : "sent"} typing-message`;
    typingMessage.innerHTML = "Escribiendo...";

    const messageDiv = document.createElement("div");
    messageDiv.className = `message ${isReceived ? "received" : "sent"}`;

    // Agrega el mensaje de "Escribiendo..." primero
    chatContent.appendChild(typingMessage);
    scrollToBottom();

    // Después de un retraso, muestra el mensaje completo
    setTimeout(() => {
        // Elimina el mensaje de "Escribiendo..."
        if (typingMessage.parentNode) {
            typingMessage.parentNode.removeChild(typingMessage);
        }

        messageDiv.innerHTML = `<p>${content}</p>`;
        chatContent.appendChild(messageDiv);
        scrollToBottom();

        // Elimina el mensaje completo después de otro retraso (messageDuration)
        if (messageDuration > 0) {
            setTimeout(() => {
                if (messageDiv.parentNode) {
                    messageDiv.parentNode.removeChild(messageDiv);
                }
                scrollToBottom(); // Asegura que el chat se desplace hacia abajo después de eliminar un mensaje
            }, messageDuration);
        }
    }, typingDelay);
}



