    const searchButton = document.createElement("button");
    searchButton.textContent = "Enviar";
    inputDiv.appendChild(keywordInput);
    inputDiv.appendChild(searchButton);
    chatContent.appendChild(inputDiv);

    searchButton.addEventListener("click", () => {
        const keyword = keywordInput.value.trim();
        if (keyword !== "") {
            addMessage("Esto es lo que pude encontrar:", true);
            const dataArray = {
 "  LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES - Título I: Disposiciones Generales - Artículo 1º": "La presente Ley establece las bases jurídicas e institucionales fundamentales del Sistema Integral de Seguridad Pública de la Ciudad Autónoma de Buenos Aires en lo referente a su composición, misión, función, organización, dirección, coordinación y funcionamiento, así como las bases jurídicas e institucionales para la formulación, implementación y control de las políticas y estrategias de seguridad pública.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES - Título I: Disposiciones Generales - Artículo 2°": "A los fines de la presente Ley se define como seguridad pública a la situación de hecho basada en el derecho en la cual se encuentran resguardadas la libertad, la vida y el patrimonio de los habitantes, sus derechos y garantías y la plena vigencia de las instituciones del sistema representativo, republicano y federal que establecen la Constitución Nacional y la Constitución de la Ciudad Autónoma de Buenos Aires.",
    
    "  LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título I: Disposiciones Generales - Artículo 3°": "La seguridad pública implica la acción coordinada y la interacción permanente entre las personas y las instituciones del sistema democrático, representativo y republicano, particularmente, los organismos componentes del Sistema Integral de Seguridad Pública de la Ciudad Autónoma de Buenos Aires.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES - Título I: Disposiciones Generales - Artículo 4°": "La seguridad pública es deber propio e irrenunciable del Estado de la Ciudad Autónoma de Buenos Aires, que debe arbitrar los medios para salvaguardar la libertad, la integridad y derechos de las personas, así como preservar el orden público, implementando políticas públicas tendientes a asegurar la convivencia y fortalecer la cohesión social, dentro del estado de derecho, posibilitando el goce y pleno ejercicio, por parte de las personas, de las libertades, derechos y garantías constitucionalmente consagrados.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título I: Disposiciones Generales - Artículo 5°": "El Ministerio de Justicia y Seguridad es el organismo encargado de elaborar los lineamientos generales en materia de seguridad, tendientes a llevar a cabo el diseño de las acciones preventivas necesarias y las tareas de control. Realizará las tareas de control y aplicará el régimen disciplinario sancionatorio de la actuación policial, conforme lo establecido por el Artículo 35 de la Constitución de la Ciudad Autónoma de Buenos Aires.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título II: Sistema Integral de Seguridad Pública - Artículo 6°": "El Sistema Integral de Seguridad Pública de la Ciudad Autónoma de Buenos Aires tiene como finalidad la formulación, implementación y control de las políticas de seguridad pública desarrolladas en el ámbito local, aquellas referidas a las estrategias sociales de prevención de la violencia y el delito, así como las estrategias institucionales de persecución penal, de seguridad preventiva comunitaria y de seguridad compleja.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título II: Sistema Integral de Seguridad Pública - Artículo 7°": "Son objetivos del Sistema Integral de Seguridad Pública de la Ciudad:\n1. Facilitar las condiciones que posibiliten el pleno ejercicio de las libertades, derechos y garantías constitucionales en la Ciudad Autónoma de Buenos Aires.\n2. Mantener el orden y la tranquilidad pública en todo el territorio de la Ciudad, con excepción de los lugares sujetos a jurisdicción federal.\n3. Proteger la integridad física de las personas, así como sus derechos y bienes.\n4. Promover y coordinar los programas de disuasión y prevención de delitos, contravenciones y faltas.\n5. Establecer los mecanismos de coordinación y colaboración para evitar la comisión de delitos, contravenciones y faltas.\n6. Promover la investigación de delitos, contravenciones y faltas, así como la persecución y sanción de sus autores.\n7. Promover el intercambio de información en los términos de esta Ley.\n8. Dirigir y coordinar los organismos de ejecución de pena a los fines de lograr la reinserción social del condenado, en cumplimiento de la legislación vigente.\n9. Establecer los mecanismos de coordinación entre las diversas autoridades para apoyo y auxilio a la población en casos de siniestros o desastres, conforme a los ordenamientos legales vigentes en la materia.\n10. Garantizar la seguridad en el tránsito a través de la prevención del riesgo vial y el control de la seguridad vial.\n11. Regular y controlar la prestación de los servicios de seguridad privada.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título III: Principios Rectores de la Gestión de la Seguridad Pública - Artículo 9°": "El Sistema Integral de Seguridad Pública y el diseño de políticas públicas en la materia en la Ciudad de Buenos Aires adopta los siguientes principios rectores:\n1. Gobierno civil: por medio del control civil sobre la gestión institucional y el proceso de formación y capacitación de los actores del Sistema Integral de Seguridad Pública y garantizando el acceso a la información.\n2. Cercanía: a través del conocimiento de las necesidades de la comunidad y la adaptación consecuente de la prestación de los servicios de seguridad, promoviendo la gestión democrática de las instituciones de la seguridad y la desconcentración de la organización policial a nivel comunal. El Gobierno de la Ciudad de Buenos Aires debe implementar acciones para promover el acceso igualitario de todas las personas a la justicia, incluido el establecimiento de un sistema de recepción de denuncias desconcentrado territorialmente.\n3. Participación ciudadana: promoviendo la integración con la comunidad y la participación de los ciudadanos y las organizaciones civiles con las autoridades encargadas de la seguridad en cada una de las comunas en el diagnóstico y la propuesta de estrategias y políticas en materia de seguridad.\n4. Innovación: estimulando la modernización de la gestión administrativa y la incorporación de nuevas tecnologías en el desarrollo de los procedimientos y servicios.\n5. Transparencia: implementando mecanismos eficaces, eficientes y ágiles en los procesos y procedimientos que tengan por objeto tutelar y proteger la seguridad pública.\n6. Prevención: desarrollando estrategias y medidas tendientes a reducir las causas generadoras de conductas ilícitas, coordinando políticas sociales con políticas de seguridad con especial atención a los grupos poblacionales más vulnerables.\n7. Desburocratización: desarrollando nuevas formas de organización y racionalización para la simplificación de los procedimientos administrativos.\n8. Eficacia y eficiencia: con el fin de alcanzar los objetivos propuestos mediante una correcta asignación y un mejor aprovechamiento de los recursos del Estado, reduciendo los tiempos de los procedimientos.\n9. Información estadística confiable: mediante la recopilación de datos relevantes en materia de seguridad sobre la base de indicadores estandarizados por el Ministerio de Justicia y Seguridad, a efectos de desarrollar informes confiables y oportunos que permitan adoptar políticas públicas eficaces en la materia.",
    
    // Continúa con los artículos existentes
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título IV: Gobierno Civil de la Seguridad - Artículo 10": "El Jefe de Gobierno, en su carácter de titular del Poder Ejecutivo de la Ciudad de Buenos Aires y Jefe de la Administración, o el funcionario que éste designe o en quien delegue esta competencia, debe articular el Sistema Integral de Seguridad Pública de la Ciudad Autónoma de Buenos Aires.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título IV: Gobierno Civil de la Seguridad - Artículo 11": "El Ministerio de Justicia y Seguridad, debe formular y presentar anualmente a la Legislatura de la Ciudad el Plan General de Seguridad Pública que debe contener la misión o premisa dominante, las metas generales y los objetivos específicos de la política de seguridad pública, así como las estrategias y directivas generales para su gestión, implementación y control. Dicha presentación se realiza junto con el giro del proyecto de presupuesto de gastos y recursos de la Ciudad y sus entes autárquicos y descentralizados.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título IV: Gobierno Civil de la Seguridad - Artículo 12": "El Jefe de Gobierno puede delegar en el Ministerio de Justicia y Seguridad las responsabilidades establecidas en la presente Ley. El Ministerio de Justicia y Seguridad es responsable de la planificación estratégica de las políticas de seguridad pública basándose en las siguientes funciones:\n1. La reunión de información estadística confiable a través de la producción y sistematización que realicen las dependencias a su cargo.\n2. La elaboración, implementación y evaluación de las políticas y las estrategias de seguridad pública y de las directivas generales y específicas necesarias para su gestión y control, a través de las áreas dependientes competentes para ello.\n3. La planificación estratégica basada en la elaboración y formulación de la estrategia institucional asentada en la realización del diagnóstico institucional y de los planes de reforma y modernización institucional, así como de las estrategias de control social e institucional de la violencia y de las diferentes modalidades delictivas.\n4. La gestión del conocimiento en materia de seguridad pública a través de la planificación, producción, coordinación y evaluación del conocimiento institucional referido a la situación y el desempeño de los componentes del Sistema Integral de Seguridad Pública, así como del conocimiento criminal referido a la situación del delito y la violencia en el nivel estratégico.\n5. La dirección superior de la Policía de la Ciudad, a través de las dependencias que determine su estructura, mediante la planificación estratégica, el diseño y formulación de las estrategias policiales de control de la violencia y el delito, la conducción y coordinación funcional y organizativa de sus diferentes instancias y componentes. Es, asimismo, responsable de la dirección del accionar específico, así como también de las actividades y labores conjuntas con otros cuerpos policiales y fuerzas de seguridad, el Cuerpo de Bomberos, el servicio de Seguridad Privada y el Cuerpo de Agentes de Control de Tránsito y Transporte, de acuerdo con sus funciones y competencias específicas.\n6. La gestión administrativa general de la Policía de la Ciudad en todo lo que compete a la dirección de los recursos humanos, la reglamentación del servicio de policía complementaria y del servicio complementario de prevención de incendios, la planificación y ejecución presupuestaria, la gestión económica, contable, financiera y patrimonial, la planificación y gestión logística e infraestructural y la asistencia y asesoramiento jurídico-legal.\n7. La dirección y coordinación del sistema de prevención de la violencia y el delito, especialmente en la formulación, implementación y evaluación de las estrategias de prevención social de la violencia y el delito.\n8. La coordinación integral de la participación ciudadana en asuntos de seguridad pública.\n9. La fiscalización del sistema de seguridad privada y la administración del régimen sancionatorio y de infracciones, a través de las dependencias a su cargo.\n10. La elaboración, implementación y evaluación de las políticas y las estrategias en materia penitenciaria y de reinserción social de los condenados y de las directivas generales y específicas necesarias para su gestión y control.\n11. La planificación, organización y ejecución de la capacitación, formación e investigación científica y técnica en materia de seguridad pública tanto para el personal policial como para los funcionarios y demás sujetos públicos y privados vinculados a la materia, a través del Instituto Superior de Seguridad Pública.\n12. Intervenir en la elaboración y evaluación de las políticas y estrategias de seguridad vial y su implementación a través del Cuerpo de Agentes de Control de Tránsito y Transporte.\n13. La coordinación de los distintos componentes del Sistema de Emergencias.\n14. La Oficina de Transparencia y Control Externo.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título IV: Gobierno Civil de la Seguridad - Artículo 13": "Los componentes del Sistema Integral de Seguridad Pública de la Ciudad de Buenos Aires no pueden ser auditados o controlados sino por los organismos creados por la Constitución de la Ciudad Autónoma de Buenos Aires o por las leyes que en su consecuencia se dicten.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título V: Coordinación Estratégica y Relaciones Interjurisdiccionales - Artículo 14": "El Ministerio de Justicia y Seguridad coordina el ejercicio de las respectivas funciones de los componentes del Sistema Integral de Seguridad Pública de la Ciudad para el cumplimiento de los objetivos previstos en la presente Ley.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título V: Coordinación Estratégica y Relaciones Interjurisdiccionales - Artículo 15": "La Ciudad Autónoma de Buenos Aires adhiere a la Ley Nacional N° 24.059 #, de Seguridad Interior, al Decreto N° 1.273/92 #, y participa e integra en todas las instancias creadas por la Ley Nacional N° 25.520 # de Inteligencia Nacional.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título V: Coordinación Estratégica y Relaciones Interjurisdiccionales - Artículo 16": "El Poder Ejecutivo, a través del Ministerio de Justicia y Seguridad, establece las formas y modalidades en que se articula la acción de los distintos ministerios en apoyo a los esfuerzos que se desarrollen para la prevención integral del delito.",
    
     " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo I: Generalidades - Artículo 17": "Es un derecho de los ciudadanos y un deber del Estado de la Ciudad promover la efectiva participación ciudadana en asuntos de seguridad pública, a través de los mecanismos dispuestos en la presente Ley y en las reglamentaciones que en consecuencia se dicten.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo I: Generalidades - Artículo 18": "El Ministro de Justicia y Seguridad aprueba los medios para canalizar las vías de participación y denuncia ciudadanas.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo I: Generalidades - Artículo 19": "La participación ciudadana se efectiviza a través de la actuación de los Foros de Seguridad Pública (FOSEP).",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo I: Generalidades - Artículo 20": "Los Foros de Seguridad Pública se constituyen como ámbitos de participación y colaboración entre la sociedad civil y las autoridades, para la canalización de demandas y la formulación de propuestas en materia de seguridad pública.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo II: Objeto - Artículo 21": "Los FOSEP se desarrollan en el ámbito territorial de las Comunas de la Ciudad Autónoma de Buenos Aires, estableciéndose uno por cada una de ellas.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo II: Objeto - Artículo 22": "Los FOSEP promueven la efectiva participación ciudadana para la formulación de propuestas y seguimiento en materia de políticas públicas de seguridad. Las propuestas de los FOSEP son consideradas prioritarias para la planificación de los planes de prevención.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo III: Composición - Artículo 23": "Cada FOSEP está integrado por:\n1. Organizaciones de la sociedad civil o entidades comunitarias y vecinales con personería jurídica, domicilio y actuación en el ámbito territorial de la Comuna correspondiente.\n2. El representante de la Junta Comunal que tenga entre sus atribuciones la temática de la seguridad pública.\n3. Un representante de cada una de las fuerzas de seguridad con actuación en la Comuna correspondiente.\n4. Un representante del Ministerio de Justicia y Seguridad.\n5. Un representante del Ministerio Público Fiscal de la Ciudad Autónoma de Buenos Aires.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo IV: Registros - Artículo 24": "A los fines de su funcionamiento los FOSEP cuentan con los siguientes Registros:\n1. Registro de Organizaciones de la sociedad civil o entidades comunitarias y vecinales con personería jurídica señaladas en el artículo 23, inciso 1 de la presente Ley.\n2. Registro de Vecinos que deseen participar a título individual de las reuniones plenarias que organice el Foro de su Comuna.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo V: Funciones - Artículo 25": "Los FOSEP tienen las siguientes funciones:\n1. Formular propuestas para el Plan General de Seguridad Pública.\n2. Colaborar en los asuntos vinculados a la seguridad pública comunal, en la forma y con los alcances que determine la reglamentación.\n3. Evaluar la implementación de políticas públicas de seguridad en la Comuna.\n4. Formular sugerencias y presentar propuestas en materia de seguridad pública.\n5. Informar y asesorar a los vecinos acerca de toda cuestión atinente a la seguridad pública en la Comuna.\n6. Establecer una relación permanente con las dependencias policiales que actúen dentro de su jurisdicción.\n7. Evaluar el funcionamiento de la actuación policial en el ámbito de la Comuna.\n8. Invitar a autoridades, funcionarios públicos, organizaciones de la sociedad civil, instituciones educativas y culturales tanto públicas como privadas, con actuación en su ámbito territorial para tratar cuestiones referentes a la seguridad pública.\n9. Participar del Sistema de Información para la Prevención Comunitaria del Delito y la Violencia (SIPREC).\n10. Coordinar conjuntamente con autoridades del Gobierno de la Ciudad Autónoma de Buenos Aires, organizaciones de la sociedad civil e instituciones educativas con actuación en su ámbito territorial, la organización de cursos, seminarios y talleres abiertos al público que versen sobre cuestiones inherentes a la seguridad pública.\n11. Facilitar la comunicación, el entendimiento y la cooperación entre los distintos actores comunitarios, las dependencias policiales de su jurisdicción y las autoridades gubernamentales.\n12. Participar en la elaboración y control de las estrategias y planes de prevención social de la violencia y el delito llevados a cabo por los organismos públicos especializados en la materia.\n13. Constituirse en un ámbito de intercambio de información y experiencias respecto de sus propios barrios, los problemas específicos que padecen y los principales lugares de conflictividad, a los fines de formular aportes a los planes de seguridad y prevención relativos a la correspondiente Comuna.\n14. Convocar a reuniones plenarias periódicas de los FOSEP a los inscriptos en los Registros establecidos en el artículo 24.\nLa evaluación prevista en el inciso 7 se realiza sin la participación de los representantes de las fuerzas de seguridad.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo VI: Participación Vecinal - Artículo 26": "Los vecinos que no integren ninguna de las organizaciones mencionadas en el artículo 23, inciso 1, pueden participar en los FOSEP a título individual, bajo las siguientes modalidades:\n1. Presentando ante el Foro de su Comuna una iniciativa, reclamo o petición por escrito, que el Foro debe considerar en la próxima reunión.\n2. Participando de los talleres y seminarios que el Foro organice o coordine.\n3. Participando de la reunión plenaria que organice el Foro de su Comuna.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo VII: Organización y Funcionamiento - Artículo 27": "La integración de la Coordinación de los FOSEP es definida por la autoridad de aplicación de la presente y tiene las siguientes funciones:\n- Convocar a todas las instituciones, organizaciones de la sociedad civil, entidades comunitarias y vecinales que reúnan los requisitos establecidos en el artículo 23, inciso 1 y vecinos, a inscribirse en los registros previstos en el artículo 24.\n- Promover la conformación de los Foros en cada una de las Comunas.\n- Brindar el soporte administrativo para el buen funcionamiento y gestión de los Foros.\n- Elaborar las actas con las resoluciones de los foros que serán firmadas por los vecinos y organizaciones participantes.\n- Coordinar las acciones y relación de los Foros con el Gobierno de la Ciudad y con las Comunas.\n- Canalizar, a través del representante del Ministerio de Justicia y Seguridad o el organismo que en un futuro lo reemplace, las respuestas y consideraciones realizadas por el Gobierno de la Ciudad Autónoma de Buenos Aires a las propuestas e inquietudes surgidas en cada Foro.\n- Elaborar un informe de gestión de las demandas surgidas en los foros que deberá ser puesto a consideración de los participantes en el siguiente encuentro para su evaluación.\n- Remitir un informe semestral que describa las actividades realizadas por los Foros con sus respectivas iniciativas, reclamos o peticiones, al Ministro de Justicia y Seguridad, quien lo remitirá a la Legislatura y a la Defensoría del Pueblo de la Ciudad Autónoma de Buenos Aires.\n- Coordinar el seguimiento de las iniciativas, reclamos o peticiones realizadas por cada uno de los Foros.\n- Establecer una mesa de trabajo permanente con la Junta Comunal.",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo VII: Organización y Funcionamiento - Artículo 28": "Las sugerencias y propuestas que surjan de los Foros son puestas en conocimiento de la autoridad de aplicación, del Consejo de Seguridad y Prevención del Delito y del Comité de Seguimiento de Seguridad Pública creado por la Ley 3253 # (texto consolidado por Ley 5454).",
    
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VII: Transparencia - Artículo 29": "Toda persona puede solicitar y recibir información completa, veraz, adecuada y oportuna ante los órganos que componen el Sistema Integral de Seguridad Pública de la Ciudad Autónoma de Buenos Aires, conforme las disposiciones vigentes del régimen general de acceso a la información pública.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VII: Transparencia - Artículo 30": "El funcionario público o agente responsable que en forma arbitraria obstruya el acceso del solicitante a la información requerida o la suministre en forma incompleta u obstaculice de cualquier modo el acceso a la información que el Gobierno de la Ciudad debe suministrar, es considerado incurso en falta grave.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VII: Transparencia - Artículo 31": "La denegatoria de la información debe ser dispuesta por un funcionario de jerarquía equivalente o superior a Director General, en forma fundada. Sólo puede rechazarse un requerimiento de información si se exponen de manera detallada los elementos y las razones por las cuales su entrega puede ocasionar un daño al bien jurídico protegido.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VII: Transparencia - Artículo 32": "Los órganos que componen el sistema integral de seguridad pública no están obligados a suministrar información cuando:\n1. Se prevea un mecanismo especial para la tramitación de la solicitud, ya sea por su naturaleza, materia o características, conforme las normas vigentes.\n2. Afecte la intimidad de las personas o bases de datos con información de domicilios o teléfonos o datos personales.\n3. Se trate de información obtenida con carácter confidencial o esté protegida por el secreto bancario.\n4. Su publicidad pudiera revelar la estrategia a adoptarse en la defensa o tramitación de una causa judicial o de cualquier tipo que resulte protegida por el secreto profesional.\n5. Se trate de notas internas con recomendaciones u opiniones producidas como parte del proceso previo a la toma de una decisión de Autoridad Pública que no formen parte de los expedientes.\n6. Sea esencial para resguardar la estrategia o dirección de la investigación u operación tendiente a hacer efectivo el deber de seguridad pública en el marco del Sistema Integral de Seguridad Pública establecido en la presente ley.\n7. Su reserva sea esencial para resguardar el respeto a los derechos de las personas, la protección de la seguridad pública, el orden público, la salud y la moral pública.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VII: Transparencia - Artículo 33": "Los interesados, oferentes, contratistas o subcontratistas que participen en procedimientos de selección o de contrataciones vinculadas con la prestación del servicio de seguridad pública, tienen la obligación de guardar confidencialidad aún después de la extinción del procedimiento o contrato, en todo cuanto se relacione con el objeto de aquél, salvo requerimiento judicial.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VIII: Oficina de Transparencia y Control Externo - Artículo 34": "Créase la Oficina de Transparencia y Control Externo de la Policía de la Ciudad, órgano desconcentrado del Ministerio de Justicia y Seguridad. Quedan sujetos a su ámbito de competencia todos los integrantes de la Policía de la Ciudad, tengan o no estado policial, y el personal retirado. Los miembros de la Policía de la Ciudad no pueden integrar la Oficina de Transparencia y Control Externo. Su personal ingresa por concurso público de oposición y antecedentes, conforme los requisitos que establezca la reglamentación. Los miembros de la Policía de la Ciudad deberán presentar una Declaración Jurada Patrimonial Integral al inicio y al final de su función y una actualización en forma anual.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VIII: Oficina de Transparencia y Control Externo - Artículo 35": "Son funciones de la Oficina de Transparencia y Control Externo:\n1. Investigar las situaciones en las que intervenga personal de la Policía de la Ciudad y en las que se denuncie o se presuma razonablemente la existencia de irregularidades.\n2. Sustanciar los sumarios administrativos y proponer al Ministro de Justicia y Seguridad, cuando corresponda, las sanciones disciplinarias a aplicar. Cuando de los hechos investigados se pueda presumir la comisión de delitos, la Oficina comunica dicha circunstancia al citado Ministro a los fines de las presentaciones judiciales que pudieran corresponder.\n3. Elaborar programas y políticas de prevención de la corrupción y promoción de la transparencia en el ámbito de las fuerzas de seguridad de la Ciudad Autónoma de Buenos Aires y proponer su implementación al Ministro de Justicia y Seguridad.\n4. Planificar programas y acciones tendientes a prevenir aquéllas conductas vinculadas con la actuación del personal policial que puedan constituir faltas éticas y abusos funcionales graves y proponer su implementación al Ministro de Justicia y Seguridad.\n5. Recibir las Declaraciones Juradas Patrimoniales Integrales de los miembros de la Policía de la Ciudad y colaborar con la autoridad de aplicación de la Ley 4895 (texto consolidado por Ley 5454).\n6. Elaborar un informe anual sobre el desempeño de la Policía de la Ciudad en materia de promoción de los derechos humanos.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VIII: Oficina de Transparencia y Control Externo - Artículo 36": "Los miembros de la Oficina de Transparencia y Control Externo de la Policía de la Ciudad deben actuar conforme los siguientes principios:\n1. Independencia de criterio, entendida como la responsabilidad de preservar la objetividad en la consideración de los hechos y ser imparcial en la formulación de conclusiones y recomendaciones. El personal debe excusarse de intervenir en aquellas investigaciones en las cuales su independencia de criterio pueda verse afectada por cualquier motivo.\n2. Idoneidad, entendida como la formación técnica y experiencia profesional adecuadas para realizar las tareas que se requieran. En tal sentido se debe fomentar la capacitación permanente encaminada a la actualización técnico-profesional y perfeccionamiento en materias que hagan al objeto y finalidad del organismo.\n3. Debido cuidado y diligencia profesional, entendida como el recto criterio a la hora de seleccionar los métodos y procedimientos a aplicar en el curso de una investigación o tarea a desarrollar.\n4. Secreto profesional. El personal que intervenga en las investigaciones y sumarios debe mantener total reserva respecto a la información a la que acceda en el curso de su tarea, excepto cuando las normas o la autoridad competente dispongan la publicidad de la información.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VIII: Oficina de Transparencia y Control Externo - Artículo 37": "Para el cumplimiento de sus funciones la Oficina de Transparencia y Control Externo de la Policía de la Ciudad tiene acceso irrestricto a toda documentación, información, sistemas informáticos, de comunicación y de imágenes de la Policía de la Ciudad, debiendo solicitarla a través del Ministro de Justicia y Seguridad o el funcionario que éste designe. Constituye falta grave la obstrucción, ocultamiento, falsedad, reticencia o retardo injustificado en el suministro de la información requerida.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VIII: Oficina de Transparencia y Control Externo - Artículo 38": "La Oficina de Transparencia y Control Externo de la Policía de la Ciudad articula su actividad con la del órgano bajo la órbita de la Policía de la Ciudad encargado de sustanciar los procedimientos disciplinarios. A estos efectos:\n1. La Oficina de Transparencia y Control Externo tiene acceso directo a la totalidad de la información relacionada con los procedimientos administrativos sustanciados por el órgano policial, a su simple requisitoria.\n2. El órgano policial debe informar a la Oficina de Transparencia y Control Externo sobre la apertura de todo nuevo procedimiento en el cual se investigue la comisión de una falta disciplinaria o la existencia de una irregularidad.\n3. Si la Oficina de Transparencia y Control Externo decidiese instruir una investigación por un hecho que es investigado por el órgano policial, el sumario de la Oficina inhibe la prosecución del órgano policial. En este caso, éste último debe remitir las actuaciones a la Oficina de Transparencia de manera inmediata a los efectos de su unificación. Asimismo, el órgano policial no puede iniciar sumarios por hechos investigados por la Oficina de Transparencia y Control Externo.\n4. Si en el transcurso de sus investigaciones el órgano policial arribase a la conclusión de la posible comisión de un hecho delictivo, debe informarlo de manera inmediata a la Oficina de Transparencia y Control Externo, junto a todos los antecedentes del caso, a los efectos dispuestos en el artículo 35, inciso 2, in fine.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VIII: Oficina de Transparencia y Control Externo - Artículo 39": "El Ministerio de Justicia y Seguridad implementa un sistema de protección para el personal de la Policía de la Ciudad destinado a las víctimas, testigos o denunciantes de ilícitos, irregularidades administrativas, hechos de corrupción, faltas de integridad, abusos funcionales y/o delitos, frente a actos o hechos que tengan por objeto la intimidación, discriminación, castigo o represalia por la denuncia o testimonio brindados. La reglamentación establece los procedimientos de recepción de las denuncias y testimonios y las medidas de protección disponibles, pudiendo contemplarse la reserva de identidad. Las denuncias no podrán ser realizadas bajo la figura del anonimato. Las medidas de protección deben ser aplicadas contra todos los actos, resoluciones, prácticas formales o informales que afecten o amenacen en modo directo o indirecto la integridad personal, la seguridad, la integridad o libertad sexual, las relaciones laborales, el desarrollo de la carrera, la reputación personal o profesional del integrante de la Policía de la Ciudad que brinde denuncia o testimonio sobre los hechos señalados en el primer párrafo, o de su grupo familiar directo. Todos los procedimientos deben basarse en los principios de efectividad, celeridad, inmediatez, concentración, economía procesal, oralidad, proporcionalidad y confidencialidad.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título VIII: Oficina de Transparencia y Control Externo - Artículo 40": "La Oficina de Transparencia y Control Externo debe someter anualmente a la ciudadanía, por las vías que la reglamentación establezca, el expediente íntegro de diez (10) investigaciones relevantes sobre faltas cometidas por el personal policial que se hayan concluido, y en las cuales hayan quedado firmes las resoluciones recaídas. La publicidad de la información contemplada en este artículo debe atenerse a lo dispuesto en el artículo 32.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título IX: Defensoría del Personal de la Policía de la Ciudad - Artículo 41": "Créase la Defensoría del Personal de la Policía de la Ciudad, órgano desconcentrado dependiente del Ministro de Justicia y Seguridad, cuya misión es la defensa, protección y promoción integral de los derechos humanos y demás derechos e intereses individuales, colectivos y difusos del personal de la Policía de la Ciudad Autónoma de Buenos Aires tutelados en la Constitución Nacional, la Constitución de la Ciudad de Buenos Aires, las leyes y las reglamentaciones frente a los actos, hechos u omisiones de la administración.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título IX: Defensoría del Personal de la Policía de la Ciudad - Artículo 42": "Los miembros de la Policía de la Ciudad no pueden integrar la Defensoría del Personal de la Policía de la Ciudad. Su personal ingresa por concurso de oposición y antecedentes.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título IX: Defensoría del Personal de la Policía de la Ciudad - Artículo 43": "Son funciones de la Defensoría del Personal de la Policía de la Ciudad:\n1. Garantizar el debido proceso legal del personal de la Policía de la Ciudad.\n2. Proponer mecanismos de salvaguarda de los derechos del personal de la Policía de la Ciudad, velando por el cumplimiento de sus derechos y garantías y de un sano ambiente laboral, tutelando el cumplimiento de los preceptos establecidos en la presente ley frente a actos, hechos u omisiones de la administración pública y de la propia institución policial en desmedro de sus integrantes.\n3. Promover el respeto integral de los derechos del personal al interior de la Policía de la Ciudad.\n4. Asistir y asesorar al personal policial respecto de la discriminación laboral por razones de género, raza, religión, orientación sexual o cualquier otro motivo de discriminación ilegítima.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título IX: Defensoría del Personal de la Policía de la Ciudad - Artículo 44": "La Defensoría del Personal de la Policía de la Ciudad tiene legitimación administrativa y procesal y actúa con plena autonomía funcional, sin recibir instrucciones de ninguna autoridad.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título IX: Defensoría del Personal de la Policía de la Ciudad - Artículo 45": "Para el cumplimiento de sus funciones la Defensoría del Personal de la Policía de la Ciudad tiene acceso irrestricto a toda documentación, información, sistemas informáticos, de comunicación y de imágenes de la Policía de la Ciudad. Constituye falta grave la obstrucción, ocultamiento, falsedad, reticencia o retardo injustificado en el suministro de la información requerida.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título IX: Defensoría del Personal de la Policía de la Ciudad - Artículo 46": "Los integrantes de la Defensoría del Personal de la Policía de la Ciudad tienen la obligación de guardar confidencialidad, aún luego de cesar en sus cargos, respecto de la información a la que tengan acceso relacionada con el despliegue operativo, métodos de investigación o cualquier otro aspecto cuya divulgación a terceros pueda comprometer la eficacia del accionar de la Policía de la Ciudad.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo I: Consideraciones Generales - Artículo 47": "El Mapa del Delito, el Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) y la Encuesta de Victimización integran el sistema de gestión de información de seguridad pública.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo I: Consideraciones Generales - Artículo 48": "El sistema de gestión de información de seguridad pública tiene como finalidad:\n1. Elaborar el Mapa del Delito de la Ciudad Autónoma de Buenos Aires conforme las disposiciones contenidas en la presente Ley;\n2. Proveer información integral, relevante, mensurable, confiable y oportuna sobre la seguridad pública en la Ciudad Autónoma de Buenos Aires;\n3. Realizar estudios e investigaciones para la formulación de las políticas de seguridad;\n4. Identificar las problemáticas en materia de seguridad y realizar propuestas para la formulación de políticas sobre la base de la información producida;\n5. Promover y coordinar el intercambio de información con las organizaciones públicas y privadas vinculadas a la seguridad.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo I: Consideraciones Generales - Artículo 49": "El sistema de gestión de información de seguridad pública debe:\n1. Desarrollar informes y estadísticas sobre la criminalidad en la Ciudad Autónoma de Buenos Aires.\n2. Establecer criterios técnicos y metodológicos para la construcción de indicadores.\n3. Brindar asesoramiento en la materia a las áreas competentes y contribuir al mejoramiento de los registros estadísticos.\n4. Monitorear y realizar el control de calidad de los resultados estadísticos.\n5. Sistematizar y brindar información criminal y estadística a las áreas que la requieran para la elaboración de políticas de seguridad.\n6. Coordinar el intercambio de información entre los diferentes componentes del sistema integral de seguridad pública.\n7. Establecer mecanismos de intercambio de información con el gobierno nacional y los gobiernos provinciales.\n8. Intercambiar información con los poderes judiciales, ministerios públicos e instituciones que administren información de utilidad para la elaboración de informes y estadísticas.\n9. Coordinar la recolección de información atinente a los delitos.\n10. Proveer la información necesaria para el sistema nacional de información criminal (SNIC).",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo I: Consideraciones Generales - Artículo 50": "El sistema de gestión de información de seguridad pública de producir:\n1. Indicadores básicos a partir de todas las fuentes de información disponibles, asegurando una adecuada sistematicidad, continuidad y homogeneidad en la producción de los datos.\n2. Información sobre la incidencia de la victimización en la sociedad, desagregada según su tipo, características de las víctimas, delitos, y contravenciones denunciados y no denunciados, lugar, hora y modalidad de producción.\n3. Información sobre las causas tramitadas por el sistema judicial desagregada en delitos y contravenciones, detenciones realizadas, características de los individuos procesados y condenados a través del mismo, las personas bajo supervisión y reincidentes, incluyendo como mínimo, edad, sexo, nivel educativo, nacionalidad y estado civil.\n4. Información sobre percepción de la ciudadanía sobre aspectos relacionados con la seguridad y las instituciones vinculada a estos.\n5. Otras variables que determine la autoridad de aplicación.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo I: Consideraciones Generales - Artículo 51": "Los datos suministrados al sistema de gestión de información de seguridad pública sólo pueden utilizarse con fines estadísticos, sin individualizar a las personas involucradas en los hechos de referencia.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo I: Consideraciones Generales - Artículo 52": "Todas las personas que por razón de sus cargos o funciones tomen conocimiento de datos estadísticos o censales deben observar la debida reserva, confidencialidad y sigilo, resultado de aplicación, en el caso de incumplimiento, lo dispuesto en la legislación penal.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo I: Consideraciones Generales - Artículo 53": "La información producida por el sistema de gestión de información de seguridad pública es de libre acceso a través del sitio web del Gobierno de la Ciudad.",
    // Capítulo II: Mapa del Delito
    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo II: Mapa del Delito - Artículo 54": "El mapa del delito constituye una herramienta de gestión dirigida a la recopilación, procesamiento y análisis de la información concerniente a las actividades delictivas que se desarrollan en el territorio de la Ciudad Autónoma de Buenos Aires.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo II: Mapa del Delito - Artículo 55": "El mapa del delito tiene por finalidad:\n1. Avanzar en la elaboración de un diagnóstico certero de las causas y procesos que confluyen en los hechos delictivos registrados en las distintas Comunas.\n2. Contribuir a la elaboración de estrategias de prevención y conjuración del delito.\n3. Promover un direccionamiento estratégico de los recursos humanos y logísticos de los servicios de seguridad.\n4. Favorecer una respuesta oportuna a los requerimientos de la población en materia de seguridad.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo II: Mapa del Delito - Artículo 56": "Constituyen fuentes del Mapa del Delito:\n1. Los componentes del Sistema Integral de Seguridad Pública mencionados en el artículo 8 de la presente Ley.\n2. Los Ministerios Públicos y Poderes Judiciales de la Nación y provinciales.\n3. El Observatorio Metropolitano de Seguridad Pública del Instituto Superior de Seguridad Pública de la Ciudad.\n4. La Agencia Gubernamental de Control.\n5. La Policía Federal Argentina, la Prefectura Naval, la Gendarmería y la Policía de Seguridad Aeroportuaria.\n6. El Registro Nacional de Reincidencia y el Servicio Penitenciario Nacional.\n7. El Ministerio de Salud de la Ciudad Autónoma de Buenos Aires.\n8. El SAME\n9. Los espacios de participación ciudadana que aborden la temática de seguridad.\n10. Las Universidades Nacionales con asiento en la Ciudad Autónoma de Buenos Aires.\n11. La Dirección General de Estadísticas y Censos de la Ciudad Autónoma de Buenos Aires.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo II: Mapa del Delito - Artículo 57": "Los organismos de la Ciudad Autónoma de Buenos Aires comprendidos en el artículo 56 deben remitir a la autoridad de aplicación toda la información que le solicite en el marco de su competencia, dentro del plazo de quince (15) días hábiles desde la recepción del correspondiente requerimiento. La obstrucción, ocultamiento, falsedad, reticencia o retardo injustificado en el suministro de la información requerida constituye falta grave.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo II: Mapa del Delito - Artículo 58": "La autoridad de aplicación se encuentra facultada a celebrar los convenios de cooperación para recabar información de las restantes instituciones públicas o privadas enumeradas en el artículo 56.",

    " LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES- Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo II: Mapa del Delito - Artículo 59": "El Ministerio de Justicia y Seguridad comunica anualmente a la Legislatura y publica el mapa del delito. Dicho mapa debe ser incorporado en la presentación del presupuesto anual y programa general de gobierno a la Legislatura de la Ciudad Autónoma de Buenos Aires, según establece la Ley 70 (texto consolidado por Ley 5454).",

    "LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo III: Mapa del Delito - Artículo 60": "El SIPREC compone el sistema de gestión de información de seguridad pública y desarrolla técnicas y metodologías que, mediante la participación ciudadana, posibilitan elaborar muestreos poblacionales que proporcionan información cuantitativa aproximada de hechos delictivos y situaciones de violencia y conflicto ocurridos en el territorio de la Ciudad Autónoma de Buenos Aires y sus características.",

    "LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo III: Mapa del Delito - Artículo 61": "El SIPREC recaba información cuantitativa y cualitativa sobre delitos y situaciones de violencia y conflicto ocurridos en el territorio de la Ciudad Autónoma de Buenos Aires, proporcionada directamente por los vecinos, hayan o no puesto en conocimiento del hecho a las fuerzas de seguridad o al Ministerio Público.",

    "LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo III: Mapa del Delito - Artículo 62": "El sistema de información para la prevención comunitaria del delito y la violencia (SIPREC) tiene las siguientes funciones:\n1. Elaborar y mantener actualizadas las estadísticas de victimización, percepción del delito y evaluación del desempeño policial de la Ciudad sobre la base de la información recabada.\n2. Brindar pautas y prioridades para la elaboración de los cuestionarios de las encuestas de victimización, percepción y evaluación.\n3. Realizar en forma anual una encuesta domiciliaria de victimización, percepción y evaluación.\n4. Identificar situaciones conflictivas locales en los barrios de la Ciudad, especialmente aquellas que preocupan en forma prioritaria a la población.\n5. Efectuar estudios comparativos de las estadísticas oficiales de criminalidad con la información recabada y las encuestas anuales de victimización.\n6. Incorporar a la comunidad a las tareas de prevención del delito y la violencia, impulsando la participación en la formulación de propuestas que contribuyan a este fin y dialogando en forma permanente con los foros de seguridad pública (FOSEP), asambleas vecinales, organizaciones no gubernamentales, consejos profesionales, asociaciones civiles y con la ciudadanía en general.",
    
    "LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo IV: Mapa del Delito - Artículo 63": "El Ministerio de Justicia y Seguridad realiza anualmente una encuesta de victimización en el ámbito de la Ciudad Autónoma de Buenos Aires.",

    "LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo IV: Mapa del Delito - Artículo 64": "El Ministerio de Justicia y Seguridad presenta el proyecto de encuesta al Consejo de Seguridad y Prevención del Delito de la Ciudad, para su consideración, en su primera sesión plenaria de cada año. El proyecto debe contener el plan de trabajo para el desarrollo de la encuesta.",

    "LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo IV: Mapa del Delito - Artículo 65": "La encuesta de victimización de la Ciudad Autónoma de Buenos Aires debe tomar en cuenta las recomendaciones establecidas por la Organización de Naciones Unidas, a través de su órgano especial UNICRI (Instituto Interregional de las Naciones Unidas para Investigación sobre Delincuencia y Justicia).",

    "LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo IV: Mapa del Delito - Artículo 66": "La encuesta de victimización puede ser producida con medios y recursos propios del Gobierno, o tercerizada a través de convenios con universidades nacionales con asiento en la Ciudad o organizaciones especializadas.",

    "LIBRO I EL MARCO GENERAL DEL SISTEMA INTEGRAL DE SEGURIDAD PÚBLICA DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES Título X: Mapa del Delito - Sistema de Información para la Prevención del Delito y la Violencia (SIPREC) - Encuesta de Victimización - Capítulo IV: Mapa del Delito - Artículo 67": "El resultado de la encuesta de victimización de la Ciudad Autónoma de Buenos Aires debe ser publicado en la página web de la Ciudad.",

    "LIBRO II LA POLICÍA DE LA CIUDAD DE BUENOS AIRES - CREACIÓN Y DEPENDENCIA FUNCIONAL - TÍTULO I: Generalidades - CAPÍTULO I: Creación y Dependencia Funcional - Artículo 68": "Créase la Policía de la Ciudad de Buenos Aires, que cumple con las funciones de seguridad general, prevención, conjuración, investigación de los delitos, protección y resguardo de personas y bienes, y de auxiliar de la Justicia.",

    "LIBRO II LA POLICÍA DE LA CIUDAD DE BUENOS AIRES - CREACIÓN Y DEPENDENCIA FUNCIONAL  - TÍTULO I: Generalidades - CAPÍTULO I: Creación y Dependencia Funcional - Artículo 69": "La Policía de la Ciudad es una institución civil armada, jerarquizada profesionalmente, depositaria de la fuerza pública del Estado en el ámbito de la Ciudad, con excepción de los lugares sujetos a jurisdicción federal.",

    "LIBRO II LA POLICÍA DE LA CIUDAD DE BUENOS AIRES - CREACIÓN Y DEPENDENCIA FUNCIONAL  - TÍTULO I: Generalidades - CAPÍTULO I: Creación y Dependencia Funcional - Artículo 70": "La Policía de la Ciudad depende jerárquica y funcionalmente del Jefe de Gobierno a través del Ministerio de Justicia y Seguridad. A los fines de cumplimentar los requisitos del artículo 39 de la Ley Nacional Nº 25.877 y las normas conexas de las Leyes Nacionales N° 24.241, 23.660, 23.661, 24.013 y 24.557, el Gobierno de la Ciudad Autónoma de Buenos Aires será considerado empleador del personal de la Policía de la Ciudad, quedando expresamente facultado para inscribirse en dicho carácter ante la Administración Federal de Ingresos Públicos y celebrar los convenios previstos en los Artículos 213 y 418 de la presente Ley. El Ministro de Justicia y Seguridad designa y remueve el personal de la Policía de la Ciudad de Buenos Aires.",

    "LIBRO II LA POLICÍA DE LA CIUDAD DE BUENOS AIRES - CREACIÓN Y DEPENDENCIA FUNCIONAL  - TÍTULO I: Generalidades - CAPÍTULO I: Creación y Dependencia Funcional - Artículo 71": "La Policía de la Ciudad integra el Consejo de Seguridad y Prevención del Delito, en los términos de la Ley 1689.",

    "LIBRO II LA POLICÍA DE LA CIUDAD DE BUENOS AIRES - CREACIÓN Y DEPENDENCIA FUNCIONAL  - TÍTULO I: Generalidades - CAPÍTULO I: Creación y Dependencia Funcional - Artículo 72": "La Policía de la Ciudad coopera dentro de sus facultades con la Justicia Local, la Justicia Federal, y la de las Provincias, para el cumplimiento de sus funciones jurisdiccionales cuando así se le solicitare, conforme la disponibilidad de los recursos presupuestarios asignados.",

    "LIBRO II LA POLICÍA DE LA CIUDAD DE BUENOS AIRES - CREACIÓN Y DEPENDENCIA FUNCIONAL  - TÍTULO I: Generalidades - CAPÍTULO I: Creación y Dependencia Funcional - Artículo 74": "La Policía de la Ciudad adhiere, en los términos del Decreto Nacional N° 684/62, y por intermedio de la Policía Federal Argentina, a la Organización Internacional de Policía Criminal (O.I.P.C. - INTERPOL).",

    "LIBRO II LA POLICÍA DE LA CIUDAD DE BUENOS AIRES - CREACIÓN Y DEPENDENCIA FUNCIONAL  - TÍTULO I: Generalidades - CAPÍTULO II: Principios Rectores - Artículo 75": "La gestión de la Policía de la Ciudad, como integrante del sistema de seguridad, se sujeta a los siguientes principios rectores: [Lista de 11 principios detallados en el artículo 75].",

    "LIBRO II LA POLICÍA DE LA CIUDAD DE BUENOS AIRES - CREACIÓN Y DEPENDENCIA FUNCIONAL  - TÍTULO I: Generalidades - CAPÍTULO III: Organización - Artículo 76": "La conducción de la Policía de la Ciudad está a cargo de un Jefe de Policía, con rango y atribuciones de Subsecretario. En su función el Jefe de Policía es asistido por un Subjefe de Policía. El Jefe de Gobierno designa al Jefe y al Subjefe de la Policía de la Ciudad, a propuesta del Ministro de Justicia y Seguridad.",

    "LIBRO II LA POLICÍA DE LA CIUDAD DE BUENOS AIRES - CREACIÓN Y DEPENDENCIA FUNCIONAL  - TÍTULO I: Generalidades - CAPÍTULO III: Organización - Artículo 77": "El Jefe de Gobierno debe publicar el nombre y antecedentes del candidato para Jefe de la Policía de la Ciudad en el Boletín Oficial de la Ciudad y en el sitio de internet oficial del Gobierno de la Ciudad durante diez (10) días hábiles. Los habitantes de la Ciudad y las organizaciones de la sociedad civil pueden presentar observaciones fundadas a la candidatura durante un plazo de diez (10) días hábiles posteriores al fin de la publicación. Vencido el plazo para la presentación de las observaciones, el Jefe de Gobierno efectúa la designación o reinicia el procedimiento establecido en este artículo.",

    "LIBRO II LA POLICÍA DE LA CIUDAD DE BUENOS AIRES - CREACIÓN Y DEPENDENCIA FUNCIONAL  - TÍTULO I: Generalidades - CAPÍTULO III: Organización - Artículo 78": "Corresponde al Jefe de Policía\n1. Conducir orgánica y funcionalmente la Fuerza, siendo su responsabilidad la organización, prestación y supervisión de los servicios policiales de la ciudad, en el marco de la Constitución, de la presente Ley y de las restantes normas aplicables.\n2. Dictar resoluciones, impartir directivas y órdenes generales o particulares necesarias para el cumplimiento de su misión.\n3. Proponer al Ministro de Justicia y Seguridad la estructura orgánica de las dependencias, organizando los servicios a través del dictado de resoluciones internas.\n4. Proponer al Ministro de Justicia y Seguridad o a quien éste designe, los ascensos ordinarios del personal de Oficiales de Dirección y de Supervisión.\n5. Proponer al Ministro de Justicia y Seguridad o a quien éste designe, los ascensos extraordinarios y menciones especiales por actos destacados del servicio, debiendo acreditarse fehacientemente los méritos.\n6. Proponer la realización de convenios con Fuerzas de Seguridad y Policiales, nacionales y provinciales, y proponer al Ministro de Justicia y Seguridad los relativos a las fuerzas de seguridad y policiales extranjeras con fines de cooperación y reciprocidad.",

    "LIBRO II LA POLICÍA DE LA CIUDAD DE BUENOS AIRES - CREACIÓN Y DEPENDENCIA FUNCIONAL  - TÍTULO I: Generalidades - CAPÍTULO III: Organización - Artículo 79": "Corresponde al Subjefe de Policía acompañar al Jefe en sus funciones y cumplimentar todas aquellas que le sean delegadas, y reemplazarlo en caso de ausencia, enfermedad, muerte, impedimento temporal, renuncia o remoción, con las mismas funciones y atribuciones de aquel.",

    "LIBRO II LA POLICÍA DE LA CIUDAD DE BUENOS AIRES - CREACIÓN Y DEPENDENCIA FUNCIONAL  - TÍTULO I: Generalidades - CAPÍTULO III: Organización - Artículo 80": "El ámbito de actuación territorial y la esfera de actuación funcional de las unidades operacionales de la Policía de la Ciudad, así como su composición, dimensión y despliegue son establecidas por el Ministerio de Justicia y Seguridad, sobre la base de la descentralización territorial prevista en la Ley 1777 # (texto consolidado por Ley 5454).",

    " Título II: De la Actuación Policial - Capítulo I: Principios Básicos de Actuación - Artículo 81": "Las tareas que desarrolla el personal de la Policía de la Ciudad constituyen un servicio público esencial tendiente a la promoción de las libertades y derechos de las personas y, como consecuencia de ello, a su protección ante hechos lesivos de dichas libertades y derechos.",

    " Título II: De la Actuación Policial - Capítulo I: Principios Básicos de Actuación - Artículo 82": "El personal policial debe adecuar su conducta durante el desempeño de sus funciones al cumplimiento, en todo momento, de los deberes legales y reglamentarios vigentes, por medio de una actividad cuyo fin es garantizar la seguridad pública. Actuará con el grado de responsabilidad y ética profesional que su función exige y tendrá como meta la preservación y protección de la libertad, los derechos de las personas y el mantenimiento del orden público.",

    " Título II: De la Actuación Policial - Capítulo I: Principios Básicos de Actuación - Artículo 83": "En la actuación del personal policial tienen plena vigencia los siguientes principios:\n1. El principio de sujeción a la ley, por medio del cual el personal policial debe adecuar sus conductas y prácticas a las normas constitucionales, legales y reglamentarias vigentes así como a los instrumentos internacionales en materia de derechos humanos ratificados por la República Argentina, el Código de Conducta para Funcionarios # encargados de hacer cumplir la Ley y los Principios de las Naciones Unidas sobre el Uso de la Fuerza y Armas de Fuego #.\n2. El principio de oportunidad, según el cual el personal policial cuenta con discrecionalidad conforme a deber para prescindir de la actuación funcional cuando, de acuerdo con las circunstancias del caso, la injerencia resulte inapropiada o inidónea para su fin. La discrecionalidad lleva ínsito el deber de evaluar previamente el riesgo, bajo propia responsabilidad del funcionario actuante.\n3. El principio de proporcionalidad, según el cual toda injerencia en los derechos de las personas debe ser idónea y necesaria para evitar el peligro que se pretende repeler y no puede ser excesiva. Por medida idónea se entiende aquella que sea apta para evitar el peligro; por necesaria, aquella que, entre las medidas idóneas, sea la menos lesiva para el individuo y para la generalidad; por no excesiva, aquella que no implique una lesión desproporcionada respecto del resultado perseguido.\n4. El principio de gradualidad, por medio del cual el personal policial debe privilegiar las tareas y el proceder preventivo y disuasivo antes que el uso efectivo de la fuerza, procurando siempre preservar la vida y la libertad de las personas en resguardo de la seguridad pública. En el uso de armas serán de preferencia las incapacitantes no letales siempre que fuera apropiado, con miras a restringir cada vez más el empleo de medios que puedan ocasionar lesiones o muertes.\n5. El principio de responsabilidad, según el cual el personal policial responde personal y directamente por los hechos que en su actuación profesional realizare en infracción de las disposiciones de esta ley, sin perjuicio de la responsabilidad civil que pueda corresponder a la administración pública.",

    " Título II: De la Actuación Policial - Capítulo I: Principios Básicos de Actuación - Artículo 84": "Durante el desempeño de sus funciones el personal policial debe adecuar su conducta a los siguientes preceptos generales:\n1. Actuar con responsabilidad, respeto a la comunidad, imparcialidad e igualdad en el cumplimiento de la ley.\n2. No infligir, instigar o tolerar ningún acto de tortura u otros tratos crueles, inhumanos o degradantes, ni invocar ilegítimamente la orden de un superior o cualquier tipo de circunstancias especiales o situación de emergencia pública para justificar la comisión de delitos contra la vida, la libertad o la integridad de las personas.\n3. Asegurar la plena protección de la integridad física, psíquica y moral de las personas bajo su cuidado o custodia.\n4. No cometer, instigar o tolerar ningún acto de corrupción que suponga abuso de autoridad o exceso en el desempeño de sus funciones y labores, persiga o no fines lucrativos, o cualquier acto que consista en uso indebido o excesivo de la fuerza, abuso verbal o mera descortesía.\n5. Impedir la violación de normas constitucionales, legales y reglamentarias durante su accionar o el de otras fuerzas, organismos o agencias con la que se desarrollen labores conjuntas o combinadas, o en las conductas de personas físicas o jurídicas, públicas o privadas, con las que se relacione. De la inconducta o del hecho de corrupción deberá dar inmediata noticia a la autoridad superior u organismo de control competente.\n6. Mantener en reserva las cuestiones de carácter confidencial, particularmente las referidas al honor, la vida y los intereses privados de las personas, de que tuvieran conocimiento, a menos que el cumplimiento de sus funciones o las necesidades de la justicia exijan estrictamente lo contrario.",

    " Título II: De la Actuación Policial - Capítulo I: Principios Básicos de Actuación - Artículo 85": "En ningún caso el personal de la Policía de la Ciudad, en el marco de las acciones y actividades propias de sus misiones y funciones, puede:\n1. Inducir a terceros a la comisión de actos delictivos o que afecten a la intimidad y privacidad de las personas.\n2. Influir indebidamente en la situación institucional, política, militar, policial, social y económica del país, en su política exterior, en la vida interna de los partidos políticos legalmente constituidos, en la opinión pública, en personas, en medios de difusión o en asociaciones o agrupaciones legales de cualquier tipo.\n3. Obtener información, producir inteligencia o almacenar datos sobre personas por el solo hecho de su raza, fe religiosa, orientación sexual o identidad de género, acciones privadas u opinión política, o de adhesión o pertenencia a organizaciones partidarias, sociales, sindicales, comunitarias, cooperativas, asistenciales, culturales o laborales, así como por la actividad lícita que desarrollen en cualquier esfera de acción.\n4. Alojar niños y adolescentes, menores de dieciocho años, en comisarías. El Gobierno de la Ciudad de Buenos Aires debe organizar y mantener instituciones específicas y especializadas como dispositivo de alojamiento para personas menores de dieciocho años de edad que resultaren privadas de la libertad por la presunta comisión de delitos. Se establece el plazo de doce (12) horas como límite para el alojamiento de personas menores de edad en dependencias asentadas en la Ciudad Autónoma de Buenos Aires. En todos los casos de detención de niños y adolescentes se dará inmediata intervención al Consejo de los Derechos de Niños, Niñas y Adolescentes de la Ciudad Autónoma de Buenos Aires.\n5. Exponer públicamente la detención de niños y adolescentes.",

    " Título II: De la Actuación Policial - Capítulo I: Principios Básicos de Actuación - Artículo 86": "Las órdenes emanadas de un superior jerárquico se presumen legales. El personal policial no guardará deber de obediencia cuando la orden de servicio impartida sea manifiestamente ilegal o contraria a los derechos humanos, su ejecución configure manifiestamente un delito, o cuando provenga de autoridades no constituidas de acuerdo con los principios y reglas contenidos en la Constitución Nacional y la Constitución de la Ciudad Autónoma de Buenos Aires.\nSi el contenido de la orden de servicio implicase la comisión de una falta disciplinaria, el subordinado debe formular la objeción siempre que la urgencia de la situación lo permita.",

    " Título II: De la Actuación Policial - Capítulo I: Principios Básicos de Actuación - Artículo 87": "El personal policial debe comunicar inmediatamente a la autoridad judicial competente los delitos y contravenciones que llegaren a su conocimiento durante el desempeño de sus funciones.",

    " Título II: De la Actuación Policial - Capítulo I: Principios Básicos de Actuación - Artículo 88": "El deber del personal policial de intervenir para evitar cualquier tipo de situaciones riesgosas o de conflictos que pudieran resultar constitutivos de delitos, contravenciones o faltas, rige durante su horario de servicio ordinario o complementario.\nCuando el personal se encuentre fuera del horario de trabajo y tome conocimiento de situaciones que requieran intervención policial tiene el deber de dar aviso a personal policial en servicio o al servicio de atención telefónica de emergencia. No está obligado a identificarse como tal ni a intervenir, pero si lo hiciera actuará en calidad de órgano del estado y se regirá según las facultades y obligaciones que corresponden al personal en servicio.",

    " Título VII: Transparencia - CAPÍTULO II: Funciones - Artículo 89": "La Policía de la Ciudad conforma su organización y desarrolla sus actividades institucionales en función de la prevención, conjuración e investigación de los delitos. A tales efectos, se define como:\n1. Prevención, a las acciones tendientes a impedir, evitar, obstaculizar o limitar aquellos hechos que, dadas determinadas circunstancias y elementos objetivos y concurrentes, pudieran resultar delictivos o pudieran configurar actos atentatorios de la seguridad pública, así como las acciones consistentes en la planificación, implementación, coordinación o evaluación de las operaciones policiales, en el nivel estratégico y táctico, orientadas a prevenirlos.\n2. Conjuración, a las acciones tendientes a neutralizar, hacer cesar o contrarrestar en forma inmediata los delitos, contravenciones o faltas en ejecución, utilizando cuando sea necesario el poder coercitivo que la ley autorice y evitando consecuencias ulteriores.\n3. Investigación, a las acciones tendientes a conocer y analizar los ilícitos y hechos que vulneran la seguridad pública, sus modalidades y manifestaciones, las circunstancias estructurales y coyunturales en cuyo marco se produjeron, sus factores determinantes y condicionantes, las personas o grupos que lo protagonizaron como autores, instigadores o cómplices y sus consecuencias y efectos institucionales y sociales mediatos e inmediatos. Cuando la investigación se desarrolla en la esfera judicial, comprende la persecución de los delitos y contravenciones consumados a través de las acciones de inteligencia criminal tendientes a constatar su comisión y sus circunstancias de tiempo, lugar y modo de ejecución, individualizar a los responsables y reunir las pruebas para acusarlos.",

    " Título VII: Transparencia - CAPÍTULO II: Funciones - Artículo 90": "Son funciones específicas de la Policía de la Ciudad:\n1. Brindar seguridad a personas y bienes.\n2. Mantener el orden y la seguridad pública.\n3. Implementar mecanismos de disuasión frente a hechos ilícitos o que afecten la seguridad pública.\n4. La Policía de la Ciudad recibe denuncias solamente en caso de flagrancia o cuando sea necesaria su inmediata intervención para evitar las consecuencias del delito, la pérdida de la prueba o la fuga de sus partícipes y, ante el conocimiento de un hecho ilícito, actúa de acuerdo con las normas procesales vigentes.\n5. Auxiliar en materia de seguridad vial de la autoridad de control establecida en el Código de Tránsito y Transporte aprobado por la Ley 2148 # (texto consolidado por Ley 5454).\n6. Intervenir en toda campaña y plan preventivo de seguridad que implemente el Ministerio de Justicia y Seguridad, en los términos que le sea requerido.\n7. Colaborar con las autoridades públicas ante una situación de emergencia.\n8. Coordinar el esfuerzo policial con el resto de los agentes sociales que intervienen en la comunidad.\n9. Mantener una relación de cooperación con la comunidad en la labor preventiva.\n10. Recoger las cosas perdidas y proceder con ellas de acuerdo a las prescripciones del Código Civil y Comercial de la Nación #.\n11. Actuar como auxiliar de la justicia en los casos en que expresamente se le requiera.\n12. Asegurar el orden público y el normal desenvolvimiento durante la realización de actos comiciales nacionales, de la Ciudad o de las Juntas Comunales.\n13. Asistir a las víctimas, tomando en cuenta sus derechos y garantías.\n14. Inspeccionar, cuando fuera necesario, los registros de pasajeros en hoteles y casas de hospedaje.\n15. Asegurar el orden público en ocasión de los eventos deportivos o artísticos masivos.\n16. Coordinar su accionar, en cuanto corresponda, con la Policía Judicial conforme los protocolos de actuación que se establezcan.",

    " Capítulo III: Facultades de Prevención - Artículo 91": "Sin perjuicio de las facultades y obligaciones previstas en otras leyes y reglamentos, el personal policial está facultado para privar de su libertad a las personas cuando, en el desempeño de funciones preventivas, existan indicios que hagan presumir que una persona pudiera relacionarse con la preparación de algún delito de acción pública o contravención, o fuera necesario para evitar un peligro para terceros o para las autoridades y se negara a identificarse o no tuviera ninguna documentación que permita acreditar su identidad.\nLa privación de la libertad debe ser notificada inmediatamente a la autoridad judicial competente y no puede durar más del tiempo estrictamente necesario para su identificación, que no podrá exceder de cuatro horas. Finalizado ese plazo, en todo caso, la persona aprehendida debe ser puesta en libertad o, cuando corresponda, a disposición de la autoridad judicial competente.\nEl procedimiento debe ajustarse a lo previsto por el artículo 153 del Código Procesal Penal de la Ciudad Autónoma de Buenos Aires.",

    " Capítulo III: Facultades de Prevención - Artículo 92": "Cuando, en el desempeño de funciones preventivas, hubiera motivos urgentes que hicieran presumir que una persona porta entre sus efectos personales o adheridas a su cuerpo o en el vehículo en que circula, cosas constitutivas de un delito o que pudieran poner en peligro a terceros o a las autoridades en el marco de un operativo policial, el personal podrá disponer que se efectúen registros personales.\nEn estos actos deberá respetarse el pudor de las personas, que serán requisadas por autoridades del mismo sexo. Previamente, se invitará a las personas a mostrar sus efectos. En caso de negarse se procederá a revisar sus ropas, elementos que porten y vehículos.\nDe lo actuado se labrará acta y se dará inmediata noticia al fiscal. Si se encontraren cosas susceptibles de secuestro, a los fines probatorios o de comiso, quedarán a disposición del fiscal. En el acta deberán constar los motivos que justificaron la actuación.",

    " Capítulo III: Facultades de Prevención - Artículo 93": "Sin perjuicio de las facultades y obligaciones previstas en otras leyes y reglamentos, cuando en el desempeño de funciones preventivas se hallaran cosas relacionadas con un hecho ilícito o que pudieran servir como medios de prueba o pongan en peligro a terceros o a las autoridades en el marco de un operativo policial, el personal policial dispondrá su secuestro, dará inmediata noticia al fiscal y las pondrá a su disposición. De lo actuado se labrará acta en la que deberán constar los motivos que justificaron la actuación.",

    " Capítulo III: Facultades de Prevención - Artículo 94": "El personal policial podrá ingresar a morada o casa de negocio únicamente en los casos en que la demora en recabar la debida autorización judicial implique un grave riesgo para su vida o integridad física, la de los moradores o de un tercero, o cuando ponga en peligro el cumplimiento de un deber de humanidad. De lo actuado se dará inmediata noticia a la autoridad judicial competente.",

    " CAPÍTULO IV: Uso de la Fuerza Directa - Artículo 95": "La regulación sobre el uso de las armas de fuego está sujeta a los Principios Básicos sobre Empleo de la Fuerza y Armas de Fuego por los funcionarios encargados de hacer cumplir la ley aprobada por la Asamblea General de Naciones Unidas y demás normativas internacionales y regionales de derechos humanos en las condiciones de su vigencia. El personal policial debe respetar al usar las armas los principios de proporcionalidad, racionalidad, necesidad y responsabilidad.",

    " CAPÍTULO IV: Uso de la Fuerza Directa - Artículo 96": "Se deben registrar todos los casos en que el personal policial hace uso de armas de fuego y emitir los informes de todos aquellos sucesos en que como consecuencia de este uso resultaren personas fallecidas o lesionadas. Anualmente la Oficina de Transparencia y Control Externo de la Policía de la Ciudad debe realizar un informe en el que se presentan estos hechos y se exponen las medidas adoptadas a fin de controlar y reducir los daños para la vida o la integridad física del personal policial y externo a la institución causado por el uso de las armas de fuego.",

    " CAPÍTULO IV: Uso de la Fuerza Directa - Artículo 97": "Para hacer uso de la fuerza directa, el personal policial deberá identificarse y dar una previa advertencia, salvo cuando ello pusiera en peligro a las personas protegidas o al funcionario del servicio, se creara un riesgo para su vida o la de otras personas, o resultara inadecuado o inútil dadas las circunstancias del caso. La fuerza directa se ejercerá en función del resguardo de la seguridad pública solamente para hacer cesar una situación en que, pese a la advertencia previa u otros medios de persuasión empleados por el funcionario del servicio, se persista en el incumplimiento de la ley o en la inconducta grave. La fuerza directa se utilizará en la medida estrictamente necesaria, idónea para su fin y siempre que no le infligiera al infractor un daño excesivamente superior al que se quiere hacer cesar.",

    " CAPÍTULO IV: Uso de la Fuerza Directa - Artículo 98": "Sólo se podrá hacer uso de armas de fuego cuando otras medidas de fuerza directa no hayan tenido éxito o cuando presumiblemente no lo tendrán. Su empleo contra personas únicamente estará permitido cuando el objetivo no pueda alcanzarse mediante el uso de armas de fuego dirigido contra cosas. El uso de armas de fuego dirigido contra personas sólo estará autorizado con el fin de incapacitarlas para el ataque. No se realizarán disparos con altas probabilidades de tener efectos mortales, salvo cuando sea el único medio para repeler un peligro grave e inminente para la vida. No podrán emplearse armas de fuego contra personas que según su apariencia sean menores de dieciocho años, salvo cuando se trate del único medio para repeler un peligro grave e inminente para la vida. El uso de armas de fuego no estará permitido cuando ponga en peligro a personas que manifiestamente no estén involucradas en la creación del riesgo, salvo cuando se trate del único medio para repeler un peligro grave e inminente para la vida. En todos los casos, el personal policial deberá obrar de modo de reducir al mínimo los posibles daños y lesiones a los infractores y a terceros ajenos a la situación.",

     " CAPÍTULO V: Uso de la Fuerza Directa en Concentraciones Públicas - Artículo 99": "La intervención policial en concentraciones o manifestaciones públicas debe garantizar el respeto y la protección de los derechos de los participantes, así como reducir las afectaciones que la concentración o manifestación cause o pudiere causar en los derechos de las personas que no participan de ella y en los bienes públicos. En el cumplimiento de estos objetivos, el personal policial debe otorgar preeminencia a la protección de la vida y la integridad física de todos los involucrados. No está autorizado a la portación de armas de fuego y municiones de poder letal el personal policial que por su función en el operativo esté destinado a entrar en contacto físico directo con los manifestantes.",

    " CAPÍTULO V: Uso de la Fuerza Directa en Concentraciones Públicas - Artículo 100": "Es obligatorio para todo el personal policial interviniente en manifestaciones públicas portar una identificación clara que pueda advertirse a simple vista en los uniformes correspondientes.",

    " Título III: Personal con Estado Policial de la Policía de la Ciudad - Artículo 101": "El estado policial es la situación jurídica resultante del conjunto de deberes, derechos y obligaciones del personal, tanto en actividad como en situación de retiro, de la Policía de la Ciudad, establecidos por esta Ley y por las demás normas que en su consecuencia se dicten.",

    " Título III: Personal con Estado Policial de la Policía de la Ciudad - Artículo 102": "Los integrantes de la Policía de la Ciudad revisten el carácter de funcionarios públicos y su relación de empleo se rige por la presente Ley.",

    " Título III: Personal con Estado Policial de la Policía de la Ciudad - Artículo 103": "El personal con estado policial está sometido a un régimen de dedicación exclusiva con expresa prohibición de cualquier otra actividad que fuera refutada incompatible, riesgosa o que pueda resultar en desmedro del rendimiento físico o psíquico de sus funciones.",

    " Título III: Personal con Estado Policial de la Policía de la Ciudad - Artículo 104": "El personal con estado policial de la Policía de la Ciudad no puede desarrollar las funciones propias de la gestión administrativa, la dirección de los recursos humanos, la gestión económica, contable, presupuestaria y patrimonial, la gerencia logística e infraestructural no operacional, la asistencia y asesoramiento jurídico-legal, las relaciones institucionales y cualquier otra función de carácter no policial.\nSin perjuicio de ello, en aquellos casos en que el personal con estado policial presente una disminución permanente de su capacidad laborativa, se puede autorizar excepcionalmente y de manera fundada el desarrollo de las tareas indicadas en el párrafo anterior. En este caso, el personal no percibe los suplementos que por la vía reglamentaria se establezcan para retribuir la efectiva prestación de determinados servicios, o aquellos destinados a compensar el riesgo profesional ligados a las actividades propias del estado policial.",

    " Título III: Personal con Estado Policial de la Policía de la Ciudad - Artículo 105": "El Ministro de Justicia y Seguridad otorga el correspondiente estado policial a los oficiales egresados del Instituto Superior de Seguridad Pública.",

    " Título III: Personal con Estado Policial de la Policía de la Ciudad - Artículo 106": "El estado policial se pierde por baja de la Policía de la Ciudad.",

    " Título III: Personal con Estado Policial de la Policía de la Ciudad - Artículo 107": "El Ministerio de Justicia y Seguridad puede establecer el servicio de Policía Complementaria, reglamentar sus condiciones, organizar su prestación y fijar su precio.\nLa organización del servicio de Policía Complementaria se efectúa en exclusivo interés de los particulares que lo contraten en las condiciones que establece la reglamentación, y en ningún caso puede implicar una disminución, menoscabo o afectación de cualquier índole del servicio público de seguridad brindado por la Policía de la Ciudad.\nLa asignación de los servicios complementarios se efectúa priorizando aquellos servicios particulares que, por su naturaleza y características de prestación, coadyuven al interés público, tales como eventos públicos masivos, eventos deportivos, seguridad bancaria, seguridad en medios de transporte público y todos aquellos que la autoridad de aplicación defina como tales.\nCréase el Fondo Especial del Servicio de Policía Complementaria, que se integra con los recursos que se obtengan por la prestación de los servicios de Policía Complementaria a terceros y por las transferencias de crédito que retribuyan la prestación de este servicio a otros órganos o entes del Gobierno de la Ciudad de Buenos Aires o a las Comunas de la Ciudad.\nLos recursos del Fondo Especial de Policía Complementaria se dedican a financiar la prestación del servicio y, en caso de existir un excedente, a la adquisición de los bienes destinados a la prestación del servicio público de seguridad que el Ministerio de Justicia y Seguridad determine.",

    "Artículo 108": "El estado policial confiere los siguientes derechos esenciales:\n1. La percepción de los sueldos, suplementos y demás asignaciones que las disposiciones legales determinen para cada grado, cargo y situación de revista.\n2. La jerarquía y el uso del grado correspondiente, con los alcances establecidos en la presente Ley y su reglamentación.\n3. El uso del armamento provisto por la Institución, del uniforme, insignias, atributos y distintivos propios del grado, antigüedad, especialidad y función de acuerdo a las disposiciones reglamentarias pertinentes.\n4. La capacitación permanente para la mejora del desarrollo de sus funciones y labores policiales.\n5. La estabilidad en el empleo de acuerdo a lo establecido en esta Ley y sus normas reglamentarias.\n6. El desarrollo de la carrera profesional en igualdad de oportunidades.\n7. Los ascensos, conforme a las normas de la reglamentación correspondiente.\n8. El servicio médico-asistencial y social para sí, y los familiares a cargo, conforme a las normas legales y reglamentarias vigentes.\n9. La percepción del haber de retiro para sí y de pensión para sus derechohabientes, conforme a las disposiciones legales sobre la materia.",
    
    "Artículo 109": "El estado policial impone los siguientes deberes y obligaciones esenciales:\n1. Adecuar su conducta pública y privada a las normas éticas acordes al estado policial y su calidad de funcionario público.\n2. Desempeñar su función de acuerdo con las leyes y reglamentaciones vigentes y cumplir con los principios básicos de actuación previstos en esta Ley y sus normas complementarias.\n3. Prestar eficientemente el servicio policial en las condiciones de tiempo, forma, lugar y modalidad determinados por la autoridad competente.\n4. Obedecer toda disposición u orden emanada del superior jerárquico competente que reúna las formalidades del caso y tenga por objeto la realización de actos de servicio con los límites establecidos en esta Ley, en la Constitución Nacional y en la Constitución de la Ciudad Autónoma de Buenos Aires.\n5. Aceptar el grado, distinciones o títulos concedidos por autoridad competente y de acuerdo con las disposiciones vigentes.\n6. Ejercer las facultades de mando y disciplinarias que para el grado y cargo establece la reglamentación correspondiente.\n7. Presentar y actualizar la declaración jurada de sus bienes y las modificaciones que se produzcan en su situación patrimonial y en la de su cónyuge, con la periodicidad y requisitos que establezca la normativa vigente en la materia.\n8. Desempeñar los cargos, funciones y comisiones del servicio dispuestas por la superioridad o autoridad competente.\n9. Asistir a las actividades de capacitación, actualización, entrenamiento y especialización que establezca el Instituto Superior de Seguridad Pública.\n10. Guardar secreto, aún después del retiro o baja de la Institución, en todo cuanto se relacione con los asuntos del servicio que por su naturaleza o en virtud de disposiciones especiales impongan esa conducta, salvo requerimiento judicial.\n11. En caso de baja voluntaria seguir desempeñando las funciones correspondientes hasta el término de treinta (30) días, si antes no fuera reemplazado o aceptada su dimisión.\n12. Someterse a la realización de los estudios y exámenes psicofísicos establecidos en la reglamentación correspondiente.\n13. Cuidar y mantener en buen estado de uso y aprovechamiento los bienes provistos para el desempeño de la labor policial.\n14. Cumplir con el régimen disciplinario previsto en la presente Ley y su reglamentación cualesquiera fuere su situación de revista.\n15. Peticionar y realizar las tramitaciones pertinentes siguiendo la vía jerárquica correspondiente.\n16. Comparecer en las actuaciones o sumarios administrativos en carácter de testigo.",
    
    "Artículo 110": "El estado policial acarrea las siguientes prohibiciones:\n1. Participar en actividades políticas, partidarias, gremiales o sectoriales, o el desempeño de cargos electivos, mientras se encuentre en actividad.\n2. Patrocinar trámites o gestiones administrativas o judiciales referentes a asuntos de terceros vinculados con la institución.\n3. Desempeñar otros cargos, funciones o empleos, en el ámbito público o privado, remunerados o no, excepto el ejercicio de la docencia en la forma que lo establezca la reglamentación, mientras permanezca en el servicio efectivo.\n4. Dirigir, administrar, representar, patrocinar, asesorar, o de cualquier otra forma prestar servicios a quien gestione o tenga una concesión o sea proveedor del Estado, o realice actividades reguladas por éste.\n5. Realizar por sí o por cuenta de terceros gestiones tendientes a obtener el otorgamiento de una concesión o adjudicación en la Administración Pública centralizada o descentralizada de la Ciudad Autónoma de Buenos Aires.\n6. Representar o patrocinar a litigantes o intervenir en gestiones judiciales o extrajudiciales contra la Ciudad Autónoma de Buenos Aires, salvo en causa propia.",
    
    "Artículo 111": "El personal en situación de retiro está sujeto a los siguientes derechos y obligaciones:\n1. Tiene los deberes y derechos del personal en actividad con las limitaciones propias de su situación que establezca la reglamentación.\n2. Está sujeto al régimen disciplinario con el grado, título y distinciones con que hubiere pasado a retiro, y en las condiciones que establezca la reglamentación.\n3. El personal retirado puede ser convocado a prestar servicio activo por resolución fundada del Ministro de Justicia y Seguridad cuando situaciones excepcionales lo ameriten. La reglamentación establece los recaudos y alcances que debe contener el llamado. En todos los casos la convocatoria reviste el carácter de obligatoria para quien fuere llamado.\n4. El personal convocado no acumula años de servicios ni evoluciona en la carrera salvo situación extraordinaria dispuesta por decreto del Jefe de Gobierno de la Ciudad Autónoma de Buenos Aires.\n5. No tiene facultades disciplinarias excepto que desempeñe funciones policiales conforme lo dispuesto en el inciso 3 del presente artículo. En ese caso, las tendrá exclusivamente respecto del personal que preste servicios directamente a sus órdenes.\n6. Debe concurrir al mantenimiento del orden público, la seguridad, la prevención y la conjuración del delito. Los actos cumplidos en virtud de este deber legal son considerados para todos sus efectos como ejercidos por personal en actividad.\n7. Puede ocupar cargos públicos y desempeñar funciones privadas compatibles con el decoro y la jerarquía policial, según lo prescriba la reglamentación.\n8. Puede hacer uso del uniforme, credencial y armas en la forma que determine esta Ley y su reglamentación.\n9. No puede hacer uso de su grado, uniforme, distintivos, arma u otros atributos propios de su jerarquía en actividades comerciales, políticas o manifestaciones públicas de cualquier índole, salvo que lo autorice expresamente la reglamentación vigente.",

    "Artículo 112": "El personal con estado policial de la Policía de la Ciudad de Buenos Aires adquiere estabilidad en el empleo después de transcurridos doce (12) meses de efectiva prestación de servicios como Oficial de la institución y una vez que hubiere aprobado las evaluaciones de rendimiento y aptitud que determine la reglamentación. Durante el tiempo en que el personal carezca de estabilidad tiene todos los derechos y deberes previstos en esta Ley y dicho lapso debe ser computado para la antigüedad en la carrera profesional.",
    
    "Artículo 113": "La estabilidad en el empleo no comprende a la estabilidad en el cargo o función ni da derecho a continuar gozando de los suplementos inherentes al mismo.",
    
    "Artículo 114": "La estabilidad en el empleo del personal con estado policial sólo se pierde por la baja justificada por las causales establecidas en la presente Ley, las normas reglamentarias, y previo sumario administrativo, si correspondiese.",

"Artículo 115": "La jerarquía es el orden que determina las relaciones de superioridad y dependencia. Se establece por grados. Grado es la denominación de cada uno de los niveles de la jerarquía. La escala jerárquica es el conjunto de los grados ordenados y clasificados. Superioridad policial es la que tiene un policía respecto a otro por razones del cargo, de jerarquía o de antigüedad.",
    
    "Artículo 116": "El ejercicio de la superioridad consiste en el ejercicio del mando a través de la emisión de una orden de servicio legal y legítima de parte de un superior y su cumplimiento estricto por un subordinado durante el desarrollo de las funciones propias del servicio y de acuerdo con las prescripciones y los límites establecidos por la Constitución Nacional, la Constitución de la Ciudad Autónoma de Buenos Aires, la presente Ley y por las normas reglamentarias.",
    
    "Artículo 117": "El ejercicio de la superioridad puede tener cuatro modalidades diferenciadas:\n1. La superioridad jerárquica, que es la que se ejerce sobre otro como consecuencia de la posesión de un grado superior en la escala jerárquica.\n2. La superioridad por antigüedad es la que, a igual grado, se determina, sucesivamente, por antigüedad en el grado, por la antigüedad general, por la fecha de ascenso al grado inmediato anterior y por la edad.\n3. La superioridad orgánica, que es la que se ejerce sobre otro como consecuencia de la ocupación de un cargo de la estructura orgánica con funciones de dirección o conducción, independientemente de su grado.\n4. La superioridad funcional, que es la que se ejerce sobre otro durante el desarrollo de una misión, operación o actividad concreta y específica, ordenada por un superior y en la que se asigna responsabilidades y atribuciones precisas de mando a un efectivo que tiene un grado o un cargo igual o inferior al de los demás integrantes de la misión, operación o actividad, siempre que medien razones de servicio que así lo justifiquen.",
    
    "Artículo 118": "Para el personal del mismo grado, y sin tener en cuenta la antigüedad, se establece el siguiente orden de precedencia:\n1. Personal en situación de actividad.\n2. Personal en situación de retiro llamado a prestar servicios.\n3. Personal en situación de retiro.",

     " Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo V: Escala Jerárquica y Grados - Artículo 119": "La Policía de la Ciudad cuenta con un escalafón único denominado Escalafón General Policial.",
    
    " Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo V: Escala Jerárquica y Grados - Artículo 120": "La escala jerárquica reconoce cuatro categorías:\n1. El Cuadro de Oficiales Superiores.\n2. El Cuadro de Oficiales de Dirección.\n3. El Cuadro de Oficiales de Supervisión.\n4. El Cuadro de Oficiales Operativos.",
    
    " Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo V: Escala Jerárquica y Grados - Artículo 121": "El Escalafón General Policial cuenta con los siguientes grados en orden decreciente:\n1. Superintendente\n2. Comisionado General\n3. Comisionado Mayor\n4. Comisario\n5. Subcomisario\n6. Inspector Principal\n7. Inspector\n8. Oficial Mayor\n9. Oficial Primero\n10. Oficial.",
    
    " Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo V: Escala Jerárquica y Grados - Artículo 122": "El Cuadro de oficiales Superiores está integrado por el personal con estado policial que alcance los grados de Superintendente y Comisionado General.\nEl Cuadro de oficiales de Dirección está integrado por el personal con estado policial que alcance los grados de Comisionado Mayor, Comisario y Subcomisario.\nEl Cuadro de oficiales de Supervisión está integrado por el personal con estado policial que alcance los grados de Inspector Principal e Inspector.\nEl Cuadro de oficiales Operativos está integrado por el personal con estado policial que alcance los grados de Oficial Mayor, Oficial Primero y Oficial.",

    " Capítulo VI: Especialidades - Artículo 123": "El Escalafón General Policial cuenta con cuatro especialidades en las cuales revista el personal con estado policial de la Policía de la Ciudad:\n1. Seguridad\n2. Investigaciones\n3. Policía Científica\n4. Tecnologías de la Información y Comunicaciones\nEl Ministro de Justicia y Seguridad puede, por resolución fundada, incrementar, fraccionar o eliminar las especialidades enunciadas.",
    
    " Capítulo VI: Especialidades - Artículo 124": "La especialidad Seguridad está conformada por el personal con estado policial abocado exclusivamente al desarrollo de las actividades y acciones propias de las funciones de seguridad.",
    
    " Capítulo VI: Especialidades - Artículo 125": "La especialidad Investigaciones está conformada por el personal con estado policial abocado exclusivamente al desarrollo de las actividades y acciones propias de las funciones de investigación.",
    
    " Capítulo VI: Especialidades - Artículo 126": "La especialidad Policía Científica está conformada por el personal con estado policial abocado exclusivamente al desarrollo de las actividades y acciones propias de las funciones de policía científica.",
    
    " Capítulo VI: Especialidades - Artículo 127": "La especialidad Tecnologías de la Información y Comunicaciones está conformada por el personal con estado policial abocado exclusivamente al desarrollo de las actividades y acciones propias de las funciones de Tecnologías de la Información y Comunicaciones.",

    " Capítulo VII: Ingreso, Requisitos e Impedimentos - Artículo 128": "Son requisitos para ser miembro de la Policía de la Ciudad:\n1. Ser ciudadano argentino nativo o por opción.\n2. Tener, al momento de ingreso, entre 18 y 30 años de edad.\n3. Tener estudios secundarios completos.\n4. Acreditar aptitud psicofísica compatible con la función y tarea a desarrollar.\n5. Declarar bajo juramento cumplir y hacer cumplir la Constitución Nacional # y la Constitución de la Ciudad Autónoma de Buenos Aires #.\n6. Acreditar una conducta pública adecuada al ejercicio de la función pública y a la función específica que reglamenta la presente Ley.\n7. Aprobar los programas y requisitos de formación y capacitación que establezca el Instituto Superior de Seguridad Pública.\n8. Residir dentro del radio de 80 kilómetros de la Ciudad de Buenos Aires.\n9. Cumplir con las condiciones fijadas por la presente Ley y sus normas reglamentarias.",
    
    " Capítulo VII: Ingreso, Requisitos e Impedimentos - Artículo 129": "Podrá ingresar a la Policía de la Ciudad, personal que acredite experiencia anterior en otras fuerzas de seguridad o armadas, con estado policial o militar, siempre que hubiese obtenido la baja en su fuerza de origen. Este personal está eximido del requisito establecido en el inciso 2 del artículo 128, exclusivamente. La reglamentación establece los requisitos mínimos de edad e idoneidad que deba cumplir.",
    
    " Capítulo VII: Ingreso, Requisitos e Impedimentos - Artículo 130": "No pueden desempeñarse como miembros de la Policía de la Ciudad las siguientes personas:\n1. Quienes hayan sido condenados o se encuentren procesados o con auto de citación a juicio o acto procesal equivalente por incurrir en actos de fuerza contra el orden institucional y el sistema democrático, aun cuando se hubieren beneficiado por un indulto, amnistía o condonación de la pena.\n2. Quienes hayan sido condenados o se encuentren procesados o con auto de citación a juicio o acto procesal equivalente por violación a los derechos humanos.\n3. Quienes hayan sido condenados, o se encuentren procesados o con auto de citación a juicio o acto procesal equivalente por delito doloso de cualquier índole.\n4. Quienes se encuentren inhabilitados para el ejercicio de cargos públicos.\n5. Quienes hayan sido sancionados con exoneración o cesantía en la Administración Pública Nacional, provincial, municipal o de la Ciudad Autónoma de Buenos Aires, o en las fuerzas policiales o de seguridad federales o provinciales u organismos de inteligencia.\n6. Quienes se encontraren incluidos en otras inhabilitaciones propias de la Policía de la Ciudad de acuerdo a lo que establezca la reglamentación.",

    " Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo VIII: Carrera Profesional - Artículo 131": "El régimen de carrera profesional del personal con estado policial se basa en los principios de profesionalización, eficiencia funcional, capacitación permanente y evaluación previa a cada ascenso, atendiendo a la satisfacción plena de las acciones tendientes a resguardar y garantizar la seguridad pública.",

    " Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo VIII: Carrera Profesional - Artículo 132": "El nivel académico exigido para el ascenso a cada cuadro se determina de acuerdo con el siguiente esquema:\nCuadro Mínimo nivel académico exigible\nOficiales Superiores Título de Grado\nOficiales de Dirección Título de Grado\nOficiales de Supervisión Título Terciario\nOficiales Operativos Título Secundario\nLos niveles académicos se acreditan con títulos oficiales.",

    " Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo VIII: Carrera Profesional - Artículo 133": "Los requisitos y exigencias profesionales para que el personal con estado policial de la Policía de la Ciudad se incorpore a cada especialidad son establecidos en la reglamentación.",

    " Título VI: Sistema de Participación Ciudadana en la Gestión de la Seguridad Pública - Capítulo VIII: Carrera Profesional - Artículo 134": "La incorporación y el desarrollo de la carrera profesional del personal en cada especialidad debe resultar de su opción vocacional así como también de la formación y capacitación que reciba, del desempeño profesional durante el ejercicio de sus funciones y las necesidades de la institución policial. Debe priorizarse la especialización del personal y evitarse los cambios de especialidad.\nSin perjuicio de ello, el personal con estado policial que cumpliere servicios en una de las especialidades previstas en la presente Ley puede continuar su carrera profesional en otra especialidad siempre que reúna los requisitos exigidos para ello y cumpla con las condiciones de aptitud y evaluación exigidas de acuerdo con la reglamentación.",
    // Agrega los nuevos artículos
    " Título X: Designación de Cargos - Artículo 135": "La ocupación de los cargos orgánicos de la Policía de la Ciudad es resuelta de acuerdo con el mérito y los antecedentes de los candidatos y siguiendo los mecanismos de selección que se implementen a través de la reglamentación, los cuales deben regirse por los siguientes criterios: 1. La formación y capacitación profesional. 2. El desempeño de la carrera profesional. 3. Los antecedentes funcionales y disciplinarios. La reglamentación determina los grados, el perfil profesional y las destrezas o formación profesionales para la ocupación de cada cargo orgánico.",
    
    " Título X: Designación de Cargos - Artículo 136": "Los ascensos y promociones del personal con estado policial correspondientes a los Cuadros de Oficiales Superiores, de Dirección y de Supervisión son dispuestos por el Ministro de Justicia y Seguridad o por el funcionario en quien éste delegue la competencia. Los ascensos y promociones de los Oficiales Operativos son dispuestos por el Jefe de Policía. El Ministro de Justicia y Seguridad debe publicar la lista de los candidatos para el ascenso al Cuadro de Oficiales Superiores en el Boletín Oficial de la Ciudad y en el sitio de Internet del Gobierno de la Ciudad durante diez (10) días, incluyendo los nombres y los antecedentes curriculares de las personas propuestas. Vencido el plazo establecido en el párrafo anterior, el Ministro de Justicia y Seguridad procede a dictar el acto administrativo correspondiente.",
    
    " Título X: Designación de Cargos - Artículo 137": "El ascenso se otorga siempre al grado inmediato superior. El ascenso puede tener carácter de ordinario o extraordinario y a quien le es otorgado le crea la obligación de prestar servicio efectivo durante un (1) año como mínimo, de acuerdo con lo que determine la reglamentación.",
    
    " Título X: Designación de Cargos - Artículo 138": "El ascenso ordinario se confiere anualmente para satisfacer las necesidades orgánicas de la institución y abarca al personal que haya cumplido las exigencias establecidas en esta Ley y su reglamentación.",
    
    " Título X: Designación de Cargos - Artículo 139": "El ascenso extraordinario puede producirse por las siguientes causas: 1. Actos destacados del servicio cuyo mérito se acredite fehaciente y comprobadamente. 2. Por pérdida grave de las aptitudes físicas o psíquicas o por fallecimiento a causa de un acto de los contemplados en el inciso 1.",
    
    " Título X: Designación de Cargos - Artículo 140": "Los ascensos extraordinarios son concedidos por el Ministro de Justicia y Seguridad, a propuesta del Jefe de Policía.",
    
    " Título X: Designación de Cargos - Artículo 141": "La calificación de las aptitudes del personal que se deba considerar, tanto para el ascenso como para la eliminación, está a cargo de las Juntas de Calificaciones, que se integran en el modo y oportunidad en que determine la reglamentación, la cual debe prever su conformación con personal policial, funcionarios designados por el Ministro de Justicia y Seguridad y representantes del Instituto Superior de Seguridad Pública. Las Juntas de Calificaciones son órganos de asesoramiento del Ministro de Justicia y Seguridad y del Jefe de la Policía, quienes resuelven sobre el particular.",
    
    " Título X: Designación de Cargos - Artículo 142": "Para los ascensos ordinarios, la reglamentación establece el régimen de calificaciones del personal, los tiempos mínimos de permanencia en el grado, el régimen de promociones y las condiciones de aptitud y formalidades para los ascensos y promociones. Asimismo la reglamentación debe prever mecanismos que habiliten la publicidad y el acceso a la información de los actos administrativos que dispongan los ascensos y promociones en la institución.",
    
    " Título X: Designación de Cargos - Artículo 143": "La reglamentación establece los mecanismos de la promoción y ascenso a un grado superior dentro de la carrera profesional, la que debe ajustarse a los siguientes requisitos: 1. La disponibilidad de vacantes en el grado al que se aspira. 2. La acreditación de los conocimientos profesionales y títulos oficiales requeridos para el desempeño de las funciones o los cargos orgánicos correspondientes al grado a cubrir. 3. La aprobación de los cursos de ascenso o nivelación. 4. La declaración de aptitud profesional establecida por un comité de evaluación. 5. El tiempo mínimo de permanencia en el grado. 6. La acreditación de las condiciones psicofísicas necesarias.",
    
    " Título X: Designación de Cargos - Artículo 144": "Sin perjuicio de lo que se establezca en la reglamentación respectiva son causales de inhabilitación para el ascenso y promoción: 1. Hallarse bajo sumario judicial con auto de procesamiento, auto de elevación a juicio o acto procesal equivalente. 2. Hallarse bajo sumario administrativo por falta grave hasta su resolución.",

 " CAPÍTULO XI: Formación y Capacitación - Artículo 145": "La formación y capacitación permanente del personal con estado policial de la Policía de la Ciudad es competencia del Instituto Superior de Seguridad Pública, conforme las disposiciones pertinentes de la presente Ley.",
    
    " CAPÍTULO XI: Formación y Capacitación - Artículo 146": "La formación y capacitación del personal policial debe garantizar:\n1. El desarrollo de las aptitudes y valores necesarios para el ejercicio responsable de las funciones y labores asignadas, con conciencia ética, solidaria, reflexiva y crítica.\n2. La propensión a un aprovechamiento integral de los recursos humanos y materiales existentes y asignados.\n3. El incremento y diversificación de las oportunidades de actualización y perfeccionamiento del personal con estado policial.\n4. El logro de la formación y capacitación especializada, científica y técnica general, procurando siempre su contenido humanístico, sociológico y ético.",
    
    " CAPÍTULO XII: Cursos de Ascenso - Artículo 147": "El Instituto Superior de Seguridad Pública imparte los cursos de ascenso mencionados en el inciso 3 del Artículo 143 y toma las evaluaciones correspondientes.",
    
    " CAPÍTULO XII: Cursos de Ascenso - Artículo 148": "Los cursos de ascenso son diferenciados de acuerdo con la jerarquía y la especialidad de los cursantes.",
    
    " CAPÍTULO XIII: Evaluación Permanente - Artículo 149": "Todo el personal con estado policial en actividad que se encuentre en servicio efectivo de la Policía de la Ciudad debe cumplir obligatoriamente una instancia de evaluación en el Instituto Superior de Seguridad Pública.",
    
    " CAPÍTULO XIII: Evaluación Permanente - Artículo 150": "La periodicidad de la evaluación, las competencias a evaluar, los contenidos, los estándares mínimos a aprobar según jerarquía, el régimen de evaluación y demás aspectos necesarios para llevarla a cabo, son determinados por el Instituto Superior de Seguridad Pública.",

" Capítulo XIV: Formación de Cadetes - Artículo 151": "Los aspirantes a Oficial de la Policía de la Ciudad se denominan Cadetes. Deben cursar y aprobar el curso de formación inicial que dicta el Instituto Superior de Seguridad Pública. Los cadetes no tienen estado policial durante su formación inicial y son becarios.",
    
    " Capítulo XIV: Formación de Cadetes - Artículo 152": "El Instituto Superior de Seguridad Pública determina los requisitos para el ingreso como cadete, los núcleos de formación, la duración del curso, el régimen de cursada, el contenido del diseño curricular, el régimen de asistencia y de evaluación, el régimen de equivalencias con otros estudios superiores, el régimen de prácticas profesionalizantes, las actividades extracurriculares y de extensión y los demás aspectos que hacen a la formación de los futuros Oficiales.",

     "Artículo 153": "Las situaciones de revista del personal con estado policial son:\n1. Actividad: es aquella que impone la obligación de desempeñar funciones policiales, en el destino o comisión que disponga la superioridad.\n2. Retiro: es aquella en la cual, sin perder su grado ni estado policial, el personal cesa en el cumplimiento de funciones con carácter voluntario u obligatorio, excepto que sea llamado a prestar servicio activo.",
    
    "Artículo 154": "El personal con estado policial que revista en actividad puede hallarse en las siguientes situaciones:\n1. Servicio efectivo.\n2. Disponibilidad.\n3. Pasiva.",
    
    "Artículo 155": "El personal con estado policial revista en servicio efectivo cuando se encuentre:\n1. Prestando servicios en la Policía de la Ciudad y desempeñe funciones propias de su grado o cumpla comisiones afines al servicio policial u otras de interés institucional\n2. En uso de las licencias establecidas en el Artículo 160, excepto expresa previsión en contrario en esta Ley o en la reglamentación. El tiempo cumplido en servicio efectivo es computado siempre a los fines del ascenso y retiro, excepto en el llamado a prestar servicios.",
    
    "Artículo 156": "El personal con estado policial revista en disponibilidad cuando permanece separado de las funciones y tareas ordinarias que le corresponderían por su grado, en los siguientes casos:\n1. Por un período de hasta un (1) año a la espera de asignación de destino. Cumplido ese lapso debe asignársele destino o ser sometido a junta de calificación. De ser considerado en aptitud, debe asignársele destino.\n2. Con licencia por enfermedad o accidente desvinculado del servicio, a partir de los seis (6) meses y hasta doce (12) meses como máximo.\n3. Cuando tramitando el retiro voluntario, solicitare conjuntamente el pasaje a esta situación, desde el momento que lo determine el Jefe de la Policía de la Ciudad.\n4. El sumariado administrativamente por causas moderadas o graves si lo dispone la autoridad policial competente por sí, o a solicitud de la Oficina de Transparencia y Control Externo, hasta tanto se dicte la resolución definitiva, pudiéndose dejar sin efecto en el transcurso del procedimiento.\n5. En uso de la licencia por estudio o investigaciones científicas, técnicas o culturales cuando la actividad tenga relación con el servicio.\n6. Detenido o con prisión preventiva por hecho vinculado al servicio si no se le imputa la comisión de un delito doloso o que por sus características afecte el prestigio institucional. Esta última circunstancia es establecida por resolución fundada del Ministro de Justicia y Seguridad.\n7. Cuando se encuentre en la situación prevista en el segundo párrafo del Artículo 104.\n8. Con asignación de tareas adecuadas a su condición de incapacidad laboral transitoria, conforme lo dispuesto en el Artículo 158 de la presente. El personal que revista en disponibilidad no porta el armamento provisto por la institución y percibe los haberes determinados en el artículo 184. El tiempo cumplido en disponibilidad no es computado a los fines del ascenso y solo computa a los fines del retiro.",
    
    "Artículo 157": "El personal con estado policial revista en servicio pasivo cuando no desempeñe cargo o función alguna, en las siguientes situaciones:\n1. En uso de licencia por enfermedad de tratamiento prolongado, desde los doce (12) meses y hasta un máximo de veinticuatro (24) meses. Vencido este plazo, en caso de no reintegrarse al servicio efectivo debe pasar a retiro o baja definitiva, según corresponda.\n2. El sometido a sumario administrativo por abandono del servicio, hasta la conclusión del procedimiento.\n3. Con prisión preventiva por hecho vinculado al servicio, cuando se le impute la comisión de un delito doloso, por el tiempo que dure la privación de la libertad a cuya finalización se determina de acuerdo a su responsabilidad, la situación de revista del causante, salvo que con anterioridad se dispusiese la cesantía o exoneración.\n4. Detenido o con prisión preventiva por hecho ajeno al servicio, por el tiempo que dure la privación de la libertad a cuya finalización se determina de acuerdo a su responsabilidad, la situación de revista del causante, salvo que con anterioridad se dispusiese la cesantía o exoneración.\n5. Detenido o sometido a proceso judicial, cuando el hecho que dio motivo a la medida revele grave indignidad o afectare manifiestamente al prestigio de la Institución, mientras se sustancie la causa disciplinaria emergente.\n6. Condenado, si por el carácter y duración de la pena o naturaleza del hecho no procede su separación, mientras dure el impedimento.\n7. El personal policial respecto del cual se haya solicitado su cesantía o exoneración, hasta que se dicte la resolución definitiva.\n8. En uso de las licencias previstas en el primer párrafo del artículo 182 o de la licencia por estudio o investigaciones científicas, técnicas o culturales cuando la actividad no tenga relación con el servicio. El tiempo pasado en situación pasiva no se computa para el ascenso ni para el retiro, salvo el personal que haya revistado en esa situación por detención o proceso y fuera absuelto o sobreseído en la causa que lo motivara, en cuyo caso ese tiempo se computará sólo a los fines del retiro. En el supuesto del inciso 1 el tiempo pasado en pasiva computa a los efectos de la antigüedad. El personal que revista en pasiva no porta el armamento provisto por la institución y percibe, de acuerdo al caso, los haberes determinados en el artículo 185.",
    
    "Artículo 158": "El personal con estado policial de la Policía de la Ciudad puede ser relevado transitoriamente de la obligación de prestar el servicio propio de su grado, asignándosele tareas adecuadas a su condición, conforme los siguientes requisitos:\n1. La asignación debe responder a una incapacidad laboral transitoria, originada en una afección transitoria determinada por la junta médica o por el servicio de medicina laboral de la Policía de la Ciudad.\n2. Las tareas adecuadas pueden desempeñarse por un plazo máximo de dos (2) años en forma continua o discontinua, por la misma o distinta patología. Vencido el plazo de dos (2) años, la Junta Médica resuelve si debe reintegrarse al servicio normal o pasar a retiro o baja obligatoria si no pudiese acceder al beneficio previsional.\n3. Agotado el plazo de dos (2) años y reintegrado el causante a sus funciones, no puede volver a hacer uso de este beneficio hasta después de transcurridos cinco (5) años y nunca mientras permanezca en el mismo grado. Caso contrario, previa intervención de la Junta Médica, pasa a situación de retiro o baja obligatoria.\n4. El personal con asignación de tareas adecuadas es considerado en disponibilidad y percibe los haberes determinados en el artículo 184.\n5. Las mujeres embarazadas tienen derecho a solicitar la asignación de tareas adecuadas durante el período del embarazo. Revistan en servicio efectivo y perciben la totalidad de los haberes y suplementos que les hubiesen correspondido en el mes inmediato anterior al inicio de las tareas adecuadas.",
    
    "Artículo 159": "El personal con estado policial usa obligatoriamente el uniforme reglamentario y su debida identificación en todos los actos de servicio, salvo en los casos de excepción que, por autorización expresa, realice la superioridad o exista orden emanada de autoridad judicial.",

    " Capítulo XVI: Licencias - Artículo 160": "El personal de la Policía de la Ciudad tiene derecho al uso de las siguientes licencias:\n1. Licencia anual ordinaria\n2. Licencia por enfermedad común o de tratamiento breve\n3. Licencia por enfermedad de tratamiento prolongado\n4. Licencia por accidente de trabajo o enfermedad profesional\n5. Licencia por maternidad\n6. Licencia para alimentación y cuidado del hijo\n7. Licencia por nacimiento de hijo/a\n8. Licencia por pérdida de gestación\n9. Licencia por adopción\n10. Licencia por hijo/a discapacitado/a\n11. Licencia por matrimonio o unión civil\n12. Licencia por exámenes\n13. Licencia por investigaciones científicas, técnicas o culturales\n14. Licencia por fallecimiento de familiar\n15. Licencia por enfermedad de un familiar a cargo\n16. Licencia por donación de sangre\n17. Licencia por asuntos de servicio\n18. Licencia por estímulo\n19. Licencia por adaptación escolar de hijo\n20. Licencia para controles periódicos de prevención\n21. Licencia por violencia de género.",
    
    " Capítulo XVI: Licencias - Artículo 161": "La licencia anual ordinaria tiene por finalidad permitir el descanso periódico del personal y, en todos los casos, es de utilización obligatoria y con goce de haberes, de acuerdo a la siguiente escala:\n1. Hasta cinco (5) años de antigüedad, corresponden quince (15) días hábiles.\n2. Hasta diez (10) años de antigüedad, corresponden veintiún (21) días hábiles.\n3. Más de diez (10) años de antigüedad, corresponden treinta (30) días hábiles.\nLa licencia anual ordinaria se computa por año calendario. El personal ingresante o reingresante que al inicio del año calendario haya prestado servicios por un período inferior a seis (6) meses, hace uso de la licencia proporcional al lapso trabajado en el año vencido una vez que haya prestado servicios por aquel plazo mínimo. Cuando se trate de oficiales casados, convivientes o unidos civilmente de acuerdo a la Ley 1004 # (texto consolidado por Ley 5454) y ambos integren la Policía de la Ciudad, les será otorgada en forma simultánea, siempre que razones de servicio lo permitan. Por razones del servicio, se puede disponer su fraccionamiento, interrupción y transferencia íntegra o parcial al año siguiente. Esta licencia se suspende por afecciones o lesiones para cuya atención la autoridad sanitaria de la institución hubiere acordado más de cinco (5) días de licencia, o bien por maternidad, paternidad, adopción o fallecimiento, a cuya finalización se reanuda automáticamente.",
    
    " Capítulo XVI: Licencias - Artículo 162": "La licencia por enfermedad de tratamiento breve tiene por finalidad atender la incapacidad temporaria para el desempeño de las tareas habituales producida por enfermedades o accidentes sufridos por causas ajenas al servicio, de corto tratamiento, incluidas las intervenciones quirúrgicas menores. Las intervenciones quirúrgicas de carácter estético no son consideradas enfermedades o lesiones a efectos del otorgamiento de esta licencia, excepto las intervenciones de cirugía reconstructiva que se establezcan por la vía reglamentaria. La licencia por afección de corto tratamiento se concede hasta cuarenta y cinco (45) días corridos por año calendario, en forma continua o discontinua, con goce de haberes. Vencido este plazo, cualquier otra licencia por enfermedad de tratamiento breve que sea necesario otorgar durante el curso del año por las causales enunciadas, será considerado revistando en disponibilidad sin goce de haberes.",
    
    " Capítulo XVI: Licencias - Artículo 163": "La licencia por enfermedad de tratamiento prolongado tiene por finalidad atender la incapacidad prolongada para el desempeño de las tareas habituales producida por enfermedades graves, intervenciones quirúrgicas excepto la cirugía menor, o accidentes graves sufridos por causas ajenas al servicio. La licencia por enfermedad de tratamiento prolongado se concede hasta seis (6) meses, en forma continua o discontinua, para una misma o distinta enfermedad o accidente grave, período durante el cual el personal con estado policial que haga uso de la misma revista en situación de servicio efectivo con goce de haberes. Agotado dicho término, previo dictamen de la Junta Médica, la misma puede prorrogarse por hasta seis (6) meses más, en forma continua o discontinua, para una misma o distinta enfermedad o accidente grave, período durante el cual el personal con estado policial que haga uso de la misma es considerado en situación de disponibilidad y percibe los haberes detallados en el Artículo 184. Si, cumplido dicho término, el personal con estado policial no se hubiere recuperado, es considerado en situación de pasiva durante un plazo de hasta doce (12) meses más, percibiendo los haberes establecidos en el Artículo 185. Al finalizar este período, la Junta Médica determina si la persona debe reintegrarse al servicio efectivo o disponerse su retiro o baja obligatoria, según corresponda. Agotado el plazo de veinticuatro (24) meses y reintegrado el causante a sus funciones, no puede volver a hacer uso de este beneficio hasta después de transcurridos cinco (5) años y nunca mientras permanezca en el mismo grado. Caso contrario, pasa a situación de retiro o baja obligatoria, según corresponda. Cuando el personal que haga uso de la licencia por enfermedad de tratamiento prolongado no goce de estabilidad, el período de duración de la misma no queda comprendido dentro del período condicional, debiendo continuarse con el cómputo de dicho lapso hasta su agotamiento a partir de la fecha en que aquél se reintegre al servicio.",
    
    " Capítulo XVI: Licencias - Artículo 164": "La licencia por enfermedad profesional o accidente de trabajo tiene por finalidad atender la incapacidad temporaria para el desempeño de las tareas habituales producida por enfermedades profesionales o accidentes de trabajo y se rige por lo previsto en las Leyes Nacionales Nº 24.557 #, 26.773 # o por las normas que las sustituyan.",
    
    " Capítulo XVI: Licencias - Artículo 165": "La licencia por maternidad se concede por ciento cinco (105) días corridos, quedando prohibido el trabajo del personal durante los treinta y cinco (35) días anteriores al parto y hasta setenta (70) días corridos después del mismo, con goce de haberes. En caso de nacimiento múltiple el lapso previsto para el período de post-parto se extiende por el término de quince (15) días corridos por cada hijo/a nacido/a con vida después del primero. En caso de adelantarse el alumbramiento, los días no utilizados de la licencia anterior al parto se acumularán al lapso previsto para el período de post-parto. Si el/los recién nacido/s debiera/n permanecer internado/s en el área de neonatología, el lapso previsto para el período de post-parto se extiende por la cantidad de días que dure dicha internación. Vencido el lapso previsto para el periodo de post-parto, la trabajadora previa comunicación fehaciente a la Policía de la Ciudad, puede optar por prorrogar su licencia hasta ciento veinte (120) días corridos, sin percepción de haberes.",
    
    " Capítulo XVI: Licencias - Artículo 166": "A los fines de la alimentación y cuidado del hijo, el personal tiene derecho a una pausa de dos (2) horas diarias que pueden ser divididas en fracciones cuando se destine a la lactancia natural o artificial del hijo menor de doce (12) meses. Puede ser utilizada durante la jornada laboral como dos (2) descansos de una (1) hora cada uno, o disminución de dos (2) horas de labor a la entrada o a la salida, o una (1) hora a la entrada y una (1) hora a la salida. Asimismo para que el padre pueda utilizar este beneficio debe acreditar fehacientemente la circunstancia de la ausencia total o imposibilidad absoluta de la madre. Igual beneficio se acuerda a los trabajadores que posean la tenencia, guarda o tutela de niños/as de hasta doce (12) meses de edad, debidamente acreditada mediante certificación expedida por autoridad judicial o administrativa competente.",
    
    " Capítulo XVI: Licencias - Artículo 167": "La licencia por nacimiento de hijo se concede por diez (10) días corridos a partir de la fecha del nacimiento, con goce de haberes.",
    
    " Capítulo XVI: Licencias - Artículo 168": "La licencia por pérdida de gestación no inferior a tres (3) meses o de nacimiento sin vida de la criatura, se concede por cuarenta y cinco (45) días corridos con goce de haberes.",
    
    " Capítulo XVI: Licencias - Artículo 169": "La licencia por adopción corresponde a quien adopte a un niño/a y se concede por noventa (90) días corridos con goce de haberes, a contar a partir del primer día hábil de tener al niño/a en guarda con fines de adopción. Quien adopte simultáneamente a más de un niño/a tiene derecho a una licencia por un período de ciento veinte (120) días corridos. Si los adoptantes fuesen cónyuges y ambos perteneciesen a la Policía de la Ciudad, pueden decidir cuál de ambos goza de esta licencia o solicitar la mitad cada uno de ellos en forma sucesiva.",
    // Puedes continuar agregando más temas o artículos si es necesario
    " Título VI: Licencias y Permisos - Artículo 170": "La licencia por hijo/a discapacitado/a se concede por tres (3) meses desde la fecha de vencimiento del período de licencia por maternidad o desde que se presente la patología, con goce de haberes. Para hacer uso de esta licencia, el personal debe presentar el Certificado Único de Discapacidad, según lo establecido en los artículos 2 y 3 de la Ley Nacional Nº 22.431. Cuando la madre y el padre se desempeñaren en la Policía de la Ciudad, deben optar por quien la utilizará o pueden solicitar cada uno la mitad de la licencia en forma sucesiva.",

    " Título VI: Licencias y Permisos - Artículo 171": "La licencia por matrimonio o unión civil es de quince (15) días corridos, con goce de haberes.",

    " Título VI: Licencias y Permisos - Artículo 172": "La licencia por exámenes en el sistema de enseñanza oficial se concede por hasta veintiocho (28) días hábiles por año calendario, fraccionables en tantos períodos como sean necesarios pero ninguno superior a tres (3) días corridos, con goce de haberes.",

    " Título VI: Licencias y Permisos - Artículo 173": "La licencia por estudios o investigaciones científicas, técnicas o culturales incluidos el usufructo de becas y la participación en conferencias, congresos o eventos académicos, tanto en el país como en el extranjero, tendientes a mejorar la preparación técnica, académica o profesional del personal, se concede por un período de hasta un (1) año, y siempre que no obstara razones de servicio o de conveniencia institucional. El plazo de un (1) año se computa por única vez en la carrera. Si la actividad en cuestión, a criterio del Instituto Superior de Seguridad Pública, estuviese relacionada con la función que desempeña el personal que la solicite, la licencia se concede con goce de haberes. De lo contrario, se concede sin goce de haberes. Para usufructuar esta licencia el personal debe contar con una antigüedad mínima de cinco (5) años de servicio efectivo en la Policía de la Ciudad.",

    " Título VI: Licencias y Permisos - Artículo 174": "La licencia por fallecimiento de familiares es otorgada en los siguientes casos, y por los plazos que se detallan a continuación:\n1. Fallecimiento de cónyuge, pareja conviviente o pareja de unión civil, padre, madre o hijo; cinco (5) días corridos.\n2. Fallecimiento de hermano: tres (3) días corridos.\n3. Fallecimiento de nieto, bisnieto, abuelo, bisabuelo, padre, madre, hijo por afinidad, padrastro o madrastra: un (1) día corrido. La licencia se otorga, a opción del beneficiario, a partir del fallecimiento o de las exequias. En el caso de que el fallecimiento de la cónyuge, pareja de unión civil o conviviente fuere producto o causa sobreviniente de un parto y el hijo o hija sobreviviera, el personal tiene derecho a una licencia análoga a la establecida para el post parto de la mujer.",

    " Título VI: Licencias y Permisos - Artículo 175": "La licencia por enfermedad de un familiar a cargo, cónyuge, conviviente o persona a cargo será de hasta diez (10) días por año calendario, en forma continua o discontinua, con goce de haberes. Este plazo puede prorrogarse sin goce de haberes hasta un máximo de sesenta (60) días corridos más.",

    " Título VI: Licencias y Permisos - Artículo 176": "La licencia por donación de sangre se otorga por el día de la donación, con goce de haberes, debiendo presentar el certificado de autoridad competente que la certifique.",

    " Título VI: Licencias y Permisos - Artículo 177": "La licencia por asuntos del servicio es concedida a quien haya sido designado para representar a la Institución en actividades sociales, culturales, deportivas y otras que puedan prestigiarla, por el tiempo que demande la representación, con goce de haberes.",

    " Título VI: Licencias y Permisos - Artículo 178": "La licencia por estímulo es concedida por actos destacados del servicio, en la siguiente forma:\n1. Por el Jefe de la Policía de la Ciudad: Hasta veinte (20) días corridos.\n2. Por el Subjefe de la Policía de la Ciudad: Hasta quince (15) días corridos.\n3. Por otros funcionarios de la estructura de la Policía de la Ciudad, en cuanto la reglamentación lo determine.",

    " Título VI: Licencias y Permisos - Artículo 179": "La licencia por adaptación escolar de hijo consiste en una franquicia horaria de hasta tres (3) horas diarias durante hasta cuatro (4) días corridos con goce de haberes. Se otorga por adaptación escolar en los niveles de jardín maternal, preescolar y primer grado, siempre que el establecimiento se encuentre fuera del lugar de trabajo. Si ambos padres integrasen la Policía de la Ciudad la licencia sólo puede ser utilizada por uno de ellos. La reglamentación establece los requisitos para acreditar la adaptación escolar del niño.",

    " Título VI: Licencias y Permisos - Artículo 180": "La licencia para controles de prevención del cáncer se otorga por un (1) día, según los siguientes criterios:\n1. A las mujeres, a fin de realizar el control ginecológico completo: Papanicolaou, colposcopia y examen de mamas.\n2. A los varones mayores de cuarenta y cinco (45) años, a fin de realizar el control del Antígeno Prostático Específico (PSA). Las constancias de haber realizado dichos exámenes deben ser presentadas por el personal que haya usufructuado la licencia, ante la dependencia que la reglamentación determine.",

    " Título VI: Licencias y Permisos - Artículo 181": "La licencia por violencia de género se otorga al personal que padezca cualquier tipo de violencia de género afectando su seguridad personal, y que por tal motivo deba ausentarse de su puesto de trabajo. Esta licencia debe contar con la debida justificación emitida por los servicios de atención y asistencia a las víctimas. En un plazo de setenta y dos (72) horas se debe presentar la denuncia judicial correspondiente o la certificación emitida por los organismos estatales competentes.",

    " Título VI: Licencias y Permisos - Artículo 182": "El Ministro de Justicia y Seguridad puede conceder, por resolución fundada, licencias sin goce de haberes no previstas en el presente régimen. Asimismo, el Jefe de la Policía de la Ciudad está facultado para conceder al personal permisos y franquicias en el cumplimiento de la jornada de trabajo, de acuerdo con los plazos, naturaleza de la relación de empleo y demás condiciones que se establecen en la reglamentación de la presente Ley. El Jefe de la Policía de la Ciudad puede delegar esta facultad en funcionarios de los grados inferiores.",

    " Capítulo XVII: Sueldos y Asignaciones - Artículo 183": "El personal de la Policía de la Ciudad en actividad goza del sueldo, bonificaciones, suplementos, viáticos, compensaciones e indemnizaciones que para cada caso determine la reglamentación. El total de las sumas remunerativas que percibe el funcionario por los conceptos señalados precedentemente, excepto las indemnizaciones, se denomina haber mensual.",

    " Capítulo XVII: Sueldos y Asignaciones - Artículo 184": "El personal con estado policial que revista en disponibilidad percibe, salvo expresa disposición en contrario en esta Ley, el cien por ciento (100%) del haber mensual que le pudiera corresponder, excepto los suplementos que por la vía reglamentaria se establezcan para retribuir la prestación de servicios efectivos y los destinados a compensar el riesgo profesional ligado a las actividades propias del estado policial. Percibe asimismo las asignaciones familiares.",

    " Capítulo XVII: Sueldos y Asignaciones - Artículo 185": "El personal que revista en situación pasiva en las circunstancias consignadas en los incisos 2, 3, 4 5, 7 y 8 del artículo 157 no percibe haberes ni asignaciones familiares. El personal que se encuentra encuadrado en los supuestos previstos en los incisos 1 y 6 del Artículo 157, percibe el cincuenta por ciento (50%) del haber mensual que le pudiera corresponder al personal en disponibilidad, más las asignaciones familiares. El personal que haya revistado en situación pasiva por detención o proceso por hecho vinculado al servicio, y resultara absuelto o sobreseído, tiene derecho a percibir el cien por ciento (100%) de los haberes que le hubieran correspondido de revistar en disponibilidad.",

    " Capítulo XVII: Sueldos y Asignaciones - Artículo 186": "La remuneración debe compensar la responsabilidad inherente al grado, al desempeño del cargo, la mayor atribución de competencias y el rendimiento efectivo en la tarea asignada, para lo cual la reglamentación puede establecer un segmento de remuneración fija y otro variable.",

    " Capítulo XVIII: Políticas Antidiscriminatorias y de Género - Artículo 187": "La Policía de la Ciudad se subordina en su conformación y funcionamiento al espíritu antidiscriminatorio establecido en el artículo 11 de la Constitución de la Ciudad Autónoma de Buenos Aires # y su personal se integra de forma proporcional según lo dispuesto en su artículo 36. Tiene en cuenta a su vez los principios dispuestos por la Ley 4376 de Políticas Públicas para el Reconocimiento y Ejercicio Pleno de la Ciudadanía de las Personas Lesbianas, Gays,Trans, Bisexuales e Intersexuales (LGTBI) # (texto consolidado por Ley 5454).",
    
    " Capítulo XVIII: Políticas Antidiscriminatorias y de Género - Artículo 188": "La Policía de la Ciudad guarda una estricta representación de géneros, favoreciendo la incorporación, participación y promoción sin ninguna limitante por género, orientación sexual o identidad de género, ya sea para el acceso efectivo a cargos de conducción, como así también en todos los niveles y áreas.",
    
    " Capítulo XVIII: Políticas Antidiscriminatorias y de Género - Artículo 189": "A los efectos de dar cumplimiento a los artículos 11, 36, 37 y 38 de la Constitución de la Ciudad Autónoma de Buenos Aires # y al artículo 5 inciso c de la Ley 4376 # (texto consolidado por Ley 5454) se promoverá a través de la reglamentación de la presente, la modificación de los patrones socioculturales estereotipados con el objeto de eliminar prácticas discriminatorias dentro de la Policía de la Ciudad, sea estas basadas en la superioridad de género, orientación sexual o identidad de género de su personal.",
    
    " Capítulo XVIII: Políticas Antidiscriminatorias y de Género - Artículo 190": "La reglamentación contemplará las siguientes cuestiones orientadas a favorecer y preservar las condiciones igualitarias en el personal de las fuerzas de seguridad:\n1. Fomenta la plena integración de las mujeres a los puestos de mando y control respetando el régimen de carrera y el plan de ascensos establecidos a tal efecto.\n2. Instituye y fomenta las acciones y disposiciones legales concretas tendientes a garantizar la paridad entre el trabajo realizado y la remuneración recibida en su consecuencia, entre hombres y mujeres.\n3. Prohíbe todas las prácticas que impliquen cualquier forma de segregación y discriminación por estado civil o maternidad.\n4. Promueve la remoción de los obstáculos de cualquier orden que, limitando de hecho la igualdad y la libertad, impidan el pleno desarrollo de la persona y la efectiva participación en la Policía de la Ciudad.",

        " Capítulo XIX: Régimen Disciplinario - Artículo 191": "Las disposiciones de este Capítulo se aplican:\n1. Al personal con estado policial en actividad.\n2. Al personal sin estado policial.\n3. Al personal en retiro:\na. en las casos y de acuerdo con las normas que establezca al respecto la reglamentación.\nb. cuando deba responder por hechos cometidos mientras estuvo en actividad.\nc. cuando esté convocado a prestar servicios, en iguales condiciones que el personal en actividad.",
    
    " Capítulo XIX: Régimen Disciplinario - Artículo 192": "La violación a los deberes y obligaciones impuestos en esta Ley y en sus normas reglamentarias por parte del personal mencionado en el artículo anterior lo hace pasible de las siguientes sanciones disciplinarias, sin perjuicio de la responsabilidad civil, penal o administrativo patrimonial que se determine por la vía correspondiente:\n1. Apercibimiento escrito.\n2. Suspensión de empleo.\n3. Cesantía.\n4. Exoneración.",
   
    " Capítulo XIX: Régimen Disciplinario - Artículo 193": "Las faltas que cometa el personal con estado policial de la Policía de la Ciudad de Buenos Aires son clasificadas como leves, moderadas y graves, según la reglamentación y pueden afectar:\n1. La disciplina.\n2. La operatividad en el servicio.\n3. La imagen pública o el prestigio de la institución.\n4. La ética y honestidad del personal.\n5. Los principios básicos de actuación policial.\nLa aplicación de sanciones administrativas por faltas graves tramita en sede de la Oficina de Transparencia y Control Externo; la facultad disciplinaria correspondiente a las faltas leves y moderadas es ejercida por los órganos competentes de la Policía de la Ciudad, conforme lo determine la reglamentación.",
   
    " Capítulo XIX: Régimen Disciplinario - Artículo 194": "Toda sanción disciplinaria debe tener por fundamento la transgresión a una norma vigente con anterioridad a la aplicación de la misma. Ningún acto u omisión es punible, administrativamente, sin una prohibición u orden anterior que se le opongan.",
    
    " Capítulo XIX: Régimen Disciplinario - Artículo 195": "Toda sanción disciplinaria debe ser impuesta en relación a la naturaleza y gravedad de la falta cometida y la circunstancia del lugar, tiempo, medio empleado y modo de ejecución. Para la graduación de las sanciones, se analiza también la personalidad y antecedentes del responsable.",
    
    " Capítulo XIX: Régimen Disciplinario - Artículo 196": "El apercibimiento consiste en el llamado de atención que se hace al responsable de la falta u omisión, el cual se puede adelantar en forma verbal y se ratificará por escrito dentro de las veinticuatro (24) horas, a los efectos administrativos pertinentes.",
    
    " Capítulo XIX: Régimen Disciplinario - Artículo 197": "La sanción de suspensión de empleo consiste en la privación temporal del ejercicio de las funciones y la pérdida proporcional de la retribución que le corresponde.",
    
    " Capítulo XIX: Régimen Disciplinario - Artículo 198": "Las sanciones disciplinarias de cesantía y exoneración, constituyen medidas expulsivas que importan la separación de la Policía de la Ciudad, con la pérdida del estado policial. La cesantía implica la inhabilitación para el reingreso a la institución y no importa la pérdida del derecho al haber de pasividad que pudiera corresponder al sancionado. La exoneración implica la pérdida del empleo, los derechos inherentes al mismo, el haber de retiro que correspondiere y la inhabilitación para el reingreso a la institución. Los derechohabientes conservan el derecho a percibir la pensión del derecho a haber de pasividad que les hubiere correspondido en caso de haber fallecido el causante a la fecha de la sanción.",
   
    " Capítulo XIX: Régimen Disciplinario - Artículo 199": "Las sanciones de cesantía y exoneración son resueltas por el Secretario de Seguridad del Ministerio de Justicia y Seguridad a propuesta de la Oficina de Transparencia y Control Externo previa instrucción del sumario administrativo correspondiente. Las sanciones de apercibimiento y suspensión de empleo son aplicadas conforme se reglamente al efecto.",
   
    " Capítulo XIX: Régimen Disciplinario - Artículo 200": "Si durante el trámite de un sumario administrativo el sumariado solicitase la baja o accediese al retiro, el procedimiento disciplinario debe continuar hasta su resolución, en cuyo caso la baja o retiro pueden reconvertirse en cesantía o exoneración, según corresponda.",
   
    " Capítulo XIX: Régimen Disciplinario - Artículo 201": "La amnistía o indulto en el delito que originó la actuación, la absolución o sobreseimiento judicial recaídos en la causa que se le refiera y el perdón del particular damnificado, no eximen de sanción, cuando corresponda, por infracción al régimen disciplinario policial.",
   
    " Capítulo XIX: Régimen Disciplinario - Artículo 202": "Contra los actos administrativos que imponen sanciones disciplinarias son procedentes los recursos administrativos contemplados en el Decreto Nº 1510/GCABA/1997 (texto consolidado por Ley Nº 5454). El recurso jerárquico contra los actos administrativos sancionatorios dictados por el Secretario de Seguridad es resuelto por el Ministro de Justicia y Seguridad. Esta resolución agota la vía administrativa.",
   
    " Capítulo XIX: Régimen Disciplinario - Artículo 203": "La acción para imponer las sanciones por faltas disciplinarias prescribe en los siguientes plazos:\n1. Para las causales que dieran lugar a apercibimiento o suspensión: un (1) año.\n2. Para las causales que dieran lugar a cesantía o exoneración: dos (2) años.\nEn todos los casos el plazo se cuenta desde el momento de la comisión de la falta administrativa, si ésta fuese instantánea, o desde que hubiera dejado de cometerse si hubiera sido continúa.",
   
    " Capítulo XIX: Régimen Disciplinario - Artículo 204": "La prescripción de la acción para imponer las sanciones por faltas disciplinarias se interrumpe por las siguientes causales:\n1. El inicio de las averiguaciones previas por parte del organismo disciplinario competente.\n2. El inicio del sumario administrativo.\n3. El llamado a prestar declaración en el sumario administrativo.",
    
    " Capítulo XIX: Régimen Disciplinario - Artículo 205": "El proceso judicial cuyo objeto verse sobre el mismo hecho que pueda configurar una falta disciplinaria suspende la prescripción de la acción para imponer sanciones administrativas hasta la sentencia judicial firme. La Administración puede imponer la sanción por la comisión de una falta administrativa antes de la culminación del proceso penal. En este caso, la sanción que se imponga en el orden administrativo tiene carácter provisional y puede ser sustituida por otra de mayor gravedad si en la sentencia definitiva se acreditase la configuración de una causal más grave que la sancionada. La Administración no puede declarar libre de responsabilidad en un sumario administrativo a una persona sujeta a causa penal por el mismo hecho, hasta tanto finalice el proceso judicial y se determine el sobreseimiento o absolución firmes del imputado.",
    
    " Capítulo XIX: Régimen Disciplinario - Artículo 206": "La reglamentación define y clasifica las faltas administrativas, establece el procedimiento de sustanciación de los sumarios administrativos y las condiciones de aplicación de las sanciones previstas en la presente Ley.",
    
    " Título V: Extinción de la Relación de Empleo - Capítulo XX: Extinción de la Relación de Empleo - Artículo 207": "La relación de empleo del personal con estado policial de la Policía de la Ciudad se extingue por las siguientes causas:\n1. Baja voluntaria.\n2. Baja definitiva.\n3. Retiro.",
   
    " Título V: Extinción de la Relación de Empleo - Capítulo XX: Extinción de la Relación de Empleo - Artículo 208": "La baja voluntaria es el derecho del personal a concluir la relación de empleo con la Policía de la Ciudad a solicitud del interesado. Implica la pérdida del estado policial y tiene efecto a partir de su concesión por parte de la institución.\nDurante los estados de guerra o de sitio y en los casos de conmoción pública su otorgamiento es optativo por parte de la autoridad competente, pero en todos los casos debe ser concedida al finalizar la circunstancia de hecho que motiva su aplazamiento.\nTambién puede solicitar la baja el personal retirado.",
    
    " Título V: Extinción de la Relación de Empleo - Capítulo XX: Extinción de la Relación de Empleo - Artículo 209": "El personal dado de baja a su solicitud puede ser reincorporado siempre que:\n1. Lo solicite dentro del plazo de dos (2) años de hecha efectiva la baja.\n2. El Ministro de Justicia y Seguridad considere conveniente su reincorporación.\n3. Cumpla al momento de la reincorporación con los requisitos establecidos en el Artículo 128 de esta Ley, con excepción del consignado en el inciso 2.\nLa reincorporación se efectiviza en el mismo grado y situación de revista que tenía el causante en el momento de su baja. En caso de reincorporarse en actividad ocupa el último puesto en el respectivo grado.",
    
    " Título V: Extinción de la Relación de Empleo - Capítulo XX: Extinción de la Relación de Empleo - Artículo 210": "La reglamentación fijará plazos mínimos de servicio o, en su caso, indemnización, para el personal que luego de haber recibido capacitación solicite su baja voluntaria.",
   
    " Título V: Extinción de la Relación de Empleo - Capítulo XX: Extinción de la Relación de Empleo - Artículo 211": "La baja definitiva importa la pérdida del estado policial y la exclusión definitiva del personal.\nLa baja definitiva es dispuesta en los siguientes casos:\n1. Fallecimiento.\n2. Cesantía o exoneración, cualquiera fuese la antigüedad del personal.\n3. Cuando en los exámenes psicofísicos periódicos se evidenciase la carencia de las aptitudes profesionales y personales indispensables para el normal ejercicio de la función policial que le compete, y no pudiere ser asignado a otro destino.\n4. Cuando las calificaciones sean inferiores a lo que determine la reglamentación.\n5. Cuando el personal sea declarado prescindible para el servicio efectivo por la Junta de Calificaciones.",
   
    " Título V: Extinción de la Relación de Empleo - Capítulo XX: Extinción de la Relación de Empleo - Artículo 212": "La baja definitiva puede producirse con derecho a haber de pasividad o sin él.\nTiene derecho a haber de pasividad:\n1. El personal - excepto el exonerado - que al momento de la baja hubiese prestado al menos veinte (20) años de servicio computables para el retiro en la Policía de la Ciudad.\n2. El personal que tuviese la baja por las causales dispuestas en los incisos 3, 4 y 5 del artículo 211, y al momento de la baja hubiese prestado al menos diez (10) años de servicios computables para el retiro en la Policía de la Ciudad.\nEn ambos casos el haber de pasividad es equivalente al 82% de lo que hubiese correspondido al causante en caso de retiro conforme la escala dispuesta en el artículo 225.",

     " Capítulo XXI: Régimen Previsional - Artículo 213": "El personal con estado policial de la Policía de la Ciudad está sujeto al régimen previsional que se establece en la presente Ley, en su reglamentación, y en los convenios que el Poder Ejecutivo está facultado a realizar. En caso de existir situaciones no previstas, se aplican analógicamente las disposiciones contenidas en los Títulos III y IV de la Ley Nacional Nº 21.965 #. Las contingencias cubiertas por este régimen son la vejez, la incapacidad y el fallecimiento.",
    
    " Capítulo XXI: Régimen Previsional - Artículo 214": "Los aportes personales y las contribuciones patronales destinadas al sistema previsional regulado por esta Ley son los establecidos en la Ley Nacional Nº 21.865 # y el artículo 26 de la Ley Nacional Nº 21.981 # respectivamente.",

    " Capítulo XXII: RETIRO - Artículo 215": "El retiro es definitivo, salvo en los casos de cesantía o exoneración posteriores. Produce los siguientes efectos:\n1. Cierra el ascenso y genera vacantes en el grado del causante.\n2. No permite desempeñar cargos propios del estado policial en la Policía de la Ciudad, excepto el caso del llamado a prestar servicios.\n3. Modifica los derechos y obligaciones propios del personal en actividad, rigiendo para el personal retirado los establecidos en el artículo 111 de la presente Ley.",
    
    " Capítulo XXII: RETIRO - Artículo 216": "El retiro del personal con estado policial es resuelto por el Ministro de Justicia y Seguridad, a propuesta del Jefe de la Policía.",
    
    " Capítulo XXII: RETIRO - Artículo 217": "Los trámites de retiro pueden ser suspendidos por decisión fundada del Ministro de Justicia y Seguridad por las siguientes causales:\n1. Cuando se trate de personal sometido a sumario administrativo o proceso judicial.\n2. Cuando lo solicite el Jefe de la Policía de la Ciudad, por razones de servicio, orden público o emergencia.",
    
    " Capítulo XXII: RETIRO - Artículo 218": "El retiro voluntario puede ser solicitado por el personal con estado policial que hubiere cumplido un mínimo de veinte (20) años de servicio en la Policía de la Ciudad.",
    
    " Capítulo XXII: RETIRO - Artículo 219": "El retiro obligatorio corresponde:\n1. A aquellos que alcancen los treinta (30) años de servicio en la Policía de la Ciudad, salvo que el Ministro de Justicia y Seguridad o el funcionario en quien éste delegue esta competencia considere oportuna la continuidad en servicio.\n2. Por enfermedad o lesión no causadas en actos de servicio, luego de agotadas las licencias para el tratamiento de la salud.\n3. Por motivos del cargo, a aquéllos que cesaren en los cargos de Jefe y Subjefe de la Policía de la Ciudad, salvo este último si fuese designado para reemplazar al titular.\n4. Para producir vacantes, quienes hubiesen obtenido los órdenes de mérito más bajos hasta completar el número de vacantes a producir en cada grado.\n5. Por incapacidad o inutilización por enfermedad contraída o agravada o por accidente producido 'en y por acto de servicio'.\n6. Por incapacidad o inutilización por enfermedad contraída o agravada o por accidente producido en servicio.\n7. Por incapacidad o inutilización por enfermedad contraída o agravada o por accidente desvinculado del servicio.",
    
    " Capítulo XXII: RETIRO - Artículo 220": "A los fines de establecer el derecho y el haber de retiro se computan los servicios prestados:\n1. Por el personal en actividad, conforme lo dispuesto por los artículos 155, 156 y en el penúltimo párrafo del Artículo 157 de la presente Ley.\n2. Por el personal llamado a prestar servicios, el tiempo de servicio efectivo prestado en esta condición. El tiempo que se computa acrecienta el haber de retiro en lo referente al cálculo de la antigüedad y el porcentaje que corresponda cuando cesa la prestación de servicios en esta condición.",
    
    " Capítulo XXII: RETIRO - Artículo 221": "Los años de servicio se computan desde la fecha de alta con estado policial hasta la fecha del acto administrativo que dispone el retiro o hasta la que éste establezca. Asimismo:\n1. Se computan los servicios prestados con anterioridad al ingreso a la Policía de la Ciudad en las Fuerzas Armadas de la Nación, Fuerzas de Seguridad, Policías Provinciales y Servicio Penitenciario Federal y Provinciales con estado militar (salvo servicio militar obligatorio), estado policial o estado penitenciario, y en el Cuerpo de Bomberos de la Ciudad, a partir de los veinte (20) años de servicio.\n2. Se computan los servicios prestados en la Administración Pública Nacional o de la Ciudad de Buenos Aires antes del ingreso a la Policía de la Ciudad con estado policial, o los prestados en la Policía de la Ciudad sin estado policial antes de adquirir el estado policial, a partir de los veinticinco (25) años de servicio con estado policial.\n3. Cuando el retiro sea obligatorio, los servicios a que se refiere el inciso 1 se computan desde que el causante haya cumplido los diez (10) años de servicios policiales, y quince (15) en años en caso del inciso 2.",
    
    " Capítulo XXII: RETIRO - Artículo 222": "El retiro se produce en el último grado que ostentaba el causante en actividad. Sin embargo, cuando el personal con estado policial resultase incapacitado por hechos que fueran calificados 'en y por acto de servicio' y como consecuencia de esto debiese acogerse al retiro, se le reconocerán dos grados inmediatos superiores al que detentaba en actividad.\nLos mismos grados se reconocen a los fallecidos a consecuencia de hechos que fueran calificados 'en y por acto de servicio', tengan o no causahabientes con derecho a pensión.\nLas promociones establecidas en los párrafos anteriores son otorgadas por resolución fundada del Ministro de Justicia y Seguridad.\nPara el cálculo del haber de retiro o pensión se toma como base el cien (100) por ciento del total del haber percibido en actividad, correspondiente a los grados que por este artículo se reconocen.",
    
    " Capítulo XXII: RETIRO - Artículo 223": "Cuando el fallecimiento se produjese por acto heroico o de arrojo en cumplimiento del deber y el Ministro de Justicia y Seguridad otorgase el ascenso post mortem, se partirá de esta última jerarquía para el reconocimiento de los grados superiores establecidos en el artículo anterior, desde el día del fallecimiento del causante.",

    "CAPÍTULO XXIII HABER DE RETIRO - Artículo 224": "El haber de retiro se calcula sobre el sueldo, los suplementos y todos los conceptos remunerativos que se establezcan para retribuir al personal en actividad. Quedan excluidas las asignaciones familiares.",

    "CAPÍTULO XXIII HABER DE RETIRO - Artículo 225": "Salvo expresa disposición en contrario en esta Ley, el haber de retiro es proporcional al tiempo de servicio conforme la siguiente escala:\nAños de Servicio Porcentaje de Haber de Retiro\n10 30%\n11 34%\n12 38%\n13 42%\n14 46%\n15 50%\n16 53%\n17 56%\n18 59%\n19 62%\n20 65%\n21 69%\n22 73%\n23 77%\n24 81%\n25 85%\n26 88%\n27 91%\n28 94%\n29 97%\n30 100%\nA los efectos del haber de retiro, la fracción que pasare los seis (6) meses se computa como año entero, siempre que el causante reúna el tiempo mínimo de servicio requerido para acceder al retiro voluntario.",
    
    "CAPÍTULO XXIII HABER DE RETIRO - Artículo 226": "Al personal que acceda al retiro voluntario le corresponde el haber de retiro conforme al cuadro establecido en el artículo 225.",
    
    "CAPÍTULO XXIII HABER DE RETIRO - Artículo 227": "Al personal que accede al retiro obligatorio le corresponde el siguiente haber de retiro:\n1. Al comprendido en los incisos 1, 2 y 4 del artículo 219, conforme al cuadro establecido en el artículo 225 a partir del cumplimiento de diez (10) años de servicio.\n2. Al comprendido en el inciso 3 del Artículo 219, el porcentaje máximo establecido en la escala del Artículo 225, cualquiera sea el tiempo de servicios o el desempeño del cargo de Jefe o Subjefe de la Policía de la Ciudad.\n3. Al comprendido en el inciso 5 del artículo 219, el total de las remuneraciones de los grados que se reconocen por el artículo 222. A estos efectos, corresponde computar el sueldo y la totalidad de los suplementos y bonificaciones de los grados superiores reconocidos, con carácter móvil, para el haber de retiro o pensión.\nCuando la inutilización produzca una incapacidad total para el trabajo en la vida civil se agrega un quince por ciento (15%) al haber de retiro fijado en el párrafo anterior.\nEn caso de no existir en el escalafón grado inmediato superior, se acuerda el sueldo íntegro bonificado en un quince por ciento (15%) más los suplementos remunerativos del grado.\n4. Al comprendido en el inciso 6 del artículo 219, conforme el cuadro establecido en el artículo 225. Si no alcanzara el mínimo de diez (10) años de servicio, percibe el treinta por ciento (30%) del total de sus remuneraciones.\nSi la incapacidad o inutilización determina una disminución en la capacidad laborativa para la vida civil del sesenta y seis (66%), el haber de retiro no puede ser inferior al setenta por ciento (70%) del total del sueldo y suplementos remunerativos que percibía en actividad.\n5. Al comprendido en el inciso 7 del artículo 219, conforme el cuadro establecido en el artículo 225. Si no alcanzara el mínimo de diez (10) años de servicio, se computa el tres por ciento (3%) del total de sus remuneraciones por año de servicio computable.",
    
    "CAPÍTULO XXIII HABER DE RETIRO - Artículo 228": "Cuando el personal con estado policial resultase incapacitado total o parcialmente en forma permanente a consecuencia de un hecho que fuese calificado como ocurrido 'en y por acto de servicio' y haya pasado a retiro obligatorio, el haber de retiro se actualiza sexenalmente, desde la fecha del hecho que motiva la incapacidad, equiparándolo al del grado inmediato superior, hasta alcanzar la percepción de un haber equivalente al correspondiente al máximo grado del escalafón.\nLa misma actualización se aplica al haber de pensión si el causante falleciera a consecuencia de un hecho calificado como ocurrido 'en y por acto de servicio'.",
    
    "CAPÍTULO XXIII HABER DE RETIRO - Artículo 229": "Los haberes de retiro y pasividad se mantienen permanentemente actualizados en referencia a las remuneraciones en cuya relación estuvieren establecidos los beneficios en cada uno de los casos detallados en los artículos anteriores.",

    " Capítulo XXIV: Deudos con Derecho a Pensión - Artículo 230": "Los deudos del personal con derecho a pensión son los siguientes:\n1. La viuda, viudo o conviviente.\n2. Los hijos solteros hasta su mayoría de edad o hasta los veintiséis (26) años si al momento del fallecimiento del causante cursaren regularmente estudios de nivel terciario o universitario y los/as mayores de edad incapacitados/as definitivamente para el trabajo siempre que estos últimos carecieran de recursos suficientes o de beneficio previsional más favorable.\n3. Los padres carentes de recursos suficientes o de beneficio previsional más favorable, que estuvieren a cargo del causante.\n4. Las hermanas y hermanos solteros menores de edad y los mayores incapacitados definitivamente para el trabajo, que estuvieran a cargo del causante en el momento del fallecimiento, y carezcan de recursos suficientes o de beneficio previsional más favorable. La carencia de recursos suficientes o de beneficio previsional más favorable, en los casos que así se exijan, son determinados y comprobados en la forma que especifique la reglamentación de la presente Ley. La incapacidad se acredita en todos los casos con el Certificado Único de Discapacidad regulado por la Ley Nacional Nº 22.431 #.",
   
    " Capítulo XXIV: Deudos con Derecho a Pensión - Artículo 231": "Los deudos del personal, con la sola excepción indicada en el inciso 3 del artículo 230 concurren a ejercitar su derecho a pensión con arreglo a la situación existente al día del fallecimiento del causante no pudiendo con posterioridad al mismo concurrir a ejercitar ese derecho cuando no lo tuvieren en aquel momento.",
    
    " Capítulo XXIV: Deudos con Derecho a Pensión - Artículo 232": "El haber de pensión se concede a los deudos con derecho a él, en el siguiente orden:\n1. A la viuda, viudo o conviviente en concurrencia con los hijos.\n2. A los hijos no existiendo la viuda, viudo o conviviente.\n3. A la viuda, viudo o conviviente en concurrencia con los padres del fallecido con derecho a pensión no habiendo hijos.\n4. A la viuda, viudo o conviviente no existiendo hijos ni padres.\n5. A los padres con derecho a pensión no existiendo viuda, viudo o conviviente ni hijos.\n6. A los hermanos con derecho a pensión, no existiendo viuda, viudo o conviviente, hijos ni padres.",
    
    " Capítulo XXIV: Deudos con Derecho a Pensión - Artículo 233": "La distribución del haber de pensión se efectúa con arreglo a las siguientes disposiciones:\n1. En caso de concurrencia de viuda, viudo o conviviente e hijos corresponderá una mitad a la viuda, viudo o conviviente y la otra mitad se dividirá en partes iguales entre los hijos.\n2. En caso de concurrencia de hijos el haber de pensión se dividirá por partes iguales entre los mismos.\n3. No existiendo y concurriendo a la pensión la viuda, viudo o conviviente y los padres del causante con derecho a pensión, los dos tercios (2/3) del haber de ésta comprenderá a la viuda, viudo o conviviente, y el tercio restante (1/3) a los padres.\n4. No existiendo hijos ni padres del causante con derecho a pensión, el haber de ésta le corresponderá íntegramente a la viuda, viudo o conviviente.\n5. En el caso de concurrencia de padre y madre con derecho a pensión y no existiendo viuda, viudo o conviviente ni hijos, el haber de pensión corresponderá íntegramente a aquellos por partes iguales.\n6. En caso de concurrencia de hermanos y no existiendo viuda, viudo o conviviente, hijos ni padres con derecho a pensión, el haber de pensión corresponderá por partes iguales entre ellos.\n7. En todos los casos en que concurran la viuda o viudo y el o la conviviente, la porción correspondiente del beneficio se divide por mitades iguales entre ellos.",
    
    " Capítulo XXIV: Deudos con Derecho a Pensión - Artículo 234": "En caso de concurrencia de derechohabientes si uno de éstos falleciera o perdiere el derecho a pensión, su parte acrecentará las de sus co-beneficiarios.",
    
    " Capítulo XXIV: Deudos con Derecho a Pensión - Artículo 235": "El derecho a pensión se pierde en forma irrevocable por las siguientes causales:\n1. Por fallecimiento.\n2. Para los hijos/as solteros/as, el día que cumplan la mayoría de edad, salvo que se encontrasen incapacitados para el trabajo, o el día que cumplan los veintiséis (26) años si al momento del fallecimiento del causante cursaren regularmente estudios de nivel terciario o universitario, o en la fecha de finalización o abandono de los estudios, o si estuvieran en una unión convivencial.\n3. Para el padre o la madre con derecho a pensión el día que contrajeran nuevas nupcias o estuvieran en una unión convivencial.\n4. Por incurrir en las causales de indignidad enunciadas en el artículo 2281 del Código Civil y Comercial de la Nación #.\n5. Por tomar estado religioso.\n6. En los casos en que el beneficio se otorga por carecer de recursos suficientes, desde que se compruebe que el beneficiario posee medios de subsistencia suficientes que hagan innecesario el haber de pensión.",
    
    " Capítulo XXIV: Deudos con Derecho a Pensión - Artículo 236": "En los casos de ausentes con presunción de fallecimiento establecida judicialmente, la pensión será provisional hasta tanto se aclare la situación legal del causante. Se otorgará a los deudos con derecho a pensión de acuerdo con la siguiente norma:\n1. La pensión se liquidará desde la fecha en que se produjo el hecho que motivó el derecho a ella.\n2. Si otro deudo justificara un derecho a participar de una pensión ya concedida, el beneficio se otorgará desde la fecha de presentación de su solicitud.\n3. Pasará a ser definitiva cuando se establezca el fallecimiento del causante.\n4. En caso de desaparición de algún derechohabiente, los restantes también recibirán la pensión provisional que corresponda y que pasará a ser definitiva al establecerse el fallecimiento del desaparecido.",
   
    " Capítulo XXIV: Deudos con Derecho a Pensión - Artículo 237": "Los haberes de pensión se liquidan desde la fecha del fallecimiento del causante sin perjuicio de aplicar las pertinentes disposiciones legales en materia de prescripción cuando así corresponda. Si el derecho a la pensión se hubiere originado con posterioridad al fallecimiento del causante la pensión se liquidará desde la fecha en que se produjo el hecho que motivó el derecho a ella. Si otro deudo justificara un derecho a participar de una pensión ya concedida, el beneficio se otorgará desde la fecha de presentación de su solicitud.",
   
    " Capítulo XXIV: Deudos con Derecho a Pensión - Artículo 238": "El haber de pensión es inembargable y no responde por las deudas contraídas por el causante, con la salvedad de las cuotas por alimentos y litis expensas u obligaciones a favor de la Nación, cualesquiera fueren sus causas. El haber de pensión es personal y por lo tanto se refuta nula la cesión que se pretenda hacer de él por cualquier causa que fuere.",
    
    " Capítulo XXIV: Deudos con Derecho a Pensión - Artículo 239": "El monto de la pensión se determina de la siguiente manera:\n1. A los derechohabientes del personal retirado, jubilado, dado de baja con derecho a haber de pasividad, o fallecido en actividad, el importe de la pensión será igual al setenta y cinco por ciento (75%) del haber de retiro, jubilación o pasividad que el causante gozaba o al que tenía derecho a percibir.\n2. A los derechohabientes del personal fallecido en actividad a consecuencia de una enfermedad o de un accidente que sea considerado ocurrido “en servicio“ de acuerdo con lo que determine la reglamentación de esta Ley el setenta y cinco por ciento (75%) del haber de retiro establecido en el artículo 225.\n3. A los derechohabientes del personal en situación de actividad, fallecido a consecuencia de un hecho calificado 'en y por acto de servicio', el setenta y cinco por ciento (75%) de las asignaciones a que se refieren los Artículos 227 inciso 3 y 228. El beneficio se bonifica en un diez por ciento (10%) por cada hijo con derecho a pensión que concurra, sin derecho a acrecer.\n4. A los derechohabientes del exonerado, el setenta y cinco por ciento (75%) del haber de pasividad que hubiera correspondido al mismo si en vez de ser exonerado hubiera sido dado de baja por cesantía. Los haberes de pensión se mantendrán permanentemente actualizados respecto de los haberes en cuya relación se encuentren establecidos.",
    
    " Capítulo XXIV: Deudos con Derecho a Pensión - Artículo 240": "Se establece como pensión global mínima la suma equivalente al setenta y cinco por ciento (75%) del sueldo y suplementos remunerativos del grado de Oficial con cuatro (4) años de antigüedad de servicios.",

    " Título IV: Gobierno Civil de la Seguridad - Capítulo XXV: Bienestar - Artículo 241": "El Gobierno de la Ciudad Autónoma de Buenos Aires se obliga a garantizar al personal con estado policial de la Policía de la Ciudad los siguientes derechos:\n1. La percepción de los sueldos, suplementos y demás asignaciones que las disposiciones legales determinen para cada grado, cargo y situación de revista.\n2. La jerarquía y el uso del grado correspondiente, con los alcances establecidos en la presente Ley y su reglamentación.\n3. El uso del armamento provisto por la Institución, del uniforme, chaleco balístico, dispositivos de comunicación, insignias, atributos y distintivos propios del grado, antigüedad, especialidad y función de acuerdo a las disposiciones reglamentarias pertinentes.\n4. La capacitación permanente para la mejora del desarrollo de sus funciones y labores policiales.\n5. La estabilidad en el empleo de acuerdo a lo establecido en esta Ley y sus normas reglamentarias.\n6. El desarrollo de la carrera profesional en igualdad de oportunidades.\n7. Los ascensos, conforme a las normas de la reglamentación correspondiente.\n8. El servicio médico-asistencial y social para sí, y los familiares a cargo, conforme a las normas legales y reglamentarias vigentes.\n9. La percepción del haber de retiro para sí y de pensión para sus derechohabientes, conforme a las disposiciones legales sobre la materia.",
    
    " Título IV: Gobierno Civil de la Seguridad - Capítulo XXV: Bienestar - Artículo 242": "El Gobierno de la Ciudad Autónoma de Buenos Aires prevé, por vía reglamentaria, políticas que permitan facilitar al personal mencionado en el artículo 241 el acceso a la vivienda única familiar y la inscripción en establecimientos educativos de la Ciudad de Buenos Aires para sus hijos en edad escolar.",
    
    " Título IV: Gobierno Civil de la Seguridad - Capítulo XXV: Bienestar - Artículo 243": "El Gobierno de la Ciudad de Buenos Aires implementa un Plan de Arraigo del Personal Policial a la Ciudad de Buenos Aires. El Plan de Arraigo contempla acciones tendientes a:\n1. Otorgar avales para contratos de alquiler de inmuebles destinados a vivienda propia única y familiar del personal policial en el territorio de la Ciudad Autónoma de Buenos Aires.\n2. Conceder adelantos sobre los haberes del personal policial, destinados a afrontar total o parcialmente los gastos de depósito y comisión inmobiliaria asociados a la concreción de los contratos de alquiler mencionados en el inciso 1. La reglamentación establece los mecanismos de recupero de los fondos que el Gobierno de la Ciudad deba eventualmente abonar a consecuencia de los avales otorgados, así como los plazos de descuento de los adelantos de haberes que haya solicitado el personal.",
    
    " Título IV: Gobierno Civil de la Seguridad - Capítulo XXV: Bienestar - Artículo 244": "Cuando se produjere el fallecimiento del personal con estado policial como consecuencia de un hecho calificado como 'en y por acto de servicio', los deudos del causante con derecho a pensión perciben por única vez y en conjunto un subsidio equivalente a treinta (30) veces el haber mensual de un Superintendente en actividad con la máxima antigüedad de servicio. Los beneficios se liquidan con arreglo al orden y distribución previstos para el otorgamiento de la pensión por fallecimiento del causante. El mismo subsidio se liquida por única vez al personal con estado policial que resultare con una incapacidad laboral total y permanente para las tareas policiales y civiles, en las circunstancias indicadas en el primer párrafo de este artículo. El beneficio establecido en este Artículo es abonado por la Obra Social del Personal de Seguridad Pública (O.S.Pe.Se.)",
    
    " Título IV: Personal Civil sin Estado Policial de la Policía de la Ciudad de Buenos Aires - Capítulo I: Especialidades y Niveles - Artículo 245": "El personal civil sin estado policial de la Policía de la Ciudad cumple tareas de apoyo al accionar del personal con estado policial, diferenciadas de aquéllas a las que habilita el estado policial.",
    
    " Título IV: Personal Civil sin Estado Policial de la Policía de la Ciudad de Buenos Aires - Capítulo I: Especialidades y Niveles - Artículo 246": "El personal civil sin estado policial se agrupa en las siguientes especialidades:\n1. Profesional. Cumple funciones para cuyo desempeño se requiere título universitario.\n2. Técnico. Cumple funciones para cuyo desempeño se requiere título terciario de una carrera de duración de al menos tres (3) años.\n3. Administrativo. Cumple funciones administrativas para cuyo desempeño se requiere título secundario nacional.\n4. Clero.\n5. Maestranza y servicios generales: Cumple funciones vinculadas con el mantenimiento o funcionamiento de instalaciones técnicas, construcciones, conservación y custodia de materiales y limpieza de dependencias.\nEl Ministro de Justicia y Seguridad puede, por resolución fundada, incrementar, fraccionar o eliminar las especialidades enunciadas.",
    
    " Título IV: Personal Civil sin Estado Policial de la Policía de la Ciudad de Buenos Aires - Capítulo I: Especialidades y Niveles - Artículo 247": "El encuadramiento dentro de una especialidad no otorga al personal una situación jurídica diferenciada sobre las demás especialidades. El Jefe de Policía puede modificar el encuadramiento del personal siempre que se cumplan los requisitos exigidos para la integración a determinada especialidad.",
    
    " Título IV: Personal Civil sin Estado Policial de la Policía de la Ciudad de Buenos Aires - Capítulo I: Especialidades y Niveles - Artículo 248": "El personal de las distintas especialidades se organiza en diez niveles, que se denominan A, B, C, D, E, F, G, H, I y J. Los niveles mencionados se vinculan por relaciones de jerarquía. La reglamentación determina las misiones, funciones y responsabilidades de cada una de los niveles en que se subdividen las especialidades.",

    " Capítulo III - Artículo 250": "El Ministro de Justicia y Seguridad designa al personal civil sin estado policial de las distintas especialidades a través de la realización de concursos públicos de oposición y antecedentes que al efecto se establezcan. En caso de necesidad fundada, el Ministro de Justicia y Seguridad puede designar personal transitorio.",
    
    " Capítulo III - Artículo 251": "El personal civil sin estado policial cesa en sus funciones:\n1. Por renuncia.\n2. Por jubilación.\n3. Por cesantía o exoneración.\n4. Por fallecimiento.\n5. Cuando en los exámenes psicofísicos periódicos se evidenciase la carencia de las aptitudes profesionales y personales indispensables para el normal ejercicio de sus funciones.\n6. Cuando fueran declarados prescindibles por la Junta de Calificaciones.",
    
    " Capítulo III - Artículo 252": "Al personal que cesa en sus funciones por renuncia, se le puede requerir, por razones de servicio, permanecer en el cargo por el término de treinta (30) días si antes no fuera reemplazado o aceptada su dimisión o autorizado a cesar en sus funciones.",

    " Capítulo IV: Estabilidad - Artículo 253": "El personal civil sin estado policial de la Policía de la Ciudad adquiere estabilidad trascurridos los doce (12) meses de efectiva prestación de servicios. Por lo demás son aplicables las disposiciones establecidas en el Título III, Capítulo III del presente Libro.",

     " Capítulo V: Derechos, Deberes y Prohibiciones - Artículo 254": "El personal civil sin estado policial goza de los siguientes derechos:\n1. La percepción de los sueldos, suplementos y demás asignaciones, que las disposiciones legales determinen para cada grado y especialidad.\n2. La capacitación permanente para la mejora del desarrollo de sus funciones y labores.\n3. La estabilidad en el empleo de acuerdo a lo establecido en esta Ley y sus normas reglamentarias.\n4. El desarrollo de la carrera profesional en igualdad de oportunidades.\n5. Los ascensos, conforme a las normas de la reglamentación correspondiente.\n6. El servicio médico-asistencial y social para sí, y los familiares a cargo, conforme a las normas legales y reglamentarias vigentes.",
    
    " Capítulo V: Derechos, Deberes y Prohibiciones - Artículo 255": "El personal civil sin estado policial tiene los siguientes deberes, sin perjuicio de los que se deriven de normas especiales y de la reglamentación de la presente:\n1. Adecuar su conducta pública y privada a las normas éticas acordes a su pertenencia a la institución policial y a su calidad de funcionario público.\n2. Desempeñar su función de acuerdo con las leyes y reglamentaciones vigentes.\n3. Desempeñar eficientemente sus tareas en las condiciones de tiempo, forma, lugar y modalidad determinados por la autoridad competente.\n4. Obedecer toda disposición u orden emanada del superior jerárquico competente, que reúna las formalidades del caso y tenga por objeto la realización de actos de servicio, con los límites establecidos en la Constitución Nacional, en la Constitución de la Ciudad Autónoma de Buenos Aires y en esta Ley.",
    
    " Capítulo V: Derechos, Deberes y Prohibiciones - Artículo 256": "El personal civil sin estado policial tiene las siguientes prohibiciones:\n1. Participar en actividades políticas, partidarias, gremiales o sectoriales, o el desempeño de cargos electivos, mientras se encuentre en actividad.\n2. Patrocinar trámites y gestiones administrativas o judiciales referentes a asuntos de terceros vinculados con la institución, se encuentren o no a su cargo, hasta un año después del egreso.\n3. Dirigir, administrar, representar, patrocinar, asesorar, o de cualquier otra forma prestar servicios a quien gestione o tenga una concesión o sea proveedor del Estado local, o realice actividades reguladas por éste.\n4. Realizar por sí o por cuenta de terceros gestiones tendientes a obtener el otorgamiento de una concesión, adjudicación en la administración pública de la Ciudad o sus Comunas.\n5. Ser proveedor por sí o por terceros del Estado de la Ciudad.\n6. Mantener relaciones contractuales con entidades directamente fiscalizadas por el Estado de la Ciudad.\n7. Representar, patrocinar a litigantes o intervenir en gestiones judiciales o extrajudiciales contra la Ciudad, salvo en causa propia.\n8. Es incompatible el desempeño de un cargo sin estado policial en la Policía de la Ciudad de Buenos Aires con otro nacional, provincial, municipal o de la Ciudad, excepto la docencia y siempre que no exista superposición de horarios.",

    " Capítulo VI: Licencias - Artículo 257": "El personal civil sin estado policial tiene el derecho al uso de las licencias enumeradas en el Título III, Capítulo XVI del presente Libro, con exclusión de cualquier otro régimen que pudiera resultar aplicable.",
    
    " Capítulo VI: Licencias - Artículo 258": "Sin perjuicio de lo expuesto, el personal civil sin estado policial designado transitoriamente para desempeñar funciones en el sector público nacional, provincial, municipal o en la Ciudad Autónoma de Buenos Aires puede solicitar licencia extraordinaria sin goce de haberes por ejercicio transitorio de otro cargo, durante el tiempo en que ejerza en esas funciones. Su otorgamiento queda a criterio del Ministro de Justicia y Seguridad, debiendo establecerse el plazo máximo de su concesión.",
    
    " Capítulo VII: Retribuciones - Artículo 259": "El personal civil sin estado policial en situación de actividad goza del sueldo mensual, suplementos y asignaciones que para cada caso determine la reglamentación correspondiente.",

    " Capítulo VIII: Régimen Disciplinario - Artículo 260": "El personal civil sin estado policial está sujeto a las disposiciones contenidas en la presente Ley en todo lo que refiere al régimen disciplinario, como a las reglamentaciones que al efecto se dicten.",
    
    " Capítulo IX: Régimen Previsional - Artículo 261": "El personal civil sin estado policial se encuentra alcanzado por las previsiones determinadas en la Ley Nacional Nº 24.241 # y sus modificatorias.",

    " LIBRO III: El Cuerpo de Bomberos de la Ciudad de Buenos Aires - Título I: Creación y Dependencia Funcional - Artículo 262": "Créase el Cuerpo de Bomberos de la Ciudad de Buenos Aires para la defensa, prevención, protección y resguardo de personas y bienes en caso de incendio, derrumbe, inundación u otros siniestros y emergencias.",
    
    " LIBRO III: El Cuerpo de Bomberos de la Ciudad de Buenos Aires - Título I: Creación y Dependencia Funcional - Artículo 263": "El Cuerpo de Bomberos de la Ciudad es una institución civil, jerarquizada profesionalmente y auxiliar de la fuerza pública del Estado, con competencia para actuar como auxiliar de la Justicia.",
    
    " LIBRO III: El Cuerpo de Bomberos de la Ciudad de Buenos Aires - Título I: Creación y Dependencia Funcional - Artículo 264": "El Cuerpo de Bomberos depende jerárquica y funcionalmente del Ministerio de Justicia y Seguridad a través de la Subsecretaría de Emergencias o el organismo que la remplace en el futuro. El Ministro de Justicia y Seguridad designa y remueve al personal del Cuerpo de Bomberos.",
    
    " LIBRO III: El Cuerpo de Bomberos de la Ciudad de Buenos Aires - Título I: Creación y Dependencia Funcional - Artículo 265": "El Cuerpo de Bomberos integra el sistema de emergencias y el Sistema Integral de Seguridad Pública del Gobierno de la Ciudad Autónoma de Buenos Aires.",
    
    " LIBRO III: El Cuerpo de Bomberos de la Ciudad de Buenos Aires - Título I: Creación y Dependencia Funcional - Artículo 266": "El Cuerpo de Bomberos integra el Consejo de Seguridad y Prevención del Delito, en los términos de la Ley 1689 (texto consolidado por Ley 5454).",
    
    " LIBRO III: El Cuerpo de Bomberos de la Ciudad de Buenos Aires - Título I: Creación y Dependencia Funcional - Artículo 267": "Colaboran con el Cuerpo de Bomberos en el cumplimiento de sus funciones los bomberos voluntarios y el personal de seguridad privada especializado en asuntos de emergencia. Cuando es requerida su colaboración actúan bajo la dirección, coordinación operativa y control del Cuerpo de Bomberos.",

     "TÍTULO II - PRINCIPIOS - CAPÍTULO I: PRINCIPIOS RECTORES - Artículo 268": "La actuación del personal del Cuerpo de Bomberos en el cumplimiento de sus funciones se sujeta a los siguientes principios rectores:\n1. Planificación estratégica: la actuación se conduce por medio de planes de acción basados en criterios estratégico-institucionales, los que son comprobados mediante la realización de los ejercicios de la gestión.\n2. Innovación tecnológica: Se promueve el uso intensivo de la tecnología para el abordaje de las diferentes problemáticas del entorno social, mejorando la gestión institucional, la transparencia y la protección del personal en el desempeño de sus funciones.\n3. Profesionalización: se desarrolla durante toda la carrera mediante la formación y la capacitación continua y permanente de los integrantes en la adquisición de competencias y habilidades especializadas para el cumplimiento adecuado de sus funciones.\n4. Información estadística confiable: implica la obligación de llevar registros de datos duros sobre siniestros y emergencias, así como del monitoreo del accionar del Cuerpo, a efectos de elaborar informes eficaces sobre la materia.\n5. Bienestar: se promueve el bienestar moral y material del personal mediante la promoción y prevención de la salud tanto en sus aspectos físicos como psíquicos, fomentando un ambiente de trabajo adecuado.\n6. Prevención: mediante el trabajo en el desarrollo de medidas destinadas a reducir el riesgo para personas y bienes en caso de incendio, derrumbe, inundación u otros siniestros y emergencias, y los efectos perjudiciales para la comunidad, con especial atención a los grupos poblacionales más vulnerables.",

    "CAPÍTULO II: CARÁCTER DEL SERVICIO - Artículo 269": "El servicio del Cuerpo de Bomberos no se interrumpe por ningún motivo. Si por cualquier causa, acción u omisión se pone en riesgo la continuidad del servicio se instrumentan las acciones pertinentes para asegurar su prestación en los términos más convenientes para la población. Las tareas que desarrolla el personal del Cuerpo de Bomberos constituyen un servicio público esencial de emergencia destinado a la protección de las personas y bienes, en forma activa y preventiva, en caso de incendios, derrumbes, inundaciones y otros siniestros o emergencias.",

    "CAPÍTULO II: CARÁCTER DEL SERVICIO - Artículo 270": "Los integrantes del Cuerpo de Bomberos deben adecuar su conducta, en el desempeño de sus funciones, al cumplimiento en todo momento de los deberes legales y reglamentarios vigentes, realizando su actividad con el único fin de garantizar la vida, los bienes y la seguridad de las personas, aun a riesgo de su propia vida, actuando con el grado de responsabilidad y profesionalismo que su función exige.",

    " Capítulo III: Principios Básicos de Actuación - Artículo 271": "La actuación del personal del Cuerpo de Bomberos se desarrolla de acuerdo con la plena vigencia de los siguientes principios:\n1. El principio de legalidad, adecuando su conducta y prácticas a las normas constitucionales, legales y reglamentarias vigentes.\n2. El principio de razonabilidad, absteniéndose de realizar cualquier labor funcional que resulte excesiva y contraria a las establecidas por las normas técnicas profesionales correspondientes, y escogiendo las modalidades de intervención adecuadas a la situación objetiva de riesgo o peligro existente, procurando en todo momento utilizar los medios humanos y materiales apropiados a esos efectos.\n3. El principio de responsabilidad, que conlleva la responsabilidad personal y directa por los actos que en su actuación profesional llevare a cabo infringiendo los principios enunciados precedentemente, sin perjuicio de la responsabilidad patrimonial que pudiera corresponder.",
    
    " Capítulo III: Principios Básicos de Actuación - Artículo 272": "Durante el desempeño de sus funciones el personal del Cuerpo de Bomberos adecua su conducta a los siguientes preceptos generales:\n1. Actúa con responsabilidad y respeto a la comunidad, dirigiendo su mayor esfuerzo a adquirir los conocimientos profesionales necesarios para el cabal cumplimiento de su misión y aplicarlos en las intervenciones operativas, protegiendo en todo momento la vida y los bienes de las personas.\n2. Asegura la protección de la integridad física, psíquica y moral de las víctimas involucradas en los siniestros a los que concurre en cumplimiento de su misión.\n3. Impide la violación de normas legales y reglamentarias durante su accionar o el de otras fuerzas, organismos o agencias con las que desarrolle labores conjuntas o combinadas, y en las conductas de personas físicas o jurídicas, públicas o privadas con las que se relacione, dando inmediata cuenta de la inconducta o del hecho de corrupción a la autoridad superior u organismo de control competente.",

    "FUNCIONES del Cuerpo de Bomberos - Artículo 273": "Son funciones del Cuerpo de Bomberos:\n1. La defensa, prevención, protección y resguardo de personas y bienes en el ámbito de su actuación.\n2. Intervenir en todo tipo de siniestros, incendios, inundaciones, accidentes y catástrofes naturales o producidas a consecuencia de la intervención del hombre, con el objeto de procurar su extinción, conjurar sus efectos, auxiliar a las víctimas y realizar todo tipo de tareas operativas profesionales tendientes a paliar sus consecuencias.\n3. Realizar proyectos, estudios, pericias y asesorar a la autoridad competente en todos los temas relacionados a la seguridad siniestral.\n4. Desarrollar tareas de capacitación, análisis e información siniestral, tanto para organismos públicos como privados, conforme a la normativa vigente.\n5. Intervenir en toda campaña y plan preventivo que implemente el Ministerio de Justicia y Seguridad, en los términos que le sea requerido.\n6. Coordinar su esfuerzo operacional con el resto de los organismos que intervienen en la emergencia.\n7. Realizar acciones de prevención e información en beneficio de la comunidad en el ámbito de su competencia.\n8. Facilitar la profesionalización y perfeccionamiento del personal mediante el intercambio de funcionarios con fines de capacitación con organismos similares del país y del exterior.\n9. Realizar las inspecciones, en el ámbito de su competencia, que le fueran solicitadas por la autoridad de aplicación.\n10. Cooperar dentro de sus facultades con la Justicia local, la Justicia Federal, y la de las Provincias, para el cumplimiento de sus funciones jurisdiccionales, cuando así se le solicite, conforme la disponibilidad de los recursos presupuestarios asignados.",

    " Título IV: Organización - Artículo 274": "La conducción del Cuerpo de Bomberos está a cargo de un Jefe, con rango y atribuciones de Director General. En el cumplimiento de sus funciones su jerarquía es equivalente a la de Superintendente de la Policía de la Ciudad. El Jefe del Cuerpo de Bomberos es asistido por un Subjefe.\nEl Jefe de Gobierno designa al Jefe y al Subjefe del Cuerpo de Bomberos a propuesta del Ministro de Justicia y Seguridad.",
    
    " Título IV: Organización - Artículo 275": "El Jefe de Gobierno debe publicar el nombre y antecedentes del candidato para Jefe del Cuerpo de Bomberos de la Ciudad en el Boletín Oficial de la Ciudad y en el sitio de internet oficial del Gobierno de la Ciudad durante diez (10) días hábiles. Los habitantes de la Ciudad y las organizaciones de la sociedad civil pueden presentar observaciones fundadas a la candidatura durante un plazo de diez (10) días hábiles posteriores al fin de la publicación. Vencido el plazo para la presentación de las observaciones, el Jefe de Gobierno efectúa la designación o reinicia el procedimiento establecido en este artículo.",
    
    " Título IV: Organización - Artículo 276": "Corresponde al Jefe del Cuerpo de Bomberos:\n1. Conducir orgánica y funcionalmente la institución, siendo su responsabilidad la organización, prestación y supervisión de los servicios del Cuerpo de Bomberos, en el marco de la Constitución, de la presente Ley y las demás normas legales y reglamentarias aplicables.\n2. Dictar resoluciones e impartir las directivas y órdenes generales o particulares necesarias para el cumplimiento de su misión.\n3. Proponer al Ministro de Justicia y Seguridad, a través de la Subsecretaría de Emergencias o el organismo que en el futuro la reemplace, la estructura orgánica de las dependencias, organizando los servicios a través del dictado de resoluciones internas.\n4. Proponer al Ministro de Justicia y Seguridad, a través de la Subsecretaría de Emergencias o el organismo que en el futuro la reemplace, los ascensos ordinarios del personal.\n5. Proponer al Ministro de Justicia y Seguridad, a través de la Subsecretaría de Emergencias o el organismo que en el futuro la reemplace, ascensos extraordinarios y menciones especiales por actos destacados del servicio, debiendo acreditarse fehacientemente los méritos ante la autoridad competente.\n6. Proponer la realización de convenios con otras organizaciones de Bomberos, nacionales y provinciales, y proponer al Ministro de Justicia y Seguridad, a través de la Subsecretaría de Emergencias o el organismo que en el futuro la reemplace, los relativos a las organizaciones extranjeras con fines de cooperación y reciprocidad.",
    
    " Título IV: Organización - Artículo 277": "Corresponde al Subjefe del Cuerpo de Bomberos acompañar al Jefe en sus funciones y cumplimentar todas aquellas que le sean delegadas, así como reemplazarlo en caso de ausencia, enfermedad, muerte, impedimento temporal, renuncia o remoción, con las mismas funciones y atribuciones de aquel.",
    
    " Título IV: Organización - Artículo 278": "El ámbito de actuación territorial y la esfera de actuación funcional de las unidades operacionales del Cuerpo de Bomberos así como su composición, dimensión y despliegue son establecidas por el Ministerio de Justicia y Seguridad, a través de la Subsecretaría de Emergencias o el organismo que en el futuro la reemplace.",
    
    " Título IV: Organización - Artículo 279": "El Ministerio de Justicia y Seguridad puede establecer el Servicio Complementario de Prevención de Incendios, reglamentar sus condiciones, organizar su prestación y fijar su precio. La organización del Servicio Complementario de Prevención de Incendios se efectúa en exclusivo interés de los particulares que lo contraten en las condiciones que establece la reglamentación, y en ningún caso puede implicar una disminución, menoscabo o afectación de cualquier índole del servicio público brindado por el Cuerpo de Bomberos. Créase el Fondo Especial del Servicio Complementario de Prevención de Incendios, que se integra con los recursos que se obtengan por la prestación de estos servicios a terceros y por las transferencias de crédito que retribuyan los servicios brindados otros órganos o entes del Gobierno de la Ciudad de Buenos Aires o a las Comunas de la Ciudad. Los recursos del Fondo Especial del Servicio Complementario de Prevención de Incendios se dedican a financiar la prestación del servicio y, en caso de existir un excedente, a la adquisición de los bienes destinados al servicio público de prevención de incendios que el Ministerio de Justicia y Seguridad determine.",

     " Título V: Ingreso - Artículo 280": "El ingreso al Cuerpo de Bomberos se produce previa aprobación del Curso de Formación Inicial y de los exámenes que al efecto establezca el Instituto Superior de Seguridad Pública. Los aspirantes no tienen estado oficial de bombero durante su formación inicial y son becarios.",
    
    " Título V: Ingreso - Artículo 281": "Son requisitos para integrar el Cuerpo de Bomberos:\n1. Ser ciudadano argentino nativo o por opción, o extranjero con dos años de residencia efectiva en el país.\n2. Tener, al momento de ingreso, entre 18 y 30 años de edad.\n3. Tener estudios secundarios completos.\n4. Acreditar aptitud psicofísica compatible con la función y tarea a desarrollar.\n5. Declarar bajo juramento cumplir y hacer cumplir la Constitución Nacional y la Constitución de la Ciudad Autónoma de Buenos Aires.\n6. Acreditar una conducta pública adecuada al ejercicio de la función pública y a la función específica que reglamenta el presente Libro.\n7. Aprobar los programas y requisitos de formación y capacitación que establezca el Instituto Superior de Seguridad Pública.\n8. Residir dentro del radio de 80 kilómetros de la Ciudad de Buenos Aires.\n9. Cumplir con las condiciones fijadas por el presente Libro y sus normas reglamentarias.",
    
    " Título V: Ingreso - Artículo 282": "Podrá ingresar al Cuerpo de Bomberos de la Ciudad, personal que acredite suficiente experiencia y conocimientos en el desempeño de las funciones propias del Cuerpo de Bomberos en instituciones similares de la Ciudad de Buenos Aires o de otras jurisdicciones. Para ello la reglamentación establecerá los requisitos de idoneidad que deba cumplir.",
    
    " Título V: Ingreso - Artículo 283": "No pueden desempeñarse como miembros del Cuerpo de Bomberos las siguientes personas:\n1. Quienes hubieran sido condenados por delito doloso o por delito contra la Administración Pública Nacional, Provincial, Municipal o de la Ciudad Autónoma de Buenos Aires, ni quienes hayan sido condenados por crímenes de guerra, contra la paz o contra la humanidad.\n2. Quienes se encuentren procesados, con auto de citación a juicio o acto procesal equivalente por un delito doloso en perjuicio de la administración pública.\n3. Quienes se encuentren inhabilitados para ejercer cargos públicos.\n4. Quienes hubieran sido sancionados con exoneración en cualquier cargo público, hasta tanto no sea dispuesta la rehabilitación.\n5. Quienes hubieran sido sancionados con cesantía conforme a lo que se establezca por vía reglamentaria.",
    
     " Título VI: Del Personal del Cuerpo de Bomberos - Capítulo I: El Personal del Cuerpo de Bomberos - Artículo 284": "Los integrantes del Cuerpo de Bomberos revisten el carácter de funcionarios públicos y en el desempeño de sus funciones como agente de la autoridad sujeto a riesgo profesional, quedan sometidos a las disposiciones del presente Libro, cuentan con los derechos que garantiza y se sujetan a las obligaciones que impone, sin perjuicio de las demás disposiciones legales y reglamentarias aplicables.",
    
    " Título VI: Del Personal del Cuerpo de Bomberos - Capítulo I: El Personal del Cuerpo de Bomberos - Artículo 285": "El personal del Cuerpo de Bomberos no puede desarrollar funciones propias de la gestión económica, contable, presupuestaria y patrimonial del Cuerpo. Sin perjuicio de ello, en aquellos casos en que el personal con estado oficial de bombero presente una disminución permanente de su capacidad laborativa, se podrá autorizar su desempeño en dichas funciones. En este caso, el personal no percibe los suplementos que por la vía reglamentaria se establezcan para retribuir la efectiva prestación de determinados servicios, o aquellos destinados a compensar el riesgo profesional ligados a las actividades propias del Cuerpo de Bomberos.",
    
    " Título VI: Del Personal del Cuerpo de Bomberos - Capítulo I: El Personal del Cuerpo de Bomberos - Artículo 286": "El Ministro de Justicia y Seguridad otorga el correspondiente estado oficial de bombero a los egresados del Instituto Superior de Seguridad Pública.",

     " Capítulo II: Deberes, Obligaciones y Derechos - Artículo 287": "El estado oficial de bombero impone los siguientes deberes esenciales:\n1. Adecuar su conducta pública y privada a normas éticas acordes con su estatus funcional.\n2. Defender, conservar y acrecentar el honor y el prestigio del Cuerpo de Bomberos.\n3. Defender, en toda actuación en la que deba intervenir en cumplimiento de su función, la vida y la propiedad de las personas, aun a riesgo de su propia vida o integridad personal.",

    " Capítulo II: Deberes, Obligaciones y Derechos - Artículo 288": "El estado oficial de bombero impone las siguientes obligaciones esenciales:\n1. Cumplir con el régimen general de la Institución y con el ejercicio de las facultades que por grado y cargo le corresponden.\n2. Aceptar el grado, título y distinciones que le concedan las autoridades competentes de acuerdo con las disposiciones legales en vigencia.\n3. Desempeñar los cargos, funciones y comisiones ordenados por los superiores que en cada caso correspondan de acuerdo con lo que orgánica y reglamentariamente se establezca para cada grado y destino.\n4. Ejercer las facultades disciplinarias propias de su grado y cargo conforme lo determinen las reglamentaciones del Cuerpo.",

    " Capítulo II: Deberes, Obligaciones y Derechos - Artículo 289": "El estado oficial de bomberos confiere los siguientes derechos esenciales:\n1. La percepción de los haberes que para cada grado y situación de revista correspondan, así como la pensión para sus derechohabientes de acuerdo con lo que determine la reglamentación y demás disposiciones legales vigentes en la materia.\n2. La posesión y uso del grado con los alcances establecidos en esta Ley y su reglamentación.\n3. La asignación del cargo que reglamentariamente corresponda a su grado y el ejercicio de las funciones inherentes al mismo.\n4. Uso del uniforme, insignias, distintivos y atributos propios del grado, función y destino que desempeñe.\n5. La capacitación permanente para la mejora del desarrollo de sus funciones y labores específicas.\n6. Las facultades que para el grado y cargo correspondan de acuerdo con las disposiciones legales vigentes o lo que determine la reglamentación de esta Ley.\n7. Los servicios de carácter social y asistencial que legalmente correspondan, para sí y para su grupo familiar.\n8. El desarrollo de la carrera profesional en igualdad de oportunidades.\n9. Los ascensos, conforme a las normas de la reglamentación correspondiente.",

    " Capítulo II: Deberes, Obligaciones y Derechos - Artículo 290": "El personal del Cuerpo de Bomberos en situación de retiro tiene los siguientes derechos:\n1. Percibir los haberes de retiro que le correspondan conforme al grado alcanzado y que sus derechohabientes perciban las pensiones que en cada caso determine la reglamentación.\n2. Puede ocupar cargos públicos y desempeñar funciones privadas.\n3. Usar el uniforme en la forma que determine la reglamentación. En actividades comerciales, políticas o manifestaciones públicas de cualquier índole, no puede hacer uso de su grado, uniformes, distintivos u otros atributos propios de su jerarquía, salvo que expresamente lo autoricen las reglamentaciones vigentes.\n4. Está sujeto al régimen disciplinario con el grado, título y distinciones con que hubiere pasado a retiro, y en las condiciones que establezca la reglamentación.\n5. El personal retirado puede ser convocado a prestar servicio activo por resolución fundada del Ministro de Justicia y Seguridad cuando situaciones excepcionales lo ameriten. La reglamentación establece los recaudos y alcances que debe contener el llamado. En todos los casos la convocatoria reviste el carácter de obligatoria para quien fuere llamado. Los actos cumplidos en virtud de este deber legal son considerados para todos sus efectos como ejercidos por personal en actividad.\n6. El personal convocado no acumula años de servicios ni evoluciona en la carrera salvo situación extraordinaria dispuesta por el Jefe de Gobierno de la Ciudad Autónoma de Buenos Aires.\n7. No tiene facultades disciplinarias excepto que desempeñe funciones conforme lo dispuesto en el punto 4. En ese caso, las tiene exclusivamente respecto del personal que preste servicios directamente a sus órdenes.",

    " Capítulo III: Estabilidad - Artículo 291": "El personal integrante del Cuerpo de Bomberos adquiere estabilidad en el empleo después de transcurridos doce (12) meses de efectiva prestación de servicios como personal de la Institución y una vez que hubiere aprobado las evaluaciones de rendimiento y aptitud que determine la reglamentación. Durante el tiempo que el personal carezca de estabilidad tiene todos los derechos y deberes previstos en esta Ley y dicho lapso debe ser computado para la antigüedad en la carrera profesional del personal.",
    
    " Capítulo III: Estabilidad - Artículo 292": "La estabilidad en el empleo del personal integrante del Cuerpo de Bomberos sólo se pierde por las causales establecidas en la presente Ley, las normas reglamentarias, y previo sumario administrativo, si correspondiese.",
    
    " Capítulo III: Estabilidad - Artículo 293": "La estabilidad en el empleo no comprende a la estabilidad en el cargo o función, ni da derecho a continuar gozando de los suplementos inherentes al mismo.",

    " Capítulo IV: Carrera Profesional - Artículo 294": "El régimen de carrera profesional del Cuerpo de Bomberos se basa en los principios de profesionalización, eficiencia funcional, capacitación permanente y evaluación previa a cada ascenso, atendiendo a la satisfacción plena de las acciones tendientes a resguardar la vida y bienes de las personas en el territorio de la Ciudad Autónoma de Buenos Aires y en el ámbito de su competencia.",
    
    " Capítulo IV: Carrera Profesional - Artículo 295": "Sin perjuicio de lo establecido en el artículo 294 de la presente ley, el personal se desempeña en las diferentes tareas requeridas para el cumplimiento de la misión asignada al Cuerpo, conforme las aptitudes que haya alcanzado en los cursos de capacitación.",
    
    " Capítulo IV: Carrera Profesional - Artículo 296": "El desarrollo de la carrera profesional del personal debe resultar de su opción vocacional y de la formación y capacitación que reciba, del desempeño profesional durante el ejercicio de sus funciones y de las necesidades de la institución. En tal sentido, se prioriza la capacitación adquirida por el personal evitando los cambios de destino que involucren la pérdida de las destrezas alcanzadas.",
    
    " Capítulo IV: Carrera Profesional - Artículo 297": "El personal que haya adquirido una determinada aptitud puede continuar su carrera profesional cumpliendo otras actividades funcionales siempre que reúna los requisitos exigidos, cuando mediaran razones de servicio o de interés institucional.",
    
    " Capítulo IV: Carrera Profesional - Artículo 298": "El nivel académico exigido para el ascenso a cada jerarquía se determina de acuerdo con el siguiente detalle:\nJerarquía Mínimo Nivel Académico Exigible\nPersonal de Conducción Título de Grado\nPersonal de Dirección Título de Grado\nPersonal de Comando de Dotación Título de Pregrado (Terciario)\nPersonal de Dotación Título Secundario\nLos niveles académicos se acreditan con títulos oficiales.",

    " Capítulo V: Jerarquía, Superioridad y Precedencia - Artículo 299": "La jerarquía es el orden que determina las relaciones de superioridad y dependencia. Se establece por grados. Grado es la denominación de cada uno de los niveles de la jerarquía. La escala jerárquica es el conjunto de los grados ordenados y clasificados. Superioridad es la que tiene un integrante del Cuerpo respecto a otro por razones de cargo, de jerarquía y de antigüedad.",

    " Capítulo V: Jerarquía, Superioridad y Precedencia - Artículo 300": "El ejercicio de la superioridad puede tener cuatro modalidades:\n1. La superioridad jerárquica, que es la que se ejerce sobre otro como consecuencia de la posesión de un grado superior en la escala jerárquica.\n2. La superioridad por antigüedad es la que, a igual grado, se determina, sucesivamente, por antigüedad en el grado, por la antigüedad general, por la fecha de ascenso al grado inmediato anterior y por la edad.\n3. La superioridad orgánica, que es la que se ejerce sobre otro como consecuencia de la ocupación de un cargo de la estructura orgánica con funciones de dirección o conducción, independientemente de su grado.\n4. La superioridad funcional, que es la que se ejerce sobre otro durante el desarrollo de una actividad concreta y específica, ordenada por un superior y en la que se asigna responsabilidades y atribuciones precisas de mando a un integrante que tiene un grado o un cargo inferior al de los demás, siempre que medien razones de servicio que lo justifiquen.",

    " Capítulo V: Jerarquía, Superioridad y Precedencia - Artículo 301": "Cuando por cualquier circunstancia el titular del ejercicio del mando no pueda ejercerlo, aunque sea momentáneamente, será ejercido de inmediato por el subordinado que le siga.",

    " Capítulo V: Jerarquía, Superioridad y Precedencia - Artículo 302": "Para el personal del mismo grado, y sin tener en cuenta la antigüedad, se establece el siguiente orden de precedencia:\n1. Personal en situación de actividad.\n2. Personal en situación de retiro llamado a prestar servicios.\n3. Personal en situación de retiro.",

    " Capítulo VI: Escala Jerárquica y Grados - Artículo 303": "El Cuerpo de Bomberos se organiza en un escalafón único.",

    " Capítulo VI: Escala Jerárquica y Grados - Artículo 304": "La escala jerárquica reconoce cuatro categorías:\n1. Cuadro de Conducción\n2. Cuadro de Dirección\n3. Cuadro de Comando de Dotación\n4. Cuadro de Dotación",

    " Capítulo VI: Escala Jerárquica y Grados - Artículo 305": "El escalafón cuenta con los siguientes grados en orden decreciente:\n1. Comandante General\n2. Comandante Director\n3. Comandante\n4. Subcomandante\n5. Capitán\n6. Teniente\n7. Subteniente\n8. Bombero Superior\n9. Bombero calificado\n10. Bombero",

    " Capítulo VI: Escala Jerárquica y Grados - Artículo 306": "El Cuadro de Conducción está integrado por el personal que alcance el grado de Comandante General.\nEl Cuadro de Dirección está integrado por el personal que alcance los grados de Comandante Director, Comandante y Subcomandante.\nEl Cuadro de Comando de Dotación está integrado por el personal que alcance los grados de Capitán, Teniente y Subteniente.\nEl Cuadro de Dotación está integrado por el personal que alcance los grados de Bombero Superior, Bombero calificado y Bombero.",
    
     " Capítulo VII: Designación de Cargos - Artículo 307": "La ocupación de los cargos orgánicos del Cuerpo de Bomberos de la Ciudad será resuelta de acuerdo con el mérito y los antecedentes de los candidatos y siguiendo los mecanismos de selección que se implementen a través de la reglamentación, los cuales deben regirse por los siguientes criterios:\n1. La formación y capacitación profesional.\n2. El desempeño de la carrera profesional.\n3. Los antecedentes funcionales y disciplinarios. La reglamentación determina los grados, el perfil profesional y las destrezas o formación profesionales para la ocupación de cada cargo orgánico del Cuerpo de Bomberos.",
    
    " Capítulo VIII: Ascensos y Promociones - Artículo 308": "Los ascensos y promociones al cuadro de conducción son dispuestos por el Ministro de Justicia y Seguridad. Los correspondientes al cuadro de comando de dotación y cuadro de dirección son dispuestos por el Subsecretario de Emergencias o el organismo que en un futuro lo reemplace, y los del cuadro de dotación son dispuestos por el Jefe del Cuerpo de Bomberos de la Ciudad.\nEl Ministro de Justicia y Seguridad debe publicar la lista de candidatos para el ascenso al cuadro de Conducción en el Boletín Oficial de la Ciudad y en el sitio de Internet del Gobierno de la Ciudad durante diez (10) días, incluyendo los nombres y los antecedentes curriculares de las personas propuestas. Vencido el plazo establecido en el párrafo anterior, el Ministro de Justicia y Seguridad procede a dictar el acto administrativo correspondiente.",
    
    " Capítulo VIII: Ascensos y Promociones - Artículo 309": "El ascenso se otorga siempre al grado inmediato superior. El ascenso puede tener carácter de ordinario o extraordinario y a quien le es otorgado le crea la obligación de prestar servicio efectivo durante un (1) año como mínimo, de acuerdo con lo que determine la reglamentación.",
    
    " Capítulo VIII: Ascensos y Promociones - Artículo 310": "El ascenso ordinario se confiere anualmente para satisfacer las necesidades orgánicas de la institución y abarca al personal que haya cumplido las exigencias establecidas en esta Ley y su reglamentación.",
    
    " Capítulo VIII: Ascensos y Promociones - Artículo 311": "El ascenso extraordinario puede producirse por las siguientes causas:\n1. Actos destacados del servicio cuyo mérito se acredite fehaciente y comprobadamente.\n2. Pérdida grave de las aptitudes físicas o psíquicas o fallecimiento a causa de un acto de los contemplados en el inciso 1.",
    
    " Capítulo VIII: Ascensos y Promociones - Artículo 312": "Los ascensos extraordinarios son concedidos por el Ministro de Justicia y Seguridad, a propuesta del Jefe del Cuerpo de Bomberos y con la conformidad del Subsecretario de Emergencias o el organismo que en el futuro lo reemplace.",
    
    " Capítulo VIII: Ascensos y Promociones - Artículo 313": "La calificación de las aptitudes del personal que se deba considerar, tanto para el ascenso como para la eliminación, está a cargo de las Juntas de Calificaciones, que se integran en el modo y oportunidad en que determine la reglamentación, la cual debe prever su conformación con personal de la Subsecretaría de Emergencias, del Cuerpo de Bomberos, funcionarios designados por el Ministro de Justicia y Seguridad y representantes del Instituto Superior de Seguridad Pública. Las Juntas de Calificaciones son órganos de asesoramiento del Ministro de Justicia y Seguridad, del Subsecretario de Emergencias y del Jefe del Cuerpo de Bomberos, quienes resuelven sobre el particular.",
    
    " Capítulo VIII: Ascensos y Promociones - Artículo 314": "Para los ascensos ordinarios, la reglamentación establece el régimen de calificaciones del personal, los tiempos mínimos de permanencia en el grado, el régimen de promociones y las condiciones de aptitud y formalidades para los ascensos y promociones. Asimismo la reglamentación debe prever mecanismos que habiliten la publicidad y el acceso a la información de los actos administrativos que dispongan los ascensos y promociones en la institución.",
    
    " Capítulo VIII: Ascensos y Promociones - Artículo 315": "La reglamentación establece los mecanismos de la promoción y ascenso a un grado superior dentro de la carrera profesional, la que debe ajustarse a los siguientes requisitos:\n1. La disponibilidad de vacantes en el grado al que se aspira.\n2. La acreditación de los conocimientos profesionales y títulos oficiales requeridos para el desempeño de las funciones o los cargos orgánicos correspondientes al grado a cubrir.\n3. La aprobación de los cursos de ascenso o nivelación.\n4. La declaración de aptitud profesional establecida por un comité de evaluación.\n5. El tiempo mínimo de permanencia en el grado.\n6. La acreditación de las condiciones psicofísicas necesarias.",
    
    " Capítulo VIII: Ascensos y Promociones - Artículo 316": "Sin perjuicio de lo que se establezca en la reglamentación respectiva son causales de inhabilitación para el ascenso y promoción:\n1. Hallarse bajo sumario judicial con auto de procesamiento, auto de citación a juicio o acto procesal equivalente.\n2. Hallarse bajo sumario administrativo por falta grave hasta su resolución.",

     " Capítulo IX: Formación y Capacitación - Artículo 317": "La formación y capacitación permanente del personal del Cuerpo de Bomberos es competencia del Instituto Superior de Seguridad Pública, conforme las disposiciones pertinentes de la presente Ley.",
    
    " Capítulo IX: Formación y Capacitación - Artículo 318": "La formación y capacitación del personal debe garantizar:\n1. El desarrollo de las aptitudes y valores necesarios para el ejercicio responsable de las funciones y labores asignadas, con conciencia ética, solidaria, reflexiva y crítica.\n2. La propensión a un aprovechamiento integral de los recursos humanos y materiales existentes y asignados.\n3. El incremento y diversificación de las oportunidades de actualización y perfeccionamiento del personal.\n4. El logro de la formación y capacitación especializada, científica y técnica general actualizada, procurando siempre su contenido humanístico, sociológico y ético.",
    
    " Capítulo X: Cursos de Ascenso - Artículo 319": "El Instituto Superior de Seguridad Pública imparte los cursos de ascenso mencionados en el inciso 3 del artículo 315 del presente Libro y toma las evaluaciones correspondientes.",
    
    " Capítulo X: Cursos de Ascenso - Artículo 320": "Los cursos de ascenso son diferenciados de acuerdo con la jerarquía de los cursantes.",

    " Capítulo XI: Evaluación Permanente - Artículo 321": "Todo el personal en actividad del Cuerpo de Bomberos debe cumplir obligatoriamente una instancia de evaluación en el Instituto Superior de Seguridad Pública.",
    
    " Capítulo XI: Evaluación Permanente - Artículo 322": "La periodicidad de la evaluación, las competencias a evaluar, los contenidos, los estándares mínimos a aprobar según jerarquía, el régimen de evaluación y demás aspectos necesarios para llevarla a cabo, son determinados por el Instituto Superior de Seguridad Pública.",
    
    " Capítulo XII: Formación de Aspirantes al Cuerpo de Bomberos - Artículo 323": "Los aspirantes a integrar el Cuerpo de Bomberos deben cursar y aprobar el Curso de Formación Inicial, el régimen de prácticas profesionalizantes y las actividades extracurriculares y de extensión que determine el Instituto Superior de Seguridad Pública. Los estudiantes no tienen el estado oficial de bombero durante su formación inicial y son becarios. Al finalizar el Curso de Formación Inicial ingresan al Cuerpo de Bomberos con el grado de Bombero Calificado.",
    
    " Capítulo XII: Formación de Aspirantes al Cuerpo de Bomberos - Artículo 324": "El Instituto Superior de Seguridad Pública determina los requisitos para el ingreso como aspirante a integrar el Cuerpo de Bomberos, los núcleos de formación, la duración del curso, el régimen de cursada, el contenido del diseño curricular, el régimen de asistencia y de evaluación, el régimen de equivalencias con otros estudios superiores, el régimen de prácticas profesionalizantes, las actividades extracurriculares y de extensión y los demás aspectos que hacen a la formación de los futuros Bomberos.",

     "CAPÍTULO XIII - SITUACIONES DE REVISTA - Artículo 325": "Las situaciones de revista del personal del Cuerpo de Bomberos son:\n1. Actividad: es aquella que impone la obligación de desempeñar funciones en el destino que disponga la superioridad.\n2. Retiro: es aquella en la cual, sin perder su grado, el personal cesa en el cumplimiento de funciones con carácter obligatorio.",
    
    "CAPÍTULO XIII - SITUACIONES DE REVISTA - Artículo 326": "El personal con estado oficial de Bombero que revista en actividad puede hallarse en las siguientes situaciones:\n1. Servicio efectivo.\n2. Disponibilidad.\n3. Pasiva.",
    
    "CAPÍTULO XIII - SITUACIONES DE REVISTA - Artículo 327": "El personal con estado oficial de Bombero revista en servicio efectivo cuando se encuentre:\n1. Prestando servicios en el Cuerpo de Bomberos y desempeñe funciones propias de su grado o cumpla comisiones afines al servicio u otras de interés institucional.\n2. En uso de las licencias establecidas en el artículo 160 de esta Ley excepto expresa previsión en contrario en esta ley o en la reglamentación. El tiempo cumplido en servicio efectivo es computado siempre a los fines del ascenso y retiro, excepto en el llamado a prestar servicios.",
    
    "CAPÍTULO XIII - SITUACIONES DE REVISTA - Artículo 328": "El personal del Cuerpo de Bomberos revista en disponibilidad cuando permanece separado de las funciones y tareas ordinarias que le corresponderían por su grado, en los siguientes casos:\n1. Con licencia por enfermedad o accidente desvinculado del servicio, a partir de los seis (6) meses y hasta doce (12) meses como máximo.\n2. Cuando tramitando el retiro voluntario, solicitare conjuntamente el pasaje a esta situación, desde el momento que lo determine el Jefe del Cuerpo de Bomberos.\n3. El sumariado administrativamente, hasta tanto se dicte la resolución definitiva, pudiéndose dejar sin efecto en el transcurso del procedimiento.\n4. En uso de la licencia por estudio o investigaciones científicas, técnicas o culturales cuando la actividad tenga relación con el servicio.\n5. Detenido o con prisión preventiva por hecho vinculado al servicio si no se le imputa la comisión de un delito doloso o que por sus características afecte el prestigio institucional. Esta última circunstancia es establecida por resolución fundada del Ministro de Justicia y Seguridad.\n6. Cuando se encuentre en la situación prevista en el segundo párrafo del Artículo 285.\n7. Con asignación de tareas adecuadas a su condición de incapacidad laboral transitoria, conforme lo dispuesto en el Artículo 330 de la presente. El personal que revista en disponibilidad percibe los haberes determinados en el Artículo 334. El tiempo cumplido en disponibilidad no es computado a los fines del ascenso y solo computa a los fines del retiro.",
    
    "CAPÍTULO XIII - SITUACIONES DE REVISTA - Artículo 329": "El personal del Cuerpo de Bomberos revista en situación pasiva cuando no desempeñe cargo o función alguna, en los siguientes supuestos:\n1. En uso de licencia por enfermedad de tratamiento prolongado, desde los doce (12) meses y hasta un máximo de veinticuatro (24) meses. Vencido este plazo, en caso de no reintegrarse al servicio efectivo debe pasar a retiro o baja obligatoria, según corresponda.\n2. El sometido a sumario administrativo por abandono del servicio, hasta la conclusión del procedimiento.\n3. Con prisión preventiva por hecho vinculado al servicio, cuando se le impute la comisión de un delito doloso, por el tiempo que dure la privación de la libertad a cuya finalización se determina de acuerdo a su responsabilidad, la situación de revista del causante, salvo que con anterioridad se dispusiese la cesantía o exoneración.\n4. Detenido o con prisión preventiva por hecho ajeno al servicio, por el tiempo que dure la privación de la libertad a cuya finalización se determina de acuerdo a su responsabilidad, la situación de revista del causante, salvo que con anterioridad se dispusiese la cesantía o exoneración.\n5. Detenido o sometido a proceso judicial, cuando el hecho que dio motivo a la medida revele grave indignidad o afectare manifiestamente al prestigio de la Institución, mientras se sustancie la causa disciplinaria emergente.\n6. Condenado, si por el carácter y duración de la pena o naturaleza del hecho no procede su separación, mientras dure el impedimento.\n7. El personal respecto del cual se haya solicitado su cesantía o exoneración, hasta que se dicte la resolución definitiva.\n8. En uso de las licencias previstas en el primer párrafo del Artículo 182 y en uso de la licencia por estudio o investigaciones científicas, técnicas o culturales cuando la actividad no tenga relación con el servicio. El tiempo pasado en situación pasiva no se computa para el ascenso ni para el retiro, salvo el personal que haya revistado en esa situación por detención o proceso y fuera absuelto o sobreseído en la causa que lo motivara, en cuyo caso ese tiempo se computará sólo a los fines del retiro. El personal que revista en situación pasiva percibe los haberes determinados en los Artículos 335 a 337 según el caso.",
    
    "CAPÍTULO XIII - SITUACIONES DE REVISTA - Artículo 330": "El personal del Cuerpo de Bomberos puede ser relevado transitoriamente de la obligación de prestar el servicio propio de su grado, asignándosele tareas adecuadas a su condición, conforme los siguientes requisitos:\n1. La asignación debe responder a una incapacidad laboral transitoria, originada en una afección transitoria determinada por la autoridad sanitaria, conforme lo determine la reglamentación.\n2. Las tareas adecuadas pueden desempeñarse por un plazo máximo de dos (2) años en forma continua o discontinua, por la misma o distinta patología. Vencido el plazo de dos (2) años, la autoridad sanitaria resuelve si debe reintegrarse al servicio normal o pasar a retiro o baja definitiva si no pudiese acceder al beneficio previsional.\n3. Agotado el plazo de dos (2) años y reintegrado el causante a sus funciones, no puede volver a hacer uso de este beneficio hasta después de transcurridos cinco (5) años y nunca mientras permanezca en el mismo grado. Caso contrario, previa intervención de la autoridad sanitaria pasa a situación de retiro o baja definitiva.\n4. El personal con asignación de tareas adecuadas es considerado en disponibilidad y percibe los haberes determinados en el Artículo 334.\n5. Las mujeres embarazadas tienen derecho a solicitar la asignación de tareas adecuadas durante el período del embarazo. Revistan en servicio efectivo y perciben la totalidad de los haberes y suplementos que les hubiesen correspondido en el mes inmediato anterior al inicio de las tareas adecuadas.",
    
    "CAPÍTULO XIII - SITUACIONES DE REVISTA - Artículo 331": "El personal del Cuerpo de Bomberos usa obligatoriamente el uniforme reglamentario y su debida identificación en todos los actos de servicio, salvo en los casos de excepción, que por autorización expresa realice la superioridad u orden emanada de autoridad judicial.",

     " Capítulo XIV: Licencias - Artículo 332": "El personal del Cuerpo de Bomberos goza de las licencias contempladas en el Capítulo XVI del Título III del Libro II de esta Ley.",
    
    " Capítulo XV: Sueldos y Asignaciones - Artículo 333": "El personal del Cuerpo de Bomberos en actividad goza del sueldo, bonificaciones, suplementos, viáticos, compensaciones e indemnizaciones que para cada caso determine la reglamentación. La suma que percibe el funcionario por los conceptos señalados precedentemente, excepto las indemnizaciones, se denomina haber mensual.",
    
    " Capítulo XV: Sueldos y Asignaciones - Artículo 334": "El personal del Cuerpo de Bomberos que revista en disponibilidad percibe, salvo expresa disposición en contrario en esta Ley, el cien por ciento (100%) del haber mensual que le pudiera corresponder, excepto los suplementos que por la vía reglamentaria se establezcan para retribuir la efectiva prestación de determinados servicios, y aquéllos destinados a compensar el riesgo profesional ligado a las actividades propias del estado de bombero. Percibe asimismo las asignaciones familiares.",
    
    " Capítulo XV: Sueldos y Asignaciones - Artículo 335": "El personal del Cuerpo de Bomberos que revista en situación pasiva en las circunstancias consignadas en los incisos 2, 3, 4 5, 7 y 8 del Artículo 329 no percibe haberes ni asignaciones familiares. El personal que se encuentra encuadrado en los supuestos previstos en los incisos 1 y 6 del Artículo 329, percibe el cincuenta por ciento (50%) del haber mensual que le pudiera corresponder al personal en disponibilidad, más las asignaciones familiares.",
    
    " Capítulo XV: Sueldos y Asignaciones - Artículo 336": "El personal que haya revistado en situación pasiva por detención o proceso por hecho vinculado al servicio, y resultara absuelto o sobreseído, tiene derecho a percibir el cien por ciento (100%) de los haberes que le hubieran correspondido de revistar en disponibilidad.",
    
    " Capítulo XV: Sueldos y Asignaciones - Artículo 337": "La remuneración debe compensar la responsabilidad inherente al grado, al desempeño del cargo, la mayor atribución de competencias y el rendimiento efectivo en la tarea asignada, para lo cual la reglamentación puede establecer un segmento de remuneración fija y otro variable.",

    " Capítulo XVI: Políticas de Género - Artículo 338": "El Cuerpo de Bomberos se subordina en su conformación y funcionamiento al espíritu antidiscriminatorio establecido en el artículo 11 de la Constitución de la Ciudad Autónoma de Buenos Aires # y su personal se integra de forma proporcional según lo dispuesto en su artículo 36. Tiene en cuenta a su vez los principios dispuestos por la Ley 4376 de Políticas Públicas para el Reconocimiento y Ejercicio Pleno de la Ciudadanía de las Personas Lesbianas, Gays, Trans, Bisexuales e Intersexuales (LGTBI) # (Texto consolidado por Ley 5454).",
    
    " Capítulo XVI: Políticas de Género - Artículo 339": "El Cuerpo de Bomberos guarda una estricta representación de géneros, favoreciendo la incorporación, participación y promoción sin ninguna limitante por género, orientación sexual o identidad de género, ya sea para el acceso efectivo a cargos de conducción, como así también en todos los niveles y áreas.",
    
    " Capítulo XVI: Políticas de Género - Artículo 340": "A los efectos de dar cumplimiento a los artículos 11, 36, 37 y 38 de la Constitución de la Ciudad Autónoma de Buenos Aires y al artículo 5 inciso c de la Ley 4376 # (texto consolidado por Ley 5454) se promoverá a través de la reglamentación de la presente, la modificación de los patrones socioculturales estereotipados con el objeto de eliminar prácticas discriminatorias dentro del Cuerpo de Bomberos, sea estas basadas en la superioridad de género, orientación sexual o identidad de género de su personal.",
    
    " Capítulo XVI: Políticas de Género - Artículo 341": "La reglamentación contemplará las siguientes cuestiones orientadas a favorecer y preservar las condiciones igualitarias en el personal de las fuerzas de seguridad:\n1. Fomenta la plena integración de las mujeres a los puestos de mando y control respetando el régimen de carrera y el plan de ascensos establecidos a tal efecto.\n2. Instituye y fomenta las acciones y disposiciones legales concretas tendientes a garantizar la paridad entre el trabajo realizado y la remuneración recibida en su consecuencia, entre hombres y mujeres.\n3. Prohíbe todas las prácticas que impliquen cualquier forma de segregación y discriminación por estado civil o maternidad.\n4. Promueve la remoción de los obstáculos de cualquier orden que, limitando de hecho la igualdad y la libertad, impidan el pleno desarrollo de la persona y la efectiva participación en el Cuerpo de Bomberos.",

    " Capítulo XVII: Régimen Disciplinario - Artículo 342": "El personal del Cuerpo de Bomberos queda sujeto al régimen disciplinario establecido en el Capítulo XII de la Ley 471 # (texto consolidado por Ley 5454) y sus normas reglamentarias.",
    
    " Capítulo XVIII: Extinción de la Relación de Empleo - Artículo 343": "La relación de empleo del personal del Cuerpo de Bomberos se extingue por las siguientes causas:\n1. Baja voluntaria.\n2. Baja definitiva.\n3. Retiro.",
    
    " Capítulo XVIII: Extinción de la Relación de Empleo - Artículo 344": "La baja voluntaria es el derecho del personal a concluir la relación de empleo con el Cuerpo de Bomberos a solicitud del interesado. Implica la pérdida del estado oficial de bombero conferido en los términos de esta Ley y tiene efecto a partir de su concesión por parte de la institución. Durante los estados de guerra o de sitio y en los casos de conmoción pública su otorgamiento es optativo por parte de la autoridad competente, pero en todos los casos debe ser concedida al finalizar la circunstancia de hecho que motiva su aplazamiento. También puede solicitar la baja el personal retirado.",
    
    " Capítulo XVIII: Extinción de la Relación de Empleo - Artículo 345": "El personal dado de baja a su solicitud puede ser reincorporado siempre que:\n1. Lo solicite dentro del plazo de dos años de hecha efectiva la baja.\n2. El Ministro de Justicia y Seguridad considere conveniente su reincorporación.\n3. Cumpla al momento de la reincorporación con los requisitos establecidos en el Artículo 281, con excepción del consignado en el inciso 2. La reincorporación se efectiviza en el mismo grado y situación de revista que tenía el causante en el momento de su baja. En caso de reincorporarse en actividad ocupa el último puesto en el respectivo grado.",
   
    " Capítulo XVIII: Extinción de la Relación de Empleo - Artículo 346": "La reglamentación fija plazos mínimos de servicio o, en su caso, indemnización, para el personal que luego de haber recibido capacitación solicite su baja voluntaria.",
    
    " Capítulo XVIII: Extinción de la Relación de Empleo - Artículo 347": "La baja definitiva importa la pérdida del estado oficial de bombero y la exclusión definitiva del personal. La baja definitiva es dispuesta en los siguientes casos:\n1. Fallecimiento.\n2. Cesantía o exoneración, cualquiera fuese la antigüedad del personal.\n3. Cuando en los exámenes psicofísicos periódicos se evidenciase la carencia de las aptitudes profesionales y personales indispensables para el normal ejercicio de la función que le compete, y no pudiere ser asignado a otro destino.\n4. Cuando las calificaciones sean inferiores a lo que determine la reglamentación.",
    
    " Capítulo XVIII: Extinción de la Relación de Empleo - Artículo 348": "La baja definitiva puede producirse con derecho a haber de pasividad o sin él. Tiene derecho a haber de pasividad:\n1. El personal - excepto el exonerado - que al momento de la baja hubiese prestado al menos veinte (20) años de servicios computables para el retiro.\n2. El personal que tuviese la baja por las causales dispuestas en los incisos 3 y 4 del artículo 347, y al momento de la baja hubiese prestado al menos diez (10) años de servicios computables para el retiro. En ambos casos el haber de pasividad es equivalente al 82% de lo que hubiese correspondido al causante en caso de retiro conforme la escala dispuesta en el art. 225.",

    " Capítulo XIX: Régimen Previsional - Artículo 349": "El personal del Cuerpo de Bomberos tiene el mismo régimen previsional establecido en esta ley para los miembros de la Policía de la Ciudad, conforme lo dispuesto en el Libro II, Título III, Capítulo XXII de la presente y tiene los mismos derechos, deberes y obligaciones previsionales que el personal con estado policial.",
    
    " Capítulo XX: Bienestar - Artículo 350": "El Gobierno de la Ciudad Autónoma de Buenos Aires se obliga a garantizar al personal del Cuerpo de Bomberos los siguientes derechos:\n1. La percepción de los sueldos, suplementos y demás asignaciones que las disposiciones legales determinen para cada grado, cargo y situación de revista.\n2. La jerarquía y el uso del grado correspondiente, con los alcances establecidos en la presente Ley y su reglamentación.\n3. El uso del uniforme, insignias, atributos y distintivos propios del grado, antigüedad, y función de acuerdo a las disposiciones reglamentarias pertinentes.\n4. La capacitación permanente para la mejora del desarrollo de sus funciones y labores.\n5. La estabilidad en el empleo de acuerdo a lo establecido en esta Ley y sus normas reglamentarias.\n6. El desarrollo de la carrera profesional en igualdad de oportunidades.\n7. Los ascensos, conforme a las normas de la reglamentación correspondiente.\n8. El servicio médico-asistencial y social para sí, y los familiares a cargo, conforme a las normas legales y reglamentarias vigentes.\n9. La percepción del haber de retiro para sí y de pensión para sus derechohabientes, conforme a las disposiciones legales sobre la materia.",
    
    " Capítulo XX: Bienestar - Artículo 351": "El Gobierno de la Ciudad Autónoma de Buenos Aires prevé, por vía reglamentaria, políticas que permitan facilitar al personal mencionado en el artículo 350 el acceso a la vivienda única familiar y la inscripción en establecimientos educativos de la Ciudad de Buenos Aires para sus hijos en edad escolar.\nEl Gobierno de la Ciudad de Buenos Aires implementa un Plan de Arraigo del Personal del Cuerpo de Bomberos a la Ciudad de Buenos Aires. El Plan de Arraigo contempla acciones tendientes a:\n1. Otorgar avales para contratos de alquiler de inmuebles destinados a vivienda propia, única y familiar del personal de bomberos en el territorio de la Ciudad Autónoma de Buenos Aires.\n2. Conceder adelantos sobre los haberes del personal de bomberos, destinados a afrontar total o parcialmente los gastos de depósito y comisión inmobiliaria asociados a la concreción de los contratos de alquiler mencionados en el inciso 1.\nLa reglamentación establece los mecanismos de recupero de los fondos que el Gobierno de la Ciudad deba eventualmente abonar a consecuencia de los avales otorgados, así como los plazos de descuento de los adelantos de haberes que haya solicitado el personal.",
    
    " Capítulo XX: Bienestar - Artículo 352": "Cuando se produjere el fallecimiento del personal del Cuerpo de Bomberos como consecuencia de un hecho calificado como 'en y por acto de servicio', los deudos del causante con derecho a pensión perciben por única vez y en conjunto un subsidio equivalente a treinta (30) veces el haber mensual del Jefe del Cuerpo de Bomberos.\nLos beneficios se liquidan con arreglo al orden y distribución previstos para el otorgamiento de la pensión por fallecimiento del causante.\nEl mismo subsidio se liquida por única vez al personal del Cuerpo de Bomberos que resultare con una incapacidad laboral total y permanente, en las circunstancias indicadas en el primer párrafo de este artículo.\nEl beneficio establecido en este Artículo es abonado por la Obra Social del Personal de Seguridad Pública (O.S.Pe.Se.).",

    "LIBRO IV - Instituto Superior de Seguridad Pública - Título I: Generalidades - Capítulo I: Disposiciones Generales - Artículo 353": "El Instituto Superior de Seguridad Pública se rige, en cuanto a su organización, funcionamiento y competencias, por las disposiciones contenidas en el presente libro.",
    
    "LIBRO IV - Instituto Superior de Seguridad Pública - Título I: Generalidades - Capítulo I: Disposiciones Generales - Artículo 354": "El Instituto Superior de Seguridad Pública es un ente autárquico y descentralizado, en la órbita del Ministerio de Justicia y Seguridad de la Ciudad Autónoma de Buenos Aires.",
    
    "LIBRO IV - Instituto Superior de Seguridad Pública - Título I: Generalidades - Capítulo I: Disposiciones Generales - Artículo 355": "El Instituto Superior de Seguridad Pública se constituye como una instancia de apoyo de la conducción política del Sistema Integral de Seguridad Pública y órgano rector de la formación y capacitación continua y permanente de los actores involucrados en todo el sistema y la producción de conocimientos científicos y técnicos sobre seguridad.",
    
    "LIBRO IV - Instituto Superior de Seguridad Pública - Título I: Generalidades - Capítulo I: Disposiciones Generales - Artículo 356": "No son aplicables, respecto del Instituto Superior de Seguridad Pública ni del personal académico y administrativo que allí se desempeñe, las normas contenidas en las ordenanzas N° 40.593 # y N° 52.136 #, Resolución N° 1278-SEC/97 #, Disposición N° 332/DGES/2003 # y cualquier otra regulación que se oponga a las presentes disposiciones.",

    " Capítulo II: Misión - Artículo 357": "El Instituto Superior de Seguridad Pública tiene la misión de formar profesionalmente y capacitar funcionalmente al personal de la Policía de la Ciudad, al Cuerpo de Bomberos, a los funcionarios responsables de la formulación, implementación y evaluación de las políticas y estrategias de seguridad ciudadana y de la dirección y la administración general del sistema policial, a todos aquellos sujetos públicos o privados vinculados con los asuntos de la seguridad, así como también la investigación científica y técnica en materia de seguridad ciudadana de acuerdo con los principios de objetividad, igualdad de oportunidades, mérito y capacidad.",
    
    " Capítulo II: Misión - Artículo 358": "El Instituto Superior de Seguridad Pública tiene a su cargo la gestión de la formación, capacitación, actualización y entrenamiento periódico de las personas que presten servicios de seguridad privada: vigilancias, custodias y seguridad de personas o bienes, de acuerdo con las disposiciones de la presente Ley y la reglamentación correspondiente.",
    
    " Capítulo II: Misión - Artículo 359": "El presente título establece los principios básicos para la capacitación, formación e investigación científica y técnica en materia de seguridad pública, la formación y capacitación del personal policial, de los funcionarios y personal civil sin estado policial de la Policía de la Ciudad, y la de todas aquellas personas que intervengan en los procesos de formación de políticas públicas en materia de seguridad, así como en la prestación del servicio de seguridad en el ámbito de la Ciudad Autónoma de Buenos Aires.",

    " Capítulo III: Principios Rectores - Artículo 360": "El Instituto Superior de Seguridad Pública, en el desarrollo de su misión y funciones, se sujeta a los siguientes principios rectores:\n1. Formación abierta: como entidad educativa, promueve la formación y la capacitación como herramientas esenciales para la superación de las desigualdades y para el crecimiento personal y profesional y, en tal sentido, apuesta al desarrollo y evolución permanente de una oferta académica abierta a la comunidad y a la generación de conocimientos científicos y técnicos por medio de la investigación en todos los temas relacionados con la seguridad.\n2. Formación en derechos: genera conciencia sobre la importancia de la protección de los derechos y garantías fundamentales de las personas establecidos en la Constitución Nacional #, la Constitución de la Ciudad # y en las Declaraciones, Convenciones, Tratados y Pactos complementarios #, como sustrato básico del significado de la seguridad íntimamente ligado al de la libertad y promoviendo el fiel cumplimiento de las normas constitucionales, legales y reglamentarias vigentes.\n3. Formación de excelencia: constituye una institución de educación superior de excelencia que conforma un espacio para la formación profesional de los actores involucrados en la implementación estratégica de políticas públicas de seguridad y para la investigación científica y técnica en materia de seguridad humana.\n4. Formación en valores: los valores que impregnan la formación y la gestión del Instituto Superior de Seguridad Pública son los de Integridad, Solidaridad, Sabiduría y Profesionalismo (ISSP).\n5. Participación ciudadana: promueve la integración con la comunidad y la participación de los ciudadanos en un espacio de debate público y de encuentro, abierto, que instale la seguridad como una problemática que incumbe a toda la ciudadanía.\n6. Innovación tecnológica: incorpora y desarrolla nuevas tecnologías para mejorar la gestión institucional, la gestión académica, el proceso de enseñanza-aprendizaje, la investigación en seguridad y la generación de información sistemática y confiable sobre temas vinculados a la seguridad.\n7. Investigación en materia criminal: mediante la recopilación de datos y su análisis coopera para la formulación de políticas en el área de la seguridad pública y en el diseño y preparación de las instituciones cuya función sea la lucha contra el delito.\n8. Transparencia y rendición de cuentas: el personal del Instituto Superior de Seguridad Pública tiene la obligación de presentar una declaración jurada patrimonial conforme la normativa vigente.",

    " Capítulo IV: Organización - Artículo 361": "El Instituto Superior de Seguridad Pública está a cargo de un Director con rango y atribuciones de Subsecretario, designado por el Ministro de Justicia y Seguridad o quien lo reemplace en un futuro. El Director integra el Consejo de Seguridad y Prevención del Delito en los términos de la Ley 1689 # (texto consolidado por Ley 5454) y sus modificatorias.",
    
    " Capítulo IV: Organización - Artículo 362": "Para ser Director del Instituto Superior de Seguridad Pública se requiere:\n1. Título universitario de grado.\n2. Ejercicio de la docencia universitaria en la categoría de profesor ordinario, por un término mínimo de cinco (5) años.\n3. Reconocida experiencia en el campo de la seguridad pública.",
    
    " Capítulo IV: Organización - Artículo 363": "No puede ser designado Director:\n1. Quienes hayan sido condenados por incurrir en actos de fuerza contra el orden institucional y el sistema democrático, aún cuando se hubieren beneficiado por un indulto o condonación de la pena.\n2. Quienes registren condena o estén procesados o con auto de citación a juicio o acto procesal equivalente, por violación a los derechos humanos.\n3. Quienes hayan sido condenados por delito doloso de cualquier índole.\n4. Quienes tengan proceso penal pendiente.\n5. Quienes se encuentren inhabilitados para el ejercicio de cargos públicos.\n6. Quienes hayan sido sancionados con exoneración o cesantía en la Administración Pública Nacional, Provincial, Municipal o de la Ciudad Autónoma de Buenos Aires.\n7. Quienes pertenezcan a las Fuerzas Armadas, fuerzas policiales o de seguridad, u organismos de inteligencia y quienes ostenten estado policial o militar.",
    
    " Capítulo IV: Organización - Artículo 364": "Son funciones del Director:\n1. Ejercer el gobierno, administración y representación del Instituto.\n2. Planificar, ejecutar y supervisar las actividades de formación, capacitación e investigación científica y técnica del Instituto.\n3. Elaborar los reglamentos que sean necesarios para el funcionamiento del Instituto y dictar su Estatuto.\n4. Establecer la estructura orgánica del Instituto.\n5. Designar la conducción académica y administrativa del Instituto.\n6. Formalizar acuerdos y convenios con instituciones universitarias públicas o privadas, organismos de investigación científica y tecnológica, instituciones y empresas públicas o privadas, todas ellas de los ámbitos municipal, provincial, nacional, regional e internacional.",

    " Capítulo VI: Áreas de Formación - Artículo 365": "El Instituto Superior de Seguridad Pública cuenta con las siguientes áreas:\n1. El Área de Formación y Capacitación Policial que tiene la responsabilidad de diagramar, brindar y evaluar las carreras y cursos de formación para el personal ingresante a la Policía de la Ciudad y al Cuerpo de Bomberos y para la capacitación, adiestramiento, entrenamiento, perfeccionamiento y actualización permanente a lo largo de toda la carrera profesional en la institución.\n2. El Área de Formación y Especialización en Seguridad, que tiene la responsabilidad de diagramar, brindar y evaluar las carreras y cursos de formación y capacitación de todos aquellos sujetos públicos o privados involucrados en el Sistema Integral de Seguridad Pública y de las personas que presten servicios de seguridad privada, vigilancias, custodias y seguridad de personas o bienes, y la investigación científica y técnica en materia de seguridad.",

     " Título II: Objetivos y Contenidos Generales de la Formación y Capacitación del Personal con Estado Policial - Capítulo I: Objetivos Generales - Artículo 366": "La formación y capacitación debe inculcar un estricto cumplimiento de las normas constitucionales, legales y reglamentarias vigentes. Importa la aprehensión de los conocimientos necesarios para que el personal pueda desempeñar su accionar con objetividad, responsabilidad, respeto a la comunidad, imparcialidad e igualdad en el cumplimiento de la ley, protegiendo los derechos y garantías fundamentales de las personas establecidos en la Constitución Nacional, la Constitución de la Ciudad Autónoma de Buenos Aires y en las Declaraciones, Convenciones, Tratados y Pactos complementarios.",
    
    " Título II: Objetivos y Contenidos Generales de la Formación y Capacitación del Personal con Estado Policial - Capítulo I: Objetivos Generales - Artículo 367": "La formación y capacitación en general tiende a la profesionalización y especialización del desempeño policial de acuerdo a la función específica de cada uno de los cargos que ejerciera el oficial a lo largo de la carrera policial. El plan de formación y capacitación se desarrolla teniendo en cuenta las competencias funcionales necesarias para el desempeño eficiente del cargo.",
    
    " Título II: Objetivos y Contenidos Generales de la Formación y Capacitación del Personal con Estado Policial - Capítulo I: Objetivos Generales - Artículo 368": "La formación y la capacitación se basan fundamentalmente en la labor policial, privilegiándose los aspectos relativos al manejo con la comunidad y la resolución de conflictos de forma autónoma, autosuficiente y responsable.",
    
    " Título II: Objetivos y Contenidos Generales de la Formación y Capacitación del Personal con Estado Policial - Capítulo I: Objetivos Generales - Artículo 369": "A fin de institucionalizar el control sobre la formación y desempeño de todos los grados y niveles dentro de la estructura organizativa de la institución, la formación y capacitación debe incluir el desarrollo permanente de las competencias propias del quehacer policial, siendo su aprobación requisito ineludible para el desempeño en las funciones de mayor jerarquía.",
    
    " Título II: Objetivos y Contenidos Generales de la Formación y Capacitación del Personal con Estado Policial - Capítulo I: Objetivos Generales - Artículo 370": "La capacitación de los oficiales consiste en el adiestramiento, entrenamiento, perfeccionamiento y actualización permanente a lo largo de toda la carrera profesional y está asentada en la producción de capacidades y competencias específicas derivadas de las tareas básicas propias de los perfiles y especialidades policiales.",

    "CAPÍTULO II - CONTENIDOS GENERALES - Artículo 371": "Los contenidos necesarios de la formación y capacitación de los oficiales deben incluir el 'Código de conducta para los funcionarios encargados de hacer cumplir la ley', aprobado por la Asamblea General de las Naciones Unidas en su Resolución 34/169 del 17 de diciembre de 1979, y los 'Principios básicos sobre el empleo de la fuerza y de armas de fuego por los funcionarios encargados de hacer cumplir la Ley', adoptados por el Octavo Congreso de las Naciones Unidas sobre Prevención del Delito y Tratamiento del Delincuente, celebrado en La Habana, Cuba, del 27 de agosto al 7 de septiembre de 1990.",
    
    "CAPÍTULO II - CONTENIDOS GENERALES - Artículo 372": "La formación y capacitación de los oficiales debe abordar un contenido legal y jurisprudencial que inculque el estricto respeto del ordenamiento jurídico vigente a los fines de desarrollar en ellos la comprensión de las actitudes exigidas para responder de manera profesional a las necesidades de la acción policial en una sociedad culturalmente pluralista, en el marco del respeto de las libertades y derechos individuales inherentes a las personas.",
    
    "CAPÍTULO II - CONTENIDOS GENERALES - Artículo 373": "La formación en el uso y manejo de armas de fuego se basa en los principios de proporcionalidad, legalidad y gradualidad. La formación debe prestar especial atención a las alternativas al uso de la fuerza y de armas de fuego, incluida la resolución pacífica de conflictos, la comprensión del comportamiento de las muchedumbres y los métodos de persuasión, así como medidas técnicas, con el fin de limitar el uso de la fuerza y de armas de fuego.",
   
    "CAPÍTULO II - CONTENIDOS GENERALES - Artículo 374": "La capacitación de los oficiales se articula en función a los siguientes núcleos que se constituyen como pautas de formación de la estructura pedagógica y curricular:\n1. El núcleo de especialización policial, destinado a la capacitación especializada en relación con las actividades que habitualmente desarrolla el oficial dentro de la institución, a través de la adquisición de conocimientos, habilidades y aptitudes especiales vinculadas con la seguridad, investigaciones, operaciones especiales, inteligencia criminal y logística policial.\n2. El núcleo de conducción policial, destinado a la capacitación de aquellos oficiales que ejerzan cargos de conducción o dirección superior o media dentro de la institución, comprendiendo contenidos referidos a la gestión de estructuras administrativas y burocráticas, manejo de personal, control y evaluación de estructuras de mando y dirección.\n3. El núcleo de actualización, referido a la continua y generalizada necesidad de actualización en las labores propias del servicio policial, intrínsecamente relacionada con los aspectos inherentes a la seguridad pública.\n4. El núcleo de promoción policial, destinado a la capacitación y preparación de los oficiales que aspiren a ascender al grado jerárquico superior de la carrera profesional policial o a ocupar los cargos orgánicos que correspondan.",
    
    "CAPÍTULO II - CONTENIDOS GENERALES - Artículo 375": "El Instituto Superior de Seguridad Pública desarrolla periódicamente actividades educativas bajo variadas modalidades para continuar la capacitación, actualización y especialización del personal con estado policial.",
    
     "CAPÍTULO I - NÚCLEOS DE FORMACIÓN DE LA ESTRUCTURA PEDAGÓGICA Y CURRICULAR - Artículo 376": "La formación inicial de los aspirantes a Oficial de la Policía de la Ciudad se articula en función a los siguientes núcleos que se constituyen como pautas de formación de la estructura pedagógica y curricular:\n1. El núcleo legal-institucional, dirigido a introducirlos en los contenidos teórico-prácticos relacionados con la normativa vigente en materia de seguridad pública, profundizando sobre las implicancias del ordenamiento jurídico en el desarrollo de la labor policial, en particular los contenidos inherentes a la administración pública, el sistema institucional administrativo, judicial y legislativo, el derecho público y administrativo, el derecho penal y procesal penal, el régimen contravencional y de faltas y los procedimientos administrativos y jurisdiccionales.\n2. El núcleo social-criminológico, orientado a la formación teórico-práctica referida a los conocimientos propios de las ciencias sociales aplicados a las problemáticas delictivas e institucionales referidas a la seguridad pública, tales como los conocimientos propios de la ciencia política, sociología y criminología.\n3. El núcleo derechos humanos y ética profesional, destinado a la formación teórico-práctica en materia de derechos humanos con un enfoque transversal que atraviese los conocimientos propios de la profesión y función policial, contemplando los principios básicos de actuación y resolución de conflictos y mitigación de sus efectos, el respeto de los derechos humanos y demás derechos y garantías legales en el desarrollo de sus funciones propias.\n4. El núcleo policial, orientado a la formación teórico-práctica en los conocimientos propios del ejercicio de las labores policiales, la obtención de los métodos, técnicas y adiestramiento para el desempeño de sus servicios, en especial aquellas referidas a las medidas de seguridad, la gestión policial estratégica y táctica, las acciones técnico-operacionales, de supervisión y de dirección superior policiales, la inteligencia criminal y la logística.\n5. El núcleo de orientación especializada, destinado a la formación práctica en relación a las labores propias del agrupamiento y especialidad seleccionados durante la última etapa de la formación inicial.",
    
    "CAPÍTULO II - REQUISITOS PARA EL INGRESO COMO ASPIRANTE A OFICIAL DE LA POLICÍA DE LA CIUDAD DE BUENOS AIRES - Artículo 377": "Para ingresar al Instituto Superior de Seguridad Pública como aspirante a Oficial de la Policía de la Ciudad se requiere certificar estudios secundarios o polimodal completos y aprobar los requisitos de admisión requeridos por la normativa vigente para ingresar a la fuerza y las etapas del proceso de incorporación.",
    
    "Artículo 378": "Para ser Cadete del Instituto Superior de Seguridad Pública y ser incorporado como alumno al Curso de Formación Inicial para Aspirante a Oficial de la Policía de la Ciudad, además de lo previsto en el artículo anterior, se requiere aprobar el periodo de adaptación establecido en el Reglamento de Cadetes.",
    
    " Capítulo III: Curso de Formación Inicial para Aspirante a Oficial de la Policía de la Ciudad - Artículo 379": "Para egresar como Oficial de la Policía de la Ciudad, el cadete debe aprobar íntegramente el Curso de Formación Inicial para Aspirante a Oficial de la Policía de la Ciudad, incluidas las prácticas profesionalizantes, visitas, seminarios, talleres y conferencias que se establezcan para contribuir a la formación integral técnico humanística del futuro Oficial. La duración del curso no puede ser inferior a un (1) año.",
    
    " Capítulo III: Curso de Formación Inicial para Aspirante a Oficial de la Policía de la Ciudad - Artículo 380": "El contenido del plan de estudios, la organización de la estructura curricular, los contenidos mínimos exigidos y los objetivos para el dictado de cada materia, las prácticas profesionalizantes y sus objetivos, las actividades extracurriculares y de extensión, como así también la duración y características del ciclo lectivo, el régimen y modalidad de cursada, el régimen de evaluaciones y promociones y demás aspectos que hacen al desarrollo del curso son establecidos por el Instituto Superior de Seguridad Pública.",
    
    " Título IV: Cursos de Ascenso para el Personal con Estado Policial - Artículo 381": "El Instituto Superior de Seguridad Pública desarrolla los cursos de ascenso mencionados en esta Ley, teniendo en cuentas las necesidades organizativas y operativas de la fuerza, a requerimiento del Jefe de la Policía de la Ciudad.",
    
    " Título IV: Cursos de Ascenso para el Personal con Estado Policial - Artículo 382": "Los contenidos y objetivos, la duración, el régimen de cursada y la forma de evaluación de los cursos de ascenso son reglamentados por el Instituto Superior de Seguridad Pública.",
    
    " Título IV: Cursos de Ascenso para el Personal con Estado Policial - Artículo 383": "Los cursos de ascenso son diferenciados de acuerdo con la jerarquía y la especialidad de los cursantes.",

     " Título VI: Formación y Capacitación del Personal Civil sin Estado Policial - Artículo 388": "Para desempeñarse como personal civil sin estado policial de la Policía de la Ciudad se requiere haber aprobado un curso de formación inicial conforme a la reglamentación que establezca el Instituto Superior de Seguridad Pública.",
    
    " Título VI: Formación y Capacitación del Personal Civil sin Estado Policial - Artículo 389": "La formación básica del personal civil sin estado policial transmite a los cursantes conocimientos sobre el marco institucional y legal de la Ciudad de Buenos Aires, sobre la normativa que regula el sistema de seguridad local y la que rige la institución policial, su organización, misión, funciones y principios básicos de actuación.",
    
    " Título VI: Formación y Capacitación del Personal Civil sin Estado Policial - Artículo 390": "La reglamentación establece todos los aspectos vinculados a la formación del personal civil sin estado policial y las futuras capacitaciones y actualizaciones que se dicten de acuerdo con las distintas especialidades funcionales que se requieran.",
    
    " Título VII: Objetivos y Contenidos de la Formación y Capacitación del Cuerpo de Bomberos de la Ciudad - Artículo 391": "La formación y capacitación debe inculcar una estricta observancia de las normas constitucionales, legales y reglamentarias vigentes y el desempeño de la función con objetividad, responsabilidad, respeto a la comunidad e imparcialidad en el cumplimiento de su misión de resguardar y garantizar la seguridad de las personas y bienes en todo el territorio de la Ciudad Autónoma de Buenos Aires.",
    
    " Título VII: Objetivos y Contenidos de la Formación y Capacitación del Cuerpo de Bomberos de la Ciudad - Artículo 392": "La formación y capacitación en general tiende a la profesionalización, la especialización y la eficiencia funcional de los integrantes del Cuerpo de Bomberos, y al desarrollo permanente de las competencias necesarias para su eficaz desempeño de acuerdo con su función específica.",
    
    " Título VII: Objetivos y Contenidos de la Formación y Capacitación del Cuerpo de Bomberos de la Ciudad - Artículo 393": "El proceso formativo contempla objetivos de formación teórica, práctica y física continuada y promueve todos aquellos estudios que puedan tener utilidad para el desarrollo técnico-profesional de los estudiantes en las diferentes especialidades operativas, investigativas, técnicas y logísticas.",
    
    " Título VIII: Formación de los Aspirantes al Cuerpo de Bomberos de la Ciudad - CAPÍTULO I: Requisitos para el Ingreso como Aspirante al Cuerpo de Bomberos de la Ciudad - Artículo 394": "Para ingresar al Instituto Superior de Seguridad Pública como aspirante al Cuerpo de Bomberos se requiere certificar estudios secundarios o polimodal completos y aprobar los requisitos de admisión requeridos por la normativa vigente y las etapas del proceso de incorporación.",
    
    " Título VIII: Formación de los Aspirantes al Cuerpo de Bomberos de la Ciudad - CAPÍTULO I: Requisitos para el Ingreso como Aspirante al Cuerpo de Bomberos de la Ciudad - Artículo 395": "Para ser incorporado como alumno al Curso de Formación Inicial para Aspirante a Bombero Calificado del Cuerpo de Bomberos, además de lo previsto en el artículo 357, se requiere aprobar el período de adaptación establecido en el reglamento del Instituto Superior de Seguridad Pública.",
    
    " Título VIII: Formación de los Aspirantes al Cuerpo de Bomberos de la Ciudad - CAPÍTULO II: Curso de Formación Inicial para Aspirante a Bombero Calificado del Cuerpo de Bomberos de la Ciudad - Artículo 396": "Para egresar como Bombero Calificado del Cuerpo de Bomberos de la Ciudad, se debe aprobar íntegramente el Curso de Formación Inicial para aspirante a Bombero Calificado, incluidas las prácticas profesionalizantes, visitas, seminarios, talleres y conferencias que se establezcan para contribuir a la formación integral técnico humanística del futuro Bombero.",
    
    " Título VIII: Formación de los Aspirantes al Cuerpo de Bomberos de la Ciudad - CAPÍTULO II: Curso de Formación Inicial para Aspirante a Bombero Calificado del Cuerpo de Bomberos de la Ciudad - Artículo 397": "El contenido del plan de estudios, la organización de la estructura curricular, los contenidos mínimos exigidos y los objetivos para el dictado de cada materia, las prácticas profesionalizantes y sus objetivos, las actividades extracurriculares y de extensión, como así también la duración y características del ciclo lectivo, el régimen y modalidad de cursada, el régimen de evaluaciones y promociones y demás aspectos que hacen al desarrollo del curso son establecidos por el Instituto Superior de Seguridad Pública.",

    " Título IX: Cursos de Ascenso para el Personal del Cuerpo de Bomberos - Artículo 398": "El Instituto Superior de Seguridad Pública desarrolla los cursos de ascenso mencionados en esta Ley, teniendo en cuenta las necesidades organizativas y operativas de la fuerza, a requerimiento del Subsecretario de Emergencias de la Ciudad de Buenos Aires o del organismo que en el futuro lo reemplace.",
    
    " Título IX: Cursos de Ascenso para el Personal del Cuerpo de Bomberos - Artículo 399": "Los contenidos y objetivos, la duración, el régimen de cursada y la forma de evaluación de los cursos de ascenso son reglamentados por el Instituto Superior de Seguridad Pública.",
    
    " Título IX: Cursos de Ascenso para el Personal del Cuerpo de Bomberos - Artículo 400": "Los cursos de ascenso son diferenciados de acuerdo con la jerarquía de los cursantes.",

    " Título X: Plan de Evaluación del Personal del Cuerpo de Bomberos - Artículo 401": "Todo el personal del Cuerpo de Bomberos en actividad debe cumplir obligatoriamente una instancia de evaluación en el Instituto Superior de Seguridad Pública.",
    
    " Título X: Plan de Evaluación del Personal del Cuerpo de Bomberos - Artículo 402": "La instancia de evaluación se constituye en una estrategia de seguimiento de las capacidades técnicas y del rendimiento físico del personal con el objetivo de mantener y potenciar las condiciones más idóneas para el cumplimiento de la función del Cuerpo de Bomberos garantizando el incremento, la diversificación de las posibilidades de actualización y el perfeccionamiento del personal.",
    
    " Título X: Plan de Evaluación del Personal del Cuerpo de Bomberos - Artículo 403": "La periodicidad de la evaluación, las competencias a evaluar, los contenidos de cada una, los estándares mínimos a aprobar según jerarquía, el régimen de evaluación y demás aspectos vinculados a la evaluación son determinados por el Instituto Superior de Seguridad Pública.",
    
    " Título X: Plan de Evaluación del Personal del Cuerpo de Bomberos - Artículo 404": "La evaluación debe incluir, por lo menos, una instancia de actualización académica y una de condición física y atlética.",
    
    " Título XI: Formación y Especialización en Seguridad Pública - Artículo 405": "La formación y capacitación general en materia de seguridad pública está destinada a todos aquellos funcionarios y personal que integra los organismos públicos involucrados en el Sistema Integral de Seguridad Pública y a los que intervengan en los procesos de elaboración, ejecución y evaluación de estrategias y políticas públicas en materia de seguridad, como así también a todos los ciudadanos interesados en formarse en temas de seguridad pública.",
    
    " Título XI: Formación y Especialización en Seguridad Pública - Artículo 406": "Los objetivos generales de la formación en seguridad pública consisten en generar conocimientos, actitudes, habilidades y elementos procedimentales, basados en estudios científicos y tecnológicos para desempeñarse en las distintas especialidades que conforman el área de la seguridad pública, integrando los campos de formación general, formación de fundamento, formación específica y de la práctica profesionalizante.",
    
    " Título XII: Formación y Capacitación en Seguridad Privada - Artículo 407": "El Instituto Superior de Seguridad Pública desarrolla, organiza y certifica la formación inicial, las capacitaciones especiales, la actualización y el entrenamiento periódico obligatorio del personal dedicado a la prestación de servicios de seguridad privada: vigilancias, custodias y seguridad de personas y bienes, conforme lo dispuesto en el Libro VI, Título XII.",
    
    " Título XII: Formación y Capacitación en Seguridad Privada - Artículo 408": "Las tareas de formación inicial, las capacitaciones especiales, la actualización y el entrenamiento periódico obligatorio pueden llevarse a cabo en el Instituto Superior de Seguridad Pública o delegarse por este en establecimientos públicos o privados, los cuales deben reunir los requisitos necesarios para garantizar el aprendizaje, práctica y perfeccionamiento del personal.",
    
    " Título XII: Formación y Capacitación en Seguridad Privada - Artículo 409": "El Instituto Superior de Seguridad Pública establece por vía de reglamentación los requisitos que deben reunir los institutos públicos y privados para ser autorizados para brindar las capacitaciones, otorga la autorización correspondiente, controla la realización y la evaluación de los cursos que se brinden.",
            
    " Libro V: Obra Social - Título I: Creación de la Obra Social, Régimen, Objetivos y Acciones - Artículo 410": "Créase la Obra Social del Personal de Seguridad Pública de la Ciudad Autónoma de Buenos Aires (O.S.Pe.Se.), continuadora de la Obra Social de la Policía Metropolitana (O.S.P.O.M.E.) creada por Ley 2894 (texto consolidado por Ley 5454), sin adhesión a las Leyes Nacionales Nº 23.660 y 23.661. Tiene carácter de Ente Público no Estatal, con individualidad jurídica, financiera y administrativa, con capacidad de estar en juicio y carácter de sujeto de derecho, con el alcance que establece el Código Civil y Comercial de la Nación.",
    
    " Libro V: Obra Social - Título I: Creación de la Obra Social, Régimen, Objetivos y Acciones - Artículo 411": "La O.S.Pe.Se. se rige por:\n1. La Constitución de la Ciudad Autónoma de Buenos Aires.\n2. Las previsiones de la presente Ley.\n3. Las disposiciones y reglamentaciones que adopten sus órganos de conducción.\n4. La Ley 153 (texto consolidado por Ley 5454) de la Ciudad Autónoma de Buenos Aires.",
    
    " Libro V: Obra Social - Título I: Creación de la Obra Social, Régimen, Objetivos y Acciones - Artículo 412": "La O.S.Pe.Se. tiene como objeto principal la prestación de servicios de salud que contengan acciones colectivas e individuales de promoción, prevención, atención, recuperación y rehabilitación, como otros de carácter social.",
    
    " Libro V: Obra Social - Título I: Creación de la Obra Social, Régimen, Objetivos y Acciones - Artículo 413": "La O.S.Pe.Se. tiene su domicilio legal en la Ciudad Autónoma de Buenos Aires.",
    
    " Libro V: Obra Social - Título I: Creación de la Obra Social, Régimen, Objetivos y Acciones - Artículo 414": "La O.S.Pe.Se. puede realizar las siguientes acciones destinadas al cumplimiento de sus fines:\n1. Realizar presentaciones y gestiones ante organismos y entidades, públicas y privadas de nuestro país y del exterior, tendientes a mejorar y fortalecer las perspectivas de la gestión institucional y el desenvolvimiento de sus actividades.\n2. Gerenciar y administrar servicios de salud, por sí o con la participación de terceros, tanto los que resulten propios a la entidad, como aquellos a los que accediera a través de convenios, licitaciones, concesiones o contratos.\n3. Celebrar convenios, acuerdos y contratos con organizaciones y entidades, nacionales, extranjeras e internacionales, públicas o privadas.\n4. Celebrar convenios con el objetivo de brindar cobertura de servicios de salud, con la Superintendencia de Bienestar de la Policía Federal Argentina, con otras obras sociales nacionales, provinciales, municipales, con agentes del seguro de salud, con entidades aseguradoras, gerenciadoras, prestadoras de servicios y empresas de medicina prepaga; y participar en licitaciones y concursos vinculados al gerenciamiento y prestaciones de servicios de salud.\n5. Administrar los bienes de la entidad, adquirir y transferir bienes muebles e inmuebles, darlos o tomarlos en arrendamiento, constituir sobre ellos derechos reales, aceptar donaciones o legados sin cargo.\n6. Contratar todos aquellos bienes y servicios que resulten necesarios para el desenvolvimiento de sus actividades.\n7. Gestionar la obtención de recursos y financiamiento interno y externo, proveniente de organismos nacionales, extranjeros e internacionales, gubernamentales o privados y realizar, conforme a la normativa y condiciones de rigor, todo otro tipo de operación bancaria, financiera y crediticia que resulte conveniente a los fines de la entidad.\n8. Desarrollar toda otra acción que resulte necesaria o conveniente para el cumplimiento de los fines institucionales.",

    "TÍTULO II: Dirección y Administración - Artículo 415": "La O.S.Pe.Se. es conducida y administrada por un Consejo Directivo, integrado por un Presidente, un Vicepresidente, cuatro Directores titulares y cuatro suplentes. Son designados y removidos por el Poder Ejecutivo, con intervención del Ministerio de Justicia y Seguridad. Duran en sus cargos dos (2) años, pudiendo ser renovados.",
    
    "TÍTULO II: Dirección y Administración - Artículo 416": "Los integrantes del Consejo Directivo son personal y solidariamente responsables por los actos y hechos ilícitos en los que pudieren incurrir con motivo y en ocasión del ejercicio de sus funciones.",
    
    "TÍTULO II: Dirección y Administración - Artículo 417": "Para ser miembro del Consejo Directivo se requiere ser argentino, por opción o naturalizado, mayor de edad y no encontrarse alcanzado por cualquiera de los siguientes impedimentos:\n1. Haber sido condenado por delito doloso o culposo, en el país o en el extranjero, siempre que en éste último caso el hecho constituya delito en la legislación de la República Argentina.\n2. Hallarse bajo sumario judicial con auto de procesamiento, citación a juicio o acto procesal equivalente por un delito doloso en perjuicio de la Administración pública nacional, provincial o de la Ciudad de Buenos Aires.",
    
    "TÍTULO II: Dirección y Administración - Artículo 418": "Son funciones y atribuciones del Consejo Directivo:\n1. Ejercer la Administración de la O.S.Pe.Se.\n2. Cumplir y hacer cumplir las normas legales que rigen el funcionamiento de la O.S.Pe.Se. y los reglamentos internos que se dicten en consecuencia.\n3. Evaluar permanentemente la gestión técnica del personal de la O.S.Pe.Se.\n4. Brindar la información que le requiera la sindicatura interna en relación a la administración y los estados contables.\n5. Dictar las normas reglamentarias necesarias para el efectivo cumplimiento de lo dispuesto en el presente Libro.\n6. Dictar su reglamento interno.\n7. Realizar las contrataciones de bienes, servicios y personal necesarias para cumplir los fines de la Obra Social.\n8. Administrar los bienes de la entidad conforme a la normativa aplicable y aprobar la compraventa de inmuebles.\n9. Considerar y aprobar el presupuesto anual de gastos y cálculo de recursos, así como los Balances generales y las cuentas de inversión como la Memoria de cada ejercicio.\n10. Establecer condiciones y procedimientos que posibiliten la percepción de los distintos tipos de recursos e ingresos que corresponden a la Obra Social.\n11. Aprobar acuerdos, convenios, contrataciones con organismos de la Seguridad Social y del sector público y privado, concesiones que realice la entidad conforme al régimen y procedimientos que a tal efecto se establezcan, como también las transacciones judiciales o extrajudiciales.\n12. Contraer préstamos y otras obligaciones en general con entidades financieras y organismos públicos o privados, nacionales o internacionales.\n13. Definir los planes de salud que desarrollará la Obra Social, así como las diversas modalidades de los servicios prestacionales.\n14. Establecer los regímenes aplicables para la afiliación y adhesión de los beneficiarios.\n15. Aprobar el esquema de organización y gerenciamiento de la entidad, comprensivo de sus unidades, servicios y actividades, los diversos reglamentos a aplicarse, tales como los de compras y contrataciones de bienes y servicios, así como los manuales de procedimientos.\n16. Designar, promover, remover y suspender al personal de la Institución.\n17. Establecer y reglamentar todo lo atinente al régimen laboral y de administración de sus recursos humanos.\n18. Desarrollar toda otra acción que resulte necesaria para el cumplimiento de los fines institucionales.",
    
    "TÍTULO II: Dirección y Administración - Artículo 419": "Son funciones y atribuciones del Presidente:\n1. Ejercer la representación legal de la O.S.Pe.Se.\n2. Convocar y presidir las reuniones del Consejo Directivo.\n3. Dictar las resoluciones que resulten necesarias a los fines del funcionamiento de la O.S.Pe.Se.\n4. Adoptar ad referéndum del Consejo Directivo las medidas que, siendo competencia de este último no admitan dilación, sometiéndolas a su consideración en la reunión subsiguiente al momento de su adopción.\n5. Suscribir conjuntamente con el Responsable de Actas todos los convenios que obliguen a la Obra Social.",
    
    "TÍTULO II: Dirección y Administración - Artículo 420": "Son funciones y atribuciones del Vicepresidente:\n1. Colaborar con el Presidente en el ejercicio de sus funciones.\n2. Ejercer las funciones que le sean encomendadas por el Presidente.\n3. Reemplazar al Presidente, en caso de vacancia o ausencia temporaria, ad referéndum de la aprobación de su gestión por parte del Presidente.\n4. Intervenir en la confección del programa de prestaciones médico asistenciales y de promoción social.",
    
    "TÍTULO II: Dirección y Administración - Artículo 421": "El Consejo Directivo celebrará por lo menos dos (2) sesiones mensuales y se constituirá con mayoría absoluta de sus miembros, debiendo uno de ellos ser el Presidente o Vicepresidente. El Presidente podrá convocar a reuniones extraordinarias por sí o a solicitud de dos (2) de los miembros del Consejo Directivo. Las decisiones que adopte el Consejo Directivo serán por mayoría de sus miembros titulares presentes. El Presidente tendrá doble voto en caso de empate.",
    
    "TÍTULO II: Dirección y Administración - Artículo 422": "Las decisiones que adopte el Consejo Directivo serán por mayoría de sus miembros titulares presentes. El Presidente tendrá doble voto en caso de empate.",
    
    "TÍTULO III: Fiscalización - Artículo 423": "La Fiscalización de la O.S.Pe.Se. está a cargo de un Síndico designado y removido por el Poder Ejecutivo, con intervención del Ministerio de Justicia y Seguridad. Dura en su función dos (2) años, pudiendo ser renovado.",
    
    "TÍTULO III: Fiscalización - Artículo 424": "Son deberes y funciones del Síndico:\n1. Controlar el cumplimiento del presente Libro como del conjunto de normas que regulen el funcionamiento de la entidad.\n2. Vigilar todas las operaciones contables, financieras y patrimoniales de la O.S.Pe.Se.\n3. Dictaminar sobre los presupuestos, memorias, balances y cuentas de gastos e inversiones.\n4. Informar periódicamente al Consejo Directivo y al Ministerio de Justicia y Seguridad sobre la situación económico financiera.\n5. Asistir con voz pero sin voto a las sesiones del Consejo Directivo, y solicitar al Presidente de la O.S.Pe.Se. la convocatoria a tal cuerpo orgánico cuando a su juicio el asunto lo requiera.",
    
    "TÍTULO III: Fiscalización - Artículo 425": "Sin perjuicio de los cometidos y responsabilidades asignados al Síndico de la O.S.Pe.Se. el Ministerio de Justicia y Seguridad solicitará los informes correspondientes a su gestión que considere pertinentes.",

      " Título IV: Patrimonio, Recursos y Operaciones Financieras - Artículo 426": "Constituyen el patrimonio de la Obra Social:\n1. Los bienes muebles e inmuebles que adquiera en lo sucesivo la Obra Social.\n2. Los Fondos de reserva que cree el organismo con el producto de sus operaciones.\n3. Los fondos que le destine el Gobierno de la Ciudad Autónoma de Buenos Aires, como también aquellos que aporten otras entidades que participen de la gestión de la Obra Social.\n4. Las donaciones, cesiones, subsidios y legados que acepte.\n5. Todo otro bien o recurso que se integre atendiendo a las finalidades de la entidad.",
    
    " Título IV: Patrimonio, Recursos y Operaciones Financieras - Artículo 427": "Los bienes inmuebles de la entidad, sus operaciones, actos, contratos y los actos cumplidos por sus representantes en tal carácter están exentos de todo impuesto establecido en esta jurisdicción. El Consejo Directivo queda facultado para acordar con autoridades nacionales o provinciales cuando corresponda, similar exención.",
    
    " Título IV: Patrimonio, Recursos y Operaciones Financieras - Artículo 428": "La Obra Social tiene los siguientes recursos:\n1. Las contribuciones a cargo del empleador y los aportes a cargo de los trabajadores que prestan servicios en relación de dependencia:\na. Una contribución a cargo del Gobierno de la Ciudad Autónoma de Buenos Aires del ocho por ciento (8 %) sobre las remuneraciones de todo el personal en actividad que se desempeñe como personal policial o civil en la Policía de la Ciudad, el Cuerpo de Bomberos y el Instituto Superior de Seguridad Pública, para la cobertura de dichos agentes y su grupo familiar.\nb. Un aporte a cargo de todo el personal en actividad que se desempeña como personal policial o civil en la Policía de la Ciudad, el Cuerpo de Bomberos, y el Instituto Superior de Seguridad Pública, del ocho por ciento (8 %) sobre sus remuneraciones, para su cobertura y la de todo su grupo familiar.\nc. Un aporte, en caso de afiliación voluntaria, a cargo del afiliado retirado, pensionado o jubilado de Policía de la Ciudad, del Cuerpo de Bomberos y del Instituto Superior de Seguridad Pública del tres por ciento (3%) del haber de retiro, jubilación o pensión y suplementos hasta su concurrencia con el haber mínimo y del seis por ciento (6%) sobre los montos que lo excedan.\n2. Los ingresos provenientes de ventas de bienes muebles e inmuebles, como de las concesiones y arrendamientos que efectuare.\n3. Los derechos, aranceles, co seguros y otras actividades que realice.\n4. Los recursos que por ley se le asigne, así como los provenientes de donaciones, legados y subsidios.\n5. El superávit obtenido al cierre del ejercicio financiero que será contabilizado en el ejercicio siguiente.\n6. Los fondos provenientes de créditos obtenidos y de las inversiones que se efectúen.\n7. Todo otro ingreso derivado de las acciones y actividades que desarrolle la entidad.\n8. Las contribuciones y aportes establecidos en el inciso 1, apartados a, b y c se liquidarán excluyendo de su cálculo a las retribuciones no remunerativas.\n9. Todo otro recurso que no contravenga las disposiciones del Estatuto y la legislación vigente.",
    
    " Título IV: Patrimonio, Recursos y Operaciones Financieras - Artículo 429": "Los afiliados de todas las categorías y el Gobierno de la Ciudad Autónoma de Buenos Aires se encuentran excluidos de los aportes y las contribuciones, establecidas en las previsiones Ley 472 # (texto consolidado por Ley 5454) y de cualquier otro que en un mismo sentido se pudiese establecer en el futuro.",

    " Título V: Beneficiarios - Artículo 430": "Serán afiliados titulares de la O.S.Pe.Se. con derecho a gozar de los servicios y prestaciones que brinde:\n1. El personal en actividad de la Policía de la Ciudad, tengan o no estado policial y del Cuerpo de Bomberos.\n2. El personal del Instituto Superior de Seguridad Pública.\n3. El personal que integra la Oficina de Transparencia y Control Externo de la Policía de la Ciudad creada por el artículo 34 de esta Ley.",
    
    " Título V: Beneficiarios - Artículo 431": "Quedan también incluidos en calidad de beneficiarios, los grupos familiares primarios del personal indicado en el artículo 430, entendiéndose por grupo familiar primario el integrado por:\n1. El cónyuge del afiliado titular.\n2. Los hijos solteros hasta los veintiún (21) años, no emancipados.\n3. Los hijos solteros mayores de veintiún (21) años y hasta los veinticinco (25) años inclusive, que estén a exclusivo cargo del afiliado titular y que cursen estudios regulares oficialmente reconocidos por la autoridad pertinente.\n4. Los hijos incapacitados y a cargo del afiliado titular, mayores de veintiún (21) años.\n5. Los menores cuya guarda y tutela haya sido acordada por autoridad judicial o administrativa.\n6. Las personas que convivan con el afiliado titular y reciban del mismo ostensible trato familiar, según la acreditación que determine la reglamentación.",
    
    " Título V: Beneficiarios - Artículo 432": "Serán afiliados voluntarios de la O.S.Pe.Se. con derecho a gozar de los servicios y prestaciones que brinde:\n1. El personal retirado con derecho a haber, pensionados y jubilados de la Policía de la Ciudad.\n2. El personal retirado con derecho a haber y los pensionados del Cuerpo de Bomberos.\n3. El personal jubilado del Instituto Superior de Seguridad Pública.",
    
    " Título VI: Asignación de Recursos - Artículo 433": "La Obra Social planifica y organiza la prestación de sus servicios otorgando absoluta prioridad a las acciones orientadas a la prevención, atención y recuperación de la salud de sus afiliados, estando facultado el Consejo Directivo a aprobar todas las disposiciones necesarias para posibilitar tal objetivo.",
    
    " Título VI: Asignación de Recursos - Artículo 434": "A fin de favorecer los objetivos institucionales planteados, corresponde al Consejo Directivo contemplar que dentro de la planificación y funcionamiento de la Obra Social se asegure que:\n1. El presupuesto general de la entidad, así como su efectiva ejecución, prevea que los recursos económicos asignados al otorgamiento de los servicios y prestaciones de salud, en forma directa, no resulte inferior al ochenta por ciento (80%) del total de los recursos disponibles.\n2. Los gastos de administración previstos en el presupuesto general de la entidad, como también durante su efectivización, no superen el ocho por ciento (8%) de los recursos disponibles por la entidad.",

    "TÍTULO VII: DE LA INTERVENCIÓN - Artículo 435": "El Poder Ejecutivo puede disponer la intervención de la O.S.Pe.Se. cuando exista un claro apartamiento de las normas que la regulan o una deficitaria prestación del servicio de salud o bien irregularidades en su gestión.",
    
    "LIBRO VI: SERVICIO DE SEGURIDAD PRIVADA - TÍTULO I: OBJETO - Artículo 436": "El presente Libro tiene por objeto regular la prestación de servicios de seguridad privada: vigilancias, custodias y seguridad de personas y bienes, por parte de personas humanas o jurídicas privadas, con domicilio en la Ciudad Autónoma de Buenos Aires o que efectúan la prestación en dicho territorio.",
    
    "LIBRO VI: SERVICIO DE SEGURIDAD PRIVADA - TÍTULO I: OBJETO - Artículo 437": "A los efectos de este libro se entiende por servicios de seguridad privada: las prestaciones mencionadas en el artículo 436 que brindan personas humanas o jurídicas habilitadas por el presente Libro, contratadas por personas humanas o personas jurídicas de carácter privado o público, con el fin de ejercer actividades de seguridad complementarias de la seguridad pública, sólo en lo concerniente a tareas de disuasión, protección de personas y resguardo de bienes.",
    
    "LIBRO VI: SERVICIO DE SEGURIDAD PRIVADA - TÍTULO II: PRINCIPIOS RECTORES - Artículo 438": "La prestación del servicio de seguridad privada y la actuación de sus agentes se sujeta a los siguientes principios rectores:\n1. Transparencia: a través del registro, la habilitación, el control y la difusión de los servicios de seguridad privada y de sus prestadores que garantice su legitimidad y una eficiente prestación.\n2. Profesionalización: mediante la formación básica y la posterior capacitación específica del personal en lo referido a la prestación, gestión y planificación de los servicios de seguridad privada.\n3. Tecnología e innovación: promoviendo la modernización y el uso de nuevas tecnologías que mejoren la gestión administrativa y el desarrollo de los servicios y procedimientos.\n4. Planificación estratégica: favoreciendo la asignación eficiente y eficaz de los recursos disponibles para su mejor aprovechamiento en un contexto de cambios y alta exigencia.\n5. Actuación coordinada y subordinada: articula su esfuerzo operacional con el resto de las organizaciones que intervienen en el Sistema Integral de Seguridad Pública.",
    
    "LIBRO VI: SERVICIO DE SEGURIDAD PRIVADA - TÍTULO III: TIPOS DE SERVICIOS - Artículo 439": "Los servicios pueden ser:\n1. Servicios con autorización de uso de armas de fuego:\na. Los de custodias personales, mercaderías en tránsito -excepto el transporte de caudales regulado por la Ley Nacional Nº 19.130 # - y en depósitos. Tienen por objeto el acompañamiento y la protección de personas o bienes en la vía pública, y en los lugares en que éstos se depositen.\nb. Los de vigilancia privada en lugares fijos sin acceso de público. Tienen por objeto resguardar la seguridad de personas o bienes en espacios privados cerrados, con control e identificación de acceso de personas.\n2. Servicios sin autorización de uso de armas de fuego:\na. Los de vigilancia privada en lugares fijos con acceso al público. Tiene por objeto la seguridad de personas o bienes en espacios privados de acceso público con fines diversos.\nb. Los de custodia y portería de locales de baile, confiterías y de espectáculos en vivo, como todo otro lugar destinado a recreación.\nc. Los de vigilancia privada de lugares fijos privados o edificios de propiedad horizontal.\nd. Los de vigilancia por medios electrónicos, ópticos y electro ópticos. Tiene por objeto brindar servicios con dispositivos centrales de observación, registro de imagen, audio y alarmas.",

    "Título IV: De los Prestadores - Artículo 440": "Los prestadores pueden ser:\n1. Personas humanas sólo autorizadas para desempeñar la actividad por sí mismas.\n2. Personas jurídicas y personas humanas con autorización para contratar personal. Quedan expresamente excluidas las asociaciones, las fundaciones y las cooperativas de trabajo que, para el cumplimiento de su objetivo social, prevean la contratación de los servicios cooperativos por terceras personas utilizando la fuerza de trabajo de sus asociados.",
    
    "Título IV: De los Prestadores - Artículo 441": "Los prestadores autorizados a desempeñar la actividad por sí mismos, deben cumplir con los siguientes requisitos:\n1. Poseer estudios secundarios completos.\n2. Ser ciudadano argentino o con dos años de residencia efectiva en el país.\n3. Ser mayor de dieciocho (18) años. En los servicios previstos en el artículo 439 inciso 1, deberá ser mayor de veintiún (21) años.\n4. Denunciar el domicilio real, y constituir domicilio en jurisdicción de la Ciudad Autónoma de Buenos Aires.\n5. Obtener certificado de aptitud psico-física, emitido por autoridad sanitaria pública, o por establecimiento privado reconocido por la autoridad pública nacional o local de sanidad. Tendrá un (1) año de validez y la reglamentación establecerá los requisitos a ser cumplidos en la evaluación psico-física.\n6. Obtener certificado de capacitación técnico-habilitante, de acuerdo a lo establecido en el Título XII del presente Libro.\n7. No haber sido condenado, indultado o amnistiado por delitos que configuren violación a los derechos humanos.\n8. No haber sido condenado por delito doloso en el país o en el extranjero. En este último caso, siempre que constituya delito en nuestra legislación.\n9. No revistar como personal en actividad de las fuerzas armadas, de seguridad, policiales, ni de organismos de inteligencia.\n10. No haber sido exonerado de cualquiera de las instituciones mencionadas en el inciso 9º, a excepción de aquellos casos en los que la medida se hubiere dispuesto por causas religiosas, políticas, o discriminatorias.\n11. Contar con un seguro de responsabilidad civil, que cubra expresamente la actividad de seguridad privada, cuyo monto se actualiza anualmente conforme lo disponga la autoridad de aplicación.\n12. Cuando los servicios se presten con autorización para usar armas de fuego, deberán cumplir además con los requisitos exigidos en el Artículo 453.\n13. Acreditar solvencia patrimonial suficiente para prestar los servicios regulados en el presente Libro de acuerdo con las exigencias que se determinen en la reglamentación.\n14. No haber sido inhabilitado por infracciones a la presente ley.",

    "LEY Q - N° [Número de la Ley] - Título V: [Título del Título V] - Artículo 442": "Los prestadores con autorización para contratar personal deben cumplir con los siguientes requisitos:\n1. Denunciar el domicilio real y constituir domicilio en jurisdicción de la Ciudad Autónoma de Buenos Aires.\n2. Contar con un seguro de responsabilidad civil, que cubra expresamente la actividad de seguridad privada, cuyo monto se actualiza anualmente conforme lo disponga la autoridad de aplicación.\n3. Acreditar solvencia patrimonial suficiente para prestar los servicios regulados en el presente Libro acorde a las exigencias que se determinen en la reglamentación.\n4. Reunir los requisitos edilicios y de seguridad en los mismos que la reglamentación determine.\n5. Presentar una declaración jurada conteniendo nómina de los socios y miembros, integrantes de los órganos de administración y representación de las personas jurídicas con especificación del porcentaje societario de cada uno.\n6. Acreditar la designación de un director técnico y, en su caso, la designación de un director técnico suplente, o de un responsable técnico si se tratase de un prestador de seguridad electrónica.",

    "LEY Q - N° [Número de la Ley] - Título V: [Título del Título V] - Artículo 443": "Los socios, miembros e integrantes de los órganos de administración o representación, deben cumplir con los siguientes requisitos:\n1. Denunciar el domicilio real.\n2. Constituir domicilio legal. El domicilio constituido de los socios, representantes y/o administradores de la sociedad será el mismo que el de la persona jurídica.\n3. No haber sido condenado, indultado o amnistiado por delitos que configuren violación a los derechos humanos.\n4. No haber sido condenado por delito doloso en el país o en el extranjero. En este último caso, siempre que constituya delito en la legislación de la República Argentina.\n5. No revistar como personal en actividad de las fuerzas armadas, de seguridad, policiales, ni de organismos de inteligencia.\n6. No haber sido exonerado de cualquiera de las instituciones mencionadas en el inciso 5, a excepción de aquellos casos en los que la medida se hubiere dispuesto por causas religiosas, políticas, gremiales o discriminatorias.\n7. No haber sido inhabilitado por infracciones a la presente Ley.",

     " Título V: Seguridad Electrónica - Artículo 444": "Los prestadores que incluyan en sus servicios los descriptos en el Artículo 439, inciso 2, apartado d, deben cumplir con los siguientes requisitos específicos:\n1. Designar un responsable técnico, graduado universitario en ingeniería electrónica, sistemas, informática, programación, comunicaciones o telecomunicaciones, licenciatura en tecnología aplicada a la seguridad o carrera afín; en este último supuesto será la autoridad de aplicación mediante resolución fundada, quien apruebe la presentación de títulos de nuevas carreras de grado que sea menester. El director técnico podrá acreditarse como responsable técnico, si cumple con los requisitos suficientes para desempeñarse en ambos cargos simultáneamente.\n2. Contar con certificados de aprobación de las instalaciones, emitidos por autoridad competente, de acuerdo a lo que la reglamentación determine.\n3. Las empresas que brinden servicios de sistemas de vigilancia, monitoreo y alarma electrónica deben inscribir a los responsables técnicos, técnicos instaladores y operadores de monitoreo en el registro creado a tales efectos. Solo sus inscriptos se encuentran autorizados para la supervisión, instalación y operatividad de dichos servicios.",
    
    " Título V: Seguridad Electrónica - Artículo 445": "El responsable técnico debe cumplir los requisitos establecidos en el Artículo 441, incisos 3, 4, 7, 8, 9, 10 y 11, y Artículo 444, inciso 1, del presente Libro. Debe además contar con un seguro de responsabilidad civil que cubra expresamente la actividad de seguridad privada.",
    
    " Título V: Seguridad Electrónica - Artículo 446": "El responsable técnico es la persona que asegura el funcionamiento técnico de las instalaciones y del equipamiento que posee la prestadora de servicios de vigilancia electrónica, como así también del que fuera entregado a los prestatarios. Responde solidariamente con la prestadora en caso de incumplimiento cuando éste se deba a fallas de orden técnico.",
    
    " Título V: Seguridad Electrónica - Artículo 447": "Los técnicos instaladores son los encargados de realizar el tendido de cables o fibras ópticas para la instalación de cámaras (CCTV), dispositivos satelitales para localización y dispositivos de detección de movimiento y apertura de puertas y ventanas, y otros elementos que cumplan funciones similares a las mencionadas.",
    
    " Título V: Seguridad Electrónica - Artículo 448": "Los operadores de monitoreo son los encargados de realizar el seguimiento de las diferentes secuencias de monitoreo emitidas por cámaras (CCTV), dispositivos satelitales para localización y dispositivos de detección de movimiento y apertura de puertas y ventanas.",
    
    " Título V: Seguridad Electrónica - Artículo 449": "Los técnicos instaladores y los operadores de monitoreo deben cumplir con los siguientes requisitos:\n1. Poseer estudios secundarios completos.\n2. Ser mayor de dieciocho (18) años.\n3. Ser ciudadano argentino o con dos años de residencia efectiva en el país.\n4. Poseer certificado de capacitación técnico habilitante de acuerdo a lo establecido por el Título XII del presente Libro.\n5. No haber sido condenado por delito doloso en el país o en el extranjero. En este último caso, siempre que constituya delito en la legislación de la República Argentina.",

    " Título VI: Prohibiciones y Obligaciones de los Prestadores - Artículo 450": "Los prestadores tienen expresamente prohibido:\n1. Prestar servicios en los espacios públicos, salvo que estuvieran concesionados o se otorgase un permiso de uso y fueran expresamente autorizados por la autoridad de aplicación. No se considera prestado en espacios públicos cuando se trate de custodias personales o de mercadería en tránsito. La reglamentación establecerá las condiciones y requisitos a cumplir para cubrir estos servicios.\n2. Prestar servicios de seguridad no autorizados o alterando el alcance de las definiciones del artículo 439.\n3. Prestar servicios sin contar con la habilitación vigente para el rubro específico.\n4. Prestar servicios en objetivos no denunciados ante la autoridad de aplicación.\n5. Ejercer tareas de investigación.\n6. Obstaculizar el legítimo ejercicio de los derechos políticos o gremiales.\n7. Dar a conocer a terceros la información de la que tomen conocimiento por el ejercicio de la actividad, sobre sus clientes, personas relacionadas con éstos, así como de los bienes o efectos que custodien.\n8. Interceptar o captar el contenido de comunicaciones postales, telefónicas, telegráficas, radiofónicas, por télex, facsímil o cualquier otro medio de transmisión de voces, imágenes o datos a distancia.\n9. Utilizar nombres o siglas similares a las que utilizan instituciones oficiales o no registradas ante la autoridad de aplicación.\n10. Utilizar armas en los lugares indicados en el Artículo 439, inciso 2, apartados a, b, y c.",
    
    " Título VI: Prohibiciones y Obligaciones de los Prestadores - Artículo 451": "Los prestadores tienen las siguientes obligaciones:\n1. Poner en conocimiento inmediato de la autoridad policial o judicial todo hecho delictivo de acción pública o incidencia constatada en el caso de los prestadores del servicio de monitoreo de alarmas del que tomen conocimiento en oportunidad del ejercicio de su actividad.\n2. Tramitar la renovación de la habilitación con una antelación no inferior a los treinta (30) días de su vencimiento.\n3. Denunciar ante la autoridad de aplicación toda variación del domicilio real y legal dentro de los diez (10) días de producido.\n4. Denunciar ante la autoridad de aplicación toda cesión o venta de cuotas o acciones societarias, así como toda modificación en la integración de los órganos de administración y representación, dentro del plazo de treinta (30) días de producidas.\n5. Llevar los siguientes libros-registro, foliados y rubricados por la autoridad de aplicación, los que deberán conservarse por un plazo mínimo de diez (10) años; sin perjuicio de los exigidos por la legislación vigente:\na) Libro de personal: en él deben asentarse las altas y las bajas del personal habilitado de la prestadora, debiendo comunicarse dichos movimientos a la autoridad de aplicación, dentro de las setenta y dos (72) horas corridas de producidos.\nb) Libro de novedades: en él deben asentarse los objetivos protegidos, las bajas, y en su caso, las armas de fuego y municiones. Toda modificación en los objetivos debe comunicarse a la autoridad de aplicación dentro de las setenta y dos (72) horas corridas de producida la misma.\nc) Libro de guardia: Debe llevarse un libro por objetivo. En él deben asentarse el personal afectado, el detalle de actividades realizadas y, en su caso, las armas de fuego y municiones que se afecten a cada uno.\n6. Proveer a su personal de uniformes, vehículos y material que sean notoriamente diferentes del que utilizan las instituciones oficiales. La reglamentación establece las características generales de los uniformes, así como la identificación de los vehículos afectados a la actividad.\n7. Acreditar la aprobación de los cursos de capacitación y entrenamiento periódico permanente para el personal, en la forma que establezca el Título XII del presente Libro.",
    
    " Título VI: Prohibiciones y Obligaciones de los Prestadores - Artículo 452": "Toda persona que se desempeñe en cualquiera de los servicios comprendidos en el presente Libro debe tener consigo la credencial que acredite su alta en el registro para desarrollar la actividad, y que exhibirá cada vez que le sea requerida por autoridad competente. En los lugares de acceso público donde se presten servicios de seguridad, se debe portar permanentemente en forma visible.",
    
    " Título VII: Armamento - Artículo 453": "En los servicios previstos en el artículo 439 inciso 1º, sólo se podrán utilizar las armas de fuego que hayan cumplido con todos los recaudos exigidos por la Agencia Nacional de Materiales Controlados - ANMaC-, las que deben registrarse como de uso colectivo. La autoridad de aplicación podrá establecer el uso y restricciones de las armas a utilizarse, de acuerdo a las características de los objetivos y funciones a desarrollar.",

    "TÍTULO VIII - Del Personal - Artículo 454": "El personal contratado por los prestadores deberá cumplir con los requisitos establecidos en el artículo 441 incisos1, 2, 3, 5, 6, 7, 8, 9, 10 y con el Artículo 464° del presente Libro. La autoridad de aplicación establecerá la forma de presentación de los legajos de personal, por parte de las prestadoras. Si cuenta con autorización para el uso de armas deberá acreditar además, su registro en la categoría de Legítimo Usuario de Armas de la Agencia Nacional de Materiales Controlados - ANMaC - y que se encuentra autorizado para la portación, de acuerdo a lo dispuesto en la Ley Nacional N° 20.429 # y su Decreto Reglamentario N° 395/75 #.",
    
    "TÍTULO VIII - Del Personal - Artículo 455": "El personal tiene las siguientes obligaciones:\n1. Llevar consigo la credencial que acredite su habilitación debiendo exhibirla cada vez que le sea requerida. Contendrá como mínimo: denominación de la empresa, foto, apellido y nombre de la persona, número de registro de inscripción o alta otorgado por la autoridad de aplicación y vigencia.\n2. Cumplir los servicios conforme a los principios de dignidad, protección y trato correcto de las personas.\n3. Realizar los cursos de acuerdo a lo establecido en el Título XII del presente Libro.\n4. Portar únicamente las armas que le suministre el empleador y sólo durante la prestación de los servicios, una vez finalizados debe reintegrarlas a la custodia del director técnico.\n5. Llevar identificación visible de nombre, apellido y número de registro en su uniforme.",
    
    "TÍTULO IX - Del Prestatario - Artículo 456": "El prestatario de los servicios, previo a la contratación, debe requerir al prestador un certificado que acredite la habilitación otorgada por la autoridad de aplicación.",
    
    "TÍTULO IX - Del Prestatario - Artículo 457": "El prestatario debe exhibir el contrato vigente celebrado con la prestadora de seguridad siempre que le sea requerido para su control por la autoridad de aplicación.",
    
    "TÍTULO X - Del Director Técnico - Artículo 458": "Para ser director técnico se requiere poseer título universitario o terciario en materia de seguridad, reconocido por la autoridad educativa correspondiente. Debe cumplir además, con los requisitos del artículo 441, incisos 3, 5, 7, 8, 9, 10 y 11 del presente Libro. En su caso, debe acreditar que cumple con el requisito establecido en el Artículo 444, inciso 1.",
    
    "TÍTULO X - Del Director Técnico - Artículo 459": "El director técnico responde solidariamente con los prestadores en caso de incumplimiento de las disposiciones de este Libro y su reglamentación.",
    
    "TÍTULO X - Del Director Técnico - Artículo 460": "El director técnico vela por el cumplimiento de las disposiciones del presente Libro y en los servicios a cargo de la prestadora y tiene las siguientes responsabilidades ante la autoridad de aplicación:\n1. Denunciar las novedades establecidas en el artículo 451, inciso 4 cuando corresponda.\n2. Mantener actualizado el libro de novedades y el de personal.\n3. Denunciar altas y bajas de personal, objetivos, armas y vehículos de acuerdo a la modalidad que establezca la reglamentación.\n4. Certificar copias de documentación que la autoridad de aplicación determine.\n5. Responder por el cumplimiento de la capacitación y el entrenamiento periódico obligatorio del personal.\n6. Disponer la custodia de las armas que utiliza el personal en los servicios.",

    " Título XI: De la Autoridad de Aplicación - Artículo 461": "El Ministerio de Justicia y Seguridad es la autoridad de aplicación, fiscalización y control del cumplimiento del presente Libro por parte de las empresas de seguridad privada y sus prestadores, teniendo al respecto las siguientes funciones:\n1. Habilitar y otorgar las renovaciones correspondientes, a las personas humanas y jurídicas, que desarrollen la actividad regulada por el presente Libro en la Ciudad Autónoma de Buenos Aires por un plazo no mayor a los dos (2) años.\n2. Inscribir en el registro de prestadores y otorgar las altas del personal por un plazo no mayor a los dos (2) años.\n3. Llevar un registro de prestadores de servicios de seguridad privada habilitados, en el que deben constar los objetivos protegidos.\n4. Llevar un registro del personal de cada prestadora.\n5. Llevar un registro especial de seguridad de locales de baile y espectáculos en vivo.\n6. Llevar un registro de las armas de fuego, inmuebles, vehículos y material de comunicaciones afectados a la actividad.\n7. Llevar un registro de los socios y miembros de las personas humanas y jurídicas y de sus órganos de administración y representación.\n8. Crear y mantener actualizado un registro de operadores de monitoreo.\n9. Llevar el registro único de técnicos instaladores de sistemas de vigilancia, monitoreo y alarma electrónica.\n10. Controlar previo a su registro que todo el armamento y las personas humanas y jurídicas estén registrados y autorizados por la Agencia Nacional de Materiales Controlados - ANMaC -, de acuerdo a la Ley Nacional N° 20.429 # y su Decreto Reglamentario N° 395/75 #.\n11. Controlar y autorizar la utilización de los uniformes, nombres, siglas, insignias, vehículos y demás materiales de las prestadoras.\n12. Extender o autorizar el otorgamiento de la credencial de habilitación del personal.\n13. Requerir de la Agencia Nacional de Materiales Controlados - ANMaC -dictamen previo para extender habilitaciones con uso de armas, solicitando además un informe semestral sobre el estado del armamento de las empresas habilitadas para su uso.\n14. Certificar a pedido de parte la habilitación de personas humanas y jurídicas.\n15. Determinar la forma en que los libros y registros deben ser llevados, pudiendo requerir en cualquier momento la información contenida en ellos.\n16. Llevar un registro de sanciones de los prestadores y prestatarios.\n17. Inscribir y llevar un registro de institutos de formación.\n18. Reglamentar las condiciones de seguridad para la custodia y la guarda de las armas y las municiones afectadas a los servicios cuando su cantidad y tipo no incluya una habilitación edilicia especial por parte de organismos competentes.\n19. Reglamentar el uso de las armas disuasivas y medios no letales que podrán utilizarse en ejercicio de la actividad.\n20. Controlar el cumplimiento de obligaciones fiscales y previsionales por parte de los prestadores.\n21. Fijar las tasas de inscripción, habilitación y trámites.\n22. Controlar y velar por el cumplimiento de las disposiciones de este Libro.",
    
    " Título XI: De la Autoridad de Aplicación - Artículo 462": "Toda persona tiene derecho a acceder a la información pública contenida en los Registros que esta ley establece. La solicitud no requerirá expresión de causa. Sin perjuicio de esto, la autoridad de aplicación publica en el sitio web oficial del Gobierno de la Ciudad de Buenos Aires los siguientes datos:\n1. Las condiciones de habilitación del servicio de seguridad privada.\n2. El listado de prestadores de servicios de seguridad privada habilitados y en su caso, la habilitación para el uso de armas.\n3. El nombre, documento nacional de identidad y antecedentes profesionales -si los tuvieren- de las personas humanas y los socios o miembros de las personas jurídicas que prestan servicios de seguridad privada.\n4. El nombre, documento nacional de identidad y antecedentes profesionales -si los tuvieren- de quienes integren los órganos de administración y representación de las personas jurídicas que presten el servicio de seguridad privada.\n5. El nombre, documento nacional de identidad y antecedentes profesionales -si los tuvieren- del personal de cada prestadora. La autoridad de aplicación autorizará los datos publicados en forma trimestral.",
    
    " Título XI: De la Autoridad de Aplicación - Artículo 463": "La autoridad de aplicación debe informar anualmente a la Legislatura de la Ciudad, respecto del cumplimiento y aplicación de esta Ley, con mención de las prestadoras que la hubieran infringido, y las sanciones impuestas.",

     " Título XII: De la Capacitación - Artículo 464": "La capacitación inicial, la actualización y el entrenamiento periódico obligatorio del personal se llevarán a cabo en establecimientos públicos o privados, con sujeción a las normas que determine la autoridad de aplicación. La capacitación referida a la eventual ejecución de medidas contra incendios, planes de evacuación, uso de extintores o prestación de primeros auxilios médicos debe ser brindada por personal idóneo de bomberos, de los hospitales dependientes del Gobierno de la Ciudad Autónoma de Buenos Aires o de la Cruz Roja Argentina. La capacitación también debe incluir la materia derechos humanos, garantías y antidiscriminación, incorporando como marco conceptual la perspectiva de género. La currícula para la formación de las personas que desempeñan tareas con uso de armas de fuego será diferenciada y se establecerán requisitos especiales en cuanto a su instrucción y entrenamiento.",
    
    " Título XII: De la Capacitación - Artículo 465": "Los institutos de formación reconocidos oficialmente deben reunir los requisitos necesarios para garantizar el aprendizaje, práctica y perfeccionamiento del personal. Deben llevar a cabo programas permanentes, orientados a fomentar en el personal el respeto por los derechos humanos y la observancia de las garantías consagradas por la Constitución Nacional y la Constitución de la Ciudad Autónoma de Buenos Aires.",
    
    " Título XII: De la Capacitación - Artículo 466": "La reglamentación establecerá la currícula básica para la capacitación inicial y el entrenamiento periódico, la que debe incluir conocimientos de primeros auxilios, de los contenidos de la presente Ley y en su caso, de capacitación para el uso de armas de fuego.",
    
    " Título XII: De la Capacitación - Artículo 467": "La autoridad de aplicación en materia de capacitación en seguridad privada es el Instituto Superior de Seguridad Pública, que tiene a su cargo el desarrollo, la organización y certificación de la capacitación inicial, la actualización y el entrenamiento periódico obligatorio de acuerdo con lo dispuesto en el Libro IV Instituto Superior de Seguridad Pública de la presente ley y su reglamentación y conforme los lineamientos del Ministerio de Justicia y Seguridad a través del área competente en la materia.",
    
    " Título XIII: Régimen Especial de Seguridad en Locales de Baile y Espectáculos en Vivo - Artículo 468": "La autoridad de aplicación lleva un Registro especial de seguridad en locales de baile y de espectáculos en vivo, en el que se asentarán los objetivos incluidos en el régimen especial, el personal asignado a las tareas y en su caso la prestadora contratada para brindar servicios de seguridad.",
    
    " Título XIII: Régimen Especial de Seguridad en Locales de Baile y Espectáculos en Vivo - Artículo 469": "Sin perjuicio del cumplimiento de la normativa aplicable para su habilitación y funcionamiento en la actividad comercial, todo local de baile y de espectáculos en vivo deberá contar con las siguientes condiciones de seguridad:\n1. Servicios de seguridad con una dotación de personal de seguridad proporcional a la capacidad máxima de asistentes para la cual fue habilitado. La reglamentación establecerá el mínimo de personal de seguridad por asistentes.\n2. Sistema de circuito cerrado de televisión con grabación de imágenes exclusivamente en los lugares de ingreso y egreso de los locales. Las grabaciones deberán conservarse por treinta (30) días. Quedan exceptuados de estos requisitos los siguientes locales de espectáculos en vivo: teatros independientes, peñas folclóricas, salones milongas y clubes de música en vivo.\n3. Libro de novedades: el titular o responsable a cargo del establecimiento debe llevar un libro de novedades rubricado por la autoridad de aplicación, en el que debe estar asentada la información correspondiente al personal asignado a las funciones de seguridad y en su caso, la correspondiente a la prestadora habilitada, y contratada al efecto, además de toda otra novedad vinculada a las funciones de seguridad.\n4. Exhibición obligatoria de una cartelera en lugar visible, con la nómina del personal asignado a la seguridad y en su caso la prestadora contratada.\n5. Contar con un Técnico en seguridad de locales bailables y espectáculos en vivo, el que deberá cumplir con los requisitos establecidos en el artículo 458 del presente Libro.",
    
    "Artículo 470": "El titular o responsable de la actividad comercial incluido en el presente título puede acreditar ante la autoridad de aplicación, personal en relación de dependencia asignado a las tareas de seguridad sin armas, cumpliendo con los siguientes requisitos especiales:\n1. Copia de la habilitación edilicia otorgada por el Gobierno de la Ciudad Autónoma de Buenos Aires, donde conste la cantidad máxima de concurrentes permitidos.\n2. Inscribir la totalidad del personal afectado a la seguridad, quienes deben cumplir con los requisitos establecidos en el artículo 441, incisos 1 a 10; acreditar la relación laboral y la capacitación inicial de acuerdo a lo establecido en el Título XII del presente Libro.\n3. Contar con un seguro de responsabilidad civil, que cubra expresamente la actividad de seguridad privada. La autoridad de aplicación actualiza periódicamente el monto de la cobertura, tomando como base el riesgo potencial de la actividad desarrollada.\n4. Abonar el arancel respectivo por las altas correspondientes al personal.\n5. Proveer vestimenta uniforme al personal con identificación visible del nombre, apellido y número de registro.",
    
    "Artículo 471": "El personal de seguridad registrado bajo este título sólo puede cumplir funciones de seguridad en el establecimiento denunciado por su empleador. Debe cumplir, a su vez, con las obligaciones dispuestas en el artículo 455, incisos 1, 2 y 3.",
    
    "Artículo 472": "En todo lo que no esté previsto por este Libro se aplicará la Ley Nacional Nº 26.370 #, que establece las reglas de habilitación del personal que realiza tareas de control de admisión y permanencia de público en general, para empleadores cuya actividad consista en la organización y explotación de eventos y espectáculos públicos.",
    
    "Artículo 473": "La infracción a lo estipulado en este Libro será objeto de las sanciones establecidas por la Ley 451 Régimen de Faltas de la Ciudad Autónoma de Buenos Aires # (texto consolidado por Ley 5454).",
    
    "Artículo 474": "Créase el Sistema Público Integral de Video Vigilancia de la Ciudad Autónoma de Buenos Aires.",
    
    "Artículo 475": "El presente título regula la utilización por parte del Poder Ejecutivo de los sistemas de video vigilancia destinados a grabar imágenes en lugares públicos y a los que se refieren los artículos 485 y 486, estableciendo específicamente el posterior tratamiento de tales imágenes y el régimen de garantías de los derechos fundamentales y libertades públicas de los ciudadanos que habrá de respetarse ineludiblemente en las sucesivas fases de grabación y uso de las imágenes.",
    
    "Artículo 476": "La utilización del sistema integral de video vigilancia está regida por el principio de proporcionalidad y razonabilidad, en su doble versión de procedencia y de intervención mínima. La procedencia determina que sólo podrá emplearse cuando resulte adecuado, en una situación concreta, para asegurar la convivencia ciudadana, la utilización pacífica de las vías y espacios públicos, la elaboración de políticas públicas de planificación urbana, así como para la prevención de faltas, contravenciones y delitos y otras infracciones relacionadas con la seguridad pública. La intervención mínima exige la ponderación en cada caso de la finalidad pretendida y la posible afectación al derecho a la propia imagen, a la intimidad y a la privacidad de las personas, de conformidad con los principios consagrados en la Constitución Nacional # y la Constitución de la Ciudad Autónoma de Buenos Aires #.",

    "TÍTULO II - PRINCIPIOS RECTORES": "Artículo 477.- La gestión del sistema público integral de video vigilancia, se sujeta a los siguientes principios rectores:\n1. Planificación estratégica: se rige por medio de planes de acción basados en criterios estratégico institucionales que son comprobados mediante los ejercicios de la gestión.\n2. Tecnología e innovación: promueve el uso intensivo de nuevas tecnologías para el abordaje de sus funciones y la mejora de la gestión institucional.\n3. Información estadística confiable: reúne registros de datos sobre la estadística y de los mapas de ocurrencia de hechos delictivos, a los efectos de desarrollar informes eficaces y oportunos sobre la materia en la Ciudad de Buenos Aires.\n4. Coordinación: articula su esfuerzo operacional con el resto de los componentes que intervienen en el sistema integral de seguridad pública.",
    
    "TÍTULO III - LOS SISTEMAS DE VIDEO VIGILANCIA INSTALADOS POR EL PODER EJECUTIVO - CAPÍTULO I": "INSTALACIÓN Y USO DE LOS SISTEMAS DE VIDEO VIGILANCIA\nArtículo 478.- La instalación de sistemas de video vigilancia por parte del Poder Ejecutivo procede en la medida en que resulte de utilidad concreta a fin de proporcionar información necesaria para adoptar eventuales medidas de gobierno relacionadas con la utilización del espacio público.\nArtículo 479.- El Poder Ejecutivo no puede utilizar los sistemas de video vigilancia para tomar imágenes del interior de propiedades privadas, salvo por autorización judicial expresa. Pueden instalarse sistemas de video vigilancia en espacios públicos de acuerdo a los principios establecidos en el presente Libro, salvo cuando se afecte de forma directa y grave la intimidad de las personas. En ningún caso los sistemas de video vigilancia pueden captar sonidos, excepto en el caso de que sea accionado el dispositivo de emergencia, y al solo efecto de establecer la comunicación con el solicitante. La captación de sonidos se debe desactivar automáticamente a los tres (3) minutos de pulsado el dispositivo y únicamente puede reactivarse mediante una nueva pulsación del dispositivo de emergencia. El sistema debe impedir su activación por parte del operador del centro de monitoreo. Si en forma accidental se obtuviesen imágenes cuya captación resulte violatoria del presente Libro, deben ser destruidas inmediatamente por quien tenga la responsabilidad de su custodia.\nArtículo 480.- Las referencias a sistemas de video vigilancia, se entienden hechas a cualquier medio técnico análogo y, en general, a cualquier sistema que permita las grabaciones previstas en este Libro.",

    "CAPÍTULO II - LAS IMÁGENES": "Artículo 481.- La captación y almacenamiento de imágenes en los términos previstos en este Libro, así como las actividades preparatorias, no se consideran intromisiones ilegítimas en el derecho a la intimidad personal y familiar y a la propia imagen, siempre y cuando no contradigan lo establecido en la Constitución Nacional, la Constitución de la Ciudad Autónoma de Buenos Aires, la Ley Nacional N° 25.326 # y la Ley 1845 # (texto consolidado por Ley 5454).\nArtículo 482.- La obtención de imágenes no tiene por objetivo la formulación de denuncias judiciales por parte de la autoridad de aplicación. En caso de detectarse la ocurrencia flagrante de un hecho delictivo o contravencional la autoridad de aplicación arbitra los medios necesarios para dar inmediato aviso a la fuerza de seguridad correspondiente y pone la cinta o soporte original de las imágenes en su integridad a disposición judicial con la mayor celeridad posible. Si la grabación captara hechos que pudieran ser constitutivos de infracciones administrativas se remiten al órgano competente, de inmediato, para el inicio del procedimiento sancionatorio.\nArtículo 483.- El acceso a toda información obtenida como consecuencia de las grabaciones se restringe a aquellos funcionarios que el Poder Ejecutivo individualmente determine, por razón de su función específica. Se prohíbe la cesión o copia de las imágenes salvo en los supuestos previstos en el presente Libro o en aquellos que se dispongan por vía reglamentaria o en el propio interés del titular. Cualquier persona que por razón del ejercicio de sus funciones tenga acceso a las grabaciones debe observar la debida reserva, confidencialidad y sigilo resultando de aplicación, en caso contrario, lo dispuesto en la legislación penal. Cuando no correspondan responsabilidades penales, las infracciones a lo dispuesto en el presente Libro son sancionadas con arreglo al régimen disciplinario correspondiente a los infractores y, en su defecto, con sujeción al régimen de sanciones en materia de protección de datos de carácter personal.\nArtículo 484.- Las grabaciones son destruidas una vez transcurridos sesenta (60) días corridos desde su captación. No serán destruidas las que estén relacionadas con infracciones penales o administrativas en materia de seguridad pública, con una investigación policial en curso o con un procedimiento judicial o administrativo abierto.",

     " Título IV: Los Sistemas de Video Vigilancia - Artículo 485": "Los establecimientos privados que cuenten con sistemas de video vigilancia en los espacios de acceso público están obligados a guardar las imágenes que registren por el término mínimo de treinta (30) días, las que podrán ser requeridas por autoridad judicial en caso de existir una investigación de un hecho ilícito en curso.",
    
    " Título IV: Los Sistemas de Video Vigilancia - Artículo 486": "Las cámaras de video vigilancia instaladas en establecimientos privados que capten imágenes del espacio público, las destinadas a la toma de imágenes de bienes muebles o inmuebles afectados a concesiones de obra o de servicios públicos y las instaladas en dependencias del Poder Ejecutivo y que capten imágenes del espacio público o de espacios de acceso público, conforman el Sistema Público Integral de Video Vigilancia de la Ciudad de Buenos Aires y se sujetan a las prescripciones de este Libro. La autoridad de aplicación puede acceder, en las condiciones establecidas en este Libro, a las imágenes capturadas por las cámaras que integran el Sistema Público Integral de Video Vigilancia de la Ciudad de Buenos Aires.",
    
    " Título IV: Los Sistemas de Video Vigilancia - Artículo 487": "Los titulares de los establecimientos privados o quienes los posean por cualquier título que instalen las cámaras a las que se refiere el primer párrafo del artículo 486 tienen las siguientes obligaciones:\n1. Registrar las cámaras instaladas que tomen imágenes del espacio público en un registro creado al efecto por la autoridad de aplicación.\n2. Respetar las especificaciones técnicas relativas al tipo de cámara y tecnología a instalar que establezca en forma general la autoridad de aplicación. La norma técnica debe facilitar la integración de las cámaras al Sistema Público Integral de Video Vigilancia de la Ciudad de Buenos Aires, sin imponer restricciones innecesarias ni favorecer indebidamente a proveedores determinados.\n3. Cuando la autoridad de aplicación lo solicite, proveer conectividad entre los dispositivos de video vigilancia instalados y el Centro de Monitoreo del Sistema Público Integral de Video Vigilancia de la Ciudad de Buenos Aires o el que aquélla determine, conforme las especificaciones técnicas que en forma general se establezcan.",
    
    " Título IV: Los Sistemas de Video Vigilancia - Artículo 488": "El incumplimiento de las obligaciones dispuestas en el artículo 487 configura la falta tipificada en el artículo 11.1.17 de la Ley 451 (conforme texto consolidado por Ley 5454).",

    " Título V: Autoridad de Aplicación - Artículo 489": "El Ministerio de Justicia y Seguridad es la autoridad de aplicación del Sistema Público Integral de Video Vigilancia de la Ciudad Autónoma de Buenos Aires y tiene a su cargo la custodia de las imágenes obtenidas y la responsabilidad sobre su ulterior destino, incluida su inutilización o destrucción.",
    
    " Título V: Autoridad de Aplicación - Artículo 490": "La autoridad de aplicación crea un Registro en el que figuren todos los sistemas de video vigilancia comprendidos en el artículo 480, especificando su estado operativo y otros datos que puedan resultar de interés.",
    
    " Título V: Autoridad de Aplicación - Artículo 491": "Los propietarios de los bienes afectados por las instalaciones reguladas en este Libro, o quienes los posean por cualquier título, están obligados a facilitar y permitir su colocación y mantenimiento, sin perjuicio de la necesidad de obtener, de parte de la autoridad de aplicación, en su caso, la autorización judicial correspondiente, y de las indemnizaciones que procedan según las leyes vigentes.",

    " Título VIII: El Cuerpo de Agentes de Control de Tránsito y Transporte - Título I: Disposiciones Generales - Artículo 492": "El Cuerpo de Agentes de Control de Tránsito y Transporte compone el Sistema Integral de Seguridad Pública de la Ciudad de Buenos Aires. Integra el Consejo de Seguridad y Prevención del Delito en los términos de la Ley 1689 # (texto consolidado por Ley 5454).",
    
    " Título VIII: El Cuerpo de Agentes de Control de Tránsito y Transporte - Título I: Disposiciones Generales - Artículo 493": "El Cuerpo de Agentes de Control de Tránsito y Transporte es la autoridad de control del tránsito y el transporte en la Ciudad de Buenos Aires, según lo determinado en el artículo 1.1.3 del Código de Tránsito y Transporte aprobado por Ley 2148 # (texto consolidado por Ley 5454) y sus modificatorias.",
    
    " Título VIII: El Cuerpo de Agentes de Control de Tránsito y Transporte - Título I: Disposiciones Generales - Artículo 494": "El Cuerpo de Agentes de Control de Tránsito y Transporte es un cuerpo civil, uniformado, no armado, debidamente identificado, que tiene como misión hacer cumplir las disposiciones del Código de Tránsito y Transporte #, el ordenamiento y control del tránsito peatonal y vehicular incluido todo tipo de transporte, la difusión entre la población de los principios de prevención, seguridad vial y movilidad sustentable y la asistencia y participación en los programas de educación vial que se establezcan.",
    
    " Título VIII: El Cuerpo de Agentes de Control de Tránsito y Transporte - Título I: Disposiciones Generales - Artículo 495": "El Cuerpo de Agentes de Control de Tránsito y Transporte depende orgánica y funcionalmente del Poder Ejecutivo.",
    
    " Título VIII: El Cuerpo de Agentes de Control de Tránsito y Transporte - Título II: Principios Rectores - Artículo 496": "La gestión del Cuerpo de Agentes de Control de Tránsito y Transporte, como componente del sistema integral de seguridad pública, se sujeta a los siguientes principios rectores:\n1. Planificación estratégica: se rige por medio de planes de acción basados en criterios estratégico institucionales que son comprobados mediante los ejercicios de la gestión.\n2. Tecnología e innovación: promueve el uso intensivo de nuevas tecnologías para el abordaje de sus funciones y la mejora de la gestión institucional.\n3. Profesionalización y capacitación: propende a la capacitación continua y permanente de sus integrantes tendiendo a una adecuada profesionalización de la función.\n4. Información estadística confiable: reúne registros de datos sobre la estadística accidentológica y de los mapas de riesgo vial, a los efectos de desarrollar informes eficaces y oportunos sobre la materia en la Ciudad de Buenos Aires.\n5. Coordinación: articula su esfuerzo operacional con el resto de los organismos que intervienen en el sistema de seguridad.",
    
    " Título VIII: El Cuerpo de Agentes de Control de Tránsito y Transporte - Título III: Principios Básicos de Actuación - Artículo 497": "Los miembros del Cuerpo de Agentes de Control de Tránsito y Transporte actúan, en el ejercicio de sus funciones y en las relaciones con la comunidad, observando y promoviendo los siguientes principios:\n1. Los Derechos y Garantías consagrados en la Constitución Nacional #, en los Tratados de Derechos Humanos # que forman parte de la Constitución Nacional y en la Constitución de la Ciudad Autónoma de Buenos Aires #.\n2. El Código de conducta para funcionarios encargados de hacer cumplir la ley, adoptado por la Asamblea General de Naciones Unidas, en su sesión del 17 de diciembre de 1979, aprobada por Resolución N° 34-169 #.\n3. El reconocimiento del derecho a la accesibilidad de las personas con discapacidad y los derechos de las personas adultas mayores.",

     " Título IV: Funciones y Facultades - Artículo 498": "El Cuerpo de Agentes de Control de Tránsito y Transporte tiene las siguientes funciones:\n1. Ordenar y dirigir el tránsito.\n2. Ejercer el control del estacionamiento en la vía pública.\n3. Prevenir y hacer cesar la comisión de faltas y contravenciones de tránsito peatonal y vehicular.\n4. Ser autoridad de fiscalización y comprobación de infracciones a las normas vigentes en materia de tránsito y transporte.\n5. Realizar controles y operativos preventivos, ordinarios y extraordinarios, de control y verificación, de conformidad con la normativa vigente.\n6. Desarrollar operativos de seguridad vial y ordenamiento del tránsito en ocasión de eventos y movilizaciones en la vía pública.\n7. Vigilar y controlar todo tipo de transportes tanto públicos como privados.\n8. Coordinar su accionar con los organismos de la administración central y descentralizada del Gobierno de la Ciudad Autónoma de Buenos Aires para promover el cumplimiento de la normativa de tránsito y transporte.\n9. Colaborar y coordinar su accionar con los organismos competentes de las diversas jurisdicciones, de conformidad con lo establecido en la Ley Nacional N° 24.449 #.\n10. Dar aviso a la autoridad que ejerza las funciones de policía de seguridad en casos de delitos y contravenciones que no sean de tránsito.\n11. Actuar como auxiliar de la justicia en los casos que se le requiera, en el marco de sus competencias.\n12. Colaborar con los organismos del Gobierno de la Ciudad Autónoma de Buenos Aires encargados de la elaboración de la estadística accidentológica y de los mapas de riesgo vial.\n13. Contribuir a la mejora de la seguridad vial y de la educación vial colaborando con los organismos que lo soliciten.\n14. Colaborar con las fuerzas de seguridad y los organismos de emergencias en las situaciones que incidan sobre el tránsito peatonal y vehicular.\n15. Velar por el cumplimiento de las normas vigentes respecto del uso, prioridades y circulación de medios de transporte que garanticen la movilidad sustentable.\n16. Garantizar las condiciones de accesibilidad y prioridad, respecto de la circulación en la vía pública de personas adultas mayores o con necesidades especiales.",

    " Título IV: Funciones y Facultades - Artículo 499": "El Cuerpo de Agentes de Control de Tránsito y Transporte tiene las siguientes facultades:\n1. Labrar actas contravencionales cumpliendo con lo establecido en la Ley 12 # (texto consolidado por Ley 5454).\n2. Labrar actas de comprobación de infracciones cumpliendo con lo establecido en la Ley 1217 # (texto consolidado por Ley 5454).\n3. Proceder a la detención del vehículo en la vía pública, tanto en caso de que la infracción de tránsito haya sido constatada y al solo efecto de confeccionar el acta contravencional o el acta de comprobación, como así también para requerir la documentación obligatoria necesaria para circular.\n4. Proceder de acuerdo a lo descripto en el artículo 5.6.1. del Código de Tránsito y Transporte # (texto consolidado por Ley 5454).\n5. Adoptar regulaciones transitorias y suspender circunstancialmente el uso de los dispositivos o instalaciones viales cuando razones de orden y seguridad pública debidamente justificadas así lo impongan.\n6. Requerir, en caso de resultar necesario, el auxilio de la fuerza pública para el efectivo cumplimiento de sus funciones.",

     " Título V: Dirección General - Artículo 500": "El Cuerpo de Agentes de Control de Tránsito y Transporte está a cargo de un Director General, designado por el Poder Ejecutivo, quien debe acreditar a través de los requisitos que la reglamentación establece poseer debida idoneidad, preparación, conocimiento y experiencia laboral en materia de seguridad vial y accidentología.",
    
    " Título V: Dirección General - Artículo 501": "No puede ser designado como Director General:\n1. Quien hubiere sido condenado por violaciones a los derechos humanos, crímenes de guerra, delitos contra la paz o de lesa humanidad.\n2. Quien esté condenado por delito doloso, o delito culposo si el hecho hubiese sido ocasionado por la conducción imprudente, negligente, inexperta, o antirreglamentaria de un vehículo automotor, hasta tanto no haya cumplido la totalidad de la pena.\n3. Quien esté condenado por un delito en perjuicio de la Administración Pública Nacional, Provincial o de la Ciudad Autónoma de Buenos Aires.\n4. Quien esté sancionado con exoneración o cesantía en cualquier cargo público hasta tanto no sea dispuesta la rehabilitación.\n5. Quien esté inscripto en el Registro de Deudores Alimentarios Morosos.\n6. Quien se encuentre inhabilitado para conducir en el momento de su designación.\n7. Quien se haya desempeñado como presidente, gerente o en cualquier cargo de conducción en empresas vinculadas con el transporte público y privado durante el período de un (1) año de antelación a la designación.\n8. Quien posea acciones o cualquier tipo de participación en empresas o sociedades relacionadas con la prestación del servicio de transporte público o privado.",
    
    " Título V: Dirección General - Artículo 502": "Son funciones del Director General:\n1. Dirigir ejecutiva y operativamente al Cuerpo de Agentes de Control de Tránsito y Transporte.\n2. Ejercer la representación del Cuerpo de Agentes de Control de Tránsito y Transporte.\n3. Promover la capacitación permanente de los agentes.\n4. Velar por el cumplimiento de las funciones del Cuerpo de Agentes de Control de Tránsito y Transporte.\n5. Planificar, organizar y ejecutar operativos y controles en la vía pública y, en caso de ser necesario, en coordinación con las demás áreas intervinientes.",
    
    " Título VI: Estructura y Gestión - Artículo 503": "El Poder Ejecutivo determina la estructura orgánica del Cuerpo de Agentes de Control de Tránsito y Transporte de acuerdo a las necesidades que se establezcan.",
    
    " Título VI: Estructura y Gestión - Artículo 504": "El Poder Ejecutivo aprueba un reglamento e instructivo de actuación del Cuerpo de Agentes de Control de Tránsito y Transporte de acuerdo a los principios establecidos en el presente Libro.",
    
    " Título VI: Estructura y Gestión - Artículo 505": "El Director General elabora la planificación operativa del Cuerpo priorizando los datos de la estadística accidentológica y de los mapas de riesgo vial, respetando las características particulares de la división territorial de la Ciudad establecida en la Ley 1777 # (texto consolidado por Ley 5454) y sus modificatorias.",
    
    " Título VI: Estructura y Gestión - Artículo 506": "El Cuerpo dispone de personal las veinticuatro (24) horas del día, todos los días del año, exclusivamente para el cumplimiento de las funciones asignadas por la presente.",
    
    " Título VI: Estructura y Gestión - Artículo 507": "El Cuerpo cuenta con equipos de comunicación, vehículos apropiados debidamente identificados y elementos tecnológicos adecuados que le permiten el cumplimiento de las funciones que en esta ley se establecen.",
    
    " Título VI: Estructura y Gestión - Artículo 508": "El Poder Ejecutivo eleva a la Legislatura un informe anual de gestión y desempeño del Cuerpo de Agentes de Control de Tránsito y Transporte.",

    " Título VII: Personal y Capacitación - Artículo 509": "La reglamentación establece la planta funcional del Cuerpo de Agentes de Control de Tránsito y Transporte determinando el régimen de selección, incorporación, ascensos y retiros, ajustándose a lo prescripto en la Ley 471 # (texto consolidado por Ley 5454) y sus modificatorias.",
    
    " Título VII: Personal y Capacitación - Artículo 510": "El Cuerpo se integra de acuerdo con los principios establecidos en el artículo 36 de la Constitución de la Ciudad Autónoma de Buenos Aires.",
    
    " Título VII: Personal y Capacitación - Artículo 511": "Los requisitos para ingresar al Cuerpo de Agentes de Control de Tránsito y Transporte, sin perjuicio de lo establecido en el artículo 501, son:\n1. Ser mayor de edad.\n2. Poseer estudios secundarios completos.\n3. Aprobar un examen psicofísico.\n4. Aprobar un curso específico sobre normas de tránsito y transporte, prevención y educación vial, socorrismo, primeros auxilios, derechos humanos y normas procesales de faltas, contravenciones y delitos.",
    
    " Título VII: Personal y Capacitación - Artículo 512": "No pueden integrar el Cuerpo de Agentes de Control de Tránsito y Transporte:\n1. Quien esté condenado por violaciones a los derechos humanos, crímenes de guerra, delitos contra la paz o de lesa humanidad.\n2. Quien esté condenado por delito doloso o delito culposo si el hecho hubiese sido ocasionado por la conducción imprudente, negligente, inexperta, o antirreglamentaria de un vehículo automotor, hasta tanto no haya cumplido con la totalidad de la pena.\n3. Quien esté condenado por un delito en perjuicio de la Administración Pública Nacional, Provincial o de la Ciudad Autónoma de Buenos Aires.\n4. Quien esté sancionado con exoneración o cesantía en cualquier cargo público, hasta tanto no sea dispuesta la rehabilitación.\n5. Quien esté inscripto en el Registro de Deudores Alimentarios Morosos de la Ciudad Autónoma de Buenos Aires.\n6. Quien se encuentre inhabilitado para conducir al momento de su designación.",
    
    " Título VII: Personal y Capacitación - Artículo 513": "Los agentes deben ser capacitados y actualizados, perfeccionando su formación, de acuerdo a los principios establecidos en el Artículo 497.",
    
    // Disposiciones finales
    " Disposiciones Finales - Artículo 514": "En todas las oportunidades en que se menciona en esta Ley al Ministerio de Justicia y Seguridad, debe entenderse que la referencia incluye al organismo que en el futuro lo reemplace.",
    
    " Disposiciones Finales - Artículo 515": "Entiéndase que a los efectos de la presente ley resulta indistinta la mención de Policía de la Ciudad de Buenos Aires o Policía de la Ciudad. De igual manera se tiene por indistinta la mención a Cuerpo de Bomberos, Cuerpo de Bomberos de la Ciudad de Buenos Aires o Cuerpo de Bomberos de la Ciudad.",
    
    " Disposiciones Finales - Artículo 516": "En todas las oportunidades en que se menciona en esta Ley al Instituto Superior de Seguridad Pública, debe entenderse que la referencia incluye al organismo que en el futuro lo reemplace.",
    
    " Disposiciones Finales - Artículo 517": "El Poder Ejecutivo adopta las previsiones presupuestarias que resulten necesarias para asegurar el normal funcionamiento del Sistema Integral de Seguridad Pública de la Ciudad Autónoma de Buenos Aires.",
    
    " Disposiciones Finales - Artículo 518": "Fe de Erratas. Autorízase al Poder Ejecutivo a corregir los errores en la numeración y las remisiones de los Títulos, Capítulos y artículos de esta Ley.",
    
    " Disposiciones Finales - Artículo 519": "Abróganse las Leyes 1913, 2593, 2602, 2652, 2854, 2883, 2894, 2895, 2947, 4007, sus modificatorias y toda otra ley que se oponga a la presente.",

     "CLÁUSULAS TRANSITORIAS - PRIMERA": "Los reglamentos de las leyes que se derogan por el Artículo 519 de la presente, mantienen su vigencia hasta tanto sean modificados, sustituidos o derogados por las normas de ejecución de esta Ley.",
    
    "CLÁUSULAS TRANSITORIAS DEL LIBRO I - SEGUNDA": "La Oficina de Transparencia y Control Externo de la Policía de la Ciudad es la continuadora de la Auditoría Externa creada por el art. 54 de la Ley 2894 # y sustancia los procedimientos e investigaciones en curso a la fecha de promulgación de la presente Ley. El personal civil que a la fecha de la promulgación de la presente Ley integre la Auditoría Externa de la Policía Metropolitana queda exceptuado de la prohibición de integración de la Oficina de Transparencia y Control Externo con personal de la Policía de la Ciudad prevista en el artículo 34 de la presente Ley.",
    
    "CLAUSULAS TRANSITORIAS DEL LIBRO II - TERCERA": "La Policía de la Ciudad es continuadora de la Policía Metropolitana creada por la Ley 2894 y es titular de todos los derechos, obligaciones y bienes de ésta. Las contrataciones y prestaciones contratadas por la Policía Metropolitana continúan vigentes hasta su finalización conforme las modalidades de sus respectivos contratos. El personal que revista en la Policía Federal Argentina transferido en virtud del 'Convenio de Transferencia Progresiva a la Ciudad Autónoma de Buenos Aires de Facultades y Funciones de Seguridad en Todas las Materias no Federales Ejercidas en la Ciudad Autónoma de Buenos Aires', aprobado por la Resolución de la Legislatura de la Ciudad de Buenos Aires N° 298/15 #, y el personal que revista en la Policía Metropolitana, integran la Policía de la Ciudad a partir del 1 de enero de 2017, conforme las disposiciones de la presente.",
    
    "CLAUSULAS TRANSITORIAS DEL LIBRO II - CUARTA": "El procedimiento establecido en artículo 77 no es de aplicación en el caso de la designación del primer Jefe de la Policía de la Ciudad, que debe ser nombrado en el cargo dentro de los diez (10) días de la promulgación de esta Ley.",
    
    "CLAUSULAS TRANSITORIAS DEL LIBRO II - QUINTA": "La disposición contenida en el inciso 4 del artículo 90 de la presente entra en vigencia una vez que el Ministerio Público Fiscal de la Ciudad Autónoma de Buenos Aires y el Ministerio de Justicia y Seguridad hayan adecuado las estructuras y procedimientos necesarios a efectos de dar cumplimiento a lo allí dispuesto.",

    "CLAUSULAS TRANSITORIAS DEL LIBRO II - Sexta Disposición": "El personal policial que revista en la Policía Federal Argentina en los agrupamientos de personal superior y subalterno establecidos en el art. 25 de la Ley Nacional N° 21.965 #, con excepción de quienes integran los grados de Suboficial Mayor, Suboficial Auxiliar, Suboficial Escribiente y Agente, y el personal policial que revista en la Policía Metropolitana en los grados establecidos en el art. 17 de la Ley 2947 #, pasan a integrar el Escalafón General Policial establecido en el artículo 119 y siguientes de la presente Ley, conforme la siguiente tabla de equivalencia de grados:\n- Policía de la Ciudad: Superintendente, Comisionado General, Comisionado Mayor, Comisario, Subcomisario, Inspector Principal, Inspector, Sargento 1°, Subinspector, Oficial Mayor, Oficial, Cabo 1°, Cabo, Oficial.\n- Policía Federal Argentina: Comisario General, Comisario Mayor, Comisario Inspector, Comisario, Subcomisario, Principal Inspector, Inspector, Subinspector, Oficial Mayor, Oficial 1°, Oficial, Suboficial 1°, Suboficial.\n- Policía Metropolitana: Superintendente, Comisionado General, Comisionado Mayor, Comisario, Comisario Mayor, Comisario Inspector, Comisario Principal, Subcomisario, Subcomisario Principal, Oficial, Oficial Principal, Suboficial 1°, Suboficial Mayor.",
    
    " CLAUSULAS TRANSITORIAS DEL LIBRO II - Séptima Disposición": "Créase el Grupo Auxiliar de Oficiales Superiores de la Policía de la Ciudad, como un órgano transitorio que no integra el escalafón general de la Policía de la Ciudad y desempeña tareas de apoyo operativo de la función policial, con la dependencia y demás funciones que establezca la reglamentación.\n- El Grupo Auxiliar de Oficiales Superiores se organiza en los grados de Oficial Primero, Oficial Segundo y Oficial Tercero. Está integrado por el personal que al 1 de enero de 2017 revista en los grados de Suboficial Mayor, Suboficial Auxiliar y Suboficial Escribiente de la Policía Federal Argentina.\n- Los integrantes del Grupo Auxiliar de Oficiales Superiores de la Policía de la Ciudad de Buenos Aires quedan sujetos a las disposiciones establecidas en la presente Ley y en su reglamentación para el personal con estado policial de la Policía de la Ciudad, excepto en lo referido al régimen de ascensos, donde continúan aplicándoseles las normas establecidas para los Suboficiales Superiores en la Ley Nacional N° 21.965 # y sus normas reglamentarias y complementarias.",

     " CLAUSULAS TRANSITORIAS DEL LIBRO II - Octava Disposición": "Créase el grado transitorio de Oficial Ayudante en el escalafón general policial de la Policía de la Ciudad. Está integrado por el personal policial transferido a la Ciudad que al 1 de enero de 2017 revista en el grado de Agente de la Policía Federal Argentina. El grado de Oficial Ayudante se ubica jerárquicamente bajo el grado de Oficial de la Policía de la Ciudad, y los Oficiales Ayudantes ascienden a aquél grado conforme las normas que establezca la reglamentación. Una vez que todos los Oficiales Ayudantes han ascendido, este grado desaparece. Los Oficiales Ayudantes integran el Cuadro de Oficiales Operativos.",
    
    " CLAUSULAS TRANSITORIAS DEL LIBRO II - Novena Disposición": "El personal transferido a la Ciudad que revista en los escalafones y especialidades contemplados en el Anexo II del Decreto 1866/PEN/83 # y que no está capacitado para la portación de armas ni el cumplimiento de las tareas propias del estado policial, integra a partir del 1 de enero de 2017 el agrupamiento de personal sin estado policial, conforme la tabla de equivalencias que se establece a continuación:\nGrado en P.F.A. Nivel en Policía de la Ciudad\nSargento 1° Nivel F\nSargento Nivel G\nCabo 1° Nivel G\nCabo Nivel H\nAgente Nivel H\nEl personal comprendido en esta cláusula puede optar por integrar el Escalafón General Policial, cumpliendo las tareas propias y específicas del mismo. A estos efectos, debe realizar y aprobar durante el año 2017 los cursos de capacitación que al efecto establezca el Instituto Superior de Seguridad Pública y cumplir los requisitos de aptitud para la labor policial que la reglamentación determine.",
    
    " CLAUSULAS TRANSITORIAS DEL LIBRO II - Décima Disposición": "Se dispone un plazo de cinco (5) años a partir de la promulgación de la presente Ley para la exigibilidad de los títulos académicos establecidos como requisito para el ascenso a los grados de Oficiales de Dirección y Oficiales Superiores de la Policía de la Ciudad establecidos en el artículo 132 de la presente. Este plazo puede ser prorrogado por una única vez por resolución fundada del Ministro de Justicia y Seguridad. Se dispone un plazo de tres (3) años a partir de la promulgación de la presente Ley para la exigibilidad de los títulos académicos establecidos como requisito para el ascenso a los grados de Oficiales de Supervisión de la Policía de la Ciudad establecidos en el artículo 132 de la presente ley. Este plazo puede ser prorrogado por una única vez por resolución fundada del Ministro de Justicia y Seguridad.",
    
    " CLAUSULAS TRANSITORIAS DEL LIBRO II - Décima Primera Disposición": "El personal con estado policial de la Policía Federal Argentina transferido a la Policía de la Ciudad de Buenos Aires goza del régimen de licencias establecido en la presente ley y sus normas reglamentarias. Asimismo, puede solicitar la licencia establecida en el art. 70 inciso a) de la Ley Nacional N° 21.965 # reglamentado por los Artículos 359 a 361 del Decreto PEN N° 1866/83 #, en las condiciones allí establecidas y vigentes al momento de la promulgación de la presente Ley, y en cuanto sea compatible con las necesidades del servicio.",
    
    " CLAUSULAS TRANSITORIAS DEL LIBRO II - Décimo Segunda Disposición": "A los efectos del cómputo de la licencia ordinaria, el tiempo durante el cual el personal haya prestado servicios con anterioridad en otra fuerza de seguridad nacional, provincial o municipal o en las Fuerzas Armadas se adiciona al tiempo de servicios prestados en la Policía de la Ciudad.",
    
    " CLAUSULAS TRANSITORIAS DEL LIBRO II - Décimo Tercera Disposición": "El personal policial y civil de la Policía Federal Argentina transferido a la Policía de la Ciudad de Buenos Aires y sus derechohabientes mantienen los derechos y obligaciones previsionales establecidos en la Ley Nacional N° 21.965 # y normas complementarias.",

    " CLAUSULAS TRANSITORIAS DEL LIBRO II - Décimo Cuarta": "El personal transferido a la Policía de la Ciudad de Buenos Aires que al 1 de enero de 2017 revista en el agrupamiento civil de la Policía Federal Argentina regulado por el Decreto-Ley N° 6581/58 # y sus modificatorias, y el personal civil de la Policía Metropolitana, integran el agrupamiento civil de la Policía de la Ciudad conforme la equivalencia de escalafones y escalas jerárquicas que a continuación se detalla:\nA) ESCALAFONES Y ESPECIALIDADES\nPolicía de la Ciudad\nESPECIALIDADES\nPolicía Federal Argentina\nESCALAFONES\nProfesional Técnico-profesional\nTécnico de obra social\nTécnico Técnico subprofesional (con título terciario)\nAdministrativo Técnico subprofesional (con título secundario)\nAdministrativo\nClero Clero\nMaestranza y Servicios Generales Maestranza y Servicios Generales\nEl Jefe de la Policía de la Ciudad encuadra al personal civil de la Policía Metropolitana en las especialidades de la Policía de la Ciudad, conforme el cumplimiento de los requisitos de idoneidad, capacitación y títulos académicos que la reglamentación establezca.\nB) NIVELES JERÁRQUICOS\nPolicía de la Ciudad Policía Federal Argentina Policía Metropolitana\nNIVEL A Auxiliar Superior 1\nNIVEL B Auxiliar Superior 2\nNIVEL C Auxiliar Superior 3\nNIVEL D Auxiliar Superior 4\nNIVEL E Auxiliar Superior 1 Auxiliar Superior 5\nNIVEL F Auxiliar Superior 2 Auxiliar 1\nNIVEL G Auxiliar Superior 3\nAuxiliar 1\nAuxiliar 2\nNIVEL H Auxiliar Superior 4\nAuxiliar 2\nAuxiliar 3\nAuxiliar 3\nNIVEL I Auxiliar Superior 5\nAuxiliar Superior 6\nAuxiliar 4\nAuxiliar 4\nNIVEL J Auxiliar 5\nAuxiliar 6\nAuxiliar 5\nAuxiliar 6",
    
    " CLAUSULAS TRANSITORIAS DEL LIBRO II - Décimo Quinta": "El personal civil transferido a la Policía de la Ciudad de Buenos Aires queda sujeto a las disposiciones de esta ley y sus normas reglamentarias, excepto en lo relativo al régimen jubilatorio, donde continúan aplicándose las normas del Título IV del Decreto - Ley N° 6581/58 # y sus normas modificatorias y complementarias.",
    
    " Clausulas Transitorias - DÉCIMO SEXTA": "Créase en la Policía de la Ciudad, la especialidad transitoria de 'Bomberos', que agrupa al personal transferido a la Ciudad de Buenos Aires que, a la fecha de la transferencia se desempeñaba en la Superintendencia de Bomberos de la Policía Federal Argentina. Esta especialidad subsiste en tanto permanezcan en servicio activo los trabajadores identificados en el párrafo anterior, y luego desaparece. El personal que integra la especialidad de Bomberos se encuentra bajo el mando funcional de la Subsecretaría de Emergencias del Ministerio de Justicia y Seguridad del Gobierno de la Ciudad Autónoma Buenos Aires, o el organismo que la reemplace en el futuro. A los efectos del desempeño del personal integrante de la especialidad de Bomberos y de su interacción con los miembros del Cuerpo de Bomberos de la Policía Federal Argentina, los grados de la jerarquía policial son equivalentes, de acuerdo al siguiente cuadro:\nPolicía de la Ciudad - Cuerpo de Bomberos\nSuperintendente - Jefe del Cuerpo de Bomberos\nComisionado General - Comandante General\nComisionado Mayor - Comandante Director\nComisario - Comandante\nSubcomisario - Subcomandante\nInspector Principal - Capitán\nInspector - Teniente\nOficial Mayor - Subteniente\nOficial Primero - Bombero Superior\nOficial - Bombero Calificado\nOficial Ayudante - Bombero",
    
    " Clausulas Transitorias - DÉCIMO SEPTIMA": "El procedimiento establecido en artículo 275 no es de aplicación en el caso de la designación del primer Jefe de Bomberos de la Ciudad, que debe ser nombrado en el cargo dentro de los diez (10) días de la promulgación de esta Ley.",
    
    " Clausulas Transitorias - DÉCIMO OCTAVA": "Se dispone un plazo de cinco (5) años a partir de la promulgación de la presente Ley para la exigibilidad de los títulos académicos establecidos como requisito para el ascenso a las categorías de Personal de Conducción y Personal de Dirección del Cuerpo de Bomberos, establecido en el artículo 298 de la presente. Este plazo puede ser prorrogado por una única vez por resolución fundada del Ministro de Justicia y Seguridad. Se dispone un plazo de tres (3) años a partir de la promulgación de la presente Ley para la exigibilidad de los títulos académicos establecidos como requisito para el ascenso a las categorías de Personal de Comando de Dotación del Cuerpo de Bomberos, establecido en el artículo 298 de la presente. Este plazo puede ser prorrogado por una vez por resolución fundada del Ministro de Justicia y Seguridad.",

    " Libro V: Clausulas Transitorias - DÉCIMO NOVENA": "Los afiliados y beneficiarios de la Obra Social de la Policía Metropolitana (O.S.P.O.M.E.) creada por Ley 2498, al tiempo de la promulgación de la presente, se consideran automáticamente transferidos a la O.S.Pe.Se., a quien se le cederá, a través de convenios específicos, los derechos y obligaciones que al efecto se determinen.",
    
    " Libro V: Clausulas Transitorias - VIGÉSIMA": "Los afiliados de la Obra Social de la Policía Federal Argentina-Superintendencia de Bienestar transferidos en virtud del 'Convenio de Transferencia Progresiva a la Ciudad Autónoma de Buenos Aires de Facultades y Funciones de Seguridad en Todas las Materias no Federales Ejercidas en la Ciudad Autónoma de Buenos Aires', aprobado por la Resolución de la Legislatura de la Ciudad de Buenos Aires 298/15, que al 31 de diciembre de 2016 no se encuentren en condiciones de retiro voluntario, jubilación o pensión, podrán optar por afiliarse a la O.S.Pe.Se. El ejercicio de la opción podrá efectuarse a partir del 1 de enero de 2017 por un plazo único y perentorio de tres (3) meses. Cumplido dicho plazo, de no haber ejercido la opción, ya no podrán hacerlo en lo sucesivo, manteniendo su afiliación anterior. En tal caso, los aportes y contribuciones serán transferidos por la Ciudad Autónoma de Buenos Aires a la Superintendencia de Bienestar de la Policía Federal Argentina.",
    
    " Libro V: Clausulas Transitorias - VIGÉSIMA PRIMERA": "Los afiliados de O.S.Pe.Se. que al 31 de diciembre de 2016 no se encuentren en condiciones de retiro voluntario, jubilación o pensión, podrán optar por afiliarse a la Obra Social de la Policía Federal Argentina - Superintendencia de Bienestar, en las condiciones que se establezcan en el Convenio que a tal efecto se suscriba. El ejercicio de la opción podrá efectuarse a partir del 1 de enero de 2017 por un plazo único y perentorio de tres (3) meses. Cumplido dicho plazo, de no haber ejercido la opción, ya no podrán hacerlo en lo sucesivo, manteniendo su afiliación anterior.",
    
    " Libro V: Clausulas Transitorias - VIGÉSIMA SEGUNDA": "O.S.Pe.Se como continuadora de O.S.P.O.M.E. es titular de todos los derechos, obligaciones y bienes de ésta. Las contrataciones y prestaciones contratadas por OSPOME continúan vigentes hasta su finalización conforme las modalidades de sus respectivos contratos.",
    
    " Libro V: Clausulas Transitorias - VIGÉSIMA TERCERA": "Aquellos beneficiarios adherentes afiliados a O.S.P.O.M.E. a la fecha de promulgación de la presente, recibirán la cobertura de la O.S.Pe.Se por un plazo de tres (3) meses.",
    
    " Libro V: Clausulas Transitorias - VIGÉSIMA CUARTA": "Aquellos beneficiarios jubilados, pensionados o retirados de la Policía Metropolitana a la fecha de promulgación de la presente ley, mantienen la cobertura de la Obra Social de la Ciudad de Buenos Aires (Ob.S.B.A).",

    "CLAUSULAS TRANSITORIAS DEL LIBRO VI - SEGURIDAD PRIVADA - VIGÉSIMO QUINTA": "Las cooperativas de trabajo debidamente conformadas que al 31 de diciembre de 2016 cuenten con una autorización vigente emitida por el Gobierno de la Ciudad para brindar servicios de seguridad privada, podrán continuar desarrollando la actividad, en tanto cumplan los restantes requisitos establecidos en esta Ley.",
    
    "CLAUSULAS TRANSITORIAS DEL LIBRO VI - SEGURIDAD PRIVADA - VIGÉSIMO SEXTA": "A los fines de dar cumplimiento a lo dispuesto en el artículo 441 inciso 1 del Libro VI, se establece un plazo de tres (3) años a partir de la promulgación de la presente ley.",
   
    "CLAUSULAS TRANSITORIAS DEL LIBRO VI - SEGURIDAD PRIVADA - VIGÉSIMO SEPTIMA": "A los fines de dar cumplimiento a lo dispuesto en el artículo 441 inciso 13 del Libro VI, se establece un plazo de un (1) año improrrogable a partir de la promulgación de la presente ley.",
    
    "CLAUSULAS TRANSITORIAS DEL LIBRO VI - SEGURIDAD PRIVADA - VIGESIMO OCTAVA": "A los fines de dar cumplimiento a lo dispuesto en el artículo 449 del Libro VI, se establece un plazo de tres (3) años improrrogable a partir de la promulgación de la presente ley.",
    
    "CLAUSULAS TRANSITORIAS DEL LIBRO VI - SEGURIDAD PRIVADA - VIGÉSIMO NOVENA": "A los fines de dar cumplimiento a lo establecido en el artículo 469 inciso 5 del Libro VI, se establece un plazo de cinco (5) años improrrogable a partir de la promulgación de la presente ley.",

    "CLAUSULAS TRANSITORIAS DEL LIBRO VII - SISTEMA INTEGRAL DE VIDEOVIGILANCIA - TRIGÉSIMA": "En el plazo de dos (2) meses a partir de la promulgación de la presente ley, la autoridad de aplicación procederá a confeccionar los informes acerca de las instalaciones de videocámaras actualmente existentes, así como a destruir aquellas grabaciones que no reúnan las condiciones legales para su conservación.",
    
    "CLAUSULAS TRANSITORIAS DEL LIBRO VII - SISTEMA INTEGRAL DE VIDEOVIGILANCIA - TRIGÉSIMO PRIMERA": "Los establecimientos privados alcanzados por la obligación emanada del artículo 487 del Libro VII, tendrán un plazo de un (1) año contado a partir de la promulgación de la presente Ley para adecuarse a lo establecido.",

    "COMISIÓN DE SEGUIMIENTO - TRIGESIMO SEGUNDA": "Créase en el ámbito de la Legislatura de la Ciudad Autónoma de Buenos Aires, la Comisión de Seguimiento de la Etapa de Consolidación conforme Resolución 289/LCABA/015. La Comisión está integrada por los/as Presidentes/as de las Comisiones de Seguridad, de Justicia y de Presupuesto, Hacienda, Administración Financiera y Política Tributaria y veintidós (22) Diputados/as respetando la proporción en que los sectores políticos están representados en el seno de la Legislatura de la Ciudad Autónoma de Buenos Aires, los que serán designados por la Vicepresidencia Primera de dicho cuerpo. La Comisión tendrá una duración de un (1) año, y tiene por objeto el seguimiento, tratamiento y análisis integral de la segunda etapa - Consolidación - conforme el Convenio 1/16 firmado entre el Estado Nacional y la Ciudad Autónoma de Buenos Aires, debiendo elaborar dos (2) informes semestrales para ser presentados en plenario de las Comisiones mencionadas precedentemente.",
    

/*
REGLAMENTACIÓN CAPÍTULO XIX DEL TÍTULO III DEL LIBRO II (Arts. 191 al 206) y
CAPÍTULO VIII DEL TÍTULO IV DEL LIBRO II (Artículo 260) DE LA LEY N° 5.688
TÍTULO I
Disposiciones Generales*/


    "Artículo 1": "El presente régimen disciplinario se aplica a todo el personal con y sin estado policial que integra la Policía de la Ciudad y al personal retirado.",
        
    "Artículo 2": "El órgano disciplinario interno de la Policía de la Ciudad es competente para entender en la investigación de las faltas leves y moderadas establecidas en los artículos 7, 8, 9 y 10 de la presente Reglamentación.",
        
    "Artículo 3": "La Oficina de Transparencia y Control Externo del Ministerio de Justicia y Seguridad de la Ciudad es competente para entender en la investigación de las faltas graves, de acuerdo con lo establecido en los artículos 11 y 12 de la presente Reglamentación. Es también competente para sustanciar las actuaciones en las que resulte involucrado personal del órgano disciplinario interno de la Policía de la Ciudad, con independencia del carácter de la falta investigada.",
        
    "Artículo 4": "Sin perjuicio de lo anterior, en aquellas actuaciones administrativas instruidas por el órgano disciplinario interno de la Policía de la Ciudad, la Oficina de Transparencia y Control Externo puede declararse competente en los siguientes casos:\n1) En el supuesto contemplado en el inciso 3 del artículo 38 de la Ley N° 5688;\n2) Cuando existan elementos que sugieran que la falta investigada puede ser grave;\n3) Cuando se investigue la comisión de más de una falta moderada;\n4) En caso de accidentes, si se comprobase la existencia de daños a los bienes de la Institución y/o si resultara lesionado y/o se hubiere dado muerte a una persona;\n5) Si el involucrado en las actuaciones administrativas hubiera sido condenado o se encontrase procesado o con auto de citación a juicio o acto procesal equivalente en causa penal;\n6) Cuando por la potencial trascendencia institucional de los actos investigados, la Oficina de Transparencia y Control Externo decida por resolución fundada abocarse a la investigación.\n7) Cuando sea expresamente solicitado por el Jefe de la Policía de la Ciudad.",

    "Artículo 5": "Constituye falta disciplinaria incurrir en alguna de las prohibiciones o incumplir alguno de los deberes y obligaciones policiales establecidos en las Leyes, Decretos, Resoluciones y Disposiciones aplicables.",

    "Artículo 6": "En la ejecución de una orden de servicio es responsable el superior que la imparta. El subalterno no incurre en falta, sino cuando se aparte de aquella, se hubiera excedido en su ejecución o cumplido con una orden manifiestamente ilegítima.",

    "Artículo 7": "Constituye falta leve:\n1) El incumplimiento a lo dispuesto en el artículo 100 o en los incisos 9, 12, 13 y 15 del artículo 109 de la Ley N° 5688.\n2) La falta de diligencia, profesionalismo, puntualidad o exactitud en el cumplimiento de los deberes inherentes a la función que se le encomiende.\n3) Adoptar posturas de descanso inapropiadas durante el servicio, aún cuando ello no afecte la debida atención que la función asignada amerita.\n... (se omite el resto de los subpuntos por brevedad)",

    "Artículo 8": "Sin perjuicio de lo dispuesto en el artículo 7, se considera falta leve aquella transgresión que por su naturaleza o las circunstancias en que fuera cometida merezca tal calificación por resolución fundada del Jefe de la Policía o del Secretario de Seguridad.",

    "Artículo 9": "Constituye falta moderada:\n1) El incumplimiento a lo dispuesto en el inciso 11 del artículo 109 de la Ley N.° 5688.\n2) Incumplir órdenes del servicio, aún en forma parcial o cumplirlas en modo negligente, cuando ello cause perjuicio de cualquier tipo.\n3) La negligencia o imprudencia en un acto de servicio, siempre que ese hecho no constituya una falta grave.\n... (se omite el resto de los subpuntos por brevedad)",

    "Artículo 10": "Sin perjuicio de lo dispuesto en el artículo 9, se considera falta moderada aquella transgresión que por su naturaleza o las circunstancias en que fuera cometida merezca tal calificación por resolución fundada del Jefe de la Policía o del Secretario de Seguridad.",

    "Artículo 11": "Constituye falta grave:\n1) El incumplimiento de lo dispuesto en los artículos 83, 84, 85, 86, 87, 88 segundo párrafo, 91, 92, 93, 94, 96, 97, 98, 99, 109 inciso 7 y 110 de la Ley N° 5688.\n2) Cometer insubordinación, provocarla o instigar a otros a cometerla.\n3) Agredir física o verbalmente a un superior, en servicio o fuera de él.\n4) Desafiar, extraer armas o efectuar otras demostraciones agresivas o intimidantes contra terceros, sin causa fundada.\n5) Acosar y/o discriminar por razones de sexo, raza, ideología, religión, condición étnica, económica, social o personal de todo tipo a cualquier persona.\n6) Cometer actos que impliquen la afectación de la dignidad humana y/o violen Derechos Humanos.\n7) Ordenar a un subalterno que transgreda las leyes en general y el régimen disciplinario en particular.\n8) Omitir sin justificación constituirse en forma inmediata en el sitio donde se requiera su presencia frente a la comunicación de una emergencia o no disponer que un subalterno lo haga.\n9) Incumplir con el servicio encomendado o cumplirlo en forma negligente, cuando de ello se verifique una amenaza o afectación a la vida, patrimonio o salud de las personas.\n10) Incumplir el servicio invocando falsa causa, ardid o engaño.\n11) Omitir, aún en forma negligente, la persecución o represión de delitos, faltas o contravenciones.\n12) Dejar huir o posibilitar la huída de un detenido.\n13) El abandono de servicio.\n14) Las inasistencias reiteradas en forma alternada y sin justificar por un plazo mayor a veinte (20) días durante el transcurso de un (1) año calendario.\n15) Incumplir, por acción u omisión, un deber legalmente impuesto, en tanto se verifique una grave afectación a la ética, la integridad y la honestidad del funcionario.\n16) La inducción a error o engaño al superior con informes que no sean exactos cuando la gravedad de la conducta lo amerite.\n17) Hacer entrega y/o disponer, a título oneroso o gratuito, de la credencial, medalla, armamento, distintivos, placa de identificación, uniformes y/o cualquier bien o equipo policial a terceros, salvo el caso contemplado en el inciso 7 del artículo 7.\n18) El manipuleo indebido del arma o el disparo injustificado, negligente o imprudente del armamento.\n19) Tener en servicio armas de fuego no autorizadas para el ejercicio de la función.\n20) La pérdida o sustracción del armamento policial, ya sea por descuido en su conservación, por negligencia o imprudencia.\n21) Hallarse en estado de ebriedad, intoxicación por estupefacientes y/o fármacos no autorizados durante el servicio.\n22) Hallarse en estado de ebriedad fuera de servicio, si como consecuencia de la falta se ocasionen daños o lesiones a particulares. En este caso, la sanción podrá acompañar la recomendación para la realización de cursos de rehabilitación que correspondan.\n23) Hallarse en estado de intoxicación por estupefacientes fuera de servicio. En este caso, la sanción podrá acompañar la recomendación para la realización de cursos de rehabilitación que correspondan.\n24) Mantener vinculaciones que le representen beneficios u obligaciones con entidades directamente controladas por la Institución.\n25) Recomendar servicios de terceros, aún cuando no se obtenga una ganancia de ello.\n26) La recepción de premios bajo cualquier forma o pretexto y de cualquier clase o valor, sin permiso previo de la Jefatura de la Policía de la Ciudad.\n27) El pedido o aceptación de propinas, recompensas o regalos en su condición de integrante de la Institución.\n28) El incumplimiento al deber de guardar secreto de todo cuanto sabe, aún después del retiro, que se relacione con los asuntos del servicio que, por su naturaleza o en virtud de disposiciones especiales, impongan dicha conducta, salvo requerimiento judicial.\n29) La pérdida, deterioro o sustracción de bienes de importancia o documentación secreta o reservada de la Institución.\n30) La incomparecencia, la negativa, falsedad u ocultamiento de la verdad por quien deba prestar testimonio en sumario administrativo y/o causa judicial.\n31) La falsa imputación maliciosa contra superiores, iguales o subalternos.\n32) Negarse a presentar la declaración jurada de antecedentes, la declaración jurada sobre la propiedad o tenencia de armas de fuego a título particular o cualquier otra declaración obligatoria establecida en la normativa vigente.\n33) Ocasionar la muerte a un animal afectado al servicio, ya sea en forma imprudente, negligente o maliciosa.\n34) Las conductas que afecten la ética, la integridad y la honestidad del funcionario y que comprometan seriamente la racionalidad y la legalidad en la actuación del personal de la Policía de la Ciudad.\n35) La condena firme por delito doloso.\n36) El incumplimiento de las formas previstas para el uso de las facultades de prevención y de la fuerza directa, según los capítulos III, IV y V del Título II del Libro II de la Ley N° 5688.\n37) El incumplimiento de los protocolos de actuación cuando ello implique una infracción al uso proporcional de la fuerza directa.",

    "Artículo 12": "Sin perjuicio de lo dispuesto en el artículo 11, se considera falta grave aquella trasgresión que por su naturaleza o las circunstancias en que se cometa, merezca tal calificación por resolución fundada del Secretario de Seguridad.",

    "Artículo 13": "También constituye falta grave la comisión de más de una falta moderada.",

    "Artículo 14": "Comprobada la comisión de una falta, la sanción no puede exceder el máximo de la especie que se imponga, sin perjuicio de lo dispuesto en el artículo 19 de esta reglamentación.",

    "Artículo 15": "Las faltas leves se sancionan con apercibimiento escrito o mediante la suspensión en el empleo por el término de un (1) día, hasta el máximo de quince (15) días de duración.",
    
    "Artículo 16": "Las faltas moderadas se sancionan con suspensión de empleo hasta un máximo de cuarenta y cinco (45) días de duración.",
    
    "Artículo 17": "Las faltas graves se sancionan con suspensión de empleo hasta un máximo de noventa (90) días de duración, o cesantía o exoneración, de acuerdo con las circunstancias del caso.",
    
    "Artículo 18": "Cuando un hecho quede encuadrado en más de una falta, se considera únicamente la falta de carácter más grave.",
    
    "Artículo 19": "Ante el eventual concurso de faltas a las que corresponda una misma especie de sanción, para la determinación del quantum aplicable debe tenerse en cuenta como máximo la suma aritmética de las sanciones máximas correspondientes a los distintos hechos.",

    "Artículo 20": "El apercibimiento escrito debe ser efectuado por el superior al subalterno ante la comisión de una falta de carácter leve cuya naturaleza, circunstancia o magnitud no merezca otra sanción mayor. Debe hacerse en términos claros, precisos y moderados, que no importen una afrenta o injuria a la persona sancionada y debe ser notificado al infractor.",

    "Artículo 21": "El apercibimiento oral no configura sanción en caso de no ser ratificado por escrito dentro de las veinticuatro (24) horas, debiendo ser notificado al sancionado.",
    
    "Artículo 22": "El apercibimiento escrito puede ser individual o colectivo:\n1) El apercibimiento individual se efectúa en forma privada, pero puede aplicarse también en presencia de los superiores que hubieran conocido la falta, cuando el que aperciba lo considere conveniente para su mayor eficacia.\n2) El apercibimiento colectivo se aplica al personal que cometa una falta leve en el supuesto contemplado en el inciso 5 del artículo 57 de la presente reglamentación.",
    
    "Artículo 23": "La suspensión de empleo se computa por días corridos y puede tener una duración máxima de noventa (90) días, sin perjuicio de lo normado en el artículo 19 de esta reglamentación.",
    
    "Artículo 24": "Mientras dure la suspensión de empleo, el funcionario policial no puede cumplir tarea alguna ni percibe haberes por el tiempo proporcional de la duración de la sanción.",
    
    "Artículo 25": "La sanción de suspensión de empleo implica la suspensión del estado policial, salvo en la observancia de sus prohibiciones. El lapso de duración de la sanción no se computa a los fines del ascenso ni del retiro.",
    
    "Artículo 26": "El acto administrativo que impone la sanción de suspensión de empleo debe contemplar, los siguientes aspectos:\n1) Individualización del sujeto en el que recae la sanción.\n2) La cantidad de días de suspensión impuestos.\n3) Especificación clara de los hechos, pruebas y encuadre normativo que justifiquen la sanción.\n4) Circunstancias agravantes o atenuantes, si las hubiera.\n5) Concepto que merece el sancionado por parte del jefe de la dependencia donde presta servicios y del superior inmediato del infractor; con prescindencia del hecho que motive la sanción.\n6) Los antecedentes disciplinarios que registre el infractor en su legajo.\n7) Consecuencias administrativas, de corresponder.",

    "Artículo 27": "La sanción debe hacerse efectiva a partir de su notificación, salvo que razones de servicio debidamente fundadas impongan su postergación.",

    "Artículo 28": "Al comenzar a ejecutarse la sanción, el infractor debe entregar todos los elementos que le fueran asignados, incluyendo la credencial, medalla, placa de identificación o cualquier atributo distintivo de grado, armamento, y/o cualquier otro elemento asignado. Dichos elementos se le restituyen al finalizar el cumplimiento de la sanción. Durante el cumplimiento de la sanción el infractor tiene prohibición absoluta de utilizar el uniforme, en cualquier ámbito, sea público o privado.",

    "Artículo 29": "En caso que en el acto de notificación de la sanción no se efectivice la entrega de la totalidad de los elementos detallados en el artículo 28, debe intimarse fehacientemente al sancionado para que en el plazo perentorio de veinticuatro (24) horas, proceda a efectuar la entrega ante la dependencia que corresponda.",

    "Artículo 30": "En el momento de notificarse la sanción debe indicarse claramente la fecha de inicio, finalización y el día en que el sancionado debe reintegrarse a sus tareas.",

    "Artículo 31": "El personal que fuera cambiado de destino y se hallara cumpliendo una sanción de suspensión, una vez finalizada, debe presentarse en la dependencia en la cual prestaba servicios originariamente a los efectos administrativos correspondientes.",

    "Artículo 32": "El cumplimiento de la sanción comienza a partir de la hora cero (00:00) del día de inicio y finaliza a la hora veinticuatro (24:00) del último día de sanción impuesta.",

    "Artículo 33": "La sanción de suspensión no puede hacerse efectiva durante el usufructo de una licencia con goce de haberes. Su cumplimiento se posterga hasta el fin de la licencia en curso. En este caso, la prescripción de la acción de la administración de hacer efectiva la pena se suspende hasta la finalización de la licencia.",

    "Artículo 34": "Una vez notificada, la sanción de suspensión de empleo no se posterga, suspende ni interrumpe por la solicitud o el otorgamiento de licencias con o sin goce de haberes. Las licencias comienzan a computarse, en caso de corresponder y por el lapso no devengado, una vez cumplida la sanción.",

    "Artículo 35": "Corresponde indefectiblemente la sanción de cesantía cuando se verifique:\n1) La condena penal firme por delito doloso, siempre que por la naturaleza o la gravedad del hecho no corresponda la sanción de exoneración. Sin embargo, si el hecho que da lugar a la condena tuviese relación con el servicio, se verificase el supuesto contemplado en el artículo 35 del Código Penal y la pena no supera los tres (3) años de prisión de cumplimiento efectivo, el condenado se mantiene en la situación contemplada en el artículo 157 inciso 6 de la Ley N° 5.688.\n2) Las faltas contempladas en los incisos 10, 13, 14, 21, y 23 del artículo 11 de la presente reglamentación.",

    "Artículo 36": "Es causa suficiente para aplicar la sanción de exoneración:\n1) La condena penal firme por delito doloso, cuando la especie y gravedad del delito lo ameriten.\n2) La comisión de una falta grave que por su magnitud y trascendencia implique grave indignidad o comprometa notoriamente el prestigio de la institución.",

    "Artículo 37": "No es necesaria la sustanciación de sumario con carácter previo a aplicar una sanción segregativa en los siguientes supuestos:\n1) Cuando exista condena firme en causa penal por delito doloso, en las condiciones establecidas en los artículos 35 y 36 de la presente reglamentación;\n2) Cuando se produzca el abandono de servicio configurado conforme lo dispuesto en los artículos 196 a 199 de la presente;\n3) Cuando se hubiese incurrido en inasistencias injustificadas reiteradas conforme lo dispuesto en el inciso 5 del artículo 200 de esta reglamentación.",

    "Artículo 38": "Cuando durante la sustanciación de un sumario administrativo se tomase conocimiento de la existencia de una condena firme originada en los mismos hechos investigados en la actuación administrativa, con la copia fehaciente de la sentencia, y sin más trámite, se ordena la clausura del sumario y se elevan las actuaciones para la aplicación de la sanción correspondiente.",

    "Artículo 39": "Cuando se impusiere una sanción segregativa en virtud de lo dispuesto en el artículo 37 de la presente reglamentación y existiesen sumarios en trámite en los que se investigan otras irregularidades imputadas a la misma persona, estas actuaciones continúan hasta que la sanción segregativa queda firme. Luego se clausuran sin más trámite y se acumulan a las actuaciones en las que esta se impuso.",

    "Artículo 40": "La facultad disciplinaria implica investigar y sancionar las faltas previstas en la presente reglamentación, así como supervisar que las sanciones que aplican los superiores a los subordinados se ajusten a la ley y a las normas reglamentarias.",

    "Artículo 41": "El Secretario de Seguridad, el Jefe, el Subjefe de la Policía de la Ciudad y el personal policial que se detallan a continuación, tienen las siguientes facultades disciplinarias:\n1) El Secretario de Seguridad puede aplicar apercibimiento, suspensión de empleo, cesantía y exoneración al personal con y sin estado policial que integra la Policía de la Ciudad.\n2) El Jefe de la Policía de la Ciudad puede aplicar apercibimiento y suspensión de empleo hasta un máximo de cuarenta y cinco (45) días de duración, sin perjuicio de lo dispuesto en el artículo 19 de la presente reglamentación.\n3) El Subjefe de la Policía de la Ciudad puede aplicar apercibimiento y suspensión de empleo hasta un máximo de treinta (30) días de duración, sin perjuicio de lo dispuesto en el artículo 19 de la presente reglamentación.\n4) El Superintendente y los titulares de los órganos que dependan en forma directa del Jefe de la Policía de la Ciudad pueden aplicar apercibimiento y suspensión en el empleo por un máximo de quince (15) días de duración, sin perjuicio de lo dispuesto en el artículo 19 de la presente reglamentación.\n5) El Comisionado General puede aplicar apercibimiento y suspensión en el empleo por un máximo de trece (13) días de duración.\n6) El Comisionado Mayor puede aplicar apercibimiento y suspensión de empleo por un máximo de diez (10) días de duración.\n7) El Comisario puede aplicar apercibimiento y suspensión de empleo por un máximo de ocho (8) días de duración.\n8) El Subcomisario puede aplicar apercibimiento y suspensión de empleo por un máximo de seis (6) días de duración.\n9) El Inspector Principal puede aplicar apercibimiento y suspensión de empleo por un máximo de cuatro (4) días de duración;\n10) El Inspector puede aplicar apercibimiento y suspensión de empleo por un máximo de tres (3) días de duración.",
    
    "Artículo 42": "El personal policial que desempeñe funciones superiores a las que le corresponden por el grado que posee tiene las facultades disciplinarias correspondientes al cargo que ocupe o del superior que reemplace.",
    
    "Artículo 43": "El personal sin estado policial tiene facultades disciplinarias respecto al personal sin estado policial que esté directamente subordinado, y puede aplicar apercibimiento y suspensión de empleo hasta un máximo de tres (3) días.",
    
    "Artículo 44": "La facultad disciplinaria es ejercida por el superior del funcionario policial que ha cometido la falta al momento del hecho, aunque esta relación fuera circunstancial o cuando hubiera sido cometida en otros destinos y fuera descubierta con posterioridad a su pase. Esta será fiscalizada por el inmediato superior al sancionante, exclusivamente.",
    
    "Artículo 45": "Todo aquel que carezca de facultades disciplinarias respecto del funcionario policial que cometió la falta debe informar al superior para que este adopte las medidas que correspondan.",
    
    "Artículo 46": "El personal sin estado policial no puede ejercer facultades disciplinarias sobre el personal con estado policial que se encuentra bajo sus órdenes. Ante la eventual comisión de una falta debe comunicar el hecho al superior policial inmediato, quien debe resolver la procedencia de aplicar la sanción que a su juicio corresponda o solicitar el inicio de las actuaciones administrativas disciplinarias.",
    
    "Artículo 47": "El personal con estado policial puede ejercer las facultades disciplinarias sobre el personal con y sin estado policial que se encuentra bajo sus órdenes, y de acuerdo con las prescripciones establecidas en el Artículo 41 de la presente reglamentación.",

    "Artículo 48": "El personal retirado no tiene facultades disciplinarias, salvo que sea llamado a prestar servicios, en cuyo caso las puede ejercer exclusivamente respecto del personal que se encuentre bajo sus órdenes y de conformidad con las prescripciones establecidas en el Artículo 41 de la presente reglamentación. En el resto de los supuestos, el personal en situación de retiro debe comunicar la falta observada al superior del infractor, quien debe resolver sobre la procedencia de aplicar la sanción que a su juicio corresponda o solicitar el inicio de las actuaciones administrativas disciplinarias.",

    "Artículo 49": "Cuando quien comprobare la comisión de una falta leve considerase insuficientes sus facultades disciplinarias para sancionarla, debe aplicar el máximo hasta el límite de aquellas, y solicitar al superior el aumento de la sanción impuesta.",

    "Artículo 50": "El superior que realice la fiscalización puede confirmar, sustituir, disminuir, dejar sin efecto o aumentar, dentro de sus facultades y en forma fundada, las sanciones que apliquen sus subordinados. Tal atribución debe ejercerse en forma y de manera que no menoscabe la autoridad de quien impuso la sanción.",

    "Artículo 51": "Si el superior de quien corresponde la fiscalización decide dejar sin efecto la sanción, debe elevar el expediente a su superior de grado inmediato para actuar como fiscalización de su decisión, y así sucesivamente hasta llegar al Jefe de la Policía de la Ciudad, si en dos instancias consecutivas no coinciden en la ratificación de la sanción a imponer o dejarla sin efecto.",

    "Artículo 52": "Cuando el fiscalizador considere no tener las facultades disciplinarias suficientes para imponer la sanción, debe actuar conforme lo normado en el Artículo 49 de la presente reglamentación.",

    "Artículo 53": "En ejercicio de sus facultades de fiscalización, el superior puede requerir directamente los antecedentes o aclaraciones que estime corresponder.",

    "Artículo 54": "Cuando una falta se cometa en presencia de un superior a quien corresponda sancionarla, ningún subalterno puede hacerlo, excepto que le fuera ordenado por aquel.",

    "Artículo 55": "Las facultades disciplinarias a igualdad de grado se ejercen conforme a las normas de precedencia, antigüedad y cargo que determina el Artículo 117 de la Ley N° 5688.",

    "Artículo 56": "Las faltas moderadas o graves que cometa el personal del órgano disciplinario interno de la Policía de la Ciudad son sancionadas por el Secretario de Seguridad previo sumario administrativo instruido por la Oficina de Transparencia y Control Externo, de corresponder.",

    "Artículo 57": "En el momento de la determinación de la pena se consideran circunstancias agravantes:\n1) Que la infracción perjudique al servicio;\n2) Que afecte al prestigio de la Policía de la Ciudad;\n3) Que la falta sea reiterada;\n4) Que exista reincidencia;\n5) Que la falta sea cometida en forma colectiva;\n6) Que la falta se cometa en presencia de subalternos;\n7) Cuanto mayor es el grado de quien la cometa;\n8) Que la cometa quien cumple funciones como Jefe de Dependencia;\n9) Que se cause perjuicio a un subalterno;\n10) Que se compruebe el empleo de elementos de uso prohibido;\n11) La entidad de la acción, su extensión, consecuencias y peligro real o abstracto;\n12) El ánimo de lucro o promesa de beneficios de cualquier índole, como agente pasivo o activo del hecho;\n13) Que el hecho haya sido motivado mediando odio o segregación por raza, ideología, sexo, religión o condición étnica, económica, social o personal de cualquier tipo y que fueran determinantes para su comisión.",

    "Artículo 58": "Se considera reincidencia en la comisión de una o diversas faltas, cualquiera sea la naturaleza de ellas, cuando se imponga una nueva sanción disciplinaria dentro de los plazos que se detallan a continuación:\n1) Apercibimiento, un (1) mes.\n2) Suspensión de empleo hasta cuarenta y cinco (45) días, seis (6) meses\n3) Suspensión de empleo por un plazo mayor a cuarenta y cinco (45) días, un (1) año.\nEstos plazos se cuentan desde la fecha en la que se notificó la última sanción.",

    "Artículo 59": "Se considera que hay reiteración en la comisión de una falta cuando se trate de otra de la misma naturaleza y haya sido cometida dentro del término de un (1) año, a contar desde la notificación de la última sanción impuesta.",

    "Artículo 60": "Comprobada la reiteración o la reincidencia de la falta cometida, debe imponerse una sanción mayor a la última aplicada, respetando el orden de prelación de la última sanción impuesta cuando fueran de igual calificación. Ante una falta de carácter más grave, la imposición de la sanción debe considerar dicha reiteración o reincidencia.",

    "Artículo 61": "La falta se considera cometida en forma colectiva cuando intervinieran tres (3) o más integrantes de la institución que se hubieren concertado para su ejecución.",

    "Artículo 62": "En el momento de la determinación de la pena se consideran circunstancias atenuantes:\n1) Cuando medie inexperiencia motivada por la antigüedad menor a un (1) año en la prestación efectiva del servicio, y siempre que la falta no sea grave;\n2) La buena conducta anterior y el buen concepto merecido por sus superiores, con independencia de la falta cometida;\n3) Cuando se comprueba que la falta fue cometida por el exceso de celo en bien del servicio;\n4) Cuando la falta fue cometida habiendo mediado abuso del superior en la orden impartida;\n5) Que la transgresión no haya producido consecuencias a la operatividad del servicio, daños materiales o lesiones a terceros.",

    "Artículo 63": "Es exclusiva facultad del Secretario de Seguridad y del Jefe de la Policía de la Ciudad remitir o conmutar fundadamente la sanción de suspensión de empleo.",

    "Artículo 64": "La remisión de la sanción consiste en el perdón del inculpado, eximiéndolo del cumplimiento de la medida disciplinaria.",

    "Artículo 65": "La conmutación consiste en sustituir la sanción por otra más benigna.",

    "Artículo 66": "La remisión o conmutación de la sanción disciplinaria solamente hace a su cumplimiento, pero no afecta su existencia, debiéndose dejar constancia de ello en el legajo personal.",

    "Artículo 67": "No puede aplicarse el beneficio de la remisión o la conmutación cuando la falta investigada se encuentra comprendida en alguno de los supuestos establecidos en los artículos 35 y 36 del presente reglamento.",

    "Artículo 68": "Las sanciones de apercibimiento y de suspensión de empleo por el término de hasta quince (15) días correspondientes a faltas leves deben imponerse en forma directa, evitándose la sustanciación de actuaciones administrativas que dilaten su aplicación, excepto el caso en que por la naturaleza de la falta se requiera la iniciación de averiguaciones previas o de un sumario administrativo para juzgar la conducta.",
    
    "Artículo 69": "Previo a la aplicación de sanciones directas, se debe garantizar al sancionado su derecho a realizar su descargo. De ello se debe dejar constancia en el escrito que informa la sanción a imponer.",
    
    "Artículo 70": "Luego de notificada fehacientemente la sanción a imponer, debe remitirse el expediente al órgano del Ministerio de Justicia y Seguridad encargado de la gestión de recursos humanos policiales para el debido registro de la sanción en el legajo personal del sancionado.",
    
    "Artículo 71": "La aplicación de sanciones directas debe ser informada a la Oficina de Transparencia y Control Externo en todos los casos.",
    
    "Artículo 72": "En caso de advertir irregularidades en el tratamiento de las sanciones aplicadas en forma directa, la Oficina de Transparencia y Control Externo remite al Jefe de la Policía de la Ciudad un informe detallado con las consideraciones que estime pertinentes.",

    "Artículo 73": "La acción para imponer las sanciones por faltas disciplinarias prescribe en los siguientes plazos, conforme lo establecido en el artículo 203 de la Ley N° 5.688:\n1) Para las causales que dieran lugar a apercibimiento o suspensión: un (1) año\n2) Para las causales que dieran lugar a cesantía o exoneración: dos (2) años.\nEn todos los casos, el plazo se cuenta desde el momento de la comisión de la falta administrativa, si fuese instantánea o desde que hubiera dejado de cometerse, si fuese continua.",
    
    "Artículo 74": "La prescripción de la acción para imponer las sanciones por faltas disciplinarias se interrumpe por las siguientes causales, conforme lo establecido en el artículo 204 de la Ley N° 5.688:\n1) El inicio de las averiguaciones previas por parte del organismo disciplinario competente\n2) El inicio del sumario administrativo\n3) El llamado a prestar declaración de descargo en el sumario administrativo.",
    
    "Artículo 75": "El proceso judicial cuyo objeto verse sobre el mismo hecho que pueda configurar una falta disciplinaria suspende la prescripción de la acción para imponer sanciones administrativas hasta la sentencia judicial firme, conforme lo dispuesto por el artículo 205 de la Ley 5.688\nLa Administración puede imponer la sanción por la comisión de una falta administrativa antes de la culminación del proceso penal. En este caso, la sanción que se imponga en el orden administrativo tiene carácter provisional y puede ser sustituida por otra de mayor gravedad, si en la sentencia definitiva se acredita la configuración de una causal más grave que la sancionada.\nLa Administración no puede declarar libre de responsabilidad en un sumario administrativo a una persona sujeta a causa penal por el mismo hecho, hasta tanto finalice el proceso judicial y se determine el sobreseimiento o absolución firmes del imputado.",

    "Artículo 76": "Toda actuación administrativa que se inicie a los fines de determinar la existencia de un reproche administrativo debe concluirse dentro del plazo de 6 (seis) meses, computados a partir del momento en que se ordena su instrucción.",

    "Artículo 77": "El plazo establecido en el artículo 76 es ordenatorio y no perentorio. Cuando por razones ajenas al Instructor la actuación administrativa no pueda finalizar en dicho plazo, este se prorroga, ya sea en forma expresa o tácita, si existen diligencias pendientes de realización.\nEl plazo se suspende por el inicio de la causa penal que verse sobre los mismos hechos que el sumario administrativo, hasta la sentencia judicial firme.\nLa inactividad en la actuación administrativa sin causa justificada es responsabilidad del instructor, y no provoca la caducidad del procedimiento practicado.",

    "Artículo 78": "En caso de inactividad injustificada imputable al Instructor, corresponde al titular del área donde preste servicios, solicitar la instrucción de un sumario administrativo a los fines de evaluar la procedencia de un reproche disciplinario.",

    "Artículo 79": "Los plazos de la Instrucción para cualquier actuación administrativa que se sustancie, se computan por días hábiles administrativos. Si hubiese plazo de horas, será entre las 8 y las 19 horas.\nEste horario puede ser modificado por Resolución del Ministro de Justicia y Seguridad u organismo que en el futuro lo reemplace.",

    "Artículo 80": "Las averiguaciones previas son secretas y reservadas hasta tanto se realice el informe del instructor, de conformidad al Artículo 100 de la presente reglamentación.",

    "Artículo 81": "En los sumarios administrativos, rige el secreto hasta tanto se cite al personal a prestar la declaración de descargo.",

    "Artículo 82": "La obligación de guardar secreto se extiende al personal que intervenga en su tramitación o fiscalización y al que por cualquier motivo tenga conocimiento de hechos o circunstancias vinculadas. Solo quien acredite un derecho subjetivo y/o su letrado patrocinante debidamente autorizado podrá tomar vista de las actuaciones una vez clausurado el período de secreto.",

    "Artículo 83": "Se considera firma de urgencia toda la referente al régimen disciplinario. Debe darse prioridad a las solicitudes que formule la Instrucción y/o los titulares a cargo de las dependencias donde se sustancien dichas investigaciones. La investigación puede continuarse incluso los días feriados, cuando la suspensión o interrupción del trámite cause perjuicios al sumariado o a la Administración.",

    "Artículo 84": "En caso de denuncia verbal o escrita de un particular que verse sobre la conducta del personal de la Policía de la Ciudad o bien sobre los servicios o procedimientos de las dependencias, deben sustanciarse averiguaciones previas al sumario administrativo.",
    
    "Artículo 85": "La denuncia recibida debe remitirse inmediatamente a la Oficina de Transparencia y Control Externo. En caso de declararse incompetente, este órgano remite las actuaciones al órgano disciplinario interno de la Policía de la Ciudad para su trámite.",
    
    "Artículo 86": "No debe darse curso a ninguna denuncia de un particular sin previa ratificación por escrito del denunciante, en cuyo caso se comprueba su identidad y domicilio y se le solicitan las aclaraciones necesarias sobre el contenido de la denuncia.",
    
    "Artículo 87": "Sin perjuicio de lo anterior, puede actuarse de oficio en los siguientes casos:\n1) Si el hecho tiene trascendencia institucional o afecta la imagen de la Institución gravemente.\n2) Si como consecuencia del hecho, se produce la muerte de una persona.\n3) Si el hecho es de público conocimiento.",
    
    "Artículo 88": "Excepcionalmente, puede hacerse la reserva de la identidad de la persona denunciante, víctima y/o testigo en los siguientes casos:\n1) Cuando se compruebe amenaza de vida a la persona del denunciante, víctima o testigo o a su círculo familiar y/o íntimo;\n2) Cuando las circunstancias del hecho ameriten tal decisión, siempre que sea para proteger tanto al denunciante, víctima y/o testigo, como a la investigación.",
    
    "Artículo 89": "La reserva de identidad es decidida por el titular del órgano disciplinario en donde tramita el sumario, a propuesta del instructor, quien debe explicitar los motivos que sustentan su petición.",
    
    "Artículo 90": "En todos los casos, la medida debe mantenerse, incluso con posterioridad al levantamiento del secreto y reserva de la actuación administrativa. Los datos personales del denunciante son resguardados por el órgano que sustancia la investigación.",

    "Artículo 91": "Cuando la denuncia sea anónima, se puede disponer el inicio de averiguaciones previas al sumario, conforme a los hechos denunciados, si por las referencias que contenga o antecedentes que se posean, aquella presente aspectos de verosimilitud. En caso contrario se procede a su archivo.",

    "Artículo 92": "Si durante el trámite de un sumario administrativo el sumariado solicita la baja o accede al retiro, el procedimiento administrativo debe continuar hasta su resolución, incluso luego del cese de la relación de empleo del imputado, en cuyo caso la baja o retiro pueden reconvertirse en cesantía o exoneración, según corresponda.",
    
    "Artículo 93": "En el caso de los hechos presuntamente cometidos por el personal dado de baja, ya sea voluntaria u obligatoria, descubiertos con posterioridad a su separación de la Policía de la Ciudad, se deja constancia de la falta imputada en su legajo personal, sin instruirse actuación alguna, sin perjuicio del inicio de las acciones judiciales que correspondan. En caso de existir condena judicial debe archivarse una copia en el legajo.",

    "Artículo 94": "El Secretario de Seguridad y/o el Jefe de la Policía de la Ciudad pueden excepcionalmente disponer la sustanciación de un procedimiento abreviado, siempre que se configure alguna de las siguientes circunstancias:\n1) Que la existencia de la falta sea notoria y su comprobación no exija la investigación escrita.\n2) Que medie reconocimiento de la falta y sea posible y verosímil.",

    "Artículo 95": "El procedimiento abreviado se sustancia conforme las siguientes reglas:\n1) El titular de la Oficina de Transparencia y Control Externo o del órgano disciplinario interno de la Policía de la Ciudad solicita al Secretario de Seguridad o al Jefe de la Policía, según corresponda, la sustanciación de un procedimiento abreviado, adjuntando todos los antecedentes del caso.\n2) El Secretario o el Jefe de la Policía evalúan la solicitud y, de considerarla procedente, ordenan la sustanciación del procedimiento abreviado.\n3) El titular de la Oficina de Transparencia y Control Externo o del órgano disciplinario interno de la Policía de la Ciudad designan instructor sumariante.\n4) El instructor dispone el traslado de los cargos al sindicado como responsable y recibe su descargo.\n5) Recibido el descargo o vencido el plazo para hacerlo, el titular de la Oficina de Transparencia y Control Externo o del órgano disciplinario interno policial recomiendan la sanción a aplicar al Secretario de Seguridad o al Jefe de la Policía.",

    "Artículo 96": "Cuando por las características del hecho resulte necesario realizar diligencias preliminares a efectos de determinar si corresponde la aplicación de una sanción de carácter directo o bien la instrucción de un sumario administrativo, se deben labrar actuaciones denominadas averiguaciones previas.",

    "Artículo 97": "Se encuentran facultados para ordenar fundadamente la iniciación de averiguaciones previas el Secretario de Seguridad, el Jefe de la Policía de la Ciudad y el titular de la Oficina de Transparencia y Control Externo.",

    "Artículo 98": "Una vez iniciadas las averiguaciones previas en la dependencia competente para su tramitación, el titular de aquélla debe designar un funcionario en calidad de instructor a tales efectos.",

    "Artículo 99": "Se deben incorporar a las actuaciones las medidas probatorias mínimas e indispensables a los fines de determinar la verosimilitud de los hechos investigados, de los cuales se deja constancia escrita. Los medios de prueba a producir son determinados por el instructor de acuerdo con las reglas de la sana crítica.",

    "Artículo 100": "Concluidas las averiguaciones previas, el instructor realiza un informe circunstanciado con la descripción de las diligencias practicadas, su resultado con directa referencia a la fuente de la información que se recabó y su opinión fundada, merituando expresamente si resulta necesario el ejercicio de facultades disciplinarias de carácter directo, o si debe iniciarse un sumario administrativo. En caso contrario, solicita el archivo de todo lo actuado.",

    "Artículo 101": "Si al momento de concluir la investigación previa, el instructor dependiente de la Oficina de Transparencia y Control Externo propicia la aplicación de una sanción directa o el inicio de un sumario administrativo por una falta moderada, se deben remitir las actuaciones al Jefe de la Policía de la Ciudad para la prosecución del trámite correspondiente.",

    "Artículo 102": "Se encuentran facultados para disponer el archivo de las averiguaciones previas el Secretario de Seguridad, el titular de la Oficina de Transparencia y Control Externo y el Jefe de la Policía de la Ciudad. Si las averiguaciones previas se tramitaron en el órgano disciplinario interno de la Policía con carácter previo a su archivo, debe darse traslado a la Oficina de Transparencia y Control Externo.",

    "Artículo 103": "La aplicación de las sanciones previstas en este régimen se realiza previa instrucción de un sumario administrativo, con excepción de los siguientes supuestos:\n1) Sanciones de aplicación directa;\n2) Sustanciación del procedimiento abreviado previsto en los artículos 94 y 95 de la presente reglamentación;\n3) Los supuestos previstos en el artículo 37.\nEl Secretario de Seguridad y el Jefe o el Subjefe de la Policía de la Ciudad se encuentran facultados para ordenar la instrucción de un sumario administrativo.",

    "Artículo 104": "Sin perjuicio de lo expuesto, se encuentran facultados para proponer la instrucción de un sumario administrativo el titular de la Oficina de Transparencia y Control Externo, el titular a cargo del órgano disciplinario interno de la Policía de la Ciudad, los Superintendentes, y Jefes de Dependencia, frente a cualquier información que llegue a su conocimiento, si se presume una irregularidad.",

    "Artículo 105": "El personal que carezca de facultades para solicitar la instrucción de sumario, debe elevar los antecedentes del hecho a la autoridad que corresponda, la que puede disponer el inicio de la investigación pertinente, adoptando los recaudos necesarios para la conservación de los elementos de prueba hasta tanto el instructor tome la intervención correspondiente.",

    "Artículo 106": "En el pedido de instrucción de sumario administrativo se deben indicar las circunstancias del lugar, tiempo y modo de ejecución del hecho u omisión del objeto de investigación, así como el encuadre normativo que corresponda al tipo de falta presuntamente cometida.",

    "Artículo 107": "No es necesario individualizar al personal de la Policía de la Ciudad al que se les atribuye responsabilidad de una falta administrativa para considerar válida la orden de sumario y darle su curso. Sin perjuicio de lo expuesto, a los fines del inciso 2 del artículo 144 de la Ley N° 5.688, sólo se considera que el personal se encuentra sometido a sumario cuando se dicte un acto administrativo emitido por la autoridad competente para ordenar la instrucción de las actuaciones que así lo determine.",

    "Artículo 108": "La orden de instrucción de sumario debe comunicarse, a excepción de los casos previstos en el Artículo 107 del presente régimen, a:\n1) El Secretario de Seguridad\n2) La Oficina de Transparencia y Control Externo\n3) El Jefe de la Policía de la Ciudad\n4) Los órganos encargados de la gestión de los recursos humanos de la Policía de la Ciudad integrantes del Ministerio de Justicia y Seguridad y de la propia Policía.\n5) La Dirección General Administrativa y Legal de Seguridad\n6) El superior jerárquico de la dependencia donde el personal involucrado presta servicios.",

    "Artículo 109": "Las investigaciones administrativas son instruidas por funcionarios letrados que a los fines de este Reglamento se denominan Instructores Sumariales.",

    "Artículo 110": "El Instructor Sumarial debe:\n1) Investigar los hechos que dan origen al sumario administrativo.\n2) Proponer las medidas preventivas que resulten necesarias para la investigación.\n3) Reunir las pruebas útiles y necesarias que conduzcan al esclarecimiento de la verdad de los hechos, conforme los medios que prevé la presente Reglamentación, teniendo en cuenta los principios de celeridad y economía procesal.\n4) Recibir declaración al personal involucrado en calidad de denunciante, testigo, sumariado o sospechoso.\n5) Identificar el daño patrimonial, si corresponde.\n6) Calificar la conducta desplegada por el personal involucrado en el sumario y determinar responsables, si los hubiera.\n7) Proponer, según los elementos de juicio obrantes en las actuaciones, la sanción que corresponda.",

    "Artículo 111": "El Instructor Sumarial instruye el sumario administrativo con imparcialidad, y debe evitar todo aquello que pudiera afectarla.",

    "Artículo 112": "El Instructor Sumarial puede ser asistido por un Secretario y/o por un Auxiliar de Investigación, quienes son responsables por las diligencias que les solicite aquél.",

    "Artículo 113": "Como primer acto del procedimiento, se debe cursar la notificación al sumariado del contenido de la Resolución que instruye sumario, así como también del acta de designación del Instructor Sumarial.",

    "Artículo 114": "Dentro del plazo de tres (3) días hábiles, el sumariado puede presentar el pedido de recusación del Instructor, el Secretario o el Auxiliar de Investigación o éstos pueden excusarse cuando se advierta la existencia de alguna de las causales establecidas en el Artículo 21 del Código Procesal Penal de la Ciudad de Buenos Aires. El titular a cargo del área donde tramita el sumario debe resolver la excusación o recusación del personal designado.",

    "Artículo 115": "Si en el escrito de recusación o excusación no se alegase concretamente alguna de las causas contenidas en el artículo 21 del Código Procesal Penal de la Ciudad Autónoma de Buenos Aires, o la que se invoca es manifiestamente improcedente, o si se presentase fuera de la oportunidad señalada en el Artículo 114 de la presente, la recusación es desechada sin darle curso.",

    "Artículo 116": "Las medidas preventivas solo pueden dictarse en el marco de un sumario administrativo y ante la existencia de elementos de sospecha suficientes que ameriten su adopción. Se las considera medios cautelares que tienen como objetivo primordial asegurar el éxito de la investigación, evitar el entorpecimiento del procedimiento disciplinario y/o evitar eventuales daños.",

    "Artículo 117": "Las medidas preventivas pueden disponerse en cualquier momento del procedimiento.",

    "Artículo 118": "Las medidas preventivas son:\n1) El cambio de situación de revista del agente a disponibilidad o servicio pasivo, siempre que fuese inconveniente su continuidad en el servicio efectivo;\n2) El cambio de destino o traslado preventivo del agente, cuando se advierta que su permanencia en servicio no resulta un riesgo para la investigación. El destino es resuelto de acuerdo con la gravedad del hecho y las circunstancias del caso.\n3) El desarme del agente, incluso cuando continúe en servicio efectivo, asignándosele en este caso tareas acordes a su situación. En este supuesto el personal no percibe los suplementos previstos para retribuir el riesgo profesional ligado a las actividades propias del estado policial.",

    "Artículo 119": "Se encuentran facultados para dictar medidas preventivas, el Secretario de Seguridad, el Jefe y/o Subjefe de la Policía de la Ciudad, ya sea de oficio o bajo requerimiento del titular de la Oficina de Transparencia y Control Externo o del titular del órgano disciplinario interno de la Policía de la Ciudad.",

    "Artículo 120": "El pedido debe estar debidamente fundado, señalando los hechos y el riesgo que ocasionaría mantener al agente en servicio efectivo o en sus tareas habituales. La denuncia por sí sola no puede motivar la adopción de una medida preventiva, ya que se deben acreditar los elementos de juicio suficientes que justifiquen su necesidad. Se puede ordenar la imposición de una medida preventiva, si la denuncia ha tomado estado público, y siempre que sea en resguardo del prestigio institucional o bien a raíz de la alta exposición a la que se viera sometido el sumariado.",

    "Artículo 121": "Por regla, la medida preventiva se dispone hasta tanto se dicte la resolución definitiva en el sumario administrativo.",

    "Artículo 122": "La medida preventiva puede ser dejada sin efecto o sustituida por la misma autoridad que la haya dispuesto, por sí o a requerimiento del titular de la Oficina de Transparencia y Control Externo o bien el titular del órgano disciplinario policial interno, si cesaran las causas que la motivaron o si fuese necesario sustituirla por otra.",

    "Artículo 123": "El cambio de situación de revista del sumariado importa la privación del uso del grado y la aplicación de lo dispuesto en el Artículo 28 del presente reglamento.",

    "Artículo 124": "En los casos del personal sin estado policial, el Secretario de Seguridad, el Jefe y/o Subjefe de la Policía de la Ciudad, ya sea de oficio o bajo requerimiento del titular de la Oficina de Transparencia y Control Externo o del titular del órgano disciplinario interno, pueden aplicar medidas de carácter preventivo.",

    "Artículo 125": "Las medidas preventivas que pueden dictarse respecto al personal sin estado policial son las siguientes:\n1) Traslado y/o reasignación de funciones;\n2) Suspensión de empleo por hasta treinta (30) días. La imposición de esta medida preventiva significa la privación de haberes por su tiempo de duración. El instructor sumariante puede solicitar la prórroga del plazo mencionado justificando en cada oportunidad la necesidad de la medida y enumerando las diligencias pendientes de producción.",

    "Artículo 126": "En el supuesto de haberse aplicado la medida preventiva de pase a situación pasiva y se hayan retenido los haberes del sumariado, y de las conclusiones del sumario no surgieran sanciones o no fueran privativas de haberes o segregativas, estos le serán íntegramente abonados. En caso que de la conclusión del sumario surja una sanción privativa de haberes de menor cuantía que la suspensión preventiva impuesta, se le abona el saldo de los haberes retenidos. Esta disposición se aplica también al personal sin estado policial que fuere suspendido preventivamente, en caso de corresponder.",

    "Artículo 127": "Iniciado el sumario, la instrucción debe dejar constancia de los antecedentes disciplinarios que registra el investigado en su legajo personal. También debe solicitar al superior jerárquico directo del sumariado el concepto que le merece, con prescindencia de la falta investigada. La opinión brindada por el superior debe ser fundada.",

    "Artículo 128": "Cuando el hecho que motiva el sumario constituya presuntamente delito de acción pública, el instructor debe verificar si se ha realizado la denuncia penal correspondiente. Si no se hubiera realizado debe poner el hecho, junto con todos los antecedentes relevantes, en conocimiento del titular de la dependencia en donde tramita el sumario. Si el sumario se tramita en el órgano disciplinario interno de la Policía de la Ciudad, su titular informa del caso al titular de la Oficina de Transparencia y Control Externo. Este pone en conocimiento al Ministro de Justicia y Seguridad quien solicita la intervención de la Procuración General de la Ciudad.",

    "Artículo 129": "La sustanciación de los sumarios administrativos y la aplicación de las sanciones pertinentes se realizan con prescindencia de que los hechos que las originaron constituyan delito. Si existiese una causa penal pendiente por el hecho que motiva el sumario y de la prueba reunida en este no se desprendiese la comisión de una falta administrativa, el instructor puede solicitar al titular de la oficina donde tramitan las actuaciones la suspensión de la investigación, quien decide sobre su procedencia. Si se suspendiese la investigación administrativa, el Instructor Sumarial debe incorporar informes periódicos sobre el estado de la causa penal. La investigación puede reanudarse en cualquier momento, sin importar el estado de la causa penal, cuando existan elementos para ello.",

    "Artículo 130": "Se admiten todos los medios de prueba, salvo los que fueran manifiestamente improcedentes, superfluos o meramente dilatorios.",
    
    "Artículo 131": "El instructor sumarial debe formar su convicción respecto de la procedencia de la prueba, en conformidad con las reglas de la sana crítica.",
    
    "Artículo 132": "El sumariado puede ofrecer todo tipo de pruebas hasta la clausura de la instrucción. Su admisión es determinada por el instructor sumarial.",
    
    "Artículo 133": "En caso que el instructor sumarial considere improcedente, superflua o meramente dilatoria la prueba ofrecida, el acto que dispone el rechazo debe ser notificado al sumariado.",
    
    "Artículo 134": "Todas las diligencias probatorias que se incorporen al sumario se realizan en forma escrita, en actas y/o constancias de instrucción, que son suscriptas por el instructor sumarial, el Secretario o el auxiliar de investigación que intervino en su producción. Indefectiblemente, el instructor sumarial es el encargado de suscribir la declaración del imputado y aquellas diligencias que resultan relevantes para la investigación.",
    
    "Artículo 135": "En ocasión de recibir declaraciones y/o practicar diligencias útiles para la investigación fuera del ámbito de la Ciudad Autónoma Buenos Aires, esas medidas pueden ser materializadas por el secretario o el auxiliar de investigación, salvo que el instructor sumarial estime que debe practicarlas por sí. Los gastos que demanden dichas diligencias son autorizados por el titular del área donde se sustancia la investigación.",
    
    "Artículo 136": "Los informes solicitados deben ser contestados dentro del plazo de diez (10) días hábiles, salvo que el acto que los haya ordenado hubiera fijado otro plazo en razón de circunstancias especiales. En caso de incumplimiento, se debe informar a la autoridad con competencia para ordenar las medidas tendientes a deslindar responsabilidades, cuando se trate de organismos oficiales.",
    
    "Artículo 137": "El instructor sumarial, el secretario y/o el auxiliar de investigación pueden practicar inspecciones en lugares o cosas, dejando la debida constancia en el acta que se debe labrar al efecto, acompañando los croquis, fotografías y objetos que correspondan. Asimismo, el instructor sumarial puede disponer la concurrencia de peritos y/o testigos a dicho acto.",
    
    "Artículo 138": "El sumariado puede proponer la designación de peritos a su costa. La Administración se abstiene de designar peritos por su parte, y se limita a recabar informes de sus agentes y oficinas técnicas y de terceros, salvo que resulte necesario designarlos para la debida sustanciación del procedimiento.",
    
    "Artículo 139": "En el acto de solicitarse la designación de un perito, el proponente precisa el cuestionario sobre el que deberá expedirse. El instructor sumarial, luego de considerar, la pertinencia de su producción, puede aceptar o rechazar, en todo o en parte, la prueba pericial ofrecida y el cuestionario propuesto.",
    
    "Artículo 140": "Dentro del plazo de cinco (5) días de notificado el nombramiento, el perito debe aceptar el cargo en el expediente o su proponente agrega una constancia autenticada por el oficial público o autoridad competente de la aceptación de aquel. Vencido dicho plazo y si no se ofreció reemplazante, se perderá el derecho a esta prueba; igualmente se perderá si ofrecido y designado reemplazantes, este no aceptare la designación o el proponente tampoco agregare la constancia aludida dentro del plazo establecido.",
    
    "Artículo 141": "Corresponde al proponente instar la diligencia y adelantar los gastos razonables que requiere el perito según la naturaleza de la pericia; la falta de presentación del informe en tiempo importará el desistimiento de esta prueba.",
    
    "Artículo 142": "Ordenada la pericia por el instructor sumarial, se debe correr vista al sumariado de dicha providencia, la que necesariamente debe contener los puntos de pericia a realizar. Asimismo, el sumariado puede proponer puntos de pericia adicionales, siempre que fueran aceptados por el instructor sumarial. La denegatoria que realice el instructor sumarial de los puntos de pericia aportados por el sumariado, ya sea por ser improcedentes, superfluos o meramente dilatorios, debe hacerse constar por escrito.",
    
    "Artículo 143": "El área encargada de realizar el examen debe presentar un informe por escrito, el que debe contener la explicación detallada de las operaciones técnicas realizadas y de los principios científicos en que se fundan. Asimismo, se deben adjuntar aquellas fotografías, registros, análisis, gráficos, croquis y/u otros elementos que hubieran sido utilizados para la realización de la pericia.",
    
    "Artículo 144": "El instructor sumarial puede solicitar la ampliación de la pericia cuantas veces sea necesario hasta contar con el elemento de prueba que resulte útil para el esclarecimiento de los hechos investigados.",
    
    "Artículo 145": "El instructor sumarial puede citar a prestar declaración testimonial a toda persona que estime que, según lo que tenga por conocido, ya sea por sí o por terceros, pueda aportar datos relevantes para el esclarecimiento de los hechos investigados.",
    
    "Artículo 146": "El personal del Gobierno de la Ciudad Autónoma de Buenos Aires está obligado a comparecer y a prestar declaración como testigo bajo apercibimiento de ser sancionado en caso de incomparecencia. La ausencia injustificada por parte del personal de la Policía de la Ciudad, constituye falta disciplinaria, conforme lo establece la presente Reglamentación.",

    "Artículo 147": "Se encuentran exceptuados de la obligación de comparecer a declarar como testigos: el Jefe de Gobierno de la Ciudad Autónoma de Buenos Aires, sus Ministros, Secretarios y Subsecretarios, así como el Ministro de Justicia y Seguridad, sus Secretarios, sus Subsecretarios y el Jefe y Subjefe de la Policía de la Ciudad, pudiendo hacerlo por oficio. Esta facultad resulta extensiva a cualquier otro funcionario que, según la normativa vigente, se encuentre exceptuado de comparecer personalmente.",
    
    "Artículo 148": "No tienen la obligación de declarar aquellas personas ajenas al ámbito del Gobierno de la Ciudad Autónoma de Buenos Aires. Aquellos sujetos particulares que hayan tenido conocimiento por cualquier medio del hecho investigado, pueden hacer su declaración en forma voluntaria y personalmente, siempre que el Instructor Sumarial considere que su declaración es conducente para el desarrollo de la investigación.",

    "Artículo 149": "Pueden abstenerse de testificar o dar información en contra del sumariado: su cónyuge; la persona con la cual se encuentra unido/a civilmente; sus ascendientes, descendientes o hermanos/as, parientes colaterales hasta el cuarto grado de consanguinidad o segundo de afinidad; Se debe advertir a dichas personas sobre esa facultad, de lo que se dejará constancia.",

    "Artículo 150": "Deben abstenerse de declarar o dar información sobre los hechos secretos que hubieren llegado a su conocimiento en razón del propio estado, oficio o profesión los ministros de un culto admitido; los abogados, procuradores y escribanos; los médicos y demás auxiliares del arte de curar; los militares y funcionarios públicos sobre secretos de Estado. Se entenderá que rige el secreto profesional en el caso de los médicos y demás profesionales del arte de curar, cuando una persona involucrada en un delito hubiera recurrido a sus servicios a fin de preservar su integridad física o la del ofendido. Sin embargo, estas personas no podrán negar su testimonio cuando sean liberadas del deber de guardar secreto por el interesado. Si el testigo invocase erróneamente ese deber con respecto a un hecho no comprendido en el secreto profesional, el instructor sumarial procederá sin más a interrogarlo. Las pruebas obtenidas en violación a los recaudos precedentes carecerán de valor probatorio y no podrán usarse para ningún efecto.",

    "Artículo 151": "El sumariado puede ofrecer testigos denunciando nombre, apellido, ocupación y domicilio.",
    
    "Artículo 152": "El pliego de preguntas a realizar a los testigos propuestos por la defensa del sumariado, debe ser presentado hasta dos (2) días hábiles previos a la audiencia testimonial. En caso contrario, se desistirá el testimonio.",
    
    "Artículo 153": "Pueden ampliarse las preguntas y los testigos pueden ser repreguntados por el sumariado o por la instrucción.",
    
    "Artículo 154": "Si alguno de los testigos se halla imposibilitado de comparecer o tuviera alguna otra razón para no hacerlo, atendible a juicio del instructor sumarial, puede prestar declaración en su domicilio o en el lugar en el que se encuentre.",
    
    "Artículo 155": "El testigo debe ser citado en forma fehaciente por el instructor sumarial, con una antelación mínima de tres (3) días hábiles. Cuando se trate de personal del Gobierno de la Ciudad Autónoma de Buenos Aires o personal de la Policía de la Ciudad, la citación debe contener la enunciación de concurrir, bajo apercibimiento de ser sancionado en caso de incomparecencia injustificada.",
    
    "Artículo 156": "En la misma acta de notificación, se debe consignar una segunda fecha de audiencia, para el caso de incomparecencia con causa justificada a la primera fecha designada, situación que debe ser debidamente acreditada en el expediente. La incomparecencia injustificada a la primer audiencia configura falta disciplinaria, aún si el obligado se presentase en la segunda convocatoria.",
    
    "Artículo 157": "Previo a recibir la declaración testimonial, los testigos deben ser instruidos acerca de las penas por el delito de falso testimonio y prestar juramento o promesa de decir verdad, con excepción de las personas involucradas en hechos conexos. El instructor sumarial debe interrogar separadamente a cada testigo, requiriendo su nombre y apellido, edad, estado civil, profesión, domicilio real, teléfono de contacto y correo electrónico, vínculos de parentesco y de interés con el sumariado o el denunciante y cualquier otra circunstancia que sirva para apreciar la veracidad de su declaración. Después de ello, lo interrogará sobre el hecho. Concluida la declaración, el interrogado debe leerla por sí mismo. Si así no lo hiciere, el instructor sumarial o el secretario la leerán íntegramente, haciéndose expresa mención de la lectura. En ese acto, se le preguntará si ratifica su contenido y si tiene algo para añadir, quitar o enmendar. La declaración es firmada por todos los que hubieren intervenido en ella. Si alguno de los intervinientes no desea firmar, se hará constar en el acta. Si el interrogado no pudiera o no quisiera firmar la declaración, se hace mención de ello y se solicita la presencia de dos testigos, previa lectura del acto. El instructor y los testigos rubrican cada una de las fojas en que conste la declaración.",

    "Artículo 158": "El instructor sumarial puede recibir declaración testimonial reservando la identidad del testigo, en forma excepcional, y sólo si se corrobora alguno de los siguientes supuestos: 1) Si existe una amenaza a la vida tanto para el testigo como para su círculo íntimo o familiar. 2) Si su testimonio se solicita en el marco de una actuación administrativa que investiga hechos vinculados a presunta connivencia del personal policial y la correcta identificación del testigo pueda significar una amenaza. En todos los casos, es exclusiva facultad del titular de la dependencia en la cual tramita el sumario determinar la procedencia para la reserva de identidad del testigo, la que deberá quedar debidamente fundada en el sumario.",

    "Artículo 159": "En caso de autorizar la reserva de identidad del testigo, debe verificarse que sus datos personales se encuentren bajo custodia exclusivamente del titular del área donde se sustancie la actuación.",

    "Artículo 160": "El instructor sumarial puede interrogar a los testigos sobre cualquier conocimiento que tengan respecto a los hechos que han motivado el sumario o de aquellas circunstancias que, a juicio de la instrucción, interesen en la investigación. Las preguntas no pueden contener más de un hecho, deben ser claras y concretas. No se permite la formulación de la pregunta en términos afirmativos o que sugieran la respuesta o sean ofensivos o vejatorios. En caso de la inobservancia, el testigo puede negarse a responder.",

    "Artículo 161": "El testigo debe rehusarse a contestar las preguntas en los siguientes casos: 1) Si la respuesta lo expone a un enjuiciamiento penal. 2) Si no pudiera responder sin revelar un secreto al que se encuentra obligado en razón de su estado o profesión. 3) Si se configurase el supuesto detallado en el artículo precedente in fine.",

    "Artículo 162": "Concluida la declaración, el interrogado debe leer la misma por sí mismo. Si así no lo hiciere, el instructor sumarial o el secretario la leerán íntegramente, con la expresa mención de la lectura. En ese acto, se debe preguntar si ratifica su contenido y si tiene algo para añadir, quitar o enmendar.",

    "Artículo 163": "La declaración debe ser firmada por todos los que intervinieron en ella. Si alguno de los intervinientes no desea firmar, se debe constar en el acta. Si el interrogado no puede firmar la declaración, se hará mención de ello y se procederá a solicitar la presencia de dos (2) testigos, previa lectura del acto. En ese supuesto, el instructor sumarial y los testigos rubricarán, además, cada una de las fojas en las que conste.",

    "Artículo 164": "Cuando el instructor sumarial estime que se encuentra reunida la prueba suficiente, procederá por auto fundado, a citar al sumariado a recibir su declaración de descargo, haciéndole saber que cuenta con tres (3) días contados desde la notificación para tomar vista del expediente. La fecha de la declaración del sumariado debe ser al menos tres (3) días posterior al vencimiento del plazo de vista.",

    "Artículo 165": "En los casos que la actuación se hubiera ordenado en los términos del Artículo 107 del presente reglamento, y las pruebas colectadas permitiesen individualizar a los presuntos involucrados, el instructor sumarial debe proponer a la autoridad competente la emisión de un acto administrativo donde conste la individualización de cada sindicado como responsable.",
    
    "Artículo 166": "En el momento de notificar al sumariado de la citación, debe hacérsele saber que goza de los siguientes derechos: 1) A ampliar su declaración cuantas veces lo considere conveniente, antes de la clausura de la instrucción; 2) A contar con patrocinio letrado.",
    
    "Artículo 167": "En el momento de prestar declaración, debe informarse al sumariado de los derechos que lo asisten, los que deben ser debidamente garantizados: 1) Su silencio o negativa a declarar no implica presunción en su contra. 2) La dispensa del juramento de decir la verdad. 3) A leer por sí el acta de declaración y rubricar cada una de sus hojas. 4) A ampliar su declaración las veces que lo estime necesario, siempre que no se haya clausurado la instrucción. 5) Comparecer con asistencia letrada, si así lo desea. La inobservancia de lo aquí estipulado hace nula la declaración.",
    
    "Artículo 168": "En el supuesto que el sumariado desee ampliar su declaración de descargo, el sumariado debe solicitar audiencia por escrito, siendo responsabilidad del instructor sumarial fijar el día y la hora en que se celebrará dicha audiencia.",
    
    "Artículo 169": "El instructor sumarial puede llamar al sumariado cuantas veces lo considere necesario, para que amplíe o aclare aspectos de su declaración.",
    
    "Artículo 170": "El sumariado puede contar con patrocinio letrado en el momento de prestar declaración. Quien ejerza dicha asistencia no puede tomar la palabra sin autorización del instructor sumarial, a quien debe dirigirse cuando se le conceda el permiso. En dicho supuesto, el letrado puede proponer medidas de prueba, formular preguntas, hacer observaciones respecto a los dichos del sumariado y solicitar que se haga constar cualquier irregularidad.",
    
    "Artículo 171": "Si el sumariado no comparece a la primera citación, se debe dejar constancia de dicha circunstancia, y citarlo por segunda y última vez. Si no concurre, se deja asentada la inasistencia y se continuará con el procedimiento. Si antes de la clausura de la instrucción, el sujeto se hace presente ante la instrucción a fin de prestar declaración, ésta será recibida, en los términos del Artículo 167 de la presente reglamentación.",

    "Artículo 172": "El sumariado debe prestar declaración en forma personal y verbal.",

    "Artículo 173": "El sumariado puede presentar un escrito de defensa para alegar acerca de lo actuado y sobre la prueba que se haya producido y él hubiese tomado conocimiento.",
    
    "Artículo 174": "Al momento de su declaración, previa acreditación de su identidad, se le pregunta al sumariado la edad, estado civil, profesión, cargo, función, domicilio, teléfono y dirección de correo electrónico. A continuación, se le hacen conocer las causas que han motivado la iniciación del sumario, el hecho que se le atribuye y las pruebas que obran en su contra. Debe interrogarse al sumariado sobre todos los pormenores que pueden conducir al esclarecimiento del hecho investigado, así como también todas las circunstancias que sirvan para establecer la mayor o menor gravedad y su participación.",
    
    "Artículo 175": "Las preguntas realizadas por la instrucción deben ser claras y precisas, y guardar relación con los hechos que se investigan. El interrogado puede, si lo desea, dictar por sí sus declaraciones. Si no lo hace, lo hará el instructor sumarial procurando utilizar las mismas palabras de las que se valió aquel.",
    
    "Artículo 176": "El sumariado puede proponer las medidas de prueba que estime oportunas en el mismo acto en el que se lleva adelante su declaración.",
    
    "Artículo 177": "Las pruebas que ofrezca el sumariado deben ser admitidas por el instructor, siempre que no fueran manifiestamente improcedentes, superfluas o meramente dilatorias, en el plazo de tres (3) días hábiles. En el caso de no admisión, se debe dejar constancia fundada de la negativa. La sustanciación de las pruebas deberá producirse en el plazo de quince (15) días hábiles desde su admisión.",
    
    "Artículo 178": "La confesión expresa del sumariado constituye plena prueba en su contra, con ella puede cerrarse la instrucción del sumario, salvo que de los restantes elementos de prueba incorporados, surja la conveniencia de continuar con su instrucción hasta el total esclarecimiento del hecho investigado.",

    "Artículo 179": "Practicadas todas las averiguaciones y tramitaciones conducentes al esclarecimiento del hecho investigado, diligenciadas las medidas de prueba y agregado el concepto y los datos relevantes que surjan del legajo personal del sumariado, el instructor sumarial da por terminada la instrucción y dispone su clausura.",

    "Artículo 180": "Clausurada la instrucción, el instructor sumarial debe producir un informe lo más preciso posible, dentro de un plazo de siete (7) días hábiles, señalando:\n1) La relación circunstanciada de los hechos investigados.\n2) El análisis de los elementos de prueba acumulados, los que deben ser apreciados según las reglas de la sana crítica.\n3) La calificación de la conducta del sumariado.\n4) Las condiciones personales del sumariado que pueda tener influencia para determinar la mayor o menor gravedad de la sanción por el hecho imputado.\n5) La determinación de la existencia del presunto perjuicio económico para el juzgamiento ulterior de la responsabilidad patrimonial.\n6) Toda otra apreciación relevante para la solución del sumario. El plazo indicado puede ser prorrogado por el titular del área donde se sustancie el sumario, bajo requerimiento fundado del instructor sumarial.",

    "Artículo 181": "Cuando los hechos investigados hayan ocasionado un daño al patrimonio de la Administración, el informe del instructor sumarial debe contener los siguientes datos:\n1) Si el bien dañado se encuentra asegurado. En caso afirmativo el monto y alcances de la cobertura.\n2) El monto actualizado a la fecha de su emisión\n3) Los intereses devengados a la fecha de emisión del informe\n4) En los casos de percepción indebida de haberes, se deberá considerar el monto del grado o nivel que revista el agente a la fecha de emisión del informe.\n5) Cuando se trata de un bien, deberá consignarse su valor de reposición.\n6) En los casos de elementos informáticos, cuando el elemento cotizado no es el mismo que el siniestrado, deberá indicarse el motivo por el cual no se cotiza el elemento siniestrado y se determinará si el cotizado reúne las características semejantes o cumple similares funciones. Asimismo, deberá determinarse a través de la oficina, dependencia o sector donde se hallaba el elemento, si contiene algún tipo de información institucional y/o reservada y/o confidencial, y, en caso afirmativo, realizar un detalle.\n7) Se deberá adicionar copias de presupuestos, indicando las fuentes.\n8) Cuando el perjuicio estuviera cotizado en moneda extranjera, deberá indicarse el valor en moneda de curso legal, basado en la cotización oficial hecha a la fecha del informe, indicando la fuente.",

    "Artículo 182": "Elaborado el informe al que se refieren los Arts. 180 y 181 del presente, se debe notificar al sumariado, quien puede tomar vista de las actuaciones en presencia del personal autorizado y solicitar la extracción de copias a su cargo. En esta diligencia puede ser asistido por su letrado.",

    "Artículo 183": "El sumariado puede presentar un escrito de defensa y proponer las medidas de prueba que estime oportunas dentro del plazo de siete (7) días hábiles a contar desde la fecha de notificación del informe que refiere el Artículo 180 del presente.",

    "Artículo 184": "Si el sumariado no compareciese a tomar vista o a producir su descargo dentro del plazo establecido, el instructor sumarial debe elevar las actuaciones al titular a cargo del área donde tramita el sumario administrativo, de conformidad al Artículo 185 de la presente Reglamentación.",

    "Artículo 185": "Producida la prueba de descargo y agotada la investigación, el instructor sumarial, previa resolución definitiva de clausura de las actuaciones, debe elevar al titular del área donde tramitará el sumario un nuevo informe en el plazo de diez (10) días hábiles, aconsejando mediante opinión fundada:\n1) La eximición de responsabilidad del sumariado, cuando de las constancias de la investigación se desprenda que este no ha cometido falta administrativa;\n2) La clausura del procedimiento sin determinación de responsables, en caso que la investigación no haya permitido individualizar al o los autores de la conducta reprochable, o eximir de responsabilidad al o los sumariados.\n3) Declarar que la falta disciplinaria objeto de la investigación en el sumario no es de aquellas comprendidas en el ámbito de competencia de la oficina que ha instruido el sumario, remitiéndose las actuaciones para su prosecución al organismo que corresponda;\n4) La aplicación de la sanción disciplinaria que corresponda en atención a la falta atribuida, consignando los atenuantes y agravantes que concurran.\n5) La calificación del hecho, determinándose si éste fue vinculado o desvinculado del servicio. En caso que el sumariado haya sufrido daños en su persona por un hecho vinculado al servicio, se determina además si el acto fue “en y por acto de servicio”, o “en servicio”.\nArtículo 186: El titular del área donde se sustancie el sumario, fundadamente puede:\n1) Ordenar la ampliación del sumario y la realización de nuevas diligencias, las que no serán susceptibles de recurso alguno.\n2) Declarar la incompetencia, remitiendo las actuaciones al organismo que corresponda para su prosecución.\n3) Elevar el sumario para su resolución, pudiendo realizar las observaciones que estime convenientes.",

    "Artículo 187": "Una vez prestada la conformidad a todo lo actuado por parte del titular del órgano donde tramita el sumario administrativo, debe elevar las actuaciones a la autoridad competente que haya ordenado la instrucción de sumario administrativo con proyecto del acto administrativo que ha de dictarse.",

    "Artículo 188": "Recibidas las actuaciones por la autoridad que corresponda, se dicta la resolución que debe especificar:\n1) El detalle circunstanciado de los hechos investigados y la prueba producida.\n2) La normativa aplicable al caso.\n3) La calificación del hecho, determinándose si éste fue vinculado o desvinculado del servicio. En caso que el sumariado haya sufrido daños en su persona por un hecho vinculado al servicio, se determina además si el acto fue “en y por acto de servicio”, o “en servicio”.\n4) La eximición de responsabilidad al sumariado, cuando de la investigación se desprenda que no ha cometido falta disciplinaria.\n5) La existencia de responsabilidad del sumariado y la aplicación de la sanción administrativa que corresponda en atención a la falta cometida, consignando los atenuantes y/o agravantes que concurran.\n6) La existencia de perjuicio económico, si corresponde.\n7) La clausura del procedimiento sin determinación de responsabilidad administrativa, en caso que la investigación no haya permitido individualizar al o los autores de la conducta reprochable o eximir de responsabilidad a los sindicados como responsables. En este caso, la investigación puede ser reabierta en cualquier momento y siempre que no haya ocurrido la prescripción.",
    
    "Artículo 189": "La imposición de una sanción segregativa genera los efectos previstos en los incisos 2 y 3 del artículo 198 del presente.",
    
    "Artículo 190": "Pendiente la causa criminal, el sumariado no puede ser declarado exento de responsabilidad.",
    
    "Artículo 191": "Puede imponerse sanción por la comisión de una falta administrativa antes de la culminación del proceso penal. En este caso, la sanción que se imponga en la órbita administrativa tiene carácter provisional y puede ser sustituida por otra de mayor gravedad, si en la sentencia definitiva se acreditase la configuración de una causal más grave que la sancionada.",
    
    "Artículo 192": "En el caso de que como consecuencia de la falta cometida se acredite la existencia de perjuicio fiscal en el acto que clausura el procedimiento puede ordenarse el recupero patrimonial respectivo, como medida reparatoria. A tales efectos, se comunica la medida adoptada a la Dirección General Administrativa y Legal de Seguridad para la prosecución de su trámite.",
    
    "Artículo 193": "Luego de notificada la resolución referida en el Artículo 188 del presente, se debe comunicar a:\n1) El Secretario de Seguridad del Ministerio de Justicia y Seguridad.\n2) La Oficina de Transparencia y Control Externo.\n3) El Jefe de la Policía de la Ciudad.\n4) El órgano disciplinario interno de la Policía de la Ciudad.\n5) Las áreas encargadas de la gestión de Recursos Humanos de la Policía de la Ciudad.\n6) Al Jefe de la dependencia en la que el personal involucrado preste servicios.\nEs responsabilidad de las áreas encargadas de la gestión de los recursos humanos de la Policía de la Ciudad notificar al sumariado de la resolución que se dicte.",
    
    "Artículo 194": "De la sanción impuesta se debe dejar constancia en el legajo del sancionado, comprendiendo los siguientes datos:\n1) Autoridad que impuso la sanción.\n2) Naturaleza y quantum de la sanción.\n3) Causa de la sanción.\n4) Número de Expediente.\n5) Fecha de cumplimiento de la sanción, en los casos que sea de suspensión de empleo.\n6) Fecha de notificación de la sanción, en los casos que la medida adoptada sea de carácter segregativo.",

    "Artículo 195": "En caso de inasistencias injustificadas del personal con o sin estado policial es de aplicación el procedimiento especial reglado en este Título.",

    "Artículo 196": "El personal, salvo casos de fuerza mayor, debe dar aviso de la enfermedad o accidente y del lugar en que se encuentra, durante el transcurso de la primera jornada de trabajo en la cual estuviera imposibilitado de concurrir por alguna de esas causas. Mientras no lo haga, pierde el derecho a percibir la remuneración correspondiente, salvo que la existencia de la enfermedad o accidente, teniendo en consideración su carácter y gravedad, resulte luego inequívocamente acreditada.",

    "Artículo 197": "El agente que incurriera en tres (3) inasistencias consecutivas, sin previo aviso y sin justificación, debe ser intimado a reintegrarse al servicio dentro de las cuarenta y ocho (48) horas de producida la notificación, bajo apercibimiento de tener por configurado el abandono de servicio. Vencido el plazo sin que el agente se haya reintegrado al servicio o haya justificado debidamente su inasistencia, se tiene por configurado el abandono de servicio.",

    "Artículo 198": "La configuración del abandono de servicio produce los siguientes efectos:\n1) Cambio de situación de revista del personal a pasiva sin goce de haberes, hasta tanto se dicte la resolución que pone fin al procedimiento.\n2) Intimación al agente a devolver todos los elementos de la institución que obren en su poder, incluidas las armas, chaleco, uniforme, credenciales, identificaciones, bajo apercibimiento de efectuar la denuncia penal y proceder al recupero del perjuicio fiscal conforme lo establecido en el inciso 3 de este artículo. Si los bienes no fuesen devueltos en el plazo perentorio que se indique, el órgano encargado de la gestión de los recursos humanos debe bloquear los haberes pendientes de pago del incumplidor, si los hubiera, e informar de inmediato a la Oficina de Transparencia y Control de Gestión a los efectos de la prosecución del trámite de presentación de la denuncia penal.\n3) Elevación de las actuaciones a la Oficina de Transparencia y Control Externo policial, a los efectos de la verificación de la configuración del abandono de servicio y la prosecución del trámite de aplicación de la sanción correspondiente. Si no se hubiesen devuelto todos o parte de los elementos indicados en el inciso anterior, debe consignarse su valor de reposición. La resolución que impone la sanción de cesantía debe disponer el recupero del monto mediante la retención efectuada sobre cualquier suma que deba abonarse al presunto infractor, incluso de montos correspondientes a servicios de Policía Complementaria. Si efectuada la retención aún quedasen montos por satisfacer a favor de la administración, debe evaluarse la conveniencia de iniciar el trámite de recupero judicial de los montos adeudados.",

    "Artículo 199": "El personal que se encuentre prófugo de la justicia debe ser considerado en abandono de servicio. A estos efectos, la declaración de rebeldía implica, ni bien es conocida por la Administración, el cambio a situación pasiva sin goce de haberes del fugado, y es causa suficiente para tener por configurado el abandono de servicio, debiendo aplicarse sin más trámite la medida segregativa correspondiente.",

    "Artículo 200": "En caso de no encontrarse configurado el abandono de servicio, pero se acreditasen inasistencias injustificadas reiteradas y alternadas, el infractor es sancionado conforme el siguiente detalle:\n1) Por tres (3) inasistencias injustificadas en el término de hasta trescientos sesenta y cinco (365) días: apercibimiento.\n2) Por cinco (5) inasistencias injustificadas en el término de hasta trescientos sesenta y cinco (365) días: cinco (5) días de suspensión de empleo.\n3) Por diez (10) inasistencias injustificadas en el término de hasta trescientos sesenta y cinco (365) días: diez (10) días de suspensión de empleo.\n4) Por quince (15) inasistencias injustificadas en el término de hasta trescientos sesenta y cinco (365) días: treinta (30) días de suspensión de empleo.\n5) Por veinte (20) inasistencias injustificadas en el término de hasta trescientos sesenta y cinco (365) días o más: cesantía.",

    "Artículo 201": "Las sanciones correspondientes a las inasistencias injustificadas consecutivas o alternadas se aplican sin la sustanciación de sumario administrativo previo, excepto que fuese necesario realizar investigaciones relacionadas con las causas de justificación de las inasistencias alegadas por el presunto infractor. En este caso, se aplican las normas del sumario administrativo.",

    "Artículo 202": "En el supuesto previsto en el inciso 5 del Artículo 200 mencionado ut supra, la verificación del hecho que da lugar a la cesantía produce los efectos previstos en el artículo 198 de esta reglamentación.",

    /*DECRETO Nº 047/017
BOCBA Nº 5054 del 24/01/2017

B*/

    "EL JEFE DE GOBIERNO DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES DECRETA - Artículo 1°": "Apruébase la reglamentación de la Ley N° 5.688 en lo referente a las retribuciones, suplementos y compensaciones de los integrantes del personal al que se hace referencia en el mencionado texto legal, conforme al Anexo I (IF-2017-3018854-MJYSGC) y de la reglamentación del artículo 361 de la mencionada Ley, conforme al Anexo II (IF-2017-3018622-MJYSGC) que, a todos los efectos, se acompañan y forman parte integrante del presente Decreto.",

    "EL JEFE DE GOBIERNO DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES DECRETA - Artículo 2°": "Créase el Módulo Retributivo Policial (MOPOL) y el Módulo Retributivo para el Personal No Policial (MONOPOL) como unidades de referencia para establecer la remuneración de los servicios de personal con estado policial y sin estado policial respectivamente.",

    "EL JEFE DE GOBIERNO DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES DECRETA - Artículo 3°": "Facúltase a los titulares de los Ministerios de Justicia y Seguridad y de Hacienda, en forma conjunta, a fijar el valor de los Módulos Retributivos creados en el artículo 2°.",

    "EL JEFE DE GOBIERNO DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES DECRETA - Artículo 4°": "Facúltase al titular del Ministerio de Justicia y Seguridad a dictar las normas complementarias, aclaratorias, interpretativas y operativas que resulten necesarias para la aplicación del presente decreto.",

    "EL JEFE DE GOBIERNO DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES DECRETA - Artículo 5°": "El presente Decreto es refrendado por los señores Ministros de Justicia y Seguridad y de Hacienda y por el señor Jefe de Gabinete de Ministros.",

    "EL JEFE DE GOBIERNO DE LA CIUDAD AUTÓNOMA DE BUENOS AIRES DECRETA - Artículo 6°": "Publíquese en el Boletín Oficial de la Ciudad de Buenos Aires. Comuníquese a la Subsecretaria de Gestión de Recursos Humanos y a la Dirección General Oficina de Gestión Pública y Presupuesto del Ministerio de Hacienda, a la Secretaría de Seguridad, a la Subsecretaría de Administración de Seguridad y a la Dirección General de Administración de Recursos Humanos de Seguridad del Ministerio de Justicia y Seguridad, y para su conocimiento y demás efectos, pase al Ministerio de Justicia y Seguridad. Cumplido, archívese. RODRÍGUEZ LARRETA - Ocampo - Mura - Miguel",


 "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186)   Artículo 1°": "La retribución bruta normal y habitual del personal de la Policía de la Ciudad con estado policial en situación de actividad está integrada por el sueldo básico y los suplementos conforme se dispone en el presente Decreto.",

    "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186)   Artículo 2°": "El sueldo básico del Jefe de la Policía de la Ciudad es equivalente a 7.000 Módulos Retributivos Policiales.",

    "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186)   Artículo 3°": "El sueldo básico correspondiente a los distintos grados que conforman el Escalafón General Policial se determina de acuerdo a los porcentajes que se establecen a continuación, en relación al sueldo básico fijado para el Jefe de la Policía de la Ciudad:\nSubjefe de la Policía de la Ciudad: 95%\nSuperintendente: 88%\nComisionado General: 80%\nComisionado Mayor: 72%\nComisario: 64%\nSubcomisario: 60%\nInspector Principal: 56%\nInspector: 48%\nOficial Mayor: 40%\nOficial Primero: 30%\nOficial: 28%",

    "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186)  Artículo 4°": "El sueldo básico correspondiente al grado transitorio de Oficial Ayudante se establece en un veinticinco por ciento (25 %) respecto al sueldo básico fijado para el Jefe de la Policía de la Ciudad.",

    "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186)  Artículo 5°": "El sueldo básico correspondiente a los grados transitorios que integran el Grupo Auxiliar de Oficiales Superiores se establece conforme los porcentajes que a continuación se detallan, respecto al sueldo básico fijado para el Jefe de la Policía de la Ciudad:\nOficial Primero: 56%\nOficial Segundo: 52%\nOficial Tercero: 48%",

    "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186)  Artículo 6°": "Establécense como suplementos los siguientes:\nSuplemento por responsabilidad jerárquica\nSuplemento por antigüedad de servicio\nSuplemento por permanencia en el grado\nSuplemento por riesgo profesional\nSuplemento por horas de vuelo\nSuplemento por riesgo profesional aeronáutico\nSuplemento por riesgo en manejo de explosivos\nSuplemento por especialidad de alto riesgo\nSuplemento por servicio en la vía pública",

    "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186)  Artículo 7°": "El suplemento por responsabilidad jerárquica, de carácter remunerativo y bonificable, es equivalente a los porcentajes del sueldo básico que a continuación se establecen:\nJefe y Subjefe: 50%\nSuperintendente: 30%\nComisionado General: 30%\nComisionado Mayor: 22%\nComisario: 22%\nSubcomisario: 22%\nInspector Principal: 12%\nInspector: 12%\nOficial Mayor: 12%",

    "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186)  Artículo 8°": "Los Oficiales Primeros, Segundos y Terceros integrantes del Grupo Auxiliar de Oficiales Superiores perciben un suplemento por responsabilidad jerárquica equivalente al doce por ciento (12%) de su sueldo básico.",

    "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186)  Artículo 9°": "El suplemento por antigüedad de servicio, de carácter remunerativo y bonificable, es equivalente al dos por ciento (2%) del sueldo básico por cada año de servicio cumplido, computándose a tal fin únicamente los años de servicio prestados en la Policía de la Ciudad.",

    "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186)  Artículo 10": "El suplemento por permanencia en el grado, de carácter remunerativo y bonificable, es percibido por el personal que cumpla el tiempo mínimo de servicio establecido para su grado y reúna los restantes requisitos exigidos para el ascenso. Equivale a un sesenta por ciento (60%) de la diferencia entre el sueldo básico de su grado y el del inmediato superior.",

    "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186)  Artículo 11": "El suplemento por riesgo profesional, de carácter remunerativo y bonificable, es percibido por todo el personal que se encuentre en servicio efectivo y cumpliendo las tareas propias y específicas del estado policial. El suplemento es equivalente al veinticinco por ciento (25%) del sueldo básico del grado correspondiente.",

    "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186)  Artículo 12": "El suplemento por horas de vuelo, de carácter no remunerativo y no bonificable, es percibido por el personal que, en cumplimiento de su labor específica, vuele seis (6) horas mensuales como mínimo. El suplemento por horas de vuelo es equivalente al quince por ciento (15%) del sueldo básico. El suplemento por horas de vuelo es incompatible con la percepción del suplemento por riesgo profesional aeronáutico.",

    "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186)  Artículo 13": "El suplemento por riesgo profesional aeronáutico, de carácter no remunerativo y no bonificable, es percibido por el personal que realice funciones aeronáuticas de conformidad con el artículo 76 del Código Aeronáutico. Para percibir este suplemento, el personal debe poseer la certificación de idoneidad expedida por la autoridad aeronáutica y demás requisitos establecidos por el Código Aeronáutico, sus normas reglamentarias y complementarias. El suplemento por riesgo profesional aeronáutico es equivalente al cuarenta por ciento (40%) del sueldo básico de un Superintendente de la Policía de la Ciudad. La percepción de este suplemento es incompatible con el suplemento de horas de vuelo.",

    "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186)  Artículo 14": "El suplemento por riesgo en manejo de explosivos, de carácter no remunerativo y no bonificable, es percibido por el personal que tenga la misión de riesgo específica y directa de manipular, desactivar o transportar material explosivo. El suplemento por riesgo en manejo de explosivos es equivalente al cuarenta por ciento (40%) del sueldo básico de un Superintendente de la Policía de la Ciudad.",

    "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186)  Artículo 15": "El suplemento por especialidad de alto riesgo, de carácter no remunerativo y no bonificable, es percibido por el personal con destino permanente o en comisión de servicios en los grupos especiales que determine el Ministro de Justicia y Seguridad de la Ciudad y que tuvieren tareas de riesgo directo y específico derivado de la misión asignada a tales unidades. El suplemento por especialidad de alto riesgo es equivalente al cuarenta por ciento (40%) del sueldo básico de un Superintendente de la Policía de la Ciudad. La percepción de este suplemento es incompatible con la percepción del suplemento por riesgo en manejo de explosivos.",

    "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186)  Artículo 16": "El suplemento por servicio en la vía pública, de carácter no remunerativo y no bonificable, es percibido por todo el personal policial que preste servicio ordinario en vía pública, cumpliendo tareas propias y específicas policiales.",

    "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186) Artículo 17": "El suplemento por servicio en la vía pública se percibe en forma proporcional al tiempo de servicios de este carácter efectivamente prestados durante el mes. Para su cómputo, el monto del suplemento se divide por la cantidad mensual de días durante los cuales el personal debe prestar servicios, y se multiplica por la cantidad de días durante los cuales se han prestado efectivamente los servicios en la vía pública. A los efectos del cálculo detallado en el párrafo anterior se consideran como días de servicio efectivamente prestado en la vía pública los siguientes: Los días de licencia anual ordinaria; Los días que sean declarados inhábiles por festividades religiosas; Los días de licencia por accidente de trabajo o enfermedad profesional. El monto del suplemento por servicio en la vía pública es establecido por resolución conjunta de los Ministros de Justicia y Seguridad y Hacienda de la Ciudad Autónoma de Buenos Aires.",

  "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186) Artículo 18": "El suplemento por presentismo, de carácter no remunerativo y no bonificable, es percibido por todo el personal que cumpla con la totalidad de los días de servicio que debe prestar en el mes. Las únicas inasistencias compatibles con la percepción del suplemento por presentismo son: Los días de licencia anual ordinaria; Los días que sean declarados inhábiles por festividades religiosas; Los días de licencia por accidente de trabajo o enfermedad profesional. El monto del suplemento por presentismo es establecido por resolución conjunta de los Ministros de Justicia y Seguridad y Hacienda de la Ciudad Autónoma de Buenos Aires.",

  "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186) Artículo 19": "La compensación por recargo de servicio, de carácter no remunerativo y no bonificable, es percibida por el personal que cumpla servicios extraordinarios fuera del horario normal de labor, liquidándose cuando los mismos excedan las tres (3) horas diarias. La compensación por recargo de servicios equivale a un porcentaje del sueldo básico del grado, conforme el siguiente detalle: Recargo de servicios de 3 a 4 horas diarias: 2,5%; Recargo de servicios de más de 4 horas y hasta 6 horas diarias: 3,75%; Recargo de servicios de más de 6 horas diarias: 5%.",

  "ANEXO I - REGLAMENTACIÓN DEL CAPÍTULO XVII DEL TÍTULO III DEL LIBRO II - PERSONAL CON ESTADO POLICIAL DE LA POLICÍA DE LA CIUDAD (Arts. 183 y 186) Artículo 20": "La compensación por gastos de comida es percibida por el personal que, en razón de realizar horas extraordinarias de trabajo, cumpla una jornada laboral de no menos de nueve (9) horas continuas. El personal puede percibir el reintegro de gastos correspondientes a dos (2) comidas (almuerzo y cena) en el caso que cumpla como mínimo una jornada de labor extraordinaria de doce (12) horas continuas. No pueden percibir este reintegro quienes perciban viáticos o ración de comida. El monto del suplemento por gastos de comida es establecida por resolución del Ministro de Justicia y Seguridad de la Ciudad Autónoma de Buenos Aires, previa intervención del Ministerio de Hacienda.",

"Artículo 21": "La retribución bruta normal y habitual del personal de la Policía de la Ciudad sin estado policial está integrada por el sueldo básico y los suplementos conforme se dispone en el presente decreto.",

  "Artículo 22": "El sueldo básico del personal sin estado policial del Nivel A es equivalente a 4.600 Módulos Retributivos para el Personal No Policial.",

  "Artículo 23": "El sueldo básico correspondiente a los restantes niveles que conforman el agrupamiento del personal sin estado policial se determina de acuerdo a los porcentajes que se establecen a continuación, en relación al sueldo básico fijado para el personal del nivel A: Nivel B: 90% Nivel C: 80% Nivel D: 70% Nivel E: 60% Nivel F: 53% Nivel G: 48% Nivel H: 43% Nivel I: 38% Nivel J: 33%",

  "Artículo 24": "Establécense como suplementos los siguientes: Suplemento por responsabilidad jerárquica. Suplemento por antigüedad de servicio Suplemento por horas de vuelo Suplemento por riesgo profesional aeronáutico",

  "Artículo 25": "El suplemento por responsabilidad jerárquica, de carácter remunerativo y bonificable, es percibido por el personal que desarrolle tareas de conducción y/o dirección de áreas técnicas o administrativas o esté a cargo del desarrollo e implementación de planes o programas afines al desenvolvimiento funcional de la institución. Se determina aplicando un porcentaje sobre el sueldo básico del nivel, conforme al siguiente detalle: Nivel A: 30% Niveles B y C: 22% Niveles D y E: 12%.",

  "Artículo 26": "El suplemento por antigüedad de servicio, de carácter remunerativo y bonificable, es equivalente al dos por ciento (2%) del sueldo básico por cada año de servicio cumplido, computándose a tal fin únicamente los años de servicio prestados en la Policía de la Ciudad.",

  "Artículo 27": "El suplemento por horas de vuelo, de carácter no remunerativo y no bonificable, es percibido por el personal que, en cumplimiento de su labor específica, vuele seis (6) horas mensuales como mínimo. El suplemento por horas de vuelo es equivalente al quince por ciento (15%) del sueldo básico. El suplemento por horas de vuelo es incompatible con la percepción del suplemento por riesgo profesional aeronáutico.",

 "Artículo 29": "El personal del Cuerpo de Bomberos de la Ciudad percibe sueldos y suplementos equivalentes a los establecidos para el personal con estado policial de la Policía de la Ciudad, conforme el cuadro de equivalencia de grados establecido en la Cláusula Transitoria DECIMO SEXTA de la Ley N° 5.688. Cuerpo de Bomberos Policía de la Ciudad Jefe del Cuerpo de Bomberos Superintendente Comandante General Comisionado General Comandante Director Comisionado Mayor Comandante Comisario Subcomandante Subcomisario Capitán Inspector Principal Teniente Inspector Subteniente Oficial Mayor Bombero Superior Oficial Primero Bombero Calificado Oficial Bombero Oficial Ayudante REGLAMENTACIÓN CLÁUSULAS TRANSITORIAS SEXTA, SÉPTIMA, OCTAVA, NOVENA Y DECIMO CUARTA DE LA LEY N° 5.688.",

  "Artículo 30": "El personal de la Policía Federal Argentina transferido a la Ciudad de Buenos Aires en virtud del “Convenio de transferencia progresiva a la Ciudad Autónoma de Buenos Aires de facultades y funciones de seguridad en todas las materias no federales ejercidas en la Ciudad Autónoma de Buenos Aires”, aprobado por Resolución N° 298/LCBA/15, y el personal de la Policía Metropolitana que integre la Policía de la Ciudad en virtud de las Cláusulas Transitorias Sexta, Séptima, Octava, Novena y Decimo Cuarta la Ley N° 5.688, percibe a partir del 1 de enero de 2017 el sueldo básico y los suplementos que se establecen en el presente régimen especial.",

  "Artículo 31": "A los efectos de los cómputos de los suplementos establecidos en este régimen para el personal de la Policía Federal Argentina transferido a la Ciudad de Buenos Aires en virtud del “Convenio de transferencia progresiva a la Ciudad Autónoma de Buenos Aires de facultades y funciones de seguridad en todas las materias no federales ejercidas en la Ciudad Autónoma de Buenos Aires”, aprobado por Resolución N° 298/LCBA/15, se utilizan los siguientes conceptos: Denomínase “SALARIO REGULARIZADO EN FUERZA DE ORIGEN” a la suma de los siguientes conceptos que percibe el personal transferido a la Ciudad de Buenos Aires en el mes de diciembre de 2016: Sueldo básico. Suplemento por responsabilidad por cargo o función (artículo 2° del Decreto N° 2.744/PEN/93). Suma fija establecida por Decreto N° 1.262/PEN/09. Denomínase “COMPENSACIÓN POR INCREMENTO DE JORNADA LABORAL” al quince por ciento (15%) del SALARIO REGULARIZADO EN FUERZA DE ORIGEN. Denomínase “SALARIO CONFORMADO EN FUERZA DE ORIGEN” a la suma de los siguientes conceptos que percibe el personal transferido a la Ciudad en el mes de diciembre de 2016: SALARIO REGULARIZADO EN FUERZA DE ORIGEN. Suplemento por Servicio Externo Uniformado (artículo 396 ter del Decreto N° 1.866/PEN/83) o Suplemento por Apoyo Operativo (artículo 396 quater del Decreto N° 1.866/PEN/83). Suplementos por Título (artículo 44 del Decreto N° 1.428/PEN/73 y artículo 76 de la Ley N° 21.965). Suplemento Sistema de Computación de Datos (Decretos Nros. 688/PEN/89 y 1.809/PEN/92). Suplemento por variabilidad de la vivienda (artículo 391 del Decreto N° 1866/PEN/83) Suplemento por Zona Sur (artículo 397 del Decreto N° 1.866/PEN/83) Suma fija establecida por Decreto N° 1322/PEN/06. Denomínase “SALARIO CONFORMADO FINAL” a la suma de los siguientes conceptos: SALARIO CONFORMADO EN FUERZA DE ORIGEN. COMPENSACIÓN POR INCREMENTO DE JORNADA LABORAL. Denomínase “SALARIO CONFORMADO EN POLICÍA DE LA CIUDAD” a la suma de los siguientes conceptos, calculados al 1 de enero de 2017: Sueldo básico (artículos 3, 4 y 5 del presente Reglamento). Suplemento por Responsabilidad Jerárquica (artículos 7 y 8 del presente Reglamento). Suplemento por Riesgo Profesional (artículo 11 del presente Reglamento).",


    "Artículo 32": "A los efectos de los cómputos de los suplementos establecidos en este régimen para el personal de la Policía Metropolitana que integre la Policía de la Ciudad, se utilizan los siguientes conceptos:\n\nDenomínase “SALARIO CONFORMADO FINAL” a la suma de los siguientes conceptos que percibe el personal de la Policía Metropolitana en el mes de diciembre de 2016:\n- Sueldo básico (artículo 3 del Decreto N° 293/14)\n- Suplemento por responsabilidad jerárquica (artículo 5 del Decreto N° 380/09).\n- Suplemento por riesgo profesional (artículo 4 del Decreto N° 380/09).\n\nDenominase “SALARIO CONFORMADO EN POLICÍA DE LA CIUDAD” a la suma de los siguientes conceptos, calculados al 1 de enero de 2017:\n- Sueldo básico (arts. 3, 4 y 5 del presente Reglamento)\n- Suplemento por Responsabilidad Jerárquica (artículo 7 del presente Reglamento)\n- Suplemento por Riesgo Profesional (artículo 11 del presente Reglamento).'",
  
    "Artículo 33": "'La retribución por antigüedad al personal de la Policía Federal Argentina transferido a la Ciudad de Buenos Aires se efectúa conforme las siguientes reglas de cálculo:\n\nEl monto que el personal hubiera percibido en concepto de antigüedad el 1 de enero de 2017 (artículo 389 del inciso a) Decreto N° 1.866/PEN/83) se incorpora al “SALARIO CONFORMADO EN POLICÍA DE LA CIUDAD\" por la diferencia con el \"SALARIO CONFORMADO FINAL\", en caso que éste resulte inferior.\nEl saldo del monto que el personal hubiera percibido en concepto de antigüedad el 1 de enero de 2017 –si lo hubiere- , conforma el “Suplemento Residual por Antigüedad en Fuerza de Origen”. Este suplemento es remunerativo, bonificable y ajustable por los porcentajes de ajuste que se apliquen al sueldo básico.\nLa antigüedad que el personal acumule con posterioridad al 1 de enero de 2017 se retribuye mediante el “Suplemento por Antigüedad de servicio” establecido en el artículo 9 de este Reglamento.'",

    "Artículo 34": "A efectos de garantizar que el personal de la Policía Federal Argentina transferido a la Ciudad de Buenos Aires y el personal de la Policía Metropolitana que integren la Policía de la Ciudad no sufra ningún menoscabo salarial como consecuencia de la conformación de la Policía de la Ciudad, establécese un 'Adicional Compensatorio' equivalente al monto en que el “SALARIO CONFORMADO FINAL” resulte superior al “SALARIO CONFORMADO EN POLICÍA DE LA CIUDAD”.\n\nEn el caso del personal transferido comprendido en la Cláusula Transitoria Novena de la Ley N° 5.688, y del personal sin estado policial transferido a la Ciudad, a los efectos del cálculo de este Adicional Compensatorio, el “SALARIO CONFORMADO FINAL” es equivalente al “SALARIO CONFORMADO EN FUERZA DE ORIGEN”.\n\nEl Adicional Compensatorio es remunerativo, bonificable y ajustable por el porcentaje de incremento que se aplique al sueldo básico del grado correspondiente de la Policía de la Ciudad.\n\nEl Adicional Compensatorio se percibe hasta el primer ascenso. Si luego del primer ascenso el SALARIO CONFORMADO EN POLICÍA DE LA CIUDAD del grado superior resultase inferior al SALARIO CONFORMADO EN POLICÍA DE LA CIUDAD del grado de origen más el Adicional Compensatorio, la persona que hubiera ascendido percibe como Adicional Compensatorio el monto equivalente a esta diferencia, hasta el ascenso siguiente.'",

    "Artículo 35": "'La retribución por antigüedad al personal de la Policía Metropolitana que integra la Policía de la Ciudad se efectúa conforme las siguientes reglas de cálculo:\n\nEl monto que el personal hubiera percibido en concepto de antigüedad el 1 de enero de 2017 (artículo 4 inciso a) del Decreto N° 380/09) conforma el “Suplemento Residual por Antigüedad en Fuerza de Origen”. Este suplemento es remunerativo, bonificable y ajustable por los porcentajes de ajuste que se apliquen al sueldo básico.\nLa antigüedad que el personal acumule con posterioridad al 1 de enero de 2017 se retribuye mediante el “Suplemento por Antigüedad de servicio” establecido en el artículo 9 de este Reglamento.'",

    "Artículo 36": "Establécese un “Suplemento por Tiempo Mínimo en el Grado en Fuerza de Origen”, de carácter remunerativo, bonificable y ajustable por los porcentajes de ajuste que se apliquen al sueldo básico. Es equivalente al monto que el personal de la Policía Federal Argentina transferido a la Ciudad y el personal de la Policía Metropolitana hubiera cobrado por el suplemento por tiempo mínimo en el grado (artículo 389 inciso b) del Decreto N° 1.866/PEN/83 o artículo 4 inciso b) del Decreto N° 380/09) el 1 de enero de 2017.\n\nEl suplemento se percibe:\n\nHasta el primer ascenso. Si el SALARIO CONFORMADO EN POLICÍA DE LA CIUDAD del grado superior fuese menor al SALARIO CONFORMADO EN POLICÍA DE LA CIUDAD del grado inferior más el “Suplemento por Tiempo Mínimo en el Grado en Fuerza de Origen”, la persona que ha ascendido percibe la diferencia como “Suplemento por Tiempo Mínimo en el Grado en Fuerza de Origen” hasta el ascenso siguiente o hasta que comience a percibir el “Suplemento por Permanencia en el Grado” establecido en el artículo 10, en el grado superior.\n\nHasta que, sin ascender, el personal comience a percibir el suplemento de “Permanencia en el Grado” establecido en el artículo 10 de este Reglamento. Si el suplemento por “Tiempo Mínimo en el Grado en Fuerza de Origen” fuese mayor al suplemento por “Permanencia en el Grado”, el personal percibirá como “Tiempo Mínimo en el Grado en fuerza de Origen” el equivalente a la diferencia, hasta el ascenso.",

    "Artículo 37": "El personal que en su fuerza de origen no percibiese el suplemento de Tiempo Mínimo en el Grado por no haber cumplido el plazo mínimo establecido para su grado, puede computar este plazo menor a los efectos del cálculo del suplemento de “Permanencia en el Grado” establecido en el art. 10 de este Reglamento, con la excepción establecida en el artículo siguiente.",

    "Artículo 38": "El personal que revistaba como Oficial en la Policía Metropolitana y que a partir del 1 de enero de 2017 adquiere el grado de Oficial Primero, es considerado ascendido. En consecuencia, no percibe el suplemento de “Tiempo Mínimo en el Grado en Fuerza de Origen” y debe computar el total del tiempo de permanencia en el grado de Oficial Primero para percibir el suplemento establecido en el artículo 10 de este Reglamento.",

    "Artículo 39": "El personal de la Policía Federal Argentina transferido a la Ciudad que haya ascendido al grado de Cabo 1° durante diciembre de 2016, continúa percibiendo el suplemento por tiempo mínimo en el grado en fuerza de origen conforme lo establece el artículo 36 de esta norma.",

    "Artículo 40": "Establécese un “Suplemento No Remunerativo en Fuerza de Origen” equivalente al monto que el personal percibió en el mes de diciembre de 2016 por el “Adicional Transitorio No Remunerativo y No Bonificable” establecido en el artículo 6 del Decreto N° 380/09. Este suplemento es no remunerativo, no bonificable y se actualiza con el porcentaje de ajuste que se aplique al sueldo básico. El suplemento es percibido siempre que el personal no hubiese ascendido en la Policía Metropolitana al 1 de enero de 2017. El suplemento se percibe hasta el primer ascenso. Si el SALARIO CONFORMADO EN LA POLICÍA DE LA CIUDAD correspondiente al grado superior fuese inferior al SALARIO CONFORMADO EN LA POLICÍA DE LA CIUDAD de su grado de origen más el “Suplemento No Remunerativo en Fuerza de Origen”, el personal percibe la diferencia como “Suplemento No Remunerativo en Fuerza de Origen”, hasta el ascenso siguiente.",

    "Artículo 41": "Establécese una “Compensación Especial Transitoria por Hijo con Discapacidad”, no remunerativa, no bonificable y no ajustable, percibido por el personal transferido a la Ciudad, equivalente a pesos mil quinientos ($ 1.500) por cada hijo/a con discapacidad que tuviese al 31 de diciembre de 2016. En caso que la asignación familiar por hijo/a con discapacidad que percibe el personal conforme al régimen vigente para los trabajadores del Gobierno de la Ciudad Autónoma de Buenos Aires incremente su valor en relación al vigente en diciembre de 2016, la Compensación Especial Transitoria por Hijo con Discapacidad se reduce en la misma medida.",

    "Artículo 42": "El personal de la Policía Federal Argentina transferido a la Ciudad percibe, a partir del 1° de enero de 2017, el Subsidio para Ex Combatientes de Malvinas establecido en la Ordenanza N° 39.827/84 (texto consolidado por Ley N° 5.666) o norma que en el futuro la reemplace. Este subsidio reemplaza a cualquier otro que, por la misma causa, el personal hubiera percibido como integrante de la Policía Federal Argentina.",

    "Artículo 43": "El personal transferido que se encuentre en la situación prevista en la Cláusula Transitoria Novena de la Ley N° 5.688, y que al 31 de diciembre de 2016 tenga el grado de Suboficial Escribiente, queda recategorizado en el Nivel F del agrupamiento de personal sin estado policial y puede ejercer la opción establecida en esa Cláusula.",

/*REGLAMENTACIÓN DEL ARTÍCULO 361 DEL CAPÍTULO IV DEL TÍTULO I DEL LIBRO IV DE LA LEY N° 5.688
INSTITUTO SUPERIOR DE SEGURIDAD PÚBLICA*/


    "Artículo 361": "El Director/a del Instituto Superior de Seguridad Pública percibe un salario básico equivalente al del Jefe de la Policía de la Ciudad. Percibe un suplemento por responsabilidad jerárquica equivalente al cincuenta por ciento (50%) de su salario básico, y el suplemento por antigüedad contemplado en el artículo 26 del Anexo I del presente Reglamento. El personal del Instituto Superior de Seguridad Pública percibe el sueldo básico y los suplementos que, en ejercicio de sus funciones propias, determine el Director/a del ente.",


/*ANEXO I
Reglamentación de los Capítulos III, IV y V del Título III del Libro II y de las
Cláusulas Transitorias Sexta, Séptima y Octava de la Ley N° 5.688
*/



     "Artículo 112": "El personal con estado policial de la Policía de la Ciudad de Buenos Aires adquiere estabilidad en el empleo después de transcurridos doce (12) meses de efectiva prestación de servicios en tareas propias de su grado, y una vez que hubiere aprobado las evaluaciones que se establecen en este artículo.\n\na) El cómputo del plazo de efectiva prestación de servicios durante doce (12) meses se realiza conforme las siguientes reglas:\n1) Los doce (12) meses de prestación de servicios pueden ser continuos o discontinuos.\n2) Los servicios computables deben ser efectivamente prestados. No se computan los períodos en que el personal ha gozado de alguna de las licencias previstas en el artículo 160 de la Ley N° 5.688, ni aquéllos en que se encuentra en disponibilidad o servicio pasivo.\n3) Los servicios deben consistir en las tareas propias y específicas de su grado. No se computa el plazo en que el personal se encuentra en las situaciones previstas en el segundo párrafo del artículo 104 y en el artículo 158 de la Ley N° 5.688, excepto para las mujeres embarazadas, a quienes se les computa el período de prestación de tareas adecuadas a su condición.\n4) Para el personal que integra la Policía de la Ciudad el 1° de enero de 2017, se computan los servicios efectivamente prestados en su fuerza de origen. Quienes hubieran adquirido la estabilidad en Policía Federal Argentina o en la Policía Metropolitana, la mantienen en la Policía de la Ciudad.\nb) Para adquirir estabilidad el personal debe aprobar las siguientes evaluaciones:\n1) Evaluación psicológica;\n2) Evaluación física de aptitud clínica;\n3) Evaluación de idoneidad física para el desempeño de la labor policial efectuada por el Instituto Superior de Seguridad Pública;\n4) Evaluación de aptitud profesional, elaborada por el superior jerárquico. Quien tuviera una calificación insuficiente en alguna de las instancias mencionadas debe ser evaluado por la Junta Médica en el caso de los incisos 1 y 2, y por la Junta Permanente de Calificaciones en el caso de los incisos 3 y 4. Si el dictamen de la Junta Médica o de la Junta Permanente de Calificaciones concluyese que la persona no cuenta con las aptitudes necesarias para el desempeño de la función policial, se dicta su baja de la Policía de la Ciudad.",

     


      };


  const matchingResults = [];

            const keywords = keyword.toLowerCase().split(" ");
            const bestMatches = [];

            for (const key in dataArray) {
                const keyLower = key.toLowerCase();
                const description = dataArray[key];
                const descriptionLower = description.toLowerCase();

                const matchPercentage = calculateMatchPercentage(keywords, keyLower, descriptionLower);

                if (matchPercentage > 0) {
                    matchingResults.push({ key, matchPercentage, description });
                    if (!bestMatches.length || matchPercentage > bestMatches[0].matchPercentage) {
                        bestMatches.length = 0; // Clear previous best matches
                        bestMatches.push({ key, matchPercentage, description });
                    } else if (matchPercentage === bestMatches[0].matchPercentage) {
                        bestMatches.push({ key, matchPercentage, description });
                    }
                }
            }

            if (bestMatches.length > 0) {
                const resultHTML = bestMatches.map(result => {
                    // Resalta las palabras encontradas en negro
                    const highlightedDescription = result.description.replace(
                        new RegExp(`(${keywords.join("|")})`, "ig"),
                        '<span style="color: black; background-color: yellow;">$1</span>'
                    );
                    return `${result.key}: ${highlightedDescription}`;
                }).join("<br>");
                addMessage(resultHTML, true);
            } else {
                addMessage("Disculpe, no puedo encontrar esa información en mi sistema. Por favor, comuníquese con garcostaborda@buenosaires.gob.ar o nicolasignaciomaciel@buenosaires.gob.ar para reportar el inconveniente.", true);
            }
        }
        addMessageWithTypingEffect("¿Necesitas buscar otra seccion del libro?", true, 1000);
        setTimeout(() => {
            showOptions();
            scrollToBottom();
        }, 1000);
    });
